    <line x1="${originX.toFixed(2)}" y1="${dimRunY.toFixed(2)}" x2="${topX.toFixed(2)}" y2="${dimRunY.toFixed(2)}" stroke="var(--accent-primary, #7aa2ff)" stroke-width="1.1"/>
