/** Default fallback code key */
const DEFAULT_BUILDING_CODE_ID = 'jnbc';

/**
 * Retrieve a building code profile by ID. Falls back to default if invalid.
 * @param {string} codeId
 * @returns {object}
 */
function getBuildingCode(codeId) {
  if (codeId && BUILDING_CODES[codeId]) {
    return BUILDING_CODES[codeId];
  }
  return BUILDING_CODES[DEFAULT_BUILDING_CODE_ID];
}

/**
 * List all available building codes.
 * @returns {Array<object>}
 */
function listBuildingCodes() {
  return Object.values(BUILDING_CODES);
}

/**
 * Inspect a calculated stair result against a specific building code.
 *
 * @param {object} stairResult - Output model from calculateStair()
 * @param {string} codeId - Identifier of building code (e.g. 'jnbc', 'sbc')
 * @param {string} [buildingType='public'] - 'public' | 'residential'
 * @returns {object} Detailed compliance scorecard
 */
function inspectStairCompliance(stairResult, codeId = 'jnbc', buildingType = 'public') {
  const code = getBuildingCode(codeId);
  const cfg = code.stair;

  if (!stairResult || !stairResult.geometry) {
    return {
      code,
      overallStatus: 'warn',
      summaryText: 'No stair geometry available to inspect.',
      summaryArabic: 'لا تتوفر بيانات هندسية للفحص.',
      checks: []
    };
  }

  const geom = stairResult.geometry;
  // calculateStair() carries riser/tread/Blondel values on risers/treads/proportion,
  // not on geometry; accept the flat legacy aliases for hand-built fixtures.
  const riserMeters = stairResult.risers?.heightMeters ?? geom.riserHeightMeters;
  const treadMeters = stairResult.treads?.depthMeters ?? geom.treadDepthMeters;
  const blondelMeters = stairResult.proportion?.twoRPlusTMeters ?? geom.blondelMeters;
  if (!Number.isFinite(riserMeters) || !Number.isFinite(treadMeters)) {
    return {
      code,
      overallStatus: 'warn',
      summaryText: 'Incomplete stair geometry — riser/tread values missing, compliance cannot be evaluated.',
      summaryArabic: 'بيانات هندسية للقلبة غير مكتملة — لا يمكن إجراء الفحص.',
      checks: []
    };
  }
  const riserMm = Math.round(riserMeters * 1000 * 10) / 10;
  const treadMm = Math.round(treadMeters * 1000 * 10) / 10;
  const blondelMm = Number.isFinite(blondelMeters) ? Math.round(blondelMeters * 1000 * 10) / 10 : null;
  const riserCount = stairResult.risers?.count || 0;

  const minTreadAllowed = buildingType === 'residential' ? cfg.treadResidentialMinMm : cfg.treadMinMm;

  const checks = [];

  // 1. Riser Height Check
  let riserStatus = 'pass';
  let riserMessage = `Within standard range (${cfg.riserMinMm}–${cfg.riserMaxMm} mm)`;
  let riserArabic = `ضمن النطاق المعتمد (${cfg.riserMinMm}–${cfg.riserMaxMm} مم)`;
  if (riserMm > cfg.riserMaxMm) {
    riserStatus = 'fail';
    riserMessage = `Exceeds maximum allowable riser of ${cfg.riserMaxMm} mm`;
    riserArabic = `يتجاوز الحد الأقصى المسموح لارتفاع القائمة (${cfg.riserMaxMm} مم)`;
  } else if (riserMm < cfg.riserMinMm) {
    riserStatus = 'fail';
    riserMessage = `Below minimum allowable riser of ${cfg.riserMinMm} mm`;
    riserArabic = `أقل من الحد الأدنى المسموح لارتفاع القائمة (${cfg.riserMinMm} مم)`;
  }
  checks.push({
    key: 'riser',
    label: 'Riser Height (القائمة)',
    value: `${riserMm} mm`,
    rule: `${cfg.riserMinMm}–${cfg.riserMaxMm} mm`,
    status: riserStatus,
    note: riserMessage,
    noteArabic: riserArabic,
    citation: cfg.citation
  });

  // 2. Tread Depth / Going Check
  let treadStatus = 'pass';
  let treadMessage = `Meets minimum tread requirement (≥ ${minTreadAllowed} mm)`;
  let treadArabic = `يحقق الحد الأدنى لعمق النائمة (≥ ${minTreadAllowed} مم)`;
  if (treadMm < minTreadAllowed) {
    treadStatus = 'fail';
    treadMessage = `Less than minimum mandated tread of ${minTreadAllowed} mm`;
    treadArabic = `أقل من الحد الأدنى القانوني لعمق النائمة (${minTreadAllowed} مم)`;
  }
  checks.push({
    key: 'tread',
    label: 'Tread Depth / Going (النائمة)',
    value: `${treadMm} mm`,
    rule: `≥ ${minTreadAllowed} mm`,
    status: treadStatus,
    note: treadMessage,
    noteArabic: treadArabic,
    citation: cfg.citation
  });

  // 3. Ergonomic Stride (Blondel 2R + T) Check
  let blondelStatus = 'pass';
  let blondelMessage = `Optimal walking stride (${cfg.blondelMinMm}–${cfg.blondelMaxMm} mm)`;
  let blondelArabic = `خطوة سير مريحة ومتزنة (${cfg.blondelMinMm}–${cfg.blondelMaxMm} مم)`;
  if (blondelMm < cfg.blondelMinMm) {
    blondelStatus = 'warn';
    blondelMessage = `Stride is tighter than standard recommendation (${blondelMm} < ${cfg.blondelMinMm} mm)`;
    blondelArabic = `الخطوة ضيقة أو سريعة (${blondelMm} < ${cfg.blondelMinMm} مم)`;
  } else if (blondelMm > cfg.blondelMaxMm) {
    blondelStatus = 'warn';
    blondelMessage = `Stride is elongated or steep (${blondelMm} > ${cfg.blondelMaxMm} mm)`;
    blondelArabic = `الخطوة مجهدة أو واسعة (${blondelMm} > ${cfg.blondelMaxMm} مم)`;
  }
  checks.push({
    key: 'blondel',
    label: 'Ergonomic Stride (2R + T) (معادلة بلونديل)',
    value: `${blondelMm} mm`,
    rule: `${cfg.blondelMinMm}–${cfg.blondelMaxMm} mm`,
    status: blondelStatus,
    note: blondelMessage,
    noteArabic: blondelArabic,
    citation: 'Blondel / Universal Human Stride Standard'
  });

  // 4. Flight Length & Intermediate Landing Check
  let flightStatus = 'pass';
  let flightMessage = `Flight within maximum single run limit (≤ ${cfg.maxFlightRisers} risers)`;
  let flightArabic = `القلبة ضمن الحد الأقصى بدون استراحة (≤ ${cfg.maxFlightRisers} قائمة)`;
  if (riserCount > cfg.maxFlightRisers) {
    flightStatus = 'warn';
    flightMessage = `Mandatory landing required: exceeds ${cfg.maxFlightRisers} continuous risers`;
    flightArabic = `يتطلب استراحة وسطية إلزامية: تجاوز ${cfg.maxFlightRisers} قائمة متتالية`;
  }
  checks.push({
    key: 'flightCount',
    label: 'Continuous Flight Risers (عدد قوائم القلبة)',
    value: `${riserCount} Risers`,
    rule: `≤ ${cfg.maxFlightRisers} risers before landing`,
    status: flightStatus,
    note: flightMessage,
    noteArabic: flightArabic,
    citation: cfg.citation
  });

  // Determine Overall Status
  let overallStatus = 'pass';
  if (checks.some(c => c.status === 'fail')) {
    overallStatus = 'fail';
  } else if (checks.some(c => c.status === 'warn')) {
    overallStatus = 'warn';
  }

  let summaryText = '';
  let summaryArabic = '';
  if (overallStatus === 'pass') {
    summaryText = `Full Compliance with ${code.name}`;
    summaryArabic = `مطابق بالكامل لمتطلبات ${code.name}`;
  } else if (overallStatus === 'warn') {
    summaryText = `Conditional / Advisory Notice under ${code.shortName}`;
    summaryArabic = `مقبول مشروط / تنبيه بموجب ${code.shortName}`;
  } else {
    summaryText = `Non-Compliant / Violation under ${code.shortName}`;
    summaryArabic = `مخالف لمتطلبات ${code.shortName}`;
  }

  return {
    code,
    overallStatus,
    summaryText,
    summaryArabic,
    checks
  };
}

/**
 * Inspect a calculated ramp result against a specific building code.
 *
 * @param {object} rampResult - Output model from calculateRamp()
 * @param {string} codeId - Identifier of building code (e.g. 'jnbc', 'sbc')
 * @returns {object} Detailed compliance scorecard
 */
function inspectRampCompliance(rampResult, codeId = 'jnbc') {
  const code = getBuildingCode(codeId);
  const cfg = code.ramp;

  if (!rampResult || !rampResult.geometry) {
    return {
      code,
      overallStatus: 'warn',
      summaryText: 'No ramp geometry available to inspect.',
      summaryArabic: 'لا تتوفر بيانات هندسية للفحص.',
      checks: []
    };
  }

  const geom = rampResult.geometry;
  const slopePercent = Math.round(geom.slopePercent * 100) / 100;
  // buildRampGeometry() exposes the run/rise ratio as `ratioValue`; the flat
  // `ratio` alias is accepted for hand-built legacy fixtures.
  const ratioSource = Number.isFinite(geom.ratioValue) ? geom.ratioValue : geom.ratio;
  const ratioVal = Number.isFinite(ratioSource) ? Math.round(ratioSource * 10) / 10 : null;
  const riseMeters = geom.riseMeters;
  const runMeters = geom.runMeters;
  if (!Number.isFinite(slopePercent)) {
    return {
      code,
      overallStatus: 'warn',
      summaryText: 'Incomplete ramp geometry — slope values missing, compliance cannot be evaluated.',
      summaryArabic: 'بيانات هندسية للمنحدر غير مكتملة — لا يمكن إجراء الفحص.',
      checks: []
    };
  }

  const checks = [];

  // 1. Ramp Slope / Incline Check
  let slopeStatus = 'pass';
  let slopeMessage = `Compliant accessible slope (≤ ${cfg.maxSlopePercent}% / 1:${cfg.maxSlopeRatio})`;
  let slopeArabic = `ميل مطابق ومقبول لإمكانية الوصول (≤ ${cfg.maxSlopePercent}% / 1:${cfg.maxSlopeRatio})`;
  if (slopePercent > cfg.maxSlopePercent + 0.05) {
    slopeStatus = 'fail';
    slopeMessage = `Steeper than legal maximum of ${cfg.maxSlopePercent}% (1:${cfg.maxSlopeRatio})`;
    slopeArabic = `أشد انحداراً من الحد القانوني الأقصى ${cfg.maxSlopePercent}% (1:${cfg.maxSlopeRatio})`;
  } else if (slopePercent <= cfg.preferredSlopePercent) {
    slopeStatus = 'pass';
    slopeMessage = `Optimal comfort slope for Universal Design / Wheelchair use (≤ ${cfg.preferredSlopePercent}%)`;
    slopeArabic = `ميل مثالي ومريح للغاية لحركة الكراسي المتحركة والوصول الشامل (≤ ${cfg.preferredSlopePercent}%)`;
  }
  checks.push({
    key: 'slope',
    label: 'Ramp Gradient / Slope (انحدار المنحدر)',
    value: `${slopePercent}% (1 : ${ratioVal})`,
    rule: `Max ${cfg.maxSlopePercent}% (1:${cfg.maxSlopeRatio}) · Ideal ≤ ${cfg.preferredSlopePercent}%`,
    status: slopeStatus,
    note: slopeMessage,
    noteArabic: slopeArabic,
    citation: cfg.citation
  });

  // 2. Single Run Rise Limit Check (Intermediate Landing Mandate)
  let riseStatus = 'pass';
  let riseMessage = `Rise within maximum single flight threshold (≤ ${cfg.maxRunRiseMeters * 1000} mm)`;
  let riseArabic = `الارتفاع ضمن الحد الأقصى للقلبة الواحدة (≤ ${cfg.maxRunRiseMeters * 1000} مم)`;
  let landingsNeeded = 0;
  if (riseMeters > cfg.maxRunRiseMeters) {
    riseStatus = 'warn';
    landingsNeeded = Math.ceil(riseMeters / cfg.maxRunRiseMeters) - 1;
    riseMessage = `Exceeds single run rise limit (${cfg.maxRunRiseMeters * 1000} mm). Requires ${landingsNeeded} intermediate landing(s).`;
    riseArabic = `يتجاوز أقصى ارتفاع للقلبة الواحدة (${cfg.maxRunRiseMeters * 1000} مم). يلزم توفير ${landingsNeeded} استراحة وسطية.`;
  }
  checks.push({
    key: 'riseLimit',
    label: 'Single Run Max Rise (أقصى ارتفاع للقلبة بدون استراحة)',
    value: `${Math.round(riseMeters * 1000)} mm`,
    rule: `≤ ${cfg.maxRunRiseMeters * 1000} mm before landing`,
    status: riseStatus,
    note: riseMessage,
    noteArabic: riseArabic,
    citation: cfg.citation
  });

  // 3. Continuous Run Length Check
  let runStatus = 'pass';
  let runMessage = `Run length within single flight limit (≤ ${cfg.maxRunLengthMeters} m)`;
  let runArabic = `طول الجريان ضمن الحد المسموح للقلبة (≤ ${cfg.maxRunLengthMeters} م)`;
  if (runMeters > cfg.maxRunLengthMeters) {
    runStatus = 'warn';
    runMessage = `Continuous run exceeds ${cfg.maxRunLengthMeters} m. Intermediate rest platform recommended.`;
    runArabic = `طول المنحدر يتجاوز ${cfg.maxRunLengthMeters} م. يوصى بفاصل استراحة لتقليل إجهاد المستخدم.`;
  }
  checks.push({
    key: 'runLength',
    label: 'Continuous Run Length (طول المنحدر المستمر)',
    value: `${runMeters.toFixed(2)} m`,
    rule: `≤ ${cfg.maxRunLengthMeters} m`,
    status: runStatus,
    note: runMessage,
    noteArabic: runArabic,
    citation: cfg.citation
  });

  // 4. Landing Size Requirement
  checks.push({
    key: 'landingSpecs',
    label: 'Mandatory Landing Dimensions (أبعاد الاستراحة المطلوبة)',
    value: `≥ ${cfg.minLandingLengthMm} × ${cfg.minLandingWidthMm} mm`,
    rule: `Min length ${cfg.minLandingLengthMm} mm (${code.id === 'dbc' ? '1800 mm turn' : '1500 mm turn'})`,
    status: 'pass',
    note: `Landings must be level (slope ≤ 2%) and unobstructed.`,
    noteArabic: `يجب أن تكون الاستراحة مستوية (الميل ≤ 2%) وخالية من أي عوائق.`,
    citation: cfg.citation
  });

  // 5. Handrail Mandate
  const handrailRequired = (riseMeters * 1000 >= cfg.handrailRequiredRiseMm) || (runMeters >= 1.8);
  checks.push({
    key: 'handrails',
    label: 'Continuous Handrails (الدرابزين المزدوج)',
    value: handrailRequired ? 'Mandatory (إلزامي على الجانبين)' : 'Recommended (مستحسن)',
    rule: `Required when rise ≥ ${cfg.handrailRequiredRiseMm} mm or run ≥ 1.8 m`,
    status: 'pass',
    note: `Continuous handrails on both sides at height 865–965 mm with 300 mm extensions.`,
    noteArabic: `درابزين مستمر على الجانبين بارتفاع 865–965 مم مع امتداد أفقي 300 مم.`,
    citation: cfg.citation
  });

  // Determine Overall Status
  let overallStatus = 'pass';
  if (checks.some(c => c.status === 'fail')) {
    overallStatus = 'fail';
  } else if (checks.some(c => c.status === 'warn')) {
    overallStatus = 'warn';
  }

  let summaryText = '';
  let summaryArabic = '';
  if (overallStatus === 'pass') {
    summaryText = `Full Compliance with ${code.name}`;
    summaryArabic = `مطابق بالكامل لمتطلبات ${code.name}`;
  } else if (overallStatus === 'warn') {
    summaryText = `Requires Landings / Advisory under ${code.shortName}`;
    summaryArabic = `يتطلب استراحة / تنبيه إشغالي بموجب ${code.shortName}`;
  } else {
    summaryText = `Non-Compliant / Gradient Violation under ${code.shortName}`;
    summaryArabic = `مخالف لمتطلبات الانحدار في ${code.shortName}`;
  }

  return {
    code,
    overallStatus,
    summaryText,
    summaryArabic,
    landingsNeeded,
    checks
  };
}

/**
 * Inspect general slope against pedestrian & vehicle classification under a building code.
 *
 * @param {object} slopeResult - Output model from calculateSlope()
 * @param {string} codeId - Identifier of building code
 * @returns {object} Scorecard
 */
function inspectSlopeCompliance(slopeResult, codeId = 'jnbc') {
  const code = getBuildingCode(codeId);
  const cfg = code.slope;

  if (!slopeResult || !slopeResult.geometry) {
    return {
      code,
      overallStatus: 'warn',
      summaryText: 'No slope geometry available.',
      summaryArabic: 'لا تتوفر بيانات ميل للفحص.',
      checks: []
    };
  }

  const rawPercent = slopeResult.geometry.slopePercent ?? slopeResult.geometry.percent ?? 0;
  const percent = Math.abs(rawPercent);
  const checks = [];

  // Pedestrian Walkway Check
  let pedStatus = 'pass';
  let pedMsg = `Within standard accessible sidewalk/walkway limit (≤ ${cfg.maxPedestrianWalkPercent}%)`;
  let pedAr = `ضمن الحد المسموح للأرصفة ومسارات المشاة الميسرة (≤ ${cfg.maxPedestrianWalkPercent}%)`;
  if (percent > cfg.maxPedestrianWalkPercent) {
    pedStatus = 'warn';
    pedMsg = `Exceeds ${cfg.maxPedestrianWalkPercent}%: Must be classified and treated as an accessible ramp (requires handrails & landings)`;
    pedAr = `يتجاوز ${cfg.maxPedestrianWalkPercent}%: يصنف معمارياً كمنحدر ويلزمه اشتراطات المنحدرات والدرابزين`;
  }

  checks.push({
    key: 'pedestrian',
    label: 'Pedestrian Walkway Limit (مسار المشاة العادي)',
    value: `${percent.toFixed(2)}%`,
    rule: `≤ ${cfg.maxPedestrianWalkPercent}% (1:20)`,
    status: pedStatus,
    note: pedMsg,
    noteArabic: pedAr,
    citation: cfg.citation
  });

  // Cross-slope check
  checks.push({
    key: 'crossSlope',
    label: 'Sidewalk Drainage Cross-Slope (الميل العرضي لتصريف الأمطار)',
    value: 'Standard Target',
    rule: `Max ${cfg.maxCrossSlopePercent}%`,
    status: 'pass',
    note: `Maximum perpendicular cross-slope to prevent wheelchair tilt.`,
    noteArabic: `أقصى ميل عرضي لمنع انحراف الكراسي المتحركة وتصريف مياه الأمطار.`,
    citation: cfg.citation
  });

  const overallStatus = pedStatus === 'pass' ? 'pass' : 'warn';

  return {
    code,
    overallStatus,
    summaryText: overallStatus === 'pass' ? `Compliant Accessible Walkway under ${code.shortName}` : `Treated as Ramp under ${code.shortName}`,
    summaryArabic: overallStatus === 'pass' ? `مسار مشاة مطابق بموجب ${code.shortName}` : `يصنف كمنحدر بموجب ${code.shortName}`,
    checks
  };
}


  // =========================================================================
  // MODULE: Project
  // =========================================================================

/**
 * Architecture Helping Hand - Project Document Model
 * Stabilization 2: a pure, deterministic, serializable project envelope.
 *
 * This is the future shared state for Rooms / Walls / Openings / Furniture /
 * Survey / snapshots / decisions / exports. It is deliberately SMALL: only
 * structures with a current consumer are modeled in depth; the rest exist as
 * reserved-but-empty containers so the envelope is stable across migrations.
 *
 * Rules (enforced by tests/core contracts):
 *  - No DOM. No localStorage. No timers. Pure data in → data out.
 *  - Deterministic: createProject() with no seed produces identical output
 *    for identical inputs; ids are random only when no id is supplied.
 *  - Unknown fields are PRESERVED on normalize so future migrations can
 *    recover data this version does not understand.
 *  - Malformed documents are rejected by validateProject with a precise
 *    error path, never silently "repaired" into plausible-looking garbage.
 */

/**
 * Current schema version of the project document.
 * Bump when the envelope changes, and add a migration in
 * src/core/project-migrations.js (Stabilization 3).
 */
const PROJECT_SCHEMA_VERSION = 2;

/** Historical schema versions (kept for migration tooling/tests). */
const PROJECT_SCHEMA_VERSION_V1 = 1;

/** Storage envelope key for the versioned project store. */
const PROJECT_STORE_KEY = 'archiscale_project_store';

/** Storage key for the multi-project library (Phase 2: Project Workspace). */
const PROJECT_LIBRARY_KEY = 'archiscale_project_library';

/** Legacy per-feature keys (read-only here; migration is non-destructive). */
const LEGACY_STORAGE_KEYS = Object.freeze({
  workspace: 'archiscale_dimension_workspace',
  chains: 'archiscale_dimension_chains',
  cadClipboard: 'archiscale_cad_clipboard_settings',
  cadHandoff: 'archiscale_cad_handoff_prefs',
  batchCad: 'archi_batch_cad_state',
  quickDimension: 'archiscale_quick_dimension_prefs',
  history: 'archiscale_calculation_history',
  multiscaleFavorites: 'archiscale_multiscale_favs',
  theme: 'archi_theme',
  sound: 'archiscale_sound_enabled'
});

const METADATA_FIELDS = ['name', 'description', 'author', 'createdBy'];

/**
 * Creates a new empty project document.
 * @param {Object} [options]
 * @param {string} [options.id] - Optional stable id (generated when omitted)
 * @param {string} [options.name] - Project name
 * @param {string} [options.description]
 * @param {string} [options.author]
 * @param {Object} [options.site] - Site descriptor { location, notes, areaM2 }
 * @returns {Object} A fresh project document (schemaVersion 1)
 */
function createProject(options = {}) {
  const now = new Date().toISOString();
  return {
    schemaVersion: PROJECT_SCHEMA_VERSION,
    id: typeof options.id === 'string' && options.id ? options.id : generateProjectId(),
    metadata: {
      name: typeof options.name === 'string' ? options.name : 'Untitled Project',
      description: typeof options.description === 'string' ? options.description : '',
      author: typeof options.author === 'string' ? options.author : '',
      createdAt: now,
      updatedAt: now
    },
    site: normalizeSite(options.site),
    // Project data containers (reserved for upcoming phases)
    dimensions: [],
    chains: [],
    notes: [],
    snapshots: [],
    decisions: [],
    exports: [],
    scratchpad: [],
    brief: {
      buildingType: '',
      site: { location: '', notes: '', areaM2: null, orientation: '' },
      floors: null,
      areaTargets: { grossM2: null, netM2: null },
      circulation: { strategy: '', targetPctOfNet: null },
      accessibility: { target: '', notes: '' },
      orientation: { primary: '', notes: '' },
      specialConstraints: [],
      userRules: [],
      roomRequirements: [],
      requirements: [],
      adjacencies: []
    },
    documents: Array.isArray(options.documents) ? options.documents : [
      {
        id: 'doc-1',
        name: 'Ground Floor',
        type: '2d',
        entities: [],
        layers: {
          walls: true,
          doors: true,
          windows: true,
          rooms: true,
          columns: true,
          furniture: true,
          dimensions: true,
          textNotes: true,
          grid: true
        },
        viewport: { zoom: 40, offsetX: 60, offsetY: 420 }
      }
    ]
  };
}

/**
 * Generates a project id. Deterministic tests pass their own ids; runtime
 * ids combine a timestamp with random suffix for practical uniqueness.
 */
function generateProjectId() {
  const rand = Math.random().toString(36).slice(2, 8);
  return `proj-${Date.now().toString(36)}-${rand}`;
}

function normalizeSite(site) {
  const s = site && typeof site === 'object' ? site : {};
  return {
    location: typeof s.location === 'string' ? s.location : '',
    notes: typeof s.notes === 'string' ? s.notes : '',
    areaM2: typeof s.areaM2 === 'number' && isFinite(s.areaM2) && s.areaM2 > 0 ? s.areaM2 : null
  };
}

/**
 * Validates a project document.
 * @param {*} doc - Candidate document
 * @returns {{ ok: boolean, errors: string[] }} Empty errors == valid
 */
function validateProject(doc) {
  const errors = [];

  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) {
    return { ok: false, errors: ['Project document must be an object'] };
  }

  if (!Number.isInteger(doc.schemaVersion) || doc.schemaVersion < 1) {
    errors.push('schemaVersion must be a positive integer');
  }

  if (typeof doc.id !== 'string' || !doc.id) {
    errors.push('id must be a non-empty string');
  }

  if (!doc.metadata || typeof doc.metadata !== 'object' || Array.isArray(doc.metadata)) {
    errors.push('metadata must be an object');
  } else {
    if (typeof doc.metadata.name !== 'string') {
      errors.push('metadata.name must be a string');
    }
    if (doc.metadata.createdAt !== undefined && typeof doc.metadata.createdAt !== 'string') {
      errors.push('metadata.createdAt must be a string when present');
    }
    if (doc.metadata.updatedAt !== undefined && typeof doc.metadata.updatedAt !== 'string') {
      errors.push('metadata.updatedAt must be a string when present');
    }
  }

  if (doc.site !== undefined && (doc.site === null || typeof doc.site !== 'object' || Array.isArray(doc.site))) {
    errors.push('site must be an object when present');
  }

  for (const key of ['dimensions', 'chains', 'notes', 'snapshots', 'decisions', 'exports', 'scratchpad', 'documents']) {
    // 'brief' normalized separately below (object, not array)
    if (doc[key] !== undefined && !Array.isArray(doc[key])) {
      errors.push(`${key} must be an array when present`);
    }
  }

  return { ok: errors.length === 0, errors };
}

/**
 * Normalizes a project document to the current schema shape:
 *  - fills missing containers with empty defaults
 *  - preserves ALL unknown fields (future migration safety)
 *  - normalizes metadata/site field types without dropping data
 *
 * Note: does NOT validate; call validateProject first when the input's
 * trustworthiness is unknown. Normalizing garbage still yields garbage
 * (deterministically).
 *
 * @param {Object} doc - Parsed document (from deserializeProject or createProject)
 * @returns {Object} Normalized document
 */
function normalizeProject(doc) {
  const src = doc && typeof doc === 'object' && !Array.isArray(doc) ? doc : {};
  const normalized = { ...src };

  normalized.schemaVersion = PROJECT_SCHEMA_VERSION;
  normalized.id = typeof src.id === 'string' && src.id ? src.id : generateProjectId();

  const metaSrc = src.metadata && typeof src.metadata === 'object' ? src.metadata : {};
  const metadata = { ...metaSrc };
  for (const field of METADATA_FIELDS) {
    if (metadata[field] !== undefined && typeof metadata[field] !== 'string') {
      metadata[field] = String(metadata[field]);
    }
  }
  if (typeof metadata.name !== 'string' || !metadata.name) metadata.name = 'Untitled Project';
  normalized.metadata = metadata;

  normalized.site = normalizeSite(src.site);

  for (const key of ['dimensions', 'chains', 'notes', 'snapshots', 'decisions', 'exports', 'scratchpad', 'documents']) {
    if (!Array.isArray(normalized[key])) normalized[key] = [];
  }

  // Project brief (schema v2 container): normalized so every field exists.
  const defaultBrief = {
    buildingType: '',
    site: { location: '', notes: '', areaM2: null, orientation: '' },
    floors: null,
    areaTargets: { grossM2: null, netM2: null },
    circulation: { strategy: '', targetPctOfNet: null },
    accessibility: { target: '', notes: '' },
    orientation: { primary: '', notes: '' },
    specialConstraints: [],
    userRules: [],
    roomRequirements: [],
    requirements: [],
    adjacencies: []
  };
  const briefSrc = src.brief && typeof src.brief === 'object' && !Array.isArray(src.brief) ? src.brief : {};
  normalized.brief = {
    ...defaultBrief,
    ...briefSrc,
    site: { ...defaultBrief.site, ...(briefSrc.site && typeof briefSrc.site === 'object' ? briefSrc.site : {}) },
    areaTargets: { ...defaultBrief.areaTargets, ...(briefSrc.areaTargets && typeof briefSrc.areaTargets === 'object' ? briefSrc.areaTargets : {}) },
    circulation: { ...defaultBrief.circulation, ...(briefSrc.circulation && typeof briefSrc.circulation === 'object' ? briefSrc.circulation : {}) },
    accessibility: { ...defaultBrief.accessibility, ...(briefSrc.accessibility && typeof briefSrc.accessibility === 'object' ? briefSrc.accessibility : {}) },
    orientation: { ...defaultBrief.orientation, ...(briefSrc.orientation && typeof briefSrc.orientation === 'object' ? briefSrc.orientation : {}) },
    specialConstraints: Array.isArray(briefSrc.specialConstraints) ? briefSrc.specialConstraints : [],
    userRules: Array.isArray(briefSrc.userRules) ? briefSrc.userRules : [],
    roomRequirements: Array.isArray(briefSrc.roomRequirements) ? briefSrc.roomRequirements : [],
    requirements: Array.isArray(briefSrc.requirements) ? briefSrc.requirements : [],
    adjacencies: Array.isArray(briefSrc.adjacencies) ? briefSrc.adjacencies : []
  };
  if (normalized.documents.length === 0) {
    let defaultEntities = [];
    if (Array.isArray(src.entities)) {
      defaultEntities = src.entities;
    } else if (src.entities && typeof src.entities === 'object') {
      defaultEntities = Object.values(src.entities).flat().filter(Boolean);
    }

    normalized.documents = [
      {
        id: 'doc-1',
        name: 'Ground Floor',
        type: '2d',
        entities: defaultEntities,
        layers: {
          walls: true,
          doors: true,
          windows: true,
          rooms: true,
          columns: true,
          furniture: true,
          dimensions: true,
          textNotes: true,
          grid: true
        },
        viewport: { zoom: 40, offsetX: 60, offsetY: 420 }
      }
    ];
  }

  return normalized;
}

/**
 * Deep-clones a project document via structured clone semantics with a
 * JSON fallback (keeps the module browser- and Node-safe).
 * @param {Object} doc - Project document
 * @returns {Object} Independent clone
 */
function cloneProject(doc) {
  if (typeof structuredClone === 'function') {
    return structuredClone(doc);
  }
  return JSON.parse(JSON.stringify(doc));
}

/**
 * Touches the document's updatedAt timestamp and returns a new document
 * (immutable style: the input is not mutated).
 * @param {Object} doc
 * @param {Date|string} [when] - Defaults to now
 */
function touchProject(doc, when) {
  const next = cloneProject(doc);
  next.metadata = { ...next.metadata, updatedAt: (when ? new Date(when) : new Date()).toISOString() };
  return next;
}

/**
 * Serializes a project document to a pretty-printed JSON string.
 * @param {Object} doc - Validated/normalized project document
 * @returns {string}
 */
function serializeProject(doc) {
  return JSON.stringify(doc, null, 2);
}

/**
 * Deserializes a JSON string into a candidate project document.
 * Throws a controlled Error for unparseable input (callers decide policy).
 * @param {string} json
 * @returns {Object} Parsed document (validate before trusting)
 */
function deserializeProject(json) {
  if (typeof json !== 'string' || !json.trim()) {
    throw new Error('deserializeProject requires a non-empty JSON string');
  }
  let parsed;
  try {
    parsed = JSON.parse(json);
  } catch (e) {
    throw new Error(`Project document is not valid JSON: ${e.message}`);
  }
  return parsed;
}

/**
 * Convenience: deserialize + validate in one step.
 * @param {string} json
 * @returns {{ ok: boolean, errors?: string[], doc?: Object }}
 */
function parseProject(json) {
  let doc;
  try {
    doc = deserializeProject(json);
  } catch (e) {
    return { ok: false, errors: [e.message] };
  }
  const check = validateProject(doc);
  if (!check.ok) return { ok: false, errors: check.errors };
  return { ok: true, doc: normalizeProject(doc) };
}


