/**
 * Architecture Helping Hand - Architectural Zoning & Area Schedule Matrix
 * Provides room scheduling, IBC / NFPA occupant load analysis, department zoning,
 * and circulation ratio calculations for architectural floor plans.
 */



const ZONING_CATEGORIES = Object.freeze({
  living: { id: 'living', name: 'Living & Social', color: '#3b82f6', tag: 'LIV' },
  sleeping: { id: 'sleeping', name: 'Sleeping & Private', color: '#8b5cf6', tag: 'SLP' },
  service: { id: 'service', name: 'Kitchen & Utility', color: '#f59e0b', tag: 'SRV' },
  sanitary: { id: 'sanitary', name: 'Sanitary & Wet', color: '#06b6d4', tag: 'SAN' },
  circulation: { id: 'circulation', name: 'Circulation & Stairs', color: '#64748b', tag: 'CIR' },
  commercial: { id: 'commercial', name: 'Office & Work', color: '#10b981', tag: 'OFF' },
  outdoor: { id: 'outdoor', name: 'Balcony & Terrace', color: '#84cc16', tag: 'OUT' }
});

/**
 * Standard IBC Chapter 10 / NFPA 101 occupant load factors in square meters per person.
 */
const OCCUPANCY_FACTORS = Object.freeze({
  residential: { factorM2: 18.6, label: 'Residential (18.6 m²/person)' },
  assembly_unconcentrated: { factorM2: 1.4, label: 'Assembly Tables/Chairs (1.4 m²/person)' },
  // IBC 1004.5 standing space: 5 net ft²/person ≈ 0.46 m²/person
  assembly_concentrated: { factorM2: 0.46, label: 'Assembly Standing (0.46 m²/person)' },
  business: { factorM2: 9.3, label: 'Business / Office (9.3 m²/person)' },
  educational: { factorM2: 1.9, label: 'Classrooms (1.9 m²/person)' },
  kitchen_commercial: { factorM2: 18.6, label: 'Kitchen / Service (18.6 m²/person)' },
  storage: { factorM2: 27.9, label: 'Storage / Mech (27.9 m²/person)' },
  circulation: { factorM2: 9.3, label: 'Circulation (9.3 m²/person)' }
});

/**
 * Infers an architectural department zoning category from a room's name.
 *
 * @param {string} roomName
 * @returns {string} Zoning category id
 */
function guessZoningFromRoomName(roomName = '') {
  const name = String(roomName || '').toLowerCase().trim();

  if (/bath|powder|toilet|wc|shower|restroom|en-suite|ensuite|lavatory|washroom/i.test(name)) {
    return 'sanitary';
  }
  if (/bed|master|guest|nursery|dorm|sleeping|\bsuite\b/i.test(name)) {
    return 'sleeping';
  }
  if (/kitchen|pantry|laundry|utility|storage|store|scullery|mech|boiler|hvac|garage/i.test(name)) {
    return 'service';
  }
  if (/hall|corridor|passage|foyer|entry|vestibule|stair|stairway|landing|lobby|circulation/i.test(name)) {
    return 'circulation';
  }
  if (/office|study|work|desk|studio|meeting|conference|library|boardroom/i.test(name)) {
    return 'commercial';
  }
  if (/balcony|terrace|porch|deck|veranda|patio|courtyard|roof/i.test(name)) {
    return 'outdoor';
  }

  return 'living';
}

/**
 * Infers IBC occupant load classification based on room name and zoning.
 *
 * @param {string} roomName
 * @param {string} zoning
 * @returns {string} Occupancy factor key in OCCUPANCY_FACTORS
 */
function guessOccupancyCategory(roomName = '', zoning = null) {
  const name = String(roomName || '').toLowerCase();
  const zone = zoning || guessZoningFromRoomName(roomName);

  if (name.includes('conference') || name.includes('auditorium') || name.includes('lounge') || name.includes('dining')) {
    return 'assembly_unconcentrated';
  }
  if (zone === 'commercial' || name.includes('office') || name.includes('work')) {
    return 'business';
  }
  if (zone === 'circulation' || /corridor|hall|passage|foyer|stair|lobby/i.test(name)) {
    return 'circulation';
  }
  if (name.includes('storage') || name.includes('mech') || name.includes('garage')) {
    return 'storage';
  }
  if (zone === 'service') {
    return 'kitchen_commercial';
  }

  return 'residential';
}

/**
 * Calculates a room's perimeter in meters.
 *
 * @param {Object} room
 * @returns {number}
 */
function calculateRoomPerimeter(room) {
  if (!room) return 0;
  return roomPerimeter(room);
}

/**
 * Computes the complete room area and occupancy schedule for a floor plan.
 *
 * @param {Object|Array} docOrEntities - Document object or entities list
 * @returns {Array<Object>} List of room schedule entries
 */
function calculateRoomSchedule(docOrEntities) {
  const entities = Array.isArray(docOrEntities)
    ? docOrEntities
    : (docOrEntities && Array.isArray(docOrEntities.entities) ? docOrEntities.entities : []);

  const rooms = entities.filter(e => e && e.kind === 'room');
  if (rooms.length === 0) return [];

  // Total floor net area for percentage calculation
  const totalNetArea = rooms.reduce((sum, r) => sum + roomArea(r), 0);

  return rooms.map((room, idx) => {
    const area = roomArea(room);
    const perimeter = calculateRoomPerimeter(room);
    const zoningKey = room.zoning || guessZoningFromRoomName(room.name);
    const zoning = ZONING_CATEGORIES[zoningKey] || ZONING_CATEGORIES.living;

    const occKey = room.occupancyCategory || guessOccupancyCategory(room.name, zoningKey);
    const occDef = OCCUPANCY_FACTORS[occKey] || OCCUPANCY_FACTORS.residential;
    const factorM2 = occDef.factorM2;

    // Occupant load: IBC rules state any fraction rounds up to next whole person, minimum 1 person
    const occupantCount = area > 0 ? Math.max(1, Math.ceil(area / factorM2)) : 0;
    const pct = totalNetArea > 0 ? (area / totalNetArea) * 100 : 0;

    return {
      id: room.id,
      number: room.number || room.roomNumber || String(101 + idx),
      name: room.name || `Room ${idx + 1}`,
      areaM2: Number(area.toFixed(2)),
      areaSqFt: Number((area * 10.7639).toFixed(1)),
      perimeterM: Number(perimeter.toFixed(2)),
      zoningKey,
      zoningName: zoning.name,
      zoningColor: zoning.color,
      zoningTag: zoning.tag,
      occupancyCategory: occKey,
      occupancyFactorM2: factorM2,
      occupantCount,
      percentOfFloor: Number(pct.toFixed(1))
    };
  });
}

/**
 * Calculates floor totals, gross internal area, circulation ratio, and total occupant load.
 *
 * @param {Object|Array} docOrEntities
 * @returns {Object} Floor summary totals
 */
function calculateFloorTotals(docOrEntities) {
  const schedule = calculateRoomSchedule(docOrEntities);
  const entities = Array.isArray(docOrEntities)
    ? docOrEntities
    : (docOrEntities && Array.isArray(docOrEntities.entities) ? docOrEntities.entities : []);

  // Sum RAW room areas (schedule entries carry display-rounded values; summing
  // those accumulates rounding error across large floors)
  const rooms = entities.filter(e => e && e.kind === 'room');
  const netInternalArea = rooms.reduce((sum, r) => sum + roomArea(r), 0);

  // Estimate wall footprint area if walls are present
  const walls = entities.filter(e => e && e.kind === 'wall' && typeof e.x1 === 'number');
  let wallArea = 0;
  for (const w of walls) {
    const len = Math.hypot(w.x2 - w.x1, w.y2 - w.y1);
    const thick = w.thickness || 0.2;
    wallArea += len * thick;
  }
  // GIA = Net Internal Area + Structural Wall Footprint
  const grossInternalArea = netInternalArea + wallArea;

  const totalOccupants = schedule.reduce((sum, r) => sum + r.occupantCount, 0);

  // Circulation analysis (raw areas, like netInternalArea)
  const circulationRooms = rooms.filter(r => {
    const key = r.zoning || guessZoningFromRoomName(r.name);
    return key === 'circulation';
  });
  const circulationArea = circulationRooms.reduce((sum, r) => sum + roomArea(r), 0);
  const circulationRatio = netInternalArea > 0 ? (circulationArea / netInternalArea) * 100 : 0;

  // Breakdown by zoning department
  const zoningBreakdown = {};
  for (const key of Object.keys(ZONING_CATEGORIES)) {
    const matching = rooms.filter(r => (r.zoning || guessZoningFromRoomName(r.name)) === key);
    const area = matching.reduce((sum, r) => sum + roomArea(r), 0);
    const pct = netInternalArea > 0 ? (area / netInternalArea) * 100 : 0;
    zoningBreakdown[key] = {
      name: ZONING_CATEGORIES[key].name,
      color: ZONING_CATEGORIES[key].color,
      areaM2: Number(area.toFixed(2)),
      percentage: Number(pct.toFixed(1)),
      count: matching.length
    };
  }

  // IBC egress corridor minimum width estimate (0.2 inches per occupant = 5.08 mm per occupant, min 900mm)
  const minEgressWidthMm = Math.max(900, Math.round(totalOccupants * 5.1));

  return {
    roomCount: schedule.length,
    netInternalArea: Number(netInternalArea.toFixed(2)),
    netInternalAreaM2: Number(netInternalArea.toFixed(2)),
    grossInternalArea: Number(grossInternalArea.toFixed(2)),
    grossInternalAreaM2: Number(grossInternalArea.toFixed(2)),
    circulationArea: Number(circulationArea.toFixed(2)),
    circulationAreaM2: Number(circulationArea.toFixed(2)),
    circulationRatioPercent: Number(circulationRatio.toFixed(1)),
    circulationRatio: Number(circulationRatio.toFixed(1)),
    totalOccupants,
    minEgressWidthMm,
    egressWidthMm: minEgressWidthMm,
    zoningBreakdown
  };
}

/**
 * Formats room schedule as a CSV string.
 *
 * @param {Array<Object>} schedule
 * @param {Object} totals
 * @returns {string} CSV text
 */
function formatScheduleCSV(schedule = [], totals = null) {
  const rows = [
    ['Room #', 'Room Name', 'Zoning', 'Area (m2)', 'Area (sq ft)', 'Perimeter (m)', 'Occupants', '% of Floor']
  ];

  for (const r of schedule) {
    rows.push([
      `"${r.number}"`,
      `"${r.name}"`,
      `"${r.zoningName}"`,
      r.areaM2.toFixed(2),
      r.areaSqFt.toFixed(1),
      r.perimeterM.toFixed(2),
      String(r.occupantCount),
      `${r.percentOfFloor.toFixed(1)}%`
    ]);
  }

  if (totals) {
    rows.push([]);
    rows.push(['TOTALS', '', '', totals.netInternalAreaM2.toFixed(2), '', '', String(totals.totalOccupants), '100.0%']);
    rows.push(['Gross Internal Area (GIA)', '', '', totals.grossInternalAreaM2.toFixed(2), '', '', '', '']);
    rows.push(['Circulation Ratio', '', '', `${totals.circulationRatioPercent}%`, '', '', '', '']);
  }

  return rows.map(row => row.join(',')).join('\n');
}

/**
 * Formats room schedule as a clean monospace ASCII table.
 *
 * @param {Array<Object>} schedule
 * @param {Object} totals
 * @returns {string} Monospace text
 */
function formatScheduleASCII(schedule = [], totals = null) {
  if (!schedule || schedule.length === 0) return 'No rooms found in floor plan.';

  const pad = (str, len) => String(str).padEnd(len, ' ');
  const padNum = (num, len) => String(num).padStart(len, ' ');

  const header = `${pad('ROOM #', 8)} | ${pad('NAME', 20)} | ${pad('ZONING', 18)} | ${padNum('AREA (m²)', 10)} | ${padNum('PERIM (m)', 10)} | ${padNum('OCC', 4)} | ${padNum('%', 6)}`;
  const divider = '-'.repeat(header.length);

  const lines = [header, divider];

  for (const r of schedule) {
    lines.push(
      `${pad(r.number, 8)} | ${pad(r.name, 20)} | ${pad(r.zoningName, 18)} | ${padNum(r.areaM2.toFixed(2), 10)} | ${padNum(r.perimeterM.toFixed(2), 10)} | ${padNum(r.occupantCount, 4)} | ${padNum(r.percentOfFloor.toFixed(1) + '%', 6)}`
    );
  }

  lines.push(divider);

  if (totals) {
    lines.push(
      `${pad('TOTAL NET', 8)} | ${pad(`${schedule.length} Rooms`, 20)} | ${pad('All Zones', 18)} | ${padNum(totals.netInternalAreaM2.toFixed(2), 10)} | ${padNum('-', 10)} | ${padNum(totals.totalOccupants, 4)} | ${padNum('100.0%', 6)}`
    );
    lines.push(`Gross Internal Area (GIA): ${totals.grossInternalAreaM2.toFixed(2)} m² · Circulation Ratio: ${totals.circulationRatioPercent}%`);
  }

  return lines.join('\n');
}


  // =========================================================================
  // MODULE: Massing3D
  // =========================================================================

/**
 * Architecture Helping Hand - Lightweight 3D Massing & Axonometric Engine
 * Pure mathematical 3D projection engine with ZERO runtime dependencies.
 * Converts 2D floor plans into 3D axonometric and isometric vector models with
 * wall extrusion, opening lintels/sills, structural columns, depth sorting,
 * and architectural directional shading.
 */




const CAMERA_PRESETS = Object.freeze({
  isometric_ne: { azimuth: 45, elevation: 35.264, label: 'Isometric NE (30°/30°)' },
  isometric_nw: { azimuth: 135, elevation: 35.264, label: 'Isometric NW' },
  isometric_se: { azimuth: -45, elevation: 35.264, label: 'Isometric SE' },
  isometric_sw: { azimuth: -135, elevation: 35.264, label: 'Isometric SW' },
  axonometric_top: { azimuth: 45, elevation: 60, label: 'Top Axo (60°)' },
  cavalier: { azimuth: 45, elevation: 45, label: 'Plan Oblique (45°)' },
  plan: { azimuth: 0, elevation: 89.9, label: 'Plan (Top)' },
  bottom: { azimuth: 0, elevation: -89.9, label: 'Bottom (Underside)' },
  front_south: { azimuth: 180, elevation: 0, label: 'Front (South)' },
  back_north: { azimuth: 0, elevation: 0, label: 'Back (North)' },
  left_west: { azimuth: -90, elevation: 0, label: 'Left (West)' },
  right_east: { azimuth: 90, elevation: 0, label: 'Right (East)' }
});

// Normalized directional sun light vector [Lx, Ly, Lz]
const SUN_VECTOR = (() => {
  const vx = 0.5, vy = -0.7, vz = 0.9;
  const len = Math.hypot(vx, vy, vz);
  return [vx / len, vy / len, vz / len];
})();

/**
 * Projects a 3D point (world meters) to screen coordinates (pixels) and depth.
 *
 * @param {{x: number, y: number, z: number}} p
 * @param {Object} camera
 * @param {number} [camera.azimuth=45] - Azimuth / yaw in degrees
 * @param {number} [camera.elevation=35.264] - Elevation / pitch in degrees
 * @param {number} [camera.zoom=40] - Pixels per meter
 * @param {number} [camera.panX=400]
 * @param {number} [camera.panY=300]
 * @returns {{x: number, y: number, depth: number}}
 */
function projectPoint3D(p, camera = {}) {
  const az = ((camera.azimuth ?? 45) * Math.PI) / 180;
  const el = ((camera.elevation ?? 35.264) * Math.PI) / 180;
  const zoom = camera.zoom || 40;
  const panX = camera.panX || 0;
  const panY = camera.panY || 0;

  // Yaw rotation around vertical Z axis
  const cosAz = Math.cos(az);
  const sinAz = Math.sin(az);
  const x1 = p.x * cosAz - p.y * sinAz;
  const y1 = p.x * sinAz + p.y * cosAz;
  const z1 = p.z || 0;

  // Pitch tilt by elevation
  const cosEl = Math.cos(el);
  const sinEl = Math.sin(el);

  // Camera-space depth BEFORE pitch (distance along the view axis used for
  // both painter sorting and the perspective divide).
  const camY = z1 * sinEl + y1 * cosEl;

  if (camera.perspective === true) {
    // One-point perspective: the eye sits `dist` meters behind the screen
    // plane along the view axis; scale each point by dist/(dist - camY).
    const dist = camera.perspectiveDistance || 30;
    const denom = Math.max(dist * 0.05, dist - camY); // never flip past the eye
    const scale = dist / denom;
    const screenX = panX + x1 * zoom * scale;
    const screenY = panY - (z1 * cosEl - y1 * sinEl) * zoom * scale;
    return { x: screenX, y: screenY, depth: -denom };
  }

  // Screen X = x1
  // Screen Y = in SVG Y is downwards, so positive world Z projects upwards (-Z)
  const screenX = panX + x1 * zoom;
  const screenY = panY - (z1 * cosEl - y1 * sinEl) * zoom;
  const depth = camY;

  return { x: screenX, y: screenY, depth };
}

/**
 * Computes the normal vector for a 3D polygon face and its lighting factor.
 */
function computeFaceLighting(vertices) {
  if (vertices.length < 3) return { normal: [0, 0, 1], factor: 1 };
  const p0 = vertices[0];
  const p1 = vertices[1];
  const p2 = vertices[2];

  // Vectors P1-P0 and P2-P0
  const v1 = [p1.x - p0.x, p1.y - p0.y, p1.z - p0.z];
  const v2 = [p2.x - p0.x, p2.y - p0.y, p2.z - p0.z];

  // Cross product
  const nx = v1[1] * v2[2] - v1[2] * v2[1];
  const ny = v1[2] * v2[0] - v1[0] * v2[2];
  const nz = v1[0] * v2[1] - v1[1] * v2[0];
  const len = Math.hypot(nx, ny, nz);

  if (len < 1e-6) return { normal: [0, 0, 1], factor: 0.8 };
  const normal = [nx / len, ny / len, nz / len];

  // Dot product with sun light vector
  const dot = normal[0] * SUN_VECTOR[0] + normal[1] * SUN_VECTOR[1] + normal[2] * SUN_VECTOR[2];
  // Ambient floor 0.35, max 1.0
  const factor = Math.max(0.35, Math.min(1.0, 0.45 + 0.55 * dot));
  return { normal, factor };
}

/**
 * Generates shaded RGB color from a base hex color and lighting factor.
 */
function applyLightingToColor(hexColor, factor) {
  let hex = hexColor.replace('#', '');
  if (hex.length === 3) hex = hex.split('').map(c => c + c).join('');
  const num = parseInt(hex, 16);
  if (isNaN(num)) return hexColor;

  const r = Math.round(Math.min(255, ((num >> 16) & 255) * factor));
  const g = Math.round(Math.min(255, ((num >> 8) & 255) * factor));
  const b = Math.round(Math.min(255, (num & 255) * factor));

  return `rgb(${r}, ${g}, ${b})`;
}

/**
 * Creates a 3D box / prism from a 2D base polygon extruded along Z.
 * All produced faces carry the source entity id (3D picking → plan entity).
 */
function extrudePolygon(basePoints, zBottom, zTop, baseColor = '#e2e8f0', strokeColor = '#334155', opacity = 1, type = 'wall', sourceId = null) {
  const faces = [];
  const n = basePoints.length;
  if (n < 3) return faces;

  const bottomVerts = basePoints.map(p => ({ x: p[0], y: p[1], z: zBottom }));
  const topVerts = basePoints.map(p => ({ x: p[0], y: p[1], z: zTop }));

  // 1. Top face
  const topLight = computeFaceLighting(topVerts);
  faces.push({
    vertices: topVerts,
    color: applyLightingToColor(baseColor, Math.min(1.0, topLight.factor + 0.15)),
    stroke: strokeColor,
    opacity,
    type,
    isTop: true
  });

  // 2. Bottom face
  const botVertsReversed = [...bottomVerts].reverse();
  const botLight = computeFaceLighting(botVertsReversed);
  faces.push({
    vertices: botVertsReversed,
    color: applyLightingToColor(baseColor, botLight.factor * 0.5),
    stroke: strokeColor,
    opacity,
    type,
    isBottom: true
  });

  // 3. Side faces
  for (let i = 0; i < n; i++) {
    const next = (i + 1) % n;
    const quad = [
      bottomVerts[i],
      bottomVerts[next],
      topVerts[next],
      topVerts[i]
    ];
    const sideLight = computeFaceLighting(quad);
    faces.push({
      vertices: quad,
      color: applyLightingToColor(baseColor, sideLight.factor),
      stroke: strokeColor,
      opacity,
      type,
      isSide: true
    });
  }

  if (sourceId != null) {
    for (const f of faces) f.entityId = sourceId;
  }
  return faces;
}

/**
 * Converts a 2D floor plan into 3D massing face polygons.
 *
 * @param {Array<Object>} entities - 2D plan entities
 * @param {Object} [options]
 * @param {number} [options.wallHeight=3.0] - Height of walls in meters
 * @param {number} [options.doorHeight=2.1] - Height of doors in meters
 * @param {number} [options.windowSill=0.9] - Height of window sill in meters
 * @param {number} [options.windowHeight=1.2] - Height of window glass in meters
 * @param {number} [options.slabThickness=0.2] - Slab thickness in meters
 * @returns {Array<Object>} Array of 3D face objects
 */
function buildMassing3DModel(entities = [], options = {}) {
  const zBase = typeof options.baseElevation === 'number' ? options.baseElevation : 0;
  const wallH = typeof options.wallHeight === 'number' && options.wallHeight > 0 ? options.wallHeight : 3.0;
  const doorH = Math.min(wallH - 0.2, options.doorHeight || 2.1);
  const winSill = options.windowSill || 0.9;
  const winH = options.windowHeight || 1.2;
  const winTop = Math.min(wallH - 0.2, winSill + winH);
  const slabThick = options.slabThickness || 0.2;

  const faces = [];
  const list = Array.isArray(entities) ? entities : [];

  // 1. Floor Slabs / Rooms
  const rooms = list.filter(e => e && e.kind === 'room');
  for (const r of rooms) {
    let poly = [];
    if (Array.isArray(r.boundary) && r.boundary.length >= 3) {
      poly = r.boundary.map(p => [p.x, p.y]);
    } else if (typeof r.x === 'number' && typeof r.width === 'number') {
      const w = r.width;
      const d = r.depth || 0;
      poly = [
        [r.x, r.y],
        [r.x + w, r.y],
        [r.x + w, r.y + d],
        [r.x, r.y + d]
      ];
    }
    if (poly.length >= 3) {
      const slabFaces = extrudePolygon(poly, zBase - slabThick, zBase, '#cbd5e1', '#94a3b8', 1, 'slab', r.id);
      faces.push(...slabFaces);
    }
  }

  // 2. Walls and Openings (Extruded with lintels & sills)
  const walls = list.filter(e => e && e.kind === 'wall' && typeof e.x1 === 'number');
  for (const w of walls) {
    const dx = w.x2 - w.x1;
    const dy = w.y2 - w.y1;
    const len = Math.hypot(dx, dy);
    if (len < 1e-4) continue;

    const thick = w.thickness || 0.2;
    const ux = dx / len;
    const uy = dy / len;
    const nx = -uy * (thick / 2);
    const ny = ux * (thick / 2);

    const openings = wallOpenings(w, list);

    if (openings.length === 0) {
      // Solid wall: full extrusion from zBase to zBase + wallH
      const basePts = [
        [w.x1 + nx, w.y1 + ny],
        [w.x2 + nx, w.y2 + ny],
        [w.x2 - nx, w.y2 - ny],
        [w.x1 - nx, w.y1 - ny]
      ];
      faces.push(...extrudePolygon(basePts, zBase, zBase + wallH, '#f1f5f9', '#475569', 1, 'wall', w.id));
    } else {
      // Segmented wall around openings
      let currentPos = 0;
      for (const op of openings) {
        const opStart = Math.max(0, Math.min(len, op.position || 0));
        const opEnd = Math.max(0, Math.min(len, opStart + (op.width || 0.9)));

        // Solid sub-segment before opening
        if (opStart > currentPos + 1e-4) {
          const pStart = { x: w.x1 + ux * currentPos, y: w.y1 + uy * currentPos };
          const pEnd = { x: w.x1 + ux * opStart, y: w.y1 + uy * opStart };
          const segPts = [
            [pStart.x + nx, pStart.y + ny],
            [pEnd.x + nx, pEnd.y + ny],
            [pEnd.x - nx, pEnd.y - ny],
            [pStart.x - nx, pStart.y - ny]
          ];
          faces.push(...extrudePolygon(segPts, zBase, zBase + wallH, '#f1f5f9', '#475569', 1, 'wall', w.id));
        }

        // Opening segment
        const oStart = { x: w.x1 + ux * opStart, y: w.y1 + uy * opStart };
        const oEnd = { x: w.x1 + ux * opEnd, y: w.y1 + uy * opEnd };
        const opPts = [
          [oStart.x + nx, oStart.y + ny],
          [oEnd.x + nx, oEnd.y + ny],
          [oEnd.x - nx, oEnd.y - ny],
          [oStart.x - nx, oStart.y - ny]
        ];

        if (op.kind === 'door') {
          // Lintel above door (from zBase + doorH to zBase + wallH)
          if (wallH > doorH) {
            faces.push(...extrudePolygon(opPts, zBase + doorH, zBase + wallH, '#f1f5f9', '#475569', 1, 'lintel', w.id));
          }
        } else if (op.kind === 'window') {
          // Parapet / sill below window (from zBase to zBase + winSill)
          if (winSill > 0) {
            faces.push(...extrudePolygon(opPts, zBase, zBase + winSill, '#f1f5f9', '#475569', 1, 'sill', w.id));
          }
          // Tinted window glass pane in middle (from zBase + winSill to zBase + winTop)
          faces.push(...extrudePolygon(opPts, zBase + winSill, zBase + winTop, '#38bdf8', '#0284c7', 0.55, 'glass', w.id));
          // Lintel above window (from zBase + winTop to zBase + wallH)
          if (wallH > winTop) {
            faces.push(...extrudePolygon(opPts, zBase + winTop, zBase + wallH, '#f1f5f9', '#475569', 1, 'lintel', w.id));
          }
        }

        currentPos = Math.max(currentPos, opEnd);
      }

      // Final solid segment after last opening
      if (currentPos < len - 1e-4) {
        const pStart = { x: w.x1 + ux * currentPos, y: w.y1 + uy * currentPos };
        const pEnd = { x: w.x2, y: w.y2 };
        const segPts = [
          [pStart.x + nx, pStart.y + ny],
          [pEnd.x + nx, pEnd.y + ny],
          [pEnd.x - nx, pEnd.y - ny],
          [pStart.x - nx, pStart.y - ny]
        ];
        faces.push(...extrudePolygon(segPts, zBase, zBase + wallH, '#f1f5f9', '#475569', 1, 'wall', w.id));
      }
    }
  }

  // 3. Structural Columns
  const columns = list.filter(e => e && e.kind === 'column');
  for (const c of columns) {
    const contour = columnContour(c);
    if (contour.length >= 3) {
      const colColor = c.material === 'steel' ? '#64748b' : '#94a3b8';
      faces.push(...extrudePolygon(contour, zBase, zBase + wallH, colColor, '#1e293b', 1, 'column', c.id));
    }
  }

  // 4. Stairs (3D Step Flight)
  const stairs = list.filter(e => e && e.kind === 'stair');
  for (const st of stairs) {
    // App stair entities use `risers` (count); `riserCount` was never set by
    // any factory, so every stair silently used the 10-riser default.
    const numRisers = st.risers || st.riserCount || 10;
    const rise = typeof st.rise === 'number' && st.rise > 0 ? st.rise : wallH;
    const riserH = rise / numRisers;
    const stW = st.width || 1.0;
    const stD = st.depth || st.run || 2.5;
    const treadD = stD / numRisers;

    for (let s = 0; s < numRisers; s++) {
      const stepBottom = zBase + s * riserH;
      const stepTop = zBase + (s + 1) * riserH;
      const stepY = st.y + s * treadD;
      const stepPts = [
        [st.x, stepY],
        [st.x + stW, stepY],
        [st.x + stW, stepY + treadD],
        [st.x, stepY + treadD]
      ];
      faces.push(...extrudePolygon(stepPts, stepBottom, stepTop, '#fbcfe8', '#db2777', 1, 'stair', st.id));
    }
  }

  return faces;
}

/**
 * Builds a multi-story building massing 3D model by stacking multiple 2D plan levels vertically.
 *
 * @param {Array<Object>} documents - Collection of 2D plan documents
 * @param {Object} [options]
 * @param {number} [options.storyHeight=3.0] - Default floor-to-floor height in meters
 * @returns {Array<Object>} Stacked 3D faces array with building metrics
 */
function buildMultiStoryMassing3DModel(documents = [], options = {}) {
  const docs = Array.isArray(documents)
    ? documents.filter(d => d && (d.type === '2d_plan' || d.type === '2d' || !d.type))
    : [];

  if (docs.length === 0) {
    const single = buildMassing3DModel([], options);
    single.storyCount = 0;
    single.totalHeight = 0;
    single.grossFloorArea = 0;
    single.grossVolume = 0;
    return single;
  }

  const defaultStoryH = typeof options.storyHeight === 'number' && options.storyHeight > 0 ? options.storyHeight : 3.0;
  const allFaces = [];
  let currentZ = 0;
  let totalGFA = 0;
  let totalVolume = 0;

  docs.forEach((doc, idx) => {
    const storyH = typeof doc.storyHeight === 'number' && doc.storyHeight > 0 ? doc.storyHeight : defaultStoryH;
    const storyFaces = buildMassing3DModel(doc.entities || [], {
      ...options,
      wallHeight: storyH,
      baseElevation: currentZ
    });

    for (const f of storyFaces) {
      f.storyIndex = idx;
      f.baseElevation = currentZ;
      f.storyName = doc.name || `Level ${idx + 1}`;
    }

    allFaces.push(...storyFaces);

    // Compute story room area
    const rooms = (doc.entities || []).filter(e => e && e.kind === 'room');
    let storyArea = 0;
    for (const r of rooms) {
      if (Array.isArray(r.boundary) && r.boundary.length >= 3) {
        let a = 0;
        for (let i = 0; i < r.boundary.length; i++) {
          const j = (i + 1) % r.boundary.length;
          a += r.boundary[i].x * r.boundary[j].y - r.boundary[j].x * r.boundary[i].y;
        }
        storyArea += Math.abs(a) / 2;
      } else if (typeof r.width === 'number' && typeof r.depth === 'number') {
        storyArea += r.width * r.depth;
      }
    }
    totalGFA += storyArea;
    // Volume must weight each story by its OWN height, not the building average
    totalVolume += storyArea * storyH;
    currentZ += storyH;
  });

  allFaces.faces = allFaces;
  allFaces.storyCount = docs.length;
  allFaces.totalHeight = Number(currentZ.toFixed(2));
  allFaces.grossFloorArea = Number(totalGFA.toFixed(2));
  allFaces.grossVolume = Number(totalVolume.toFixed(2));

  return allFaces;
}

/**
 * Projects 3D faces to 2D screen coordinates and depth-sorts them (Painter's algorithm).
 *
 * @param {Array<Object>} faces3D - 3D face objects
 * @param {Object} camera - Camera projection settings
 * @returns {Array<Object>} Sorted 2D projected faces
 */
function projectAndSortFaces(faces3D, camera) {
  const projected = [];

  for (const face of faces3D) {
    let sumDepth = 0;
    const pts2D = [];

    for (const v of face.vertices) {
      const p = projectPoint3D(v, camera);
      pts2D.push([p.x, p.y]);
      sumDepth += p.depth;
    }

    const avgDepth = pts2D.length > 0 ? sumDepth / pts2D.length : 0;

    // Under perspective the eye looks along −viewY, so nearer faces have a
    // LARGER negative denominator; normalize both modes to "bigger = nearer".
    const nearness = camera.perspective === true ? avgDepth : -avgDepth;

    projected.push({
      points: pts2D,
      depth: nearness,
      color: face.color,
      stroke: face.stroke,
      opacity: face.opacity || 1
    });
  }

  // Painter's algorithm: sort ascending by nearness (farthest rendered first, nearest on top)
  projected.sort((a, b) => a.depth - b.depth);

  return projected;
}

// ---------------------------------------------------------------------------
// 3D picking — the tested geometry3d raycaster against massing faces
// ---------------------------------------------------------------------------




/**
 * Picks the nearest massing face under a screen point.
 * Returns { entityId, type, t, point } | null. `entityId` maps back to the
 * 2D plan entity that produced the face (walls/rooms/columns/stairs).
 */
function pickMassingFace(faces3D, screenX, screenY, camera) {
  const ray = screenToWorldRay(screenX, screenY, camera);
  let best = null;
  for (const face of faces3D) {
    const hit = rayIntersectsFace(ray, face.vertices);
    if (hit && (!best || hit.t < best.t)) {
      best = { t: hit.t, point: hit.point, entityId: face.entityId || null, type: face.type };
    }
  }
  return best;
}

/**
 * Applies a horizontal section clip plane to the massing faces: everything
 * above zClip is removed (keep the normal-pointing side — the plane normal
 * points −z so points BELOW survive). Returns a new face array.
 */
function clipMassingFaces(faces3D, zClip) {
  if (!Number.isFinite(zClip)) return faces3D;
  // normal (0,0,-1) through (0,0,zClip): planeDistance = zClip − z ≥ 0 keeps z ≤ zClip
  const plane = createPlane({ x: 0, y: 0, z: zClip }, { x: 0, y: 0, z: -1 });
  const out = [];
  for (const face of faces3D) {
    const res = clipPolygonAgainstPlane(face.vertices, plane);
    const verts = res && Array.isArray(res.vertices) ? res.vertices : res;
    if (Array.isArray(verts) && verts.length >= 3) {
      out.push({ ...face, vertices: verts });
    }
  }
  return out;
}

/**
 * Generates standalone clean SVG markup for a 3D massing model.
 *
 * @param {Array<Object>} entities - 2D plan entities
 * @param {Object} [camera] - Camera options
 * @param {Object} [options] - Modeling & rendering options
 * @returns {string} Standalone SVG string
 */
function generateMassingSVG(entities = [], arg2 = {}, arg3 = {}) {
  let camera, options;
  if (arg2 && (typeof arg2.azimuth === 'number' || typeof arg2.elevation === 'number')) {
    camera = arg2;
    options = arg3 || {};
  } else {
    options = arg2 || {};
    camera = options.camera || {};
  }

  let faces3D;
  if (Array.isArray(entities) && entities.length > 0 && entities[0] && Array.isArray(entities[0].vertices)) {
    faces3D = entities;
  } else if (entities && Array.isArray(entities.faces)) {
    faces3D = entities.faces;
  } else if (options.multiStory && Array.isArray(options.documents)) {
    faces3D = buildMultiStoryMassing3DModel(options.documents, options);
  } else if (Array.isArray(entities) && entities.length > 0 && entities[0] && Array.isArray(entities[0].entities)) {
    faces3D = buildMultiStoryMassing3DModel(entities, options);
  } else {
    faces3D = buildMassing3DModel(entities, options);
  }

  const width = options.width || 800;
  const height = options.height || 600;

  const cam = {
    azimuth: camera.azimuth ?? 45,
    elevation: camera.elevation ?? 35.264,
    zoom: camera.zoom || (faces3D.storyCount > 1 ? Math.max(15, 32 / (faces3D.storyCount * 0.7)) : 32),
    panX: camera.panX || width / 2,
    panY: camera.panY || (faces3D.storyCount > 1 ? height / 2 + 80 : height / 2 + 50)
  };

  const sortedFaces = projectAndSortFaces(faces3D, cam);

  const polygonsMarkup = sortedFaces.map(f => {
    const pointsAttr = f.points.map(pt => `${pt[0].toFixed(1)},${pt[1].toFixed(1)}`).join(' ');
    const op = f.opacity < 1 ? ` opacity="${f.opacity}"` : '';
    return `    <polygon points="${pointsAttr}" fill="${f.color}" stroke="${f.stroke}" stroke-width="1.2" stroke-linejoin="round"${op} />`;
  }).join('\n');

  const title = options.title || camera.title || '';
  const titleMarkup = title
    ? `  <text id="massing-title" x="24" y="36" fill="#f8fafc" font-family="system-ui, sans-serif" font-size="14" font-weight="600">${title}</text>\n`
    : '';

  const metricsMarkup = (faces3D.storyCount && faces3D.storyCount > 1)
    ? `  <text id="massing-metrics" x="24" y="56" fill="#94a3b8" font-family="system-ui, sans-serif" font-size="11">${faces3D.storyCount} Stories · Total H: ${faces3D.totalHeight}m · GFA: ${faces3D.grossFloorArea}m²</text>\n`
    : '';

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} ${height}" width="${width}" height="${height}">
  <rect width="100%" height="100%" fill="#0f172a" />
${titleMarkup}${metricsMarkup}  <g class="massing-faces">
${polygonsMarkup}
  </g>
</svg>`;
}

// ---------------------------------------------------------------------------
// Phase 9: Rhino Computational NURBS Curve & Surface Evaluator
// ---------------------------------------------------------------------------

/**
 * Generates a standard clamped uniform knot vector for n+1 control points and degree p.
 * Length = n + p + 2.
 * @param {number} n - Last index of control points (count - 1)
 * @param {number} p - Degree of the curve
 * @returns {Array<number>} Knot vector clamped to [0, 1]
 */
function generateClampedKnotVector(n, p) {
  const m = n + p + 1;
  const knots = new Array(m + 1);
  for (let i = 0; i <= p; i++) knots[i] = 0;
  const interior = m - 2 * p;
  for (let i = 1; i < interior; i++) {
    knots[p + i] = i / interior;
  }
  for (let i = m - p; i <= m; i++) knots[i] = 1;
  return knots;
}

/**
 * Evaluates a 2D or 3D NURBS / B-Spline curve at parameter t in [0, 1] using Cox-de Boor's algorithm.
 *
 * @param {Array<Object>} controlPoints - Array of point objects ({x, y} or {x, y, z})
 * @param {number} [degree=3] - Degree of the spline (default cubic)
 * @param {number} t - Parameter in [0, 1]
 * @param {Array<number>} [customKnots=null] - Optional custom knot vector
 * @returns {Object} Evaluated point {x, y, z}
 */
function evaluateNurbsCurve(controlPoints = [], degree = 3, t = 0, customKnots = null) {
  if (!Array.isArray(controlPoints) || controlPoints.length === 0) {
    return { x: 0, y: 0, z: 0 };
  }
  if (controlPoints.length === 1) {
    const pt = controlPoints[0];
    return { x: pt.x || 0, y: pt.y || 0, z: pt.z || 0 };
  }

  const p = Math.min(degree, controlPoints.length - 1);
  const n = controlPoints.length - 1;
  const knots = Array.isArray(customKnots) && customKnots.length === (n + p + 2)
    ? customKnots
    : generateClampedKnotVector(n, p);

  // Clamp t to [0, 1]
  const clampedT = Math.max(0, Math.min(1, t));

  // Find knot span k such that knots[k] <= clampedT < knots[k+1]
  let k = n;
  for (let i = p; i <= n; i++) {
    if (clampedT >= knots[i] && clampedT < knots[i + 1]) {
      k = i;
      break;
    }
  }
  if (clampedT >= 1) k = n;

  // Initialize de Boor working array d[0..p]
  const d = [];
  for (let j = 0; j <= p; j++) {
    const cp = controlPoints[k - p + j] || controlPoints[n];
    d[j] = {
      x: cp.x || 0,
      y: cp.y || 0,
      z: cp.z || 0
    };
  }

  // de Boor recursion
  for (let r = 1; r <= p; r++) {
    for (let j = p; j >= r; j--) {
      const idx = k - p + j;
      const denom = knots[idx + p - r + 1] - knots[idx];
      const alpha = denom > 1e-9 ? (clampedT - knots[idx]) / denom : 0;
      d[j] = {
        x: (1 - alpha) * d[j - 1].x + alpha * d[j].x,
        y: (1 - alpha) * d[j - 1].y + alpha * d[j].y,
        z: (1 - alpha) * d[j - 1].z + alpha * d[j].z
      };
    }
  }

  return {
    x: Number(d[p].x.toFixed(4)),
    y: Number(d[p].y.toFixed(4)),
    z: Number(d[p].z.toFixed(4))
  };
}

/**
 * Evaluates a tensor-product NURBS / B-Spline surface at parameters (u, v) in [0, 1] x [0, 1].
 *
 * @param {Array<Array<Object>>} controlGrid - 2D grid of control points [row][col]
 * @param {number} [degreeU=3] - Degree along U axis
 * @param {number} [degreeV=3] - Degree along V axis
 * @param {number} u - Parameter along U [0, 1]
 * @param {number} v - Parameter along V [0, 1]
 * @returns {Object} Evaluated surface point {x, y, z}
 */
function evaluateNurbsSurface(controlGrid = [], degreeU = 3, degreeV = 3, u = 0, v = 0) {
  if (!Array.isArray(controlGrid) || controlGrid.length === 0 || !Array.isArray(controlGrid[0])) {
    return { x: 0, y: 0, z: 0 };
  }

  // Evaluate each row along U to get intermediate column control points
  const intermediateCol = controlGrid.map(row => evaluateNurbsCurve(row, degreeU, u));

  // Evaluate column along V
  return evaluateNurbsCurve(intermediateCol, degreeV, v);
}

/**
 * Tessellates a NURBS surface into 3D quad faces ready for 3D projection & rendering.
 *
 * @param {Array<Array<Object>>} controlGrid - 2D grid of control points
 * @param {Object} [options]
 * @param {number} [options.samplesU=8] - Subdivision steps in U
 * @param {number} [options.samplesV=8] - Subdivision steps in V
 * @param {string} [options.color='#38bdf8'] - Face fill color
 * @param {string} [options.stroke='#0284c7'] - Edge wireframe color
 * @returns {Array<Object>} 3D quad faces array
 */
function tessellateNurbsSurface(controlGrid = [], options = {}) {
  if (!Array.isArray(controlGrid) || controlGrid.length === 0 || !Array.isArray(controlGrid[0])) {
    return [];
  }

  const su = options.samplesU || 8;
  const sv = options.samplesV || 8;
  const color = options.color || '#38bdf8';
  const stroke = options.stroke || '#0284c7';
  const opacity = options.opacity || 0.85;

  const grid = [];
  for (let i = 0; i <= su; i++) {
    const row = [];
    const u = i / su;
    for (let j = 0; j <= sv; j++) {
      const v = j / sv;
      row.push(evaluateNurbsSurface(controlGrid, options.degreeU || 3, options.degreeV || 3, u, v));
    }
    grid.push(row);
  }

  const faces = [];
  for (let i = 0; i < su; i++) {
    for (let j = 0; j < sv; j++) {
      const p0 = grid[i][j];
      const p1 = grid[i + 1][j];
      const p2 = grid[i + 1][j + 1];
      const p3 = grid[i][j + 1];

      faces.push({
        vertices: [
          { x: p0.x, y: p0.y, z: p0.z },
          { x: p1.x, y: p1.y, z: p1.z },
          { x: p2.x, y: p2.y, z: p2.z },
          { x: p3.x, y: p3.y, z: p3.z }
        ],
        color,
        stroke,
        opacity,
        type: 'nurbs_surface'
      });
    }
  }

  return faces;
}



  // =========================================================================
  // MODULE: SectionsElevations
  // =========================================================================

/**
 * Architecture Helping Hand - Orthographic Sections & Elevations Engine
 * Zero-dependency architectural projection and section-slicing engine.
 * Generates orthographic building elevations (North, South, East, West) and
 * cross-sectional building cuts with architectural pochè, level datums,
 * ground grade linework, fenestration details, and vertical dimension strings.
 */







const ELEVATION_DIRECTIONS = Object.freeze({
  south: { id: 'south', label: 'South Elevation (Front)', axis: 'x', sign: 1, viewDir: [0, 1] },
  north: { id: 'north', label: 'North Elevation (Rear)', axis: 'x', sign: -1, viewDir: [0, -1] },
  east: { id: 'east', label: 'East Elevation (Right)', axis: 'y', sign: 1, viewDir: [-1, 0] },
  west: { id: 'west', label: 'West Elevation (Left)', axis: 'y', sign: -1, viewDir: [1, 0] }
});

/**
 * Helper to normalize input into an array of story objects with elevations.
 */
function normalizeStories(entitiesOrDocs, defaultStoryHeight = 3.0) {
  if (!entitiesOrDocs) return [];

  // Case 1: Array of document tabs
  if (Array.isArray(entitiesOrDocs) && entitiesOrDocs.some(d => d && (d.type === '2d_plan' || d.type === '2d' || Array.isArray(d.entities)))) {
    const planDocs = entitiesOrDocs.filter(d => d && (d.type === '2d_plan' || d.type === '2d' || (!d.type && Array.isArray(d.entities))));
    if (planDocs.length > 0) {
      let currentZ = 0;
      return planDocs.map((doc, idx) => {
        const h = typeof doc.storyHeight === 'number' && doc.storyHeight > 0 ? doc.storyHeight : defaultStoryHeight;
        const story = {
          name: doc.name || `Level ${idx + 1}`,
          index: idx,
          baseElevation: currentZ,
          height: h,
          topElevation: currentZ + h,
          entities: Array.isArray(doc.entities) ? doc.entities : []
        };
        currentZ += h;
        return story;
      });
    }
  }

  // Case 2: Direct array of entities (single story)
  const list = Array.isArray(entitiesOrDocs)
    ? entitiesOrDocs
    : (entitiesOrDocs && Array.isArray(entitiesOrDocs.entities) ? entitiesOrDocs.entities : []);

  return [{
    name: 'Ground Floor',
    index: 0,
    baseElevation: 0,
    height: defaultStoryHeight,
    topElevation: defaultStoryHeight,
    entities: list
  }];
}

/**
 * Calculates project bounding limits in world meters across all stories.
 */
function computeBuildingLimits(stories) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  let hasEntities = false;

  for (const s of stories) {
    for (const e of s.entities) {
      if (!e) continue;
      if (e.kind === 'wall' && typeof e.x1 === 'number') {
        minX = Math.min(minX, e.x1, e.x2);
        minY = Math.min(minY, e.y1, e.y2);
        maxX = Math.max(maxX, e.x1, e.x2);
        maxY = Math.max(maxY, e.y1, e.y2);
        hasEntities = true;
      } else if (typeof e.x === 'number' && typeof e.y === 'number') {
        const w = e.width || (e.radius ? e.radius * 2 : 1);
        const d = e.depth || (e.radius ? e.radius * 2 : 1);
        minX = Math.min(minX, e.x);
        minY = Math.min(minY, e.y);
        maxX = Math.max(maxX, e.x + w);
        maxY = Math.max(maxY, e.y + d);
        hasEntities = true;
      }
    }
  }

  if (!hasEntities) {
    return { minX: 0, minY: 0, maxX: 12, maxY: 10, width: 12, depth: 10 };
  }

  return {
    minX, minY, maxX, maxY,
    width: Math.max(1, maxX - minX),
    depth: Math.max(1, maxY - minY)
  };
}

/**
 * Maps a 2D world coordinate (x, y) to a horizontal elevation axis U
 * according to the cardinal elevation direction.
 */
function mapWorldToElevationU(x, y, dirKey, limits) {
  switch (dirKey) {
    case 'north':
      // Looking from North towards South (-Y). Invert X so Left is East, Right is West.
      return limits.maxX - x;
    case 'east':
      // Looking from East towards West (-X). Horizontal axis is Y.
      return y - limits.minY;
    case 'west':
      // Looking from West towards East (+X). Invert Y so Left is North, Right is South.
      return limits.maxY - y;
    case 'south':
    default:
      // Looking from South towards North (+Y). Horizontal axis is X.
      return x - limits.minX;
  }
}

/**
 * Generates an orthographic Building Elevation model.
 *
 * @param {Array<Object>} entitiesOrDocs - Floor plan entities or array of document tabs
 * @param {'south'|'north'|'east'|'west'} [direction='south'] - Elevation direction
 * @param {Object} [options]
 * @param {number} [options.storyHeight=3.0]
 * @returns {Object} Elevation projection model
 */
function generateBuildingElevation(entitiesOrDocs, direction = 'south', options = {}) {
  const dirKey = (direction in ELEVATION_DIRECTIONS) ? direction : 'south';
  const defaultStoryH = typeof options.storyHeight === 'number' && options.storyHeight > 0 ? options.storyHeight : 3.0;
  const stories = normalizeStories(entitiesOrDocs, defaultStoryH);
  const limits = computeBuildingLimits(stories);

  // Total building height
  const totalHeight = stories.length > 0 ? stories[stories.length - 1].topElevation : defaultStoryH;

  // Horizontal span along projection axis
  let elevationSpan = (dirKey === 'south' || dirKey === 'north') ? limits.width : limits.depth;
  elevationSpan = Math.max(2, elevationSpan);

  const projectedWalls = [];
  const projectedOpenings = [];
  const projectedColumns = [];
  const projectedStairs = [];
  const datums = [];

  // 1. Build Level Datums
  stories.forEach((s) => {
    datums.push({
      name: s.name.toUpperCase(),
      elevation: s.baseElevation,
      label: `EL +${s.baseElevation.toFixed(2)}m`,
      u1: -1.0,
      u2: elevationSpan + 2.0
    });
  });
  // Top Roof Datum
  datums.push({
    name: 'ROOF',
    elevation: totalHeight,
    label: `EL +${totalHeight.toFixed(2)}m`,
    u1: -1.0,
    u2: elevationSpan + 2.0
  });

  // 2. Process each story
  stories.forEach((story) => {
    const baseZ = story.baseElevation;
    const wallH = story.height;
    const entities = story.entities || [];

    const walls = entities.filter(e => e && e.kind === 'wall');
    const columns = entities.filter(e => e && e.kind === 'column');
    const stairs = entities.filter(e => e && e.kind === 'stair');

    for (const w of walls) {
      if (typeof w.x1 !== 'number' || typeof w.x2 !== 'number') continue;
      // Project wall endpoints
      const u1 = mapWorldToElevationU(w.x1, w.y1, dirKey, limits);
      const u2 = mapWorldToElevationU(w.x2, w.y2, dirKey, limits);
      const minU = Math.min(u1, u2);
      const maxU = Math.max(u1, u2);
      const wSpan = Math.max(0.1, maxU - minU);

      projectedWalls.push({
        id: w.id,
        u: minU,
        z: baseZ,
        width: wSpan,
        height: wallH,
        thickness: w.thickness || 0.20,
        storyIndex: story.index
      });

      // Project openings on this wall
      const openings = wallOpenings(w, entities);
      for (const op of openings) {
        const p = typeof op.position === 'number' ? op.position : (typeof op.offset === 'number' ? op.offset : 0);
        const wLen = wallLength(w) || 1;
        const opFrac = Math.min(1, Math.max(0, p / wLen));
        const opWidthFrac = Math.min(1, (op.width || 0.9) / wLen);

        const opU1 = minU + opFrac * wSpan;
        const opU2 = minU + (opFrac + opWidthFrac) * wSpan;
        const opMinU = Math.min(opU1, opU2);
        const opW = Math.max(0.2, Math.abs(opU2 - opU1));

        if (op.kind === 'door') {
          const doorH = op.height || 2.1;
          projectedOpenings.push({
            id: op.id,
            kind: 'door',
            wallId: w.id,
            u: opMinU,
            z: baseZ,
            width: opW,
            height: doorH,
            storyIndex: story.index
          });
        } else if (op.kind === 'window') {
          const sillH = op.sill || 0.9;
          const winH = op.height || 1.2;
          projectedOpenings.push({
            id: op.id,
            kind: 'window',
            wallId: w.id,
            u: opMinU,
            z: baseZ + sillH,
            width: opW,
            height: winH,
            storyIndex: story.index
          });
        }
      }
    }

    // Project columns
    for (const c of columns) {
      if (typeof c.x !== 'number' || typeof c.y !== 'number') continue;
      const colU = mapWorldToElevationU(c.x, c.y, dirKey, limits);
      const colW = c.width || (c.radius ? c.radius * 2 : 0.4);
      projectedColumns.push({
        id: c.id,
        name: c.name || 'Col',
        u: colU - colW / 2,
        z: baseZ,
        width: colW,
        height: wallH,
        storyIndex: story.index
      });
    }

    // Project stairs
    for (const st of stairs) {
      if (typeof st.x !== 'number' || typeof st.y !== 'number') continue;
      const stU = mapWorldToElevationU(st.x, st.y, dirKey, limits);
      const stW = st.width || 1.0;
      const stD = st.depth || st.run || 2.8;
      const numRisers = st.riserCount || st.risers || 16;
      const stRise = st.rise || st.totalRise || wallH;
      const riserH = stRise / numRisers;
      const spanU = (dirKey === 'south' || dirKey === 'north') ? stW : stD;

      const steps = [];
      for (let s = 0; s < numRisers; s++) {
        steps.push({
          u1: stU + (s / numRisers) * spanU,
          u2: stU + ((s + 1) / numRisers) * spanU,
          z1: baseZ + s * riserH,
          z2: baseZ + (s + 1) * riserH
        });
      }

      projectedStairs.push({
        id: st.id,
        name: st.name || 'Stair',
        u: stU,
        z: baseZ,
        width: spanU,
        height: stRise,
        numRisers,
        steps,
        handrail: {
          u1: stU,
          z1: baseZ + 0.90,
          u2: stU + spanU,
          z2: baseZ + stRise + 0.90
        },
        storyIndex: story.index
      });
    }
  });

  // 3. Ground line & Earth Grade
  const groundLine = {
    u1: -2.0,
    u2: elevationSpan + 2.0,
    z: 0.0,
    earthDepth: 1.2
  };

  // 4. Vertical Dimension Strings
  const dimensions = [];
  stories.forEach((s) => {
    dimensions.push({
      label: `${s.height.toFixed(2)}m`,
      z1: s.baseElevation,
      z2: s.topElevation,
      u: elevationSpan + 0.8
    });
  });
  if (stories.length > 1) {
    dimensions.push({
      label: `TOTAL ${totalHeight.toFixed(2)}m`,
      z1: 0,
      z2: totalHeight,
      u: elevationSpan + 1.8
    });
  }

  return {
    direction: dirKey,
    title: ELEVATION_DIRECTIONS[dirKey].label,
    limits,
    span: elevationSpan,
    totalHeight,
    stories,
    walls: projectedWalls,
    openings: projectedOpenings,
    columns: projectedColumns,
    stairs: projectedStairs,
    datums,
    dimensions,
    groundLine
  };
}

/**
 * Generates an architectural Building Section model along a cut plane line.
 *
 * @param {Array<Object>} entitiesOrDocs - Floor plan entities or array of document tabs
 * @param {Object} [sectionCut] - Section cut parameters or 'section_cut' entity
 * @param {Object} [options]
 * @returns {Object} Section cut model with cut pochè, slabs, background projection, and datums
 */
function generateBuildingSection(entitiesOrDocs, sectionCut = {}, options = {}) {
  const defaultStoryH = typeof options.storyHeight === 'number' && options.storyHeight > 0 ? options.storyHeight : 3.0;
  const slabThickness = typeof options.slabThickness === 'number' && options.slabThickness > 0 ? options.slabThickness : 0.25;
  const stories = normalizeStories(entitiesOrDocs, defaultStoryH);
  const limits = computeBuildingLimits(stories);
  const totalHeight = stories.length > 0 ? stories[stories.length - 1].topElevation : defaultStoryH;

  // Determine section cut line in world coordinates
  let p1 = { x: limits.minX - 1.0, y: limits.minY + limits.depth / 2 };
  let p2 = { x: limits.maxX + 1.0, y: limits.minY + limits.depth / 2 };
  let sectionLabel = 'A';

  if (sectionCut && sectionCut.p1 && sectionCut.p2) {
    p1 = { x: sectionCut.p1.x, y: sectionCut.p1.y };
    p2 = { x: sectionCut.p2.x, y: sectionCut.p2.y };
    if (sectionCut.label) sectionLabel = sectionCut.label;
  } else if (typeof sectionCut.coord === 'number') {
    p1 = { x: limits.minX - 1.0, y: sectionCut.coord };
    p2 = { x: limits.maxX + 1.0, y: sectionCut.coord };
  }

  const cutVector = { x: p2.x - p1.x, y: p2.y - p1.y };
  const cutLength = Math.hypot(cutVector.x, cutVector.y) || 1;
  const cutUnit = { x: cutVector.x / cutLength, y: cutVector.y / cutLength };

  // Function to project world point along cut line axis U
  function worldToCutU(x, y) {
    return (x - p1.x) * cutUnit.x + (y - p1.y) * cutUnit.y;
  }

  const cutWalls = [];
  const cutSlabs = [];
  const cutOpenings = [];
  const backgroundWalls = [];
  const cutStairs = [];
  const backgroundStairs = [];
  const datums = [];

  // 1. Build Level Datums
  stories.forEach((s) => {
    datums.push({
      name: s.name.toUpperCase(),
      elevation: s.baseElevation,
      label: `EL +${s.baseElevation.toFixed(2)}m`,
      u1: -1.0,
      u2: cutLength + 1.0
    });
  });
  datums.push({
    name: 'ROOF SLAB',
    elevation: totalHeight,
    label: `EL +${totalHeight.toFixed(2)}m`,
    u1: -1.0,
    u2: cutLength + 1.0
  });

  // 2. Intersect walls on each story with section cut line
  stories.forEach((story) => {
    const baseZ = story.baseElevation;
    const wallH = story.height;
    const entities = story.entities || [];
    const walls = entities.filter(e => e && e.kind === 'wall');

    // Structural floor slab for this story spanning cut extent
    cutSlabs.push({
      storyIndex: story.index,
      name: `${story.name} Slab`,
      u1: 0.5,
      u2: cutLength - 0.5,
      z1: baseZ - slabThickness,
      z2: baseZ,
      thickness: slabThickness
    });

    for (const w of walls) {
      if (typeof w.x1 !== 'number' || typeof w.x2 !== 'number') continue;
      const wallSeg = { p1: { x: w.x1, y: w.y1 }, p2: { x: w.x2, y: w.y2 } };

      const hit = intersectSegments(p1, p2, wallSeg.p1, wallSeg.p2);
      const wThick = w.thickness || 0.20;

      if (hit) {
        // Cut wall slice
        const hitU = worldToCutU(hit.x, hit.y);
        const wLen = wallLength(w) || 1;
        const openings = wallOpenings(w, entities);

        // Check if cut passed directly through an opening
        const hitOffset = Math.hypot(hit.x - w.x1, hit.y - w.y1);
        const hitOpening = openings.find(op => {
          const p = typeof op.position === 'number' ? op.position : (typeof op.offset === 'number' ? op.offset : 0);
          return hitOffset >= p && hitOffset <= (p + (op.width || 0.9));
        });

        if (hitOpening) {
          if (hitOpening.kind === 'door') {
            const doorH = hitOpening.height || 2.1;
            // Cut door: open from floor to door height, cut lintel header above
            cutOpenings.push({
              id: hitOpening.id,
              kind: 'door',
              u: hitU - wThick / 2,
              z: baseZ,
              thickness: wThick,
              height: doorH,
              storyIndex: story.index
            });
            cutWalls.push({
              id: w.id,
              isHeader: true,
              u: hitU - wThick / 2,
              z: baseZ + doorH,
              thickness: wThick,
              height: wallH - doorH,
              storyIndex: story.index
            });
          } else if (hitOpening.kind === 'window') {
            const sillH = hitOpening.sill || 0.9;
            const winH = hitOpening.height || 1.2;
            // Cut window: cut sill below, opening/glazing in middle, cut lintel above
            cutWalls.push({
              id: w.id,
              isSill: true,
              u: hitU - wThick / 2,
              z: baseZ,
              thickness: wThick,
              height: sillH,
              storyIndex: story.index
            });
            cutOpenings.push({
              id: hitOpening.id,
              kind: 'window',
              u: hitU - wThick / 2,
              z: baseZ + sillH,
              thickness: wThick,
              height: winH,
              storyIndex: story.index
            });
            cutWalls.push({
              id: w.id,
              isHeader: true,
              u: hitU - wThick / 2,
              z: baseZ + sillH + winH,
              thickness: wThick,
              height: wallH - (sillH + winH),
              storyIndex: story.index
            });
          }
        } else {
          // Solid wall cut slice (POCHÈ)
          cutWalls.push({
            id: w.id,
            isSolid: true,
            u: hitU - wThick / 2,
            z: baseZ,
            thickness: wThick,
            height: wallH,
            storyIndex: story.index
          });
        }
      } else {
        // Wall is in projection (background elevation)
        const u1 = worldToCutU(w.x1, w.y1);
        const u2 = worldToCutU(w.x2, w.y2);
        const minU = Math.min(u1, u2);
        const maxU = Math.max(u1, u2);
        if (maxU >= 0 && minU <= cutLength) {
          backgroundWalls.push({
            id: w.id,
            u: Math.max(0, minU),
            z: baseZ,
            width: Math.min(cutLength, maxU) - Math.max(0, minU),
            height: wallH,
            storyIndex: story.index
          });
        }
      }
    }

    // Process stairs on this story
    const stairs = entities.filter(e => e && e.kind === 'stair');
    for (const st of stairs) {
      if (typeof st.x !== 'number' || typeof st.y !== 'number') continue;
      const stW = st.width || 1.0;
      const stD = st.depth || st.run || 2.8;
      const stRise = st.rise || st.totalRise || wallH;
      const numRisers = st.riserCount || st.risers || 16;
      const riserH = stRise / numRisers;

      const stMinX = st.x;
      const stMaxX = st.x + stW;
      const stMinY = st.y;
      const stMaxY = st.y + stD;

      // Check intersection with cut line
      const leftEdge = { p1: { x: stMinX, y: stMinY }, p2: { x: stMinX, y: stMaxY } };
      const rightEdge = { p1: { x: stMaxX, y: stMinY }, p2: { x: stMaxX, y: stMaxY } };
      const bottomEdge = { p1: { x: stMinX, y: stMinY }, p2: { x: stMaxX, y: stMinY } };
      const topEdge = { p1: { x: stMinX, y: stMaxY }, p2: { x: stMaxX, y: stMaxY } };

      const hitL = intersectSegments(p1, p2, leftEdge.p1, leftEdge.p2);
      const hitR = intersectSegments(p1, p2, rightEdge.p1, rightEdge.p2);
      const hitB = intersectSegments(p1, p2, bottomEdge.p1, bottomEdge.p2);
      const hitT = intersectSegments(p1, p2, topEdge.p1, topEdge.p2);
      const isInside = (
        (p1.x >= stMinX && p1.x <= stMaxX && p1.y >= stMinY && p1.y <= stMaxY) ||
        (p2.x >= stMinX && p2.x <= stMaxX && p2.y >= stMinY && p2.y <= stMaxY)
      );
      const isCut = Boolean(hitL || hitR || hitB || hitT || isInside);

      const u1 = worldToCutU(stMinX, stMinY);
      const u2 = worldToCutU(stMaxX, stMaxY);
      const minU = Math.min(u1, u2);
      const maxU = Math.max(u1, u2);
      const spanU = Math.max(1.0, maxU - minU);

      const steps = [];
      for (let s = 0; s < numRisers; s++) {
        const stepU1 = minU + (s / numRisers) * spanU;
        const stepU2 = minU + ((s + 1) / numRisers) * spanU;
        const stepZ = baseZ + s * riserH;
        const nextZ = baseZ + (s + 1) * riserH;
        steps.push({ u1: stepU1, u2: stepU2, z: stepZ, zNext: nextZ, stepIndex: s + 1 });
      }

      const handrail = {
        u1: minU,
        z1: baseZ + riserH + 0.90,
        u2: maxU,
        z2: baseZ + stRise + 0.90,
        posts: [
          { u: minU, z1: baseZ + riserH, z2: baseZ + riserH + 0.90 },
          { u: minU + spanU * 0.5, z1: baseZ + stRise * 0.5, z2: baseZ + stRise * 0.5 + 0.90 },
          { u: maxU, z1: baseZ + stRise, z2: baseZ + stRise + 0.90 }
        ]
      };

      const stairItem = {
        id: st.id,
        name: st.name || 'Stair',
        isCut,
        minU,
        maxU,
        spanU,
        baseZ,
        rise: stRise,
        numRisers,
        riserH,
        steps,
        waistThickness: 0.15,
        handrail,
        storyIndex: story.index
      };

      if (isCut) {
        cutStairs.push(stairItem);
      } else if (maxU >= 0 && minU <= cutLength) {
        backgroundStairs.push(stairItem);
      }
    }
  });

  // Top roof slab cap
  cutSlabs.push({
    storyIndex: stories.length,
    name: 'Roof Slab Cap',
    u1: 0.5,
    u2: cutLength - 0.5,
    z1: totalHeight,
    z2: totalHeight + slabThickness,
    thickness: slabThickness
  });

  // 3. Ground grade linework
  const groundLine = {
    u1: -1.5,
    u2: cutLength + 1.5,
    z: 0.0,
    earthDepth: 1.2
  };

  // 4. Vertical Dimensions (clear height, slab, total)
  const dimensions = [];
  stories.forEach((s) => {
    dimensions.push({
      label: `CLR ${(s.height - slabThickness).toFixed(2)}m`,
      z1: s.baseElevation,
      z2: s.baseElevation + s.height - slabThickness,
      u: cutLength + 0.6
    });
  });
  dimensions.push({
    label: `TOTAL ${totalHeight.toFixed(2)}m`,
    z1: 0,
    z2: totalHeight,
    u: cutLength + 1.4
  });

  return {
    sectionLabel,
    title: `Section ${sectionLabel}-${sectionLabel}`,
    p1,
    p2,
    cutLength,
    totalHeight,
    stories,
    cutWalls,
    cutSlabs,
    cutOpenings,
    backgroundWalls,
    cutStairs,
    backgroundStairs,
    datums,
    dimensions,
    groundLine
  };
}

/**
 * Generates standalone clean SVG markup for a Building Elevation.
 */
function generateElevationSVG(elevationModelOrEntities, direction = 'south', options = {}) {
  const model = (elevationModelOrEntities && elevationModelOrEntities.walls && elevationModelOrEntities.datums)
    ? elevationModelOrEntities
    : generateBuildingElevation(elevationModelOrEntities, direction, options);

  const scale = options.scale || 40; // pixels per meter
  const marginX = 80;
  const marginY = 60;

  const contentW = (model.span + 4.0) * scale;
  const contentH = (model.totalHeight + 3.0) * scale;
  const svgW = contentW + marginX * 2;
  const svgH = contentH + marginY * 2;

  // Coordinate mapper: world meters (u, z) to screen pixels (sx, sy)
  function toSvg(u, z) {
    const sx = marginX + (u + 2.0) * scale;
    const sy = svgH - marginY - (z + 1.2) * scale;
    return { sx, sy };
  }

  const parts = [];
  parts.push(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${svgW.toFixed(0)} ${svgH.toFixed(0)}" width="100%" height="100%" style="background:#0f172a; font-family:'Segoe UI',system-ui,sans-serif;">`);

  // Defs & Patterns (Earth hatching)
  parts.push(`
    <defs>
      <pattern id="earth-hatch" width="12" height="12" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
        <line x1="0" y1="0" x2="0" y2="12" stroke="#475569" stroke-width="1.2" opacity="0.6"/>
      </pattern>
    </defs>
  `);

  // 1. Earth / Grade Hatch
  const gP1 = toSvg(model.groundLine.u1, 0);
  const gP2 = toSvg(model.groundLine.u2, 0);
  const earthP = toSvg(model.groundLine.u1, -model.groundLine.earthDepth);
  const earthH = Math.abs(earthP.sy - gP1.sy);
  parts.push(`<rect x="${gP1.sx.toFixed(1)}" y="${gP1.sy.toFixed(1)}" width="${(gP2.sx - gP1.sx).toFixed(1)}" height="${earthH.toFixed(1)}" fill="url(#earth-hatch)"/>`);
  parts.push(`<line x1="${gP1.sx.toFixed(1)}" y1="${gP1.sy.toFixed(1)}" x2="${gP2.sx.toFixed(1)}" y2="${gP2.sy.toFixed(1)}" stroke="#94a3b8" stroke-width="2.5"/>`);

  // 2. Projected Exterior Walls
  for (const w of model.walls) {
    const pTopLeft = toSvg(w.u, w.z + w.height);
    const wPx = w.width * scale;
    const hPx = w.height * scale;
    parts.push(`<rect x="${pTopLeft.sx.toFixed(1)}" y="${pTopLeft.sy.toFixed(1)}" width="${wPx.toFixed(1)}" height="${hPx.toFixed(1)}" fill="#1e293b" stroke="#38bdf8" stroke-width="1.8"/>`);
  }

  // 3. Projected Columns
  for (const c of model.columns) {
    const pTop = toSvg(c.u, c.z + c.height);
    const colW = c.width * scale;
    const colH = c.height * scale;
    parts.push(`<rect x="${pTop.sx.toFixed(1)}" y="${pTop.sy.toFixed(1)}" width="${colW.toFixed(1)}" height="${colH.toFixed(1)}" fill="#334155" stroke="#94a3b8" stroke-width="1.4"/>`);
  }

  // 4. Projected Openings (Doors and Windows)
  for (const op of model.openings) {
    const pTop = toSvg(op.u, op.z + op.height);
    const opW = op.width * scale;
    const opH = op.height * scale;

    if (op.kind === 'door') {
      // Door frame & panel
      parts.push(`<rect x="${pTop.sx.toFixed(1)}" y="${pTop.sy.toFixed(1)}" width="${opW.toFixed(1)}" height="${opH.toFixed(1)}" fill="#78350f" stroke="#fbbf24" stroke-width="1.5"/>`);
      parts.push(`<circle cx="${(pTop.sx + opW * 0.85).toFixed(1)}" cy="${(pTop.sy + opH * 0.5).toFixed(1)}" r="2" fill="#fbbf24"/>`);
    } else if (op.kind === 'window') {
      // Window frame & tinted glass
      parts.push(`<rect x="${pTop.sx.toFixed(1)}" y="${pTop.sy.toFixed(1)}" width="${opW.toFixed(1)}" height="${opH.toFixed(1)}" fill="#0369a1" fill-opacity="0.45" stroke="#38bdf8" stroke-width="1.5"/>`);
      // Vertical mullion
      if (opW > 30) {
        parts.push(`<line x1="${(pTop.sx + opW / 2).toFixed(1)}" y1="${pTop.sy.toFixed(1)}" x2="${(pTop.sx + opW / 2).toFixed(1)}" y2="${(pTop.sy + opH).toFixed(1)}" stroke="#38bdf8" stroke-width="1"/>`);
      }
    }
  }

  // 4b. Projected Stairs
  for (const st of (model.stairs || [])) {
    for (const step of st.steps) {
      const p1 = toSvg(step.u1, step.z1);
      const p2 = toSvg(step.u1, step.z2);
      const p3 = toSvg(step.u2, step.z2);
      parts.push(`<polyline points="${p1.sx.toFixed(1)},${p1.sy.toFixed(1)} ${p2.sx.toFixed(1)},${p2.sy.toFixed(1)} ${p3.sx.toFixed(1)},${p3.sy.toFixed(1)}" fill="none" stroke="#ec4899" stroke-width="1.5"/>`);
    }
    if (st.handrail) {
      const h1 = toSvg(st.handrail.u1, st.handrail.z1);
      const h2 = toSvg(st.handrail.u2, st.handrail.z2);
      parts.push(`<line x1="${h1.sx.toFixed(1)}" y1="${h1.sy.toFixed(1)}" x2="${h2.sx.toFixed(1)}" y2="${h2.sy.toFixed(1)}" stroke="#f472b6" stroke-width="2"/>`);
    }
  }

  // 5. Level Datums
  for (const d of model.datums) {
    const pt1 = toSvg(d.u1, d.elevation);
    const pt2 = toSvg(d.u2, d.elevation);
    // Datum line
    parts.push(`<line x1="${pt1.sx.toFixed(1)}" y1="${pt1.sy.toFixed(1)}" x2="${pt2.sx.toFixed(1)}" y2="${pt2.sy.toFixed(1)}" stroke="#a855f7" stroke-width="1" stroke-dasharray="8 4 2 4" opacity="0.75"/>`);
    // Elevation target bubble
    const targetX = pt2.sx + 16;
    const targetY = pt2.sy;
    parts.push(`<circle cx="${targetX.toFixed(1)}" cy="${targetY.toFixed(1)}" r="8" fill="#1e1b4b" stroke="#a855f7" stroke-width="1.5"/>`);
    parts.push(`<line x1="${(targetX - 8).toFixed(1)}" y1="${targetY.toFixed(1)}" x2="${(targetX + 8).toFixed(1)}" y2="${targetY.toFixed(1)}" stroke="#a855f7" stroke-width="1"/>`);
    parts.push(`<line x1="${targetX.toFixed(1)}" y1="${(targetY - 8).toFixed(1)}" x2="${targetX.toFixed(1)}" y2="${(targetY + 8).toFixed(1)}" stroke="#a855f7" stroke-width="1"/>`);
    // Text label
    parts.push(`<text x="${(targetX + 14).toFixed(1)}" y="${(targetY - 2).toFixed(1)}" fill="#e2e8f0" font-size="11" font-weight="700">${d.name}</text>`);
    parts.push(`<text x="${(targetX + 14).toFixed(1)}" y="${(targetY + 11).toFixed(1)}" fill="#c084fc" font-size="10" font-family="monospace">${d.label}</text>`);
  }

  // 6. Title and Drawing Label
  parts.push(`<text x="${marginX}" y="36" fill="#f8fafc" font-size="16" font-weight="700" letter-spacing="1">${model.title.toUpperCase()}</text>`);
  parts.push(`<text x="${marginX}" y="52" fill="#94a3b8" font-size="11">SCALE 1:${(1000 / scale).toFixed(0)} · ALL LEVELS ORTHOGRAPHIC PROJECTION</text>`);

  parts.push(`</svg>`);
  return parts.join('\n');
}

/**
 * Generates standalone clean SVG markup for a Building Section Cut.
 */
function generateSectionSVG(sectionModelOrEntities, sectionCut, options = {}) {
  const model = (sectionModelOrEntities && sectionModelOrEntities.cutWalls && sectionModelOrEntities.cutSlabs)
    ? sectionModelOrEntities
    : generateBuildingSection(sectionModelOrEntities, sectionCut, options);

  const scale = options.scale || 40;
  const marginX = 80;
  const marginY = 60;

  const contentW = (model.cutLength + 4.0) * scale;
  const contentH = (model.totalHeight + 3.0) * scale;
  const svgW = contentW + marginX * 2;
  const svgH = contentH + marginY * 2;

  function toSvg(u, z) {
    const sx = marginX + (u + 1.5) * scale;
    const sy = svgH - marginY - (z + 1.2) * scale;
    return { sx, sy };
  }

  const parts = [];
  parts.push(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${svgW.toFixed(0)} ${svgH.toFixed(0)}" width="100%" height="100%" style="background:#0f172a; font-family:'Segoe UI',system-ui,sans-serif;">`);

  // Defs & Pochè Pattern
  parts.push(`
    <defs>
      <pattern id="poche-hatch" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)">
        <line x1="0" y1="0" x2="0" y2="8" stroke="#f87171" stroke-width="1.2" opacity="0.5"/>
      </pattern>
      <pattern id="concrete-slab-hatch" width="10" height="10" patternUnits="userSpaceOnUse">
        <line x1="0" y1="0" x2="10" y2="10" stroke="#94a3b8" stroke-width="0.8" opacity="0.3"/>
        <line x1="10" y1="0" x2="0" y2="10" stroke="#94a3b8" stroke-width="0.8" opacity="0.3"/>
      </pattern>
    </defs>
  `);

  // 1. Earth & Grade
  const gP1 = toSvg(model.groundLine.u1, 0);
  const gP2 = toSvg(model.groundLine.u2, 0);
  parts.push(`<line x1="${gP1.sx.toFixed(1)}" y1="${gP1.sy.toFixed(1)}" x2="${gP2.sx.toFixed(1)}" y2="${gP2.sy.toFixed(1)}" stroke="#94a3b8" stroke-width="2.5"/>`);

  // 2. Background Projection Walls
  for (const bw of model.backgroundWalls) {
    const pTop = toSvg(bw.u, bw.z + bw.height);
    const wPx = bw.width * scale;
    const hPx = bw.height * scale;
    parts.push(`<rect x="${pTop.sx.toFixed(1)}" y="${pTop.sy.toFixed(1)}" width="${wPx.toFixed(1)}" height="${hPx.toFixed(1)}" fill="#1e293b" fill-opacity="0.4" stroke="#475569" stroke-width="1" stroke-dasharray="4 2"/>`);
  }

  // 3. Cut Slabs (Structural Concrete Floor Slabs)
  for (const sl of model.cutSlabs) {
    const pTop = toSvg(sl.u1, sl.z2);
    const wPx = (sl.u2 - sl.u1) * scale;
    const hPx = (sl.z2 - sl.z1) * scale;
    parts.push(`<rect x="${pTop.sx.toFixed(1)}" y="${pTop.sy.toFixed(1)}" width="${wPx.toFixed(1)}" height="${hPx.toFixed(1)}" fill="#334155" stroke="#cbd5e1" stroke-width="1.8"/>`);
    parts.push(`<rect x="${pTop.sx.toFixed(1)}" y="${pTop.sy.toFixed(1)}" width="${wPx.toFixed(1)}" height="${hPx.toFixed(1)}" fill="url(#concrete-slab-hatch)"/>`);
  }

  // 4. Cut Walls (POCHÈ)
  for (const cw of model.cutWalls) {
    const pTop = toSvg(cw.u, cw.z + cw.height);
    const wPx = cw.thickness * scale;
    const hPx = cw.height * scale;
    // Heavy Pochè Fill
    parts.push(`<rect x="${pTop.sx.toFixed(1)}" y="${pTop.sy.toFixed(1)}" width="${wPx.toFixed(1)}" height="${hPx.toFixed(1)}" fill="#ef4444" fill-opacity="0.25" stroke="#f87171" stroke-width="2.2"/>`);
    parts.push(`<rect x="${pTop.sx.toFixed(1)}" y="${pTop.sy.toFixed(1)}" width="${wPx.toFixed(1)}" height="${hPx.toFixed(1)}" fill="url(#poche-hatch)"/>`);
  }

  // 5. Cut Openings
  for (const co of model.cutOpenings) {
    const pTop = toSvg(co.u, co.z + co.height);
    const wPx = co.thickness * scale;
    const hPx = co.height * scale;
    if (co.kind === 'window') {
      // Cut double-glazing slice
      parts.push(`<rect x="${pTop.sx.toFixed(1)}" y="${pTop.sy.toFixed(1)}" width="${wPx.toFixed(1)}" height="${hPx.toFixed(1)}" fill="#0284c7" fill-opacity="0.3" stroke="#38bdf8" stroke-width="1.2"/>`);
      parts.push(`<line x1="${(pTop.sx + wPx / 2).toFixed(1)}" y1="${pTop.sy.toFixed(1)}" x2="${(pTop.sx + wPx / 2).toFixed(1)}" y2="${(pTop.sy + hPx).toFixed(1)}" stroke="#38bdf8" stroke-width="1.5"/>`);
    }
  }

  // 5b. Cut Stairs (Stepped profile, concrete waist slab, handrail)
  for (const st of (model.cutStairs || [])) {
    // Structural waist slab polygon
    const pStartBottom = toSvg(st.minU, st.baseZ - st.waistThickness);
    const pEndBottom = toSvg(st.maxU, st.baseZ + st.rise - st.waistThickness);
    const pEndTop = toSvg(st.maxU, st.baseZ + st.rise);
    const pStartTop = toSvg(st.minU, st.baseZ);
    parts.push(`<polygon points="${pStartTop.sx.toFixed(1)},${pStartTop.sy.toFixed(1)} ${pEndTop.sx.toFixed(1)},${pEndTop.sy.toFixed(1)} ${pEndBottom.sx.toFixed(1)},${pEndBottom.sy.toFixed(1)} ${pStartBottom.sx.toFixed(1)},${pStartBottom.sy.toFixed(1)}" fill="#be123c" fill-opacity="0.25" stroke="#f43f5e" stroke-width="2"/>`);
    parts.push(`<polygon points="${pStartTop.sx.toFixed(1)},${pStartTop.sy.toFixed(1)} ${pEndTop.sx.toFixed(1)},${pEndTop.sy.toFixed(1)} ${pEndBottom.sx.toFixed(1)},${pEndBottom.sy.toFixed(1)} ${pStartBottom.sx.toFixed(1)},${pStartBottom.sy.toFixed(1)}" fill="url(#concrete-slab-hatch)"/>`);

    // Stepped profile
    for (const step of st.steps) {
      const p1 = toSvg(step.u1, step.z);
      const p2 = toSvg(step.u1, step.zNext);
      const p3 = toSvg(step.u2, step.zNext);
      parts.push(`<polyline points="${p1.sx.toFixed(1)},${p1.sy.toFixed(1)} ${p2.sx.toFixed(1)},${p2.sy.toFixed(1)} ${p3.sx.toFixed(1)},${p3.sy.toFixed(1)}" fill="none" stroke="#f43f5e" stroke-width="2.5"/>`);
    }

    // Handrail & posts
    if (st.handrail) {
      const h1 = toSvg(st.handrail.u1, st.handrail.z1);
      const h2 = toSvg(st.handrail.u2, st.handrail.z2);
      parts.push(`<line x1="${h1.sx.toFixed(1)}" y1="${h1.sy.toFixed(1)}" x2="${h2.sx.toFixed(1)}" y2="${h2.sy.toFixed(1)}" stroke="#fb7185" stroke-width="2.2"/>`);
      for (const post of st.handrail.posts || []) {
        const postP1 = toSvg(post.u, post.z1);
        const postP2 = toSvg(post.u, post.z2);
        parts.push(`<line x1="${postP1.sx.toFixed(1)}" y1="${postP1.sy.toFixed(1)}" x2="${postP2.sx.toFixed(1)}" y2="${postP2.sy.toFixed(1)}" stroke="#fb7185" stroke-width="1.8"/>`);
      }
    }
  }

  // 5c. Background Stairs (projected in elevation)
  for (const st of (model.backgroundStairs || [])) {
    for (const step of st.steps) {
      const p1 = toSvg(step.u1, step.z);
      const p2 = toSvg(step.u1, step.zNext);
      const p3 = toSvg(step.u2, step.zNext);
      parts.push(`<polyline points="${p1.sx.toFixed(1)},${p1.sy.toFixed(1)} ${p2.sx.toFixed(1)},${p2.sy.toFixed(1)} ${p3.sx.toFixed(1)},${p3.sy.toFixed(1)}" fill="none" stroke="#94a3b8" stroke-width="1.2" stroke-dasharray="3 2"/>`);
    }
  }

  // 6. Level Datums
  for (const d of model.datums) {
    const pt1 = toSvg(d.u1, d.elevation);
    const pt2 = toSvg(d.u2, d.elevation);
    parts.push(`<line x1="${pt1.sx.toFixed(1)}" y1="${pt1.sy.toFixed(1)}" x2="${pt2.sx.toFixed(1)}" y2="${pt2.sy.toFixed(1)}" stroke="#a855f7" stroke-width="1" stroke-dasharray="8 4 2 4" opacity="0.75"/>`);
    const targetX = pt2.sx + 16;
    const targetY = pt2.sy;
    parts.push(`<circle cx="${targetX.toFixed(1)}" cy="${targetY.toFixed(1)}" r="8" fill="#1e1b4b" stroke="#a855f7" stroke-width="1.5"/>`);
    parts.push(`<line x1="${(targetX - 8).toFixed(1)}" y1="${targetY.toFixed(1)}" x2="${(targetX + 8).toFixed(1)}" y2="${targetY.toFixed(1)}" stroke="#a855f7" stroke-width="1"/>`);
    parts.push(`<line x1="${targetX.toFixed(1)}" y1="${(targetY - 8).toFixed(1)}" x2="${targetX.toFixed(1)}" y2="${(targetY + 8).toFixed(1)}" stroke="#a855f7" stroke-width="1"/>`);
    parts.push(`<text x="${(targetX + 14).toFixed(1)}" y="${(targetY - 2).toFixed(1)}" fill="#e2e8f0" font-size="11" font-weight="700">${d.name}</text>`);
    parts.push(`<text x="${(targetX + 14).toFixed(1)}" y="${(targetY + 11).toFixed(1)}" fill="#c084fc" font-size="10" font-family="monospace">${d.label}</text>`);
  }

  // 7. Title & Metadata
  parts.push(`<text x="${marginX}" y="36" fill="#f8fafc" font-size="16" font-weight="700" letter-spacing="1">${model.title.toUpperCase()}</text>`);
  parts.push(`<text x="${marginX}" y="52" fill="#94a3b8" font-size="11">SCALE 1:${(1000 / scale).toFixed(0)} · ARCHITECTURAL POCHÈ SECTION</text>`);

  parts.push(`</svg>`);
  return parts.join('\n');
}


