    options: [
      { token: 'WIDTH', label: 'Width', kind: 'length', min: 0.05, max: 2, fallback: 0.2 },
      { token: 'ALIGN', label: 'Align', kind: 'option', values: ['Center', 'Left', 'Right'], fallback: 'Center' },
      { token: 'REVERSE', label: 'Reverse', kind: 'boolean', fallback: false }
    ],
