/** Non-interactive commands executed in one shot. args: [] = none accepted. */
const SIMPLE = [
  { name: 'UNDO', aliases: ['U'], description: 'Undo the last action', category: 'edit', run: 'undo' },
  { name: 'REDO', aliases: ['R'], description: 'Redo the previously undone action', category: 'edit', run: 'redo' },
  { name: 'DELETE', aliases: ['E', 'ERASE', 'DEL'], description: 'Delete the current selection', category: 'edit', run: 'delete' },
  { name: 'ZOOM', aliases: ['Z'], description: 'Zoom: ZOOM E (extents), ZOOM 100, ZOOM IN, ZOOM OUT', category: 'view', run: 'zoom' },
  { name: 'PAN', aliases: ['P'], description: 'Activate the pan tool (drag to pan)', category: 'view', run: 'pan' },
  { name: 'FIT', aliases: ['ZE', 'ZOOMEXTENTS'], description: 'Zoom to fit all content', category: 'view', run: 'zoom_extents' },
  { name: 'TOP', aliases: ['PLAN'], description: 'Switch to the plan (top) view', category: 'view', run: 'view_top' },
  { name: 'FRONT', aliases: ['ELEV', 'SOUTH'], description: 'Switch to the front (south) elevation', category: 'view', run: 'view_front' },
  { name: 'RIGHT', aliases: ['EAST'], description: 'Switch to the right (east) elevation', category: 'view', run: 'view_right' },
  { name: 'PERSPECTIVE', aliases: ['PERSP', '3D', 'MASSING'], description: 'Switch to the 3D massing view', category: 'view', run: 'view_perspective' },
  { name: '4VIEW', aliases: ['SPLIT', 'QUAD'], description: 'Switch to the 4-viewport workspace', category: 'view', run: 'view_4split' },
  { name: 'SELECT', aliases: ['SEL', 'V'], description: 'Activate the selection tool', category: 'tool', run: 'tool:select' },
  { name: 'SELECTALL', aliases: ['ALL', 'CTRLA'], description: 'Select every entity in the document', category: 'tool', run: 'select_all' },
  { name: 'PROPERTIES', aliases: ['PROPS', 'CH'], description: 'Inspect the current selection in the properties panel', category: 'inquiry', run: 'properties' },
  { name: 'INFO', aliases: ['INSPECT'], description: 'Show detailed information about the current selection', category: 'inquiry', run: 'info' },
  { name: 'SUGGEST', aliases: ['SUGGESTIONS'], description: 'Ranked, evidence-backed suggestions for the current selection or document', category: 'ai', run: 'suggest' },
  { name: 'ISSUES', aliases: ['AUDIT'], description: 'Deterministic project audit — geometry, rooms, doors, dimensions, documentation', category: 'ai', run: 'issues' },
  { name: 'AI', aliases: ['ASK', 'AIQUERY'], description: 'Ask the AI about the current selection: AI <question…>', category: 'ai', run: 'ai_query' },
  { name: 'ANALYZE', aliases: ['AICRITIQUE'], description: 'Project-wide AI review with deterministic evidence', category: 'ai', run: 'ai_analyze' },
  { name: 'BRIEF', aliases: ['REQ', 'REQUIREMENTS'], description: 'Open the Brief & Requirements studio (evaluate requirements vs model)', category: 'system', run: 'brief' },
  { name: 'LAYER', aliases: ['LA'], description: 'Open the layers panel', category: 'organize', run: 'panel:layers' },
  { name: 'HELP', aliases: ['?'], description: 'List commands: HELP [search…]', category: 'system', run: 'help' }
];

/**
 * Builds the full command registry. toolCatalog entries that expose a
 * commandAlias become instant tool-activation commands, so the palette,
 * shortcuts and the command line stay a single source of truth.
 */
function buildCommandRegistry(toolCatalog = []) {
  const commands = new Map();
  const aliasIndex = new Map();

  function register(def) {
    commands.set(def.name, def);
    aliasIndex.set(def.name.toLowerCase(), def.name);
    for (const a of def.aliases || []) aliasIndex.set(a.toLowerCase(), def.name);
  }

  for (const def of INTERACTIVE) {
    register({ ...def, interactive: true, aliases: [...(def.aliases || [])] });
  }
  for (const def of SIMPLE) register({
    ...def,
    id: def.id || 'cmd.' + def.name.toLowerCase(),
    interactive: false,
    aliases: [...(def.aliases || [])],
    selection: def.selection || 'none',
    undo: def.undo !== undefined ? def.undo : (def.category === 'edit'),
    aiDescription: def.aiDescription || def.description
  });

  for (const tool of toolCatalog) {
    if (!tool || !tool.commandAlias) continue;
    const alias = String(tool.commandAlias).toUpperCase();
    if (aliasIndex.has(alias.toLowerCase())) continue;
    register({
      name: alias,
      aliases: [],
      id: 'cmd.tool.' + tool.id,
      description: tool.description || `Activate ${tool.name} tool`,
      category: 'tool',
      run: `tool:${tool.id}`,
      toolId: tool.id,
      toolName: tool.name,
      shortcut: tool.shortcut || null,
      selection: 'none',
      undo: false,
      aiDescription: `Activates the ${tool.name} tool on the canvas.`
    });
  }

  return { commands, aliasIndex };
}

// ---------------------------------------------------------------------------
// Coordinate & numeric input (single unit engine: parseInput)
// ---------------------------------------------------------------------------

/**
 * Parses a point token: "10,20", "10,20,0", "@5,0" (relative), "@5<90"
 * (polar relative), or a bare unit-bearing length for guided entry.
 * @returns {{ value: {x,y}, relative: boolean } | { error: string }}
 */
function parsePointToken(token, lastPoint = null) {
  if (!token || typeof token !== 'string') return { error: 'Enter a coordinate like 10,20 or @5<90.' };
  const t = token.trim();
  if (!t) return { error: 'Enter a coordinate like 10,20 or @5<90.' };

  if (t.startsWith('@')) {
    const rest = t.slice(1);
    const polar = rest.match(/^([^<]+)<(.+)$/);
    if (polar) {
      const dist = parseLengthToken(polar[1]);
      if (dist.error) return { error: dist.error };
      const ang = parseInput(polar[2].replace(/°|deg|°/gi, ''));
      if (!ang.isValid) return { error: `Invalid angle "${polar[2]}" — try @5<90.` };
      const rad = (ang.value * Math.PI) / 180;
      return { value: { x: dist.value * Math.cos(rad), y: dist.value * Math.sin(rad) }, relative: true };
    }
    const parts = rest.split(',');
    if (parts.length < 2) return { error: 'Relative entry needs @dx,dy (or @dist<angle).' };
    const dx = parseLengthToken(parts[0]);
    const dy = parseLengthToken(parts[1]);
    if (dx.error) return { error: dx.error };
    if (dy.error) return { error: dy.error };
    return { value: { x: dx.value, y: dy.value }, relative: true };
  }

  const parts = t.split(',');
  if (parts.length >= 2) {
    const x = parseLengthToken(parts[0]);
    const y = parseLengthToken(parts[1]);
    if (x.error) return { error: x.error };
    if (y.error) return { error: y.error };
    return { value: { x: x.value, y: y.value }, relative: false };
  }

  if (lastPoint) {
    // Guided length entry while the cursor previews a direction.
    const len = parseLengthToken(t);
    if (!len.error) return { value: { x: len.value, y: 0 }, relative: true, guided: true };
  }
  return { error: `"${t}" is not a coordinate — try 10,20 · @5,0 · @5<90 · 2400mm.` };
}

/** Parses a unit-bearing length: expressions ("2m+400mm") via the math
 *  engine, single values via the shared parser ("2400mm", "2.4m", "8'"). */
function parseLengthToken(token) {
  const t = String(token ?? '').trim();
  // Expression path: any input with an operator runs through the
  // deterministic math engine (same units, same parser family).
  if (/[+\-*/%^]/.test(t.slice(1)) && isExpressionLike(t)) {
    const res = evaluateExpressionSafe(t, { defaultUnit: 'm', displayUnit: 'm' });
    if (res.isValid && (res.dimension === 'length' || res.dimension === 'scalar')) {
      return { value: res.value };
    }
    if (res.isValid && (res.dimension === 'area' || res.dimension === 'volume')) {
      return { error: `"${t}" results in an ${res.dimension} — a point or length is required here (e.g. 2m+400mm).` };
    }
    // fall through to parseInput for non-expression strings
  }
  const res = parseInput(t, { allowNegative: true });
  if (!res.isValid) {
    return { error: `"${token}" is not a valid length — try 2400mm, 2.4m, 8', or an expression like 2m+400mm.` };
  }
  // parseInput returns the value in the DETECTED unit ("2400mm" → 2400 mm);
  // the command engine's canonical unit is meters (canvas world space).
  let meters = res.value;
  if (res.detectedUnit && UNITS[res.detectedUnit]?.toMeters) {
    meters = res.value * UNITS[res.detectedUnit].toMeters;
  }
  return { value: meters };
}

// ---------------------------------------------------------------------------
// Session: interactive multi-step state machine
// ---------------------------------------------------------------------------

function createCommandSession({ registry, execute, storage = null, historyLimit = 100 } = {}) {
  if (!registry || !registry.commands) throw new Error('createCommandSession requires a registry');
  if (typeof execute !== 'function') throw new Error('createCommandSession requires an execute(command, args) function');

  let history = [];
  let historyCursor = -1;
  let draft = null; // active interactive command state
  let recents = [];

  // Restore session history
  if (storage) {
    try {
      const raw = storage.getItem('ahh_command_history');
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) history = parsed.filter(x => typeof x === 'string').slice(-historyLimit);
      }
      const rawRecents = storage.getItem('ahh_command_recents');
      if (rawRecents) {
        const parsed = JSON.parse(rawRecents);
        if (Array.isArray(parsed)) recents = parsed.filter(x => typeof x === 'string').slice(0, 12);
      }
    } catch { /* corrupt storage is ignored by design */ }
  }

  function persist() {
    if (!storage) return;
    try {
      storage.setItem('ahh_command_history', JSON.stringify(history.slice(-historyLimit)));
      storage.setItem('ahh_command_recents', JSON.stringify(recents.slice(0, 12)));
    } catch { /* quota — session history is best-effort */ }
  }

  function remember(raw) {
    // Consecutive duplicates collapse; cursor always restarts at the newest.
    if (history[history.length - 1] !== raw) {
      history.push(raw);
      if (history.length > historyLimit) history.shift();
    }
    historyCursor = -1;
    const verb = raw.trim().split(/\s+/)[0].toUpperCase();
    recents = [verb, ...recents.filter(r => r !== verb)].slice(0, 12);
    persist();
  }

  /**
   * Begin an interactive command programmatically (e.g. from a palette click).
   */
  function start(name) {
    const def = registry.commands.get(String(name).toUpperCase());
    if (!def || !def.interactive) return { ok: false, error: `"${name}" is not an interactive command.` };
    draft = { def, stepIndex: 0, points: [], options: {} };
    for (const opt of def.options || []) draft.options[opt.token] = opt.fallback;
    return { ok: true, state: state() };
  }

  function state() {
    if (!draft) return { active: false, lifecycle: 'IDLE' };
    const def = draft.def;
    const step = def.steps[draft.stepIndex];
    return {
      active: true,
      lifecycle: 'PROMPT',
      command: def.name,
      stepIndex: draft.stepIndex,
      stepCount: def.steps.length,
      prompt: `${step.prompt}:`,
      options: (def.options || []).map(o => ({ ...o, value: draft.options[o.token] })),
      collected: draft.points.length
    };
  }

  function cancel(reason = 'canceled') {
    const name = draft ? draft.def.name : null;
    draft = null;
    return { ok: true, message: name ? `${name} ${reason}.` : 'Nothing to cancel.' };
  }

  /**
   * Feed one line of input into the session. Handles: option tokens
   * ("Width=0.3"), point/length tokens for the current step, and completion.
   * @param {string} text - raw user text for this step
   * @param {{ currentPoint?: {x,y}, snap?: (p:{x,y})=>{x,y} }} ctx
   */
  function submit(text, ctx = {}) {
    if (!draft) return { ok: false, error: 'No active command.' };
    const def = draft.def;
    const trimmed = String(text || '').trim();
    if (!trimmed) return { ok: false, error: `${def.steps[draft.stepIndex].prompt}:` };

    // Option token? "WIDTH=0.3" / "ALIGN=Left" / bare option name cycles values
    const optMatch = trimmed.match(/^([A-Za-z]+)\s*=?\s*(.*)$/);
    if (optMatch && def.options) {
      const opt = def.options.find(o => o.token === optMatch[1].toUpperCase());
      if (opt) {
        let arg = optMatch[2].trim();
        // bare option name cycles/toggles its values (AutoCAD-style)
        if (!arg) {
          if (opt.kind === 'boolean') {
            draft.options[opt.token] = !draft.options[opt.token];
            return { ok: true, optionSet: { token: opt.token, value: draft.options[opt.token] }, state: state() };
          }
          if (opt.kind === 'option') {
            const i = opt.values.indexOf(draft.options[opt.token]);
            draft.options[opt.token] = opt.values[(i + 1) % opt.values.length];
            return { ok: true, optionSet: { token: opt.token, value: draft.options[opt.token] }, state: state() };
          }
          return { ok: false, error: `${opt.label} needs a value — e.g. ${opt.token}=${opt.fallback}` };
        }
        if (opt.kind === 'option') {
          const match = opt.values.find(v => v.toLowerCase() === arg.toLowerCase());
          if (!match) {
            return { ok: false, error: `${opt.label} must be one of: ${opt.values.join(', ')} (received "${arg}")` };
          }
          draft.options[opt.token] = match;
          return { ok: true, optionSet: { token: opt.token, value: match }, state: state() };
        }
        const val = parseLengthToken(arg);
        if (val.error) return { ok: false, error: `${opt.label}: ${val.error}` };
        const clamped = Math.max(opt.min, Math.min(opt.max, val.value));
        draft.options[opt.token] = clamped;
        return { ok: true, optionSet: { token: opt.token, value: clamped }, state: state() };
      }
    }

    const step = def.steps[draft.stepIndex];
    let point = null;
    if (step.kind === 'point') {
      const parsed = parsePointToken(trimmed, ctx.currentPoint || draft.points[draft.points.length - 1] || null);
      if (parsed.error) return { ok: false, error: parsed.error };
      point = parsed.relative
        ? {
            x: (draft.points.length ? draft.points[draft.points.length - 1].x : (ctx.currentPoint ? ctx.currentPoint.x : 0)) + parsed.value.x,
            y: (draft.points.length ? draft.points[draft.points.length - 1].y : (ctx.currentPoint ? ctx.currentPoint.y : 0)) + parsed.value.y
          }
        : parsed.value;
      if (typeof ctx.snap === 'function') point = ctx.snap(point);
    } else if (step.kind === 'length') {
      const len = parseLengthToken(trimmed);
      if (len.error) return { ok: false, error: len.error };
      point = { value: len.value };
    } else {
      return { ok: false, error: `Unsupported step kind "${step.kind}".` };
    }

    draft.points.push(point);
    if (draft.stepIndex < def.steps.length - 1) {
      draft.stepIndex += 1;
      return { ok: true, accepted: true, state: state() };
    }

    // Command complete — build args and hand to the executor.
    const args = {
      command: def.name,
      result: def.result,
      points: draft.points.map(p => ({ x: p.x, y: p.y })),
      options: { ...draft.options }
    };
    const wasCommand = def.name;
    draft = null;
    let outcome;
    try {
      outcome = execute(def.result, args);
    } catch (e) {
      outcome = { ok: false, error: e.message };
    }
    return {
      ok: true,
      completed: wasCommand,
      outcome: outcome || { ok: true },
      state: state()
    };
  }

  /**
   * Feeds a canvas point directly into the active step (pointer input path).
   * @param {{x,y}} point - resolved world coordinate (already un-projected)
   * @param {{ snap?: Function }} [ctx]
   */
  function submitPoint(point, ctx = {}) {
    if (!draft) return { ok: false, error: 'No active command.' };
    const def = draft.def;
    const step = def.steps[draft.stepIndex];
    if (!step || step.kind !== 'point') {
      return { ok: false, error: `${def.name}: the current step does not accept a canvas point.` };
    }
    if (!point || typeof point.x !== 'number' || typeof point.y !== 'number' ||
        !Number.isFinite(point.x) || !Number.isFinite(point.y)) {
      return { ok: false, error: 'Invalid canvas point.' };
    }
    let pt = { x: point.x, y: point.y };
    if (typeof ctx.snap === 'function') pt = ctx.snap(pt);
    draft.points.push(pt);
    if (draft.stepIndex < def.steps.length - 1) {
      draft.stepIndex += 1;
      return { ok: true, accepted: true, state: state() };
    }
    const args = {
      command: def.name,
      result: def.result,
      points: draft.points.map(p => ({ x: p.x, y: p.y })),
      options: { ...draft.options }
    };
    const wasCommand = def.name;
    draft = null;
    let outcome;
    try {
      outcome = execute(def.result, args);
    } catch (e) {
      outcome = { ok: false, error: e.message };
    }
    return { ok: true, completed: wasCommand, outcome: outcome || { ok: true }, state: state() };
  }

  // ---------------------------------------------------------------------------
  // One-shot execution + autocomplete + history navigation
  // ---------------------------------------------------------------------------

  /**
   * Executes a full command line. Returns a structured outcome:
   *   { handled, kind: 'interactive'|'simple'|'tool'|'unknown', ... }
   */
  function run(rawLine, ctx = {}) {
    const raw = String(rawLine || '').trim();
    if (!raw) return { handled: false, kind: 'empty', message: '' };
    const tokens = raw.split(/\s+/);
    const verb = tokens[0].toUpperCase();
    const rest = tokens.slice(1);
    remember(raw);

    const name = registry.aliasIndex.get(verb.toLowerCase());
    if (!name) {
      const suggestion = suggestCommands(verb, { registry, limit: 1 })[0];
      return {
        handled: false,
        kind: 'unknown',
        command: verb,
        message: suggestion
          ? `Unknown command "${verb}". Did you mean ${suggestion.name}?`
          : `Unknown command "${verb}". Type HELP for the command list.`
      };
    }
    const def = registry.commands.get(name);

    if (def.interactive) {
      const started = start(name);
      if (!started.ok) return { handled: false, kind: 'error', message: started.error };
      // Remaining tokens feed the interactive steps (e.g. "LINE 0,0 2.4,0").
      for (const token of rest) {
        const stepRes = submit(token, ctx);
        if (!stepRes.ok) return { handled: true, kind: 'interactive', command: def.name, error: stepRes.error, state: state() };
        if (stepRes.completed) return { handled: true, kind: 'interactive', command: def.name, completed: def.name, outcome: stepRes.outcome, state: state() };
      }
      return { handled: true, kind: 'interactive', command: def.name, state: state() };
    }

    let outcome;
    try {
      outcome = execute(def.run, { command: def.name, args: rest, raw });
    } catch (e) {
      outcome = { ok: false, error: e.message };
    }
    return { handled: true, kind: 'simple', command: def.name, run: def.run, outcome: outcome || { ok: true } };
  }

  function historyStep(direction) {
    if (history.length === 0) return { ok: false, message: 'No command history yet.' };
    if (direction === 'up') {
      historyCursor = historyCursor === -1 ? history.length - 1 : Math.max(0, historyCursor - 1);
    } else {
      if (historyCursor === -1) return { ok: false, message: 'Already at the newest command.' };
      historyCursor += 1;
      if (historyCursor >= history.length) { historyCursor = -1; return { ok: true, value: '' }; }
    }
    return { ok: true, value: history[historyCursor] };
  }

  function historySearch(query, limit = 10) {
    const q = String(query || '').toLowerCase();
    if (!q) return history.slice(-limit).reverse();
    return history.filter(h => h.toLowerCase().includes(q)).slice(-limit).reverse();
  }

  function clearHistory() {
    history = [];
    historyCursor = -1;
    persist();
    return { ok: true, message: 'Command history cleared.' };
  }

  return {
    run, submit, submitPoint, start, cancel, state,
    autocomplete: (q, opts) => suggestCommands(q, { registry, recents, ...opts }),
    historyStep, historySearch, clearHistory,
    getHistory: () => history.slice(),
    getRecents: () => recents.slice()
  };
}

// ---------------------------------------------------------------------------
// Autocomplete
// ---------------------------------------------------------------------------

function fuzzySubsequence(query, target) {
  let i = 0;
  for (const ch of target) {
    if (ch === query[i]) i += 1;
    if (i === query.length) return true;
  }
  return false;
}

/**
 * Ranks commands for a query: exact > prefix (name) > prefix (alias) >
 * substring > fuzzy. Recent history and catalog metadata boost ordering.
 */
function suggestCommands(query, { registry, recents = [], limit = 8 } = {}) {
  const q = String(query || '').trim().toLowerCase();
  if (!q) {
    return [...registry.commands.values()].slice(0, limit).map(def => describeCommand(def));
  }
  const results = [];
  for (const def of registry.commands.values()) {
    const name = def.name.toLowerCase();
    const aliases = (def.aliases || []).map(a => a.toLowerCase());
    let score = -1;
    if (name === q) score = 120;
    else if (aliases.includes(q)) score = 110;
    else if (name.startsWith(q)) score = 100 - name.length;
    else if (aliases.some(a => a.startsWith(q))) score = 90 - name.length;
    else if (name.includes(q) || aliases.some(a => a.includes(q))) score = 60;
    else if (fuzzySubsequence(q, name) || fuzzySubsequence(q, def.description?.toLowerCase() || '')) score = 40;
    if (score < 0) continue;
    if (recents.includes(def.name)) score += 15;
    results.push({ def, score });
  }
  results.sort((a, b) => b.score - a.score || a.def.name.localeCompare(b.def.name));
  return results.slice(0, limit).map(({ def }) => describeCommand(def));
}

function describeCommand(def) {
  return {
    name: def.name,
    id: def.id || null,
    aliases: def.aliases || [],
    description: def.description || '',
    category: def.category,
    interactive: !!def.interactive,
    shortcut: def.shortcut || null,
    toolId: def.toolId || null,
    selection: def.selection || 'none',
    undo: def.undo !== undefined ? def.undo : !def.interactive,
    help: def.help || def.description || '',
    aiDescription: def.aiDescription || def.description || ''
  };
}


  // =========================================================================
  // MODULE: Suggestions
  // =========================================================================

/**
 * Architecture Helping Hand — Deterministic Suggestion Engine
 *
 * Evidence-backed, ranked suggestions for a selected entity or a whole
 * document. NO AI involved: every finding is computed from real geometry with
 * a citable number, so the AI layer can quote them and the user can trust
 * them. Severity: critical > high > medium > low > informational.
 */



const BLONDEL_MIN = 0.6;
const BLONDEL_MAX = 0.66;
const RAMP_MAX_SLOPE = 8.33;

function sev(level) {
  return { critical: 0, high: 1, medium: 2, low: 3, informational: 4 }[level] ?? 4;
}

/**
 * Suggestions for one selected entity.
 * @returns {Array<{severity, problem, evidence, recommendation, toolId}>}
 */
function suggestForEntity(entity, entities = []) {
  if (!entity) return [];
  const out = [];
  const push = (severity, problem, evidence, recommendation, toolId) =>
    out.push({ severity, problem, evidence, recommendation, toolId });

  switch (entity.kind) {
    case 'wall': {
      const len = wallLength(entity);
      const touching = entities.filter(d => d.kind === 'dimension' && suggestDimensionOnWall(d, entity));
      if (touching.length === 0) {
        push('medium', 'Wall has no dimension annotation',
          `Wall "${entity.name}" is ${len.toFixed(2)} m long; no dimension entity references its endpoints.`,
          'Place a linear dimension (DIMLIN) so the drawing communicates its length.', 'dimension');
      }
      const thickness = entity.thickness ?? 0.2;
      if (thickness < 0.1) {
        push('high', 'Wall thickness below light-frame minimum',
          `Thickness ${thickness.toFixed(3)} m is thinner than a 100 mm partition.`,
          'Verify the assembly — most buildable partitions are ≥ 0.10 m.', 'properties');
      }
      const openings = wallOpenings(entity, entities);
      for (const o of openings) {
        if (typeof o.width === 'number' && o.width > len - 0.1) {
          push('high', 'Opening wider than the wall segment',
            `"${o.name}" is ${o.width.toFixed(2)} m in a ${len.toFixed(2)} m wall segment.`,
            'Shorten the opening, lengthen the wall, or split the wall.', 'window');
        }
      }
      const junctions = entities.filter(w => w.kind === 'wall' && w.id !== entity.id && sharesEndpoint(w, entity)).length;
      if (junctions === 0) {
        push('low', 'Wall is disconnected',
          `"${entity.name}" shares no endpoint with any other wall.`,
          'Join it to the wall network (WALL command snaps to endpoints).', 'wall');
      }
      break;
    }
    case 'room': {
      const area = roomArea(entity);
      const ratio = roomAspectRatio(entity);
      if (ratio > 2.5) {
        push('medium', 'Room proportions are extreme',
          `Aspect ratio ${ratio.toFixed(2)}:1 (${entity.width?.toFixed(2)} × ${entity.depth?.toFixed(2)} m).`,
          'Consider an L-shape, an internal partition, or re-proportioning.', 'room');
      }
      const furniture = entities.filter(f => f.kind === 'furniture' &&
        f.x >= entity.x - 0.01 && f.x <= entity.x + entity.width + 0.01 &&
        f.y >= entity.y - 0.01 && f.y <= entity.y + entity.depth + 0.01);
      if (furniture.length > 0) {
        const furnitureArea = furniture.reduce((s, f) => s + (f.width * f.depth || 0), 0);
        const density = area > 0 ? furnitureArea / area : 0;
        if (density > 0.45) {
          push('high', 'Furniture density very high',
            `Furniture occupies ${(density * 100).toFixed(0)}% of the ${(area).toFixed(1)} m² room floor.`,
            'Reduce furniture, enlarge the room, or check circulation with a clearance test.', 'select');
        } else if (density > 0.32) {
          push('medium', 'Furniture density above comfortable range',
            `Furniture occupies ${(density * 100).toFixed(0)}% of the floor; comfortable plans stay under ~32%.`,
            'Verify clearances around each piece.', 'select');
        }
      }
      const name = String(entity.name || '').toLowerCase();
      if (/bed/.test(name) && area > 0 && area < 7.5) {
        push('medium', 'Bedroom below common minimum',
          `Named bedroom is ${area.toFixed(1)} m²; many codes/standards expect ≥ 7.5 m² for a habitable bedroom.`,
          'Enlarge the room or rename it to match its actual function.', 'room');
      }
      const dims = entities.filter(d => d.kind === 'dimension' && suggestDimensionNearRoom(d, entity));
      if (dims.length === 0) {
        push('low', 'Room is undimensioned',
          `No dimension entities sit on the boundaries of "${entity.name}".`,
          'Add dimension chains for construction layout (DIMCHAIN tool).', 'dimension');
      }
      break;
    }
    case 'stair': {
      const blondel = typeof entity.blondel === 'number' ? entity.blondel : 2 * (entity.riserHeight || 0) + (entity.tread || 0);
      if (blondel > 0 && (blondel < BLONDEL_MIN || blondel > BLONDEL_MAX)) {
        push('medium', 'Stair proportion outside the Blondel band',
          `2R+T = ${(blondel * 1000).toFixed(0)} mm (comfort band 600–660 mm).`,
          'Adjust riser/tread with the Stair Calculator (STAIR command or the studio tool).', 'stair');
      }
      const risers = entity.risers ?? 0;
      if (risers > 16) {
        push('informational', 'Flight exceeds 16 risers',
          `${risers} risers in one flight — many codes require an intermediate landing beyond 16.`,
          'Split the flight with a landing.', 'stair');
      }
      break;
    }
    case 'ramp': {
      const slope = typeof entity.slopePercent === 'number' ? entity.slopePercent : null;
      if (slope !== null && slope > RAMP_MAX_SLOPE + 0.05) {
        push('high', 'Ramp steeper than the 1:12 accessibility maximum',
          `Slope ${slope.toFixed(2)}% (1:${(entity.slopeRatio || 100 / slope).toFixed(1)}).`,
          'Lengthen the run or add switchbacks (Ramp Calculator).', 'ramp');
      }
      break;
    }
    case 'dimension': {
      const val = suggestDimensionValue(entity);
      const match = entities.find(t => (t.kind === 'wall' || t.kind === 'line' || t.kind === 'room') &&
        Math.abs(suggestEntityPrimaryLength(t) - val) < 0.02);
      if (!match) {
        push('medium', 'Dimension does not match any nearby geometry',
          `Dimension measures ${val.toFixed(2)} m; no wall/line/room edge of that exact length exists in the document.`,
          'Re-measure with DIST and re-place the dimension, or update the geometry.', 'measure');
      } else {
        push('informational', 'Dimension verified against geometry',
          `${val.toFixed(2)} m matches ${match.kind} "${match.name}" (${suggestEntityPrimaryLength(match).toFixed(2)} m).`,
          'No action needed.', null);
      }
      break;
    }
    case 'door': {
      const host = entity.wallId ? entities.find(w => w.id === entity.wallId) : null;
      if (!host) {
        push('low', 'Door has no verified host wall',
          `"${entity.name}" is not linked to a wall segment in this document.`,
          'Re-place it on a wall so swing and clearance stay valid.', 'door');
      }
      break;
    }
    case 'furniture': {
      const hostRoom = entities.find(r => r.kind === 'room' &&
        entity.x >= r.x - 0.01 && entity.x <= r.x + r.width + 0.01 &&
        entity.y >= r.y - 0.01 && entity.y <= r.y + r.depth + 0.01);
      if (!hostRoom) {
        push('low', 'Furniture placed outside any room',
          `"${entity.name}" does not sit inside a room boundary.`,
          'Move it into a room for clearance and density checks.', 'move');
      }
      break;
    }
    default:
      break;
  }
  return out.sort((a, b) => sev(a.severity) - sev(b.severity));
}

/**
 * Whole-document suggestions: overlaps, undimensioned walls, extreme rooms,
 * non-compliant stairs/ramps, unplaced furniture.
 */
function suggestForDocument(entities = []) {
  const out = [];
  const push = (severity, problem, evidence, recommendation, toolId) =>
    out.push({ severity, problem, evidence, recommendation, toolId });

  const rooms = entities.filter(e => e.kind === 'room');
  const walls = entities.filter(e => e.kind === 'wall');
  const stairs = entities.filter(e => e.kind === 'stair');
  const ramps = entities.filter(e => e.kind === 'ramp');

  const roomOverlaps = [];
  for (let i = 0; i < rooms.length; i++) {
    for (let j = i + 1; j < rooms.length; j++) {
      const a = rooms[i], b = rooms[j];
      const ox = Math.min(a.x + a.width, b.x + b.width) - Math.max(a.x, b.x);
      const oy = Math.min(a.y + a.depth, b.y + b.depth) - Math.max(a.y, b.y);
      if (ox > 0.02 && oy > 0.02) roomOverlaps.push({ a, b, ox, oy });
    }
  }
  if (roomOverlaps.length > 0) {
    push('high', 'Room footprints overlap',
      `${roomOverlaps.length} overlapping room pair(s), e.g. "${roomOverlaps[0].a.name}" × "${roomOverlaps[0].b.name}" (${(roomOverlaps[0].ox * roomOverlaps[0].oy).toFixed(1)} m² shared).`,
      'Resolve the overlap before area schedules are trusted.', 'select');
  }

  const undimensioned = walls.filter(w => !entities.some(d => d.kind === 'dimension' && suggestDimensionOnWall(d, w)));
  if (walls.length > 2 && undimensioned.length > walls.length / 2) {
    push('medium', 'Most walls are undimensioned',
      `${undimensioned.length} of ${walls.length} walls carry no dimension on their endpoints.`,
      'Run dimension chains or DIMLIN per wall for layout.', 'dimension');
  }

  for (const s of stairs) {
    const blondel = typeof s.blondel === 'number' ? s.blondel : 2 * (s.riserHeight || 0) + (s.tread || 0);
    if (blondel > 0 && (blondel < BLONDEL_MIN || blondel > BLONDEL_MAX)) {
      out.push(...suggestForEntity(s, entities));
      break; // one representative stair finding keeps the list scannable
    }
  }
  for (const r of ramps) {
    if (typeof r.slopePercent === 'number' && r.slopePercent > RAMP_MAX_SLOPE + 0.05) {
      out.push(...suggestForEntity(r, entities));
      break;
    }
  }

  const orphanFurniture = entities.filter(f => f.kind === 'furniture' &&
    !rooms.some(r => f.x >= r.x - 0.01 && f.x <= r.x + r.width + 0.01 && f.y >= r.y - 0.01 && f.y <= r.y + r.depth + 0.01));
  if (orphanFurniture.length > 0) {
    push('low', 'Furniture outside room boundaries',
      `${orphanFurniture.length} piece(s) not inside any room (e.g. "${orphanFurniture[0].name}").`,
      'Move into rooms so clearance/density checks apply.', 'move');
  }

  if (rooms.length > 0 && entities.filter(e => e.kind === 'dimension').length === 0) {
    push('medium', 'Plan has zero dimensions',
      `${rooms.length} room(s) but no dimension entities anywhere in the document.`,
      'Add overall + room dimensions before issuing the plan.', 'dimension');
  }

  return out.sort((a, b) => sev(a.severity) - sev(b.severity));
}

// --- helpers ---------------------------------------------------------------

function suggestDimensionValue(d) {
  const p1 = d.p1 || { x: d.x1, y: d.y1 };
  const p2 = d.p2 || { x: d.x2, y: d.y2 };
  if (typeof p1?.x !== 'number' || typeof p2?.x !== 'number') return NaN;
  return Math.hypot(p2.x - p1.x, p2.y - p1.y);
}

function suggestDimensionOnWall(d, wall) {
  const p1 = d.p1 || { x: d.x1, y: d.y1 };
  const p2 = d.p2 || { x: d.x2, y: d.y2 };
  const near = (p, q) => Math.hypot(p.x - q.x, p.y - q.y) < 0.05;
  return (near(p1, { x: wall.x1, y: wall.y1 }) && near(p2, { x: wall.x2, y: wall.y2 })) ||
         (near(p1, { x: wall.x2, y: wall.y2 }) && near(p2, { x: wall.x1, y: wall.y1 }));
}

function suggestDimensionNearRoom(d, room) {
  const p1 = d.p1 || { x: d.x1, y: d.y1 };
  const p2 = d.p2 || { x: d.x2, y: d.y2 };
  const nearEdge = p => Math.abs(p.x - room.x) < 0.05 || Math.abs(p.x - (room.x + room.width)) < 0.05 ||
                        Math.abs(p.y - room.y) < 0.05 || Math.abs(p.y - (room.y + room.depth)) < 0.05;
  return nearEdge(p1) && nearEdge(p2);
}

function sharesEndpoint(w, other) {
  const near = (a, b) => Math.hypot(a.x - b.x, a.y - b.y) < 0.05;
  const pts = [{ x: other.x1, y: other.y1 }, { x: other.x2, y: other.y2 }];
  return [{ x: w.x1, y: w.y1 }, { x: w.x2, y: w.y2 }].some(p => pts.some(q => near(p, q)));
}

function suggestEntityPrimaryLength(e) {
  if (e.kind === 'wall' || e.kind === 'line') return wallLength(e);
  if (e.kind === 'room') return typeof e.width === 'number' ? e.width : 0;
  return 0;
}


  // =========================================================================
  // MODULE: Constraints
  // =========================================================================

/**
 * Architecture Helping Hand — Deterministic Constraint System
 *
 * Named architectural constraints recorded on the document and enforced by a
 * single-pass deterministic solver. NO general-purpose solver, NO iteration:
 * each constraint type has one well-defined enforcement rule. When a
 * constraint cannot be satisfied, the solver returns a CONFLICT with possible
 * resolutions — it never silently distorts geometry.
 *
 * Constraint changes are plain data; the caller (plan workspace) wraps
 * enforcement in its transaction/undo system.
 */



const CONSTRAINT_TYPES = Object.freeze({
  HORIZONTAL: 'horizontal',          // segment forced horizontal
  VERTICAL: 'vertical',              // segment forced vertical
  PARALLEL: 'parallel',              // two segments parallel
  PERPENDICULAR: 'perpendicular',    // two segments perpendicular
  EQUAL_LENGTH: 'equal_length',      // two segments same length
  FIXED_DISTANCE: 'fixed_distance',  // segment held at a fixed length
  FIXED_ANGLE: 'fixed_angle',        // segment at fixed angle (degrees)
  WALL_THICKNESS: 'wall_thickness',  // wall thickness = value
  DOOR_WIDTH: 'door_width',          // door width = value
  WINDOW_WIDTH: 'window_width',      // window width = value
  ROOM_MIN_AREA: 'room_min_area',    // room area >= value (grows depth)
  CORRIDOR_MIN_WIDTH: 'corridor_min_width', // parallel wall gap >= value
  STAIR_RISE: 'stair_rise',          // stair riser height = value
  STAIR_TREAD: 'stair_tread',        // stair tread depth = value
  CLEARANCE_ENVELOPE: 'clearance_envelope' // clearance around object >= value
});

const CONSTRAINT_STATUS = Object.freeze({
  SATISFIED: 'satisfied',   // already true, nothing changed
  ADJUSTED: 'adjusted',     // deterministic change applied
  CONFLICT: 'conflict'      // cannot satisfy — geometry untouched
});

let constraintCounter = 0;

/** Creates a named constraint record (data only — enforcement is separate). */
function createConstraint(type, targetIds, params = {}) {
  // Accept either the enum key (WALL_THICKNESS) or its value (wall_thickness)
  const known = Object.values(CONSTRAINT_TYPES).includes(type);
  if (!known) {
    throw new Error(`Unknown constraint type "${type}" — allowed: ${Object.values(CONSTRAINT_TYPES).join(', ')}`);
  }
  if (!Array.isArray(targetIds) || targetIds.length === 0) {
    throw new Error('Constraint requires at least one target entity id');
  }
  constraintCounter += 1;
  return {
    id: `con-${Date.now().toString(36)}-${constraintCounter}`,
    type,
    targetIds: [...targetIds],
    params: { ...params },
    status: CONSTRAINT_STATUS.SATISFIED,
    message: ''
  };
}

function entityById(entities, id) {
  return entities.find(e => e && e.id === id) || null;
}

function segmentOf(entity) {
  if (entity.kind === 'wall' || entity.kind === 'line' || entity.kind === 'dimension') {
    return { p1: { x: entity.x1, y: entity.y1 }, p2: { x: entity.x2, y: entity.y2 } };
  }
  return null;
}

/**
 * Attempts to satisfy one constraint against the entity list.
 * Returns the constraint with `status` + `message` set. On CONFLICT the
 * solver also returns `resolutions: string[]` — geometry is NOT modified.
 */
function solveConstraint(constraint, entities) {
  const targets = constraint.targetIds.map(id => entityById(entities, id));
  if (targets.some(t => !t)) {
    constraint.status = CONSTRAINT_STATUS.CONFLICT;
    constraint.message = 'Referenced entity not found in the document.';
    return constraint;
  }

  const p = constraint.params || {};
  switch (constraint.type) {
    case CONSTRAINT_TYPES.HORIZONTAL:
    case CONSTRAINT_TYPES.VERTICAL: {
      const seg = segmentOf(targets[0]);
      if (!seg) { conflict(constraint, `${targets[0].kind} has no segment geometry.`); return constraint; }
      const mid = { x: (seg.p1.x + seg.p2.x) / 2, y: (seg.p1.y + seg.p2.y) / 2 };
      const len = distance(seg.p1, seg.p2);
      if (constraint.type === CONSTRAINT_TYPES.HORIZONTAL) {
        targets[0].x1 = mid.x - len / 2; targets[0].y1 = mid.y;
        targets[0].x2 = mid.x + len / 2; targets[0].y2 = mid.y;
      } else {
        targets[0].x1 = mid.x; targets[0].y1 = mid.y - len / 2;
        targets[0].x2 = mid.x; targets[0].y2 = mid.y + len / 2;
      }
      satisfy(constraint, `${constraint.type} applied about the segment midpoint.`);
      return constraint;
    }

    case CONSTRAINT_TYPES.PARALLEL:
    case CONSTRAINT_TYPES.PERPENDICULAR: {
      if (targets.length < 2) { conflict(constraint, 'Requires two segment entities.'); return constraint; }
      const s1 = segmentOf(targets[0]);
      const s2 = segmentOf(targets[1]);
      if (!s1 || !s2) { conflict(constraint, 'Both targets need segment geometry.'); return constraint; }
      const angle = (constraint.type === CONSTRAINT_TYPES.PARALLEL)
        ? Math.atan2(s1.p2.y - s1.p1.y, s1.p2.x - s1.p1.x)
        : Math.atan2(s1.p2.y - s1.p1.y, s1.p2.x - s1.p1.x) + Math.PI / 2;
      const len = distance(s2.p1, s2.p2);
      const mid = { x: (s2.p1.x + s2.p2.x) / 2, y: (s2.p1.y + s2.p2.y) / 2 };
      targets[1].x1 = mid.x - Math.cos(angle) * len / 2;
      targets[1].y1 = mid.y - Math.sin(angle) * len / 2;
      targets[1].x2 = mid.x + Math.cos(angle) * len / 2;
      targets[1].y2 = mid.y + Math.sin(angle) * len / 2;
      satisfy(constraint, `${constraint.type} applied to the second segment.`);
      return constraint;
    }

    case CONSTRAINT_TYPES.EQUAL_LENGTH: {
      if (targets.length < 2) { conflict(constraint, 'Requires two segment entities.'); return constraint; }
      const a = segmentOf(targets[0]);
      const b = segmentOf(targets[1]);
      if (!a || !b) { conflict(constraint, 'Both targets need segment geometry.'); return constraint; }
      const targetLen = (distance(a.p1, a.p2) + distance(b.p1, b.p2)) / 2;
      applySegmentLength(targets[1], targetLen);
      satisfy(constraint, `Both segments set to ${targetLen.toFixed(2)} m (average).`);
      return constraint;
    }

    case CONSTRAINT_TYPES.FIXED_DISTANCE: {
      const seg = segmentOf(targets[0]);
      if (!seg) { conflict(constraint, 'Target needs segment geometry.'); return constraint; }
      const value = Number(p.value);
      if (!(value > 0)) {
        conflict(constraint, 'A positive length is required.',
          ['Provide the required distance in meters, e.g. 3.5.']);
        return constraint;
      }
      applySegmentLength(targets[0], value);
      satisfy(constraint, `Segment set to ${value.toFixed(2)} m.`);
      return constraint;
    }

    case CONSTRAINT_TYPES.FIXED_ANGLE: {
      const seg = segmentOf(targets[0]);
      if (!seg) { conflict(constraint, 'Target needs segment geometry.'); return constraint; }
      const angleDeg = Number(p.angle);
      if (!Number.isFinite(angleDeg)) {
        conflict(constraint, 'A fixed angle in degrees is required.',
          ['Provide the angle in degrees, e.g. 45.']);
        return constraint;
      }
      const len = distance(seg.p1, seg.p2);
      const rad = (angleDeg * Math.PI) / 180;
      targets[0].x2 = seg.p1.x + Math.cos(rad) * len;
      targets[0].y2 = seg.p1.y + Math.sin(rad) * len;
      satisfy(constraint, `Segment angle set to ${angleDeg}°.`);
      return constraint;
    }

    case CONSTRAINT_TYPES.WALL_THICKNESS: {
      const wall = targets[0];
      if (wall.kind !== 'wall') { conflict(constraint, 'Target must be a wall.'); return constraint; }
      const t = Number(p.thickness);
      if (!(t >= 0.05 && t <= 2)) {
        conflict(constraint, `Wall thickness ${t} m is outside the buildable range.`,
          ['Use a thickness between 0.05 m and 2 m.']);
        return constraint;
      }
      wall.thickness = t;
      satisfy(constraint, `Wall thickness set to ${(t * 1000).toFixed(0)} mm.`);
      return constraint;
    }

    case CONSTRAINT_TYPES.DOOR_WIDTH:
    case CONSTRAINT_TYPES.WINDOW_WIDTH: {
      const opening = targets[0];
      if (opening.kind !== 'door' && opening.kind !== 'window') {
        conflict(constraint, 'Target must be a door or window.'); return constraint;
      }
      const width = Number(p.width);
      const wall = entityById(entities, opening.wallId);
      if (wall) {
        const wallLen = distance({ x: wall.x1, y: wall.y1 }, { x: wall.x2, y: wall.y2 });
        if (width >= wallLen) {
          conflict(constraint, `${width.toFixed(2)} m opening does not fit in a ${wallLen.toFixed(2)} m wall.`,
            [`Shorten the opening below ${wallLen.toFixed(2)} m, or lengthen the wall.`]);
          return constraint;
        }
      }
      opening.width = width;
      satisfy(constraint, `${opening.kind} width set to ${(width * 1000).toFixed(0)} mm.`);
      return constraint;
    }

    case CONSTRAINT_TYPES.ROOM_MIN_AREA: {
      const room = targets[0];
      if (room.kind !== 'room') { conflict(constraint, 'Target must be a room.'); return constraint; }
      const minArea = Number(p.minArea);
      const area = (room.width || 0) * (room.depth || 0);
      if (!(minArea > 0)) {
        conflict(constraint, 'A positive minimum area is required.', ['e.g. minArea=9.5']); return constraint;
      }
      if (area >= minArea) {
        satisfy(constraint, `Room area ${area.toFixed(1)} m² already meets the ${minArea.toFixed(1)} m² minimum.`);
        return constraint;
      }
      // deterministic growth: scale depth (keep width), centered on the room
      const neededDepth = minArea / room.width;
      const dy = neededDepth - room.depth;
      room.y -= dy / 2;
      room.depth = neededDepth;
      if (Array.isArray(room.boundary) && room.boundary.length >= 3) {
        // rescale the polygon too, about its vertical center, so the boundary
        // stays consistent with the width/depth fields (no mixed geometry)
        const ys = room.boundary.map(p => p.y);
        const cy = (Math.min(...ys) + Math.max(...ys)) / 2;
        const oldSpan = Math.max(...ys) - Math.min(...ys);
        const sy = oldSpan > 1e-9 ? neededDepth / oldSpan : 1;
        room.boundary = room.boundary.map(p => ({ x: p.x, y: cy + (p.y - cy) * sy }));
      }
      satisfy(constraint, `Room depth grown to ${neededDepth.toFixed(2)} m → ${minArea >= 0 ? minArea.toFixed(1) : ''} m² minimum met.`);
      return constraint;
    }

    case CONSTRAINT_TYPES.CORRIDOR_MIN_WIDTH: {
      if (targets.length < 2) { conflict(constraint, 'Requires the two corridor walls.'); return constraint; }
      const s1 = segmentOf(targets[0]);
      const s2 = segmentOf(targets[1]);
      if (!s1 || !s2) { conflict(constraint, 'Both targets need segment geometry.'); return constraint; }
      // perpendicular distance from s2 midpoint to wall 1
      const mid = { x: (s2.p1.x + s2.p2.x) / 2, y: (s2.p1.y + s2.p2.y) / 2 };
      const dirLen = distance(s1.p1, s1.p2);
      if (dirLen < 1e-9) { conflict(constraint, 'First wall has zero length.'); return constraint; }
      const nx = -(s1.p2.y - s1.p1.y) / dirLen;
      const ny = (s1.p2.x - s1.p1.x) / dirLen;
      const signed = (mid.x - s1.p1.x) * nx + (mid.y - s1.p1.y) * ny;
      const minW = Number(p.minWidth);
      if (!(minW > 0)) {
        conflict(constraint, 'A positive minimum width is required.', ['e.g. minWidth=1.2']);
        return constraint;
      }
      if (Math.abs(signed) >= minW) {
        satisfy(constraint, `Corridor width ${Math.abs(signed).toFixed(2)} m already meets the ${minW.toFixed(2)} m minimum.`);
        return constraint;
      }
      // move wall 2 outward along the normal to meet the minimum
      const shift = (minW - Math.abs(signed)) * Math.sign(signed || 1);
      targets[1].x1 += nx * shift; targets[1].y1 += ny * shift;
      targets[1].x2 += nx * shift; targets[1].y2 += ny * shift;
      satisfy(constraint, `Second wall moved ${(shift).toFixed(2)} m → corridor width ${minW.toFixed(2)} m.`);
      return constraint;
    }

    case CONSTRAINT_TYPES.STAIR_RISE:
    case CONSTRAINT_TYPES.STAIR_TREAD: {
      const stair = targets[0];
      if (stair.kind !== 'stair') { conflict(constraint, 'Target must be a stair.'); return constraint; }
      const value = Number(p.value ?? (constraint.type === CONSTRAINT_TYPES.STAIR_RISE ? p.rise : p.tread));
      if (!(value > 0)) {
        conflict(constraint, 'A positive value in meters is required.', ['e.g. 0.17 for a 170 mm riser']);
        return constraint;
      }
      if (constraint.type === CONSTRAINT_TYPES.STAIR_RISE) stair.riserHeight = value;
      else stair.tread = value;
      stair.blondel = 2 * (stair.riserHeight || 0) + (stair.tread || 0);
      satisfy(constraint, `Stair ${constraint.type === CONSTRAINT_TYPES.STAIR_RISE ? 'riser' : 'tread'} set to ${(value * 1000).toFixed(0)} mm.`);
      return constraint;
    }

    case CONSTRAINT_TYPES.CLEARANCE_ENVELOPE: {
      const obj = targets[0];
      const wall = targets[1] || entityById(entities, obj?.wallId);
      if (!obj || !wall) { conflict(constraint, 'Requires an object and a reference wall.'); return constraint; }
      const minClear = Number(p.minClearance);
      if (!(minClear > 0)) {
        conflict(constraint, 'A positive clearance is required.', ['e.g. minClearance=0.9']);
        return constraint;
      }
      const objBox = { x: obj.x ?? 0, y: obj.y ?? 0, w: obj.width ?? 0, d: obj.depth ?? 0 };
      const wBox = { x1: wall.x1, y1: wall.y1, x2: wall.x2, y2: wall.y2 };
      // vertical/horizontal walls only (deterministic scope)
      const verticalWall = Math.abs(wBox.x1 - wBox.x2) < 1e-9;
      const dist = verticalWall ? Math.abs(objBox.x - wBox.x1) : Math.abs(objBox.y - wBox.y1);
      if (dist >= minClear) {
        satisfy(constraint, `Clearance ${dist.toFixed(2)} m already meets the ${minClear.toFixed(2)} m envelope.`);
        return constraint;
      }
      const shift = minClear - dist;
      if (verticalWall) obj.x += shift * Math.sign(obj.x - wBox.x1 || 1);
      else obj.y += shift * Math.sign(obj.y - wBox.y1 || 1);
      satisfy(constraint, `Object moved ${(shift).toFixed(2)} m away — ${minClear.toFixed(2)} m clearance met.`);
      return constraint;
    }

    default:
      conflict(constraint, `No deterministic enforcement rule for "${constraint.type}".`);
      return constraint;
  }

  function satisfy(c, message) {
    c.status = CONSTRAINT_STATUS.SATISFIED;
    c.message = message;
  }
  function conflict(c, message, resolutions = []) {
    c.status = CONSTRAINT_STATUS.CONFLICT;
    c.message = message;
    c.resolutions = resolutions;
  }
  function applySegmentLength(entity, len) {
    const seg = segmentOf(entity);
    const cur = distance(seg.p1, seg.p2);
    if (cur < 1e-9) {
      entity.x2 = entity.x1 + len;
      entity.y2 = entity.y1;
      return;
    }
    const ux = (seg.p2.x - seg.p1.x) / cur;
    const uy = (seg.p2.y - seg.p1.y) / cur;
    entity.x2 = entity.x1 + ux * len;
    entity.y2 = entity.y1 + uy * len;
  }
}

/**
 * Solves a list of constraints in order (single deterministic pass —
 * later constraints see the results of earlier ones). Returns a report.
 */
function solveConstraints(constraints, entities) {
  const report = { satisfied: 0, adjusted: 0, conflicts: 0, results: [] };
  for (const c of constraints || []) {
    solveConstraint(c, entities);
    report.results.push(c);
    if (c.status === CONSTRAINT_STATUS.CONFLICT) report.conflicts += 1;
    else if (c.status === CONSTRAINT_STATUS.ADJUSTED) report.adjusted += 1;
    else report.satisfied += 1;
  }
  return report;
}


  // =========================================================================
  // MODULE: Parametric
  // =========================================================================

/**
 * Architecture Helping Hand — Parametric Object Descriptors
 *
 * Typed parameters for architectural objects. Each parameter declares:
 *   name, label, unit, kind ('length'|'angle'|'enum'|'area'|'count'),
 *   get(entity), apply(entity, value), and optional min/max/derived flag.
 *
 * `apply` recomputes the FULL dependent chain (geometry + derived scalars +
 * compliance flags) so derived truth is never stale and the canvas, which
 * derives all rendering from these fields, regenerates automatically:
 *
 *   stair:   risers → riserHeight, run/depth, tread, pitch, Blondel, compliance
 *   door:    width → opening spans, jambs, swing radius (host wall punching
 *            is derived at render time via wallOpenings/punchWallSpans)
 *   window:  sill/head → height relationship
 *   room:    targetArea → deterministic depth growth (width preserved),
 *            polygon boundary rescaled consistently
 *
 * These descriptors are the single source of truth for the inspector UI,
 * the constraint system, and AI context.
 */

const PARAMETRIC_OBJECTS = Object.freeze({
  door: Object.freeze({
    label: 'Door',
    parameters: Object.freeze([
      { name: 'width', label: 'Width', unit: 'm', kind: 'length', min: 0.6, max: 2.5,
        get: e => e.width,
        apply: (e, v) => {
          e.width = v;
          recomputeDoor(e);
        } },
      { name: 'height', label: 'Height', unit: 'm', kind: 'length', min: 1.8, max: 2.7,
        get: e => e.height ?? 2.1,
        apply: (e, v) => { e.height = v; } },
      { name: 'swing', label: 'Swing', unit: '', kind: 'enum', values: ['left', 'right'],
        get: e => e.swing || 'left',
        apply: (e, v) => { e.swing = v === 'right' ? 'right' : 'left'; } },
      { name: 'flipSide', label: 'Hinge', unit: '', kind: 'enum', values: ['near', 'far'],
        get: e => e.flipSide ? 'far' : 'near',
        apply: (e, v) => { e.flipSide = v === 'far'; } },
      { name: 'wallId', label: 'Host wall', unit: '', kind: 'reference',
        get: e => e.wallId || null,
        apply: (e, v) => { e.wallId = v; } }
    ])
  }),
  window: Object.freeze({
    label: 'Window',
    parameters: Object.freeze([
      { name: 'width', label: 'Width', unit: 'm', kind: 'length', min: 0.4, max: 4,
        get: e => e.width,
        apply: (e, v) => {
          e.width = v;
          recomputeWindow(e);
        } },
      { name: 'sill', label: 'Sill height', unit: 'm', kind: 'length', min: 0, max: 2,
        get: e => e.sill ?? 0.9,
        apply: (e, v) => {
          e.sill = v;
          recomputeWindow(e);
        } },
      { name: 'head', label: 'Head height', unit: 'm', kind: 'length', min: 0.5, max: 4,
        get: e => (e.sill ?? 0.9) + (e.height ?? 1.2),
        apply: (e, v) => {
          e.height = Math.max(0.1, v - (e.sill ?? 0.9));
          recomputeWindow(e);
        } },
      { name: 'wallId', label: 'Host wall', unit: '', kind: 'reference',
        get: e => e.wallId || null,
        apply: (e, v) => { e.wallId = v; } }
    ])
  }),
  stair: Object.freeze({
    label: 'Stair',
    parameters: Object.freeze([
      { name: 'risers', label: 'Riser count', unit: '', kind: 'count', min: 3, max: 50,
        get: e => e.risers ?? 16,
        apply: (e, v) => {
          e.risers = Math.round(v);
          recomputeStair(e);
        } },
      { name: 'riserHeight', label: 'Riser height', unit: 'm', kind: 'length', min: 0.1, max: 0.25,
        get: e => e.riserHeight ?? 0.175,
        apply: (e, v) => {
          // rise is the driver: new riser count = rise / riser height
          if (typeof e.rise === 'number' && e.rise > 0) {
            e.risers = Math.max(3, Math.round(e.rise / v));
          }
          recomputeStair(e);
        } },
      { name: 'tread', label: 'Tread depth', unit: 'm', kind: 'length', min: 0.2, max: 0.45,
        get: e => e.tread ?? 0.28,
        apply: (e, v) => {
          e.tread = v;
          recomputeStair(e);
        } },
      { name: 'width', label: 'Flight width', unit: 'm', kind: 'length', min: 0.6, max: 4,
        get: e => e.width ?? 1.1,
        apply: (e, v) => { e.width = v; } },
      { name: 'blondel', label: 'Blondel 2R+T', unit: 'm', kind: 'length', derived: true,
        get: e => e.blondel ?? (2 * (e.riserHeight ?? 0.175) + (e.tread ?? 0.28)),
        apply: () => { throw new Error('Blondel 2R+T is derived — set riser height and tread instead.'); } },
      { name: 'run', label: 'Total run', unit: 'm', kind: 'length', derived: true,
        get: e => e.run ?? ((e.risers ?? 16) - 1) * (e.tread ?? 0.28),
        apply: () => { throw new Error('Total run is derived — set tread depth or riser count instead.'); } }
    ])
  }),
  room: Object.freeze({
    label: 'Room',
    parameters: Object.freeze([
      { name: 'name', label: 'Name', unit: '', kind: 'string',
        get: e => e.name || '',
        apply: (e, v) => { e.name = String(v).trim() || e.name; } },
      { name: 'width', label: 'Width', unit: 'm', kind: 'length', min: 0.3, max: 100,
        get: e => e.width ?? 0,
        apply: (e, v) => {
          e.width = v;
          recomputeRoom(e);
        } },
      { name: 'depth', label: 'Depth', unit: 'm', kind: 'length', min: 0.3, max: 100,
        get: e => e.depth ?? 0,
        apply: (e, v) => {
          e.depth = v;
          recomputeRoom(e);
        } },
      { name: 'targetArea', label: 'Target area', unit: 'm²', kind: 'area', min: 1, max: 10000,
        get: e => (e.width ?? 0) * (e.depth ?? 0),
        apply: (e, v) => {
          // keep width, grow depth to the target area (deterministic);
          // polygon boundaries rescale consistently — never mixed geometry
          if ((e.width ?? 0) > 0.1) e.depth = v / e.width;
          recomputeRoom(e);
        } },
      { name: 'type', label: 'Room type', unit: '', kind: 'string',
        get: e => e.zoning || '',
        apply: (e, v) => { e.zoning = v; } }
    ])
  }),
  wall: Object.freeze({
    label: 'Wall',
    parameters: Object.freeze([
      { name: 'thickness', label: 'Thickness', unit: 'm', kind: 'length', min: 0.05, max: 2,
        get: e => e.thickness ?? 0.2,
        apply: (e, v) => { e.thickness = v; } },
      { name: 'height', label: 'Height', unit: 'm', kind: 'length', min: 1, max: 10,
        get: e => e.height ?? 2.7,
        apply: (e, v) => { e.height = v; } },
      { name: 'assemblyId', label: 'Assembly', unit: '', kind: 'string',
        get: e => e.assemblyId || 'generic-200',
        apply: (e, v) => { e.assemblyId = v; } }
    ])
  })
});

// ---------------------------------------------------------------------------
// Dependent-chain recompute — one per object family. All fields the canvas
// and engines read are regenerated here so nothing stays stale.
// ---------------------------------------------------------------------------

function recomputeStair(stair) {
  const risers = Math.max(1, Math.round(stair.risers ?? 16));
  const rise = typeof stair.rise === 'number' && stair.rise > 0 ? stair.rise : 2.7;
  const tread = stair.tread ?? 0.28;
  const riserHeight = rise / risers;
  const run = risers > 1 ? (risers - 1) * tread : tread;
  const blondel = 2 * riserHeight + tread;

  stair.risers = risers;
  stair.riserCount = risers; // legacy alias kept in sync
  stair.rise = rise;
  stair.totalRise = rise;
  stair.riserHeight = riserHeight;
  stair.riser = riserHeight;
  stair.tread = tread;
  stair.going = tread;
  stair.run = run;
  stair.depth = run; // plan footprint depth follows the run
  stair.blondel = blondel;
  stair.pitchAngle = Math.atan2(riserHeight, tread) * (180 / Math.PI);
  // IBC heuristics (same band the factory uses)
  stair.isCompliant = blondel >= 0.60 && blondel <= 0.66 && tread >= 0.24 && riserHeight <= 0.19;
}

function recomputeDoor(door) {
  // Rendering derives jambs/swing from width+position+swing at draw time
  // (calcDoorCADGeometry); what stays stale is the door's own dimension
  // label and any fit data. Recompute the label so measurements stay true.
  door.name = door.name && !/^\s*Door(\s*\(\d+(\.\d+)?m\))?\s*$/.test(door.name)
    ? door.name
    : `Door (${door.width.toFixed(2)}m)`;
}

function recomputeWindow(win) {
  // head = sill + height stays a consistent triple; label follows width
  win.headHeight = (win.sill ?? 0.9) + (win.height ?? 1.2);
  win.name = win.name && !/^\s*Window(\s*\(\d+(\.\d+)?m\))?\s*$/.test(win.name)
    ? win.name
    : `Window (${win.width.toFixed(2)}m)`;
}

function recomputeRoom(room) {
  const w = room.width ?? 0;
  const d = room.depth ?? 0;
  const area = w * d;
  room.area = area;
  if (Array.isArray(room.boundary) && room.boundary.length >= 3) {
    // rescale boundary about its center so the polygon matches w×d
    const xs = room.boundary.map(p => p.x);
    const ys = room.boundary.map(p => p.y);
    const minX = Math.min(...xs), maxX = Math.max(...xs);
    const minY = Math.min(...ys), maxY = Math.max(...ys);
    const oldW = maxX - minX, oldH = maxY - minY;
    const cx = (minX + maxX) / 2, cy = (minY + maxY) / 2;
    const sx = oldW > 1e-9 ? w / oldW : 1;
    const sy = oldH > 1e-9 ? d / oldH : 1;
    room.boundary = room.boundary.map(p => ({ x: cx + (p.x - cx) * sx, y: cy + (p.y - cy) * sy }));
  }
}

/** Parameter descriptors for an entity kind (null when unknown). */
function getParametersFor(kind) {
  return PARAMETRIC_OBJECTS[kind]?.parameters || null;
}

/** Reads all parameter values of an entity as a plain record. */
function readParameters(entity) {
  const params = getParametersFor(entity?.kind);
  if (!params) return null;
  const out = {};
  for (const p of params) out[p.name] = p.get(entity);
  return out;
}

/**
 * Applies one parameter by name. Returns
 *   { ok: true, changed: [name] } |
 *   { ok: false, error, expected? }
 * Throws only for programming errors (unknown kind); user errors are values.
 */
function applyParameter(entity, name, value) {
  const params = getParametersFor(entity?.kind);
  if (!params) return { ok: false, error: `No parameters defined for "${entity?.kind}".` };
  const param = params.find(p => p.name === name);
  if (!param) {
    const names = params.map(p => p.name).join(', ');
    return { ok: false, error: `Unknown parameter "${name}" — available: ${names}.` };
  }
  if (param.derived) {
    return { ok: false, error: `"${param.label}" is derived — set the driving parameters instead.` };
  }
  if (param.kind === 'length' || param.kind === 'area') {
    const v = Number(value);
    if (!Number.isFinite(v)) {
      return { ok: false, error: `${param.label} must be a number in ${param.unit || 'm'} — e.g. ${param.fallbackExample || param.min}.` };
    }
    if (v < param.min || v > param.max) {
      return { ok: false, error: `${param.label} must be between ${param.min} and ${param.max} ${param.unit || ''}.` };
    }
    param.apply(entity, v);
    return { ok: true, changed: [name] };
  }
  if (param.kind === 'count') {
    const v = Math.round(Number(value));
    if (!Number.isFinite(v) || v < param.min || v > param.max) {
      return { ok: false, error: `${param.label} must be an integer between ${param.min} and ${param.max}.` };
    }
    param.apply(entity, v);
    return { ok: true, changed: [name] };
  }
  if (param.kind === 'enum') {
    const match = param.values.find(x => String(x).toLowerCase() === String(value).toLowerCase());
    if (!match) {
      return { ok: false, error: `${param.label} must be one of: ${param.values.join(', ')} (received "${value}").` };
    }
    param.apply(entity, match);
    return { ok: true, changed: [name] };
  }
  // string / reference
  param.apply(entity, value == null ? '' : value);
  return { ok: true, changed: [name] };
}


  // =========================================================================
  // MODULE: IssueEngine
  // =========================================================================

/**
 * Architecture Helping Hand — Deterministic Issue Engine
 *
 * A rule registry where every rule is an explicit record:
 *   { id, name, severity, scope, description, run(entities, context) }
 *
 * run() returns issue objects or null. Issues carry: id, severity, rule,
 * entityIds, location, evidence, message, recommendation, status, createdAt.
 * Every check is deterministic — same model in, same issues out. No AI.
 *
 * Status vocabulary: PASS | WARNING | FAIL | NOT_APPLICABLE | NEEDS_INPUT |
 * UNVERIFIED. The engine emits issues for WARNING/FAIL; PASS summaries come
 * from the report object.
 */




const ISSUE_SEVERITIES = Object.freeze(['critical', 'high', 'medium', 'low', 'info']);
const ISSUE_STATUS = Object.freeze(['FAIL', 'WARNING', 'PASS', 'NOT_APPLICABLE', 'NEEDS_INPUT', 'UNVERIFIED']);

let issueCounter = 0;
function issue(severity, rule, entityIds, location, evidence, message, recommendation) {
  issueCounter += 1;
  return {
    id: `iss-${Date.now().toString(36)}-${issueCounter}`,
    severity,
    rule,
    entityIds: [...entityIds],
    location: location ? { ...location } : null,
    evidence: { ...evidence },
    message,
    recommendation,
    status: severity === 'critical' || severity === 'high' ? 'FAIL' : 'WARNING',
    createdAt: new Date().toISOString()
  };
}

// ---------------------------------------------------------------------------
// Rule registry — every rule is explicit and self-describing
// ---------------------------------------------------------------------------

const RULES = [];
function rule(def, run) {
  RULES.push(Object.freeze({
    id: def.id, name: def.name, severity: def.severity, scope: def.scope,
    description: def.description, recommendedAction: def.recommendedAction,
    run
  }));
}

// --- Geometry rules ---------------------------------------------------------

rule(
  { id: 'geo.invalid', name: 'Invalid geometry', severity: 'critical', scope: 'entity',
    description: 'Entity fails basic geometric validity (zero length, bad boundary, missing host).',
    recommendedAction: 'Recreate the entity or correct its geometry.' },
  (entities, ctx) => {
    const issues = [];
    for (const e of entities) {
      const v = validateEntityGeometry(e);
      if (!v.valid) {
        issues.push(issue('critical', 'geo.invalid', [e.id],
          bboxOf(e), { violations: v.violations.map(x => x.message) },
          `${e.kind} "${e.name || e.id}" has invalid geometry: ${v.violations.map(x => x.message).join('; ')}.`,
          'Correct the geometry or delete and redraw the entity.'));
      }
    }
    return issues;
  }
);

rule(
  { id: 'geo.self_intersection', name: 'Self-intersecting boundary', severity: 'high', scope: 'entity',
    description: 'A room boundary crosses itself (bowtie shape).',
    recommendedAction: 'Re-trace the boundary so edges do not cross.' },
  (entities) => {
    const issues = [];
    for (const e of entities) {
      if (e.kind === 'room' && Array.isArray(e.boundary) && e.boundary.length >= 4) {
        if (polygonSelfIntersects(e.boundary)) {
          issues.push(issue('high', 'geo.self_intersection', [e.id], bboxOf(e),
            { vertices: e.boundary.length },
            `Room "${e.name}" boundary self-intersects — its area is not well defined.`,
            'Re-trace the room boundary so edges do not cross.'));
        }
      }
    }
    return issues;
  }
);

rule(
  { id: 'geo.duplicate', name: 'Duplicate entity', severity: 'medium', scope: 'document',
    description: 'Two entities of the same kind occupy the same position with the same size.',
    recommendedAction: 'Delete one of the duplicates.' },
  (entities) => {
    const issues = [];
    const boxes = new Map();
    const posKeyOf = (e) => {
      if (Number.isFinite(e.x1) && Number.isFinite(e.y1) && Number.isFinite(e.x2) && Number.isFinite(e.y2)) {
        return `${e.x1}|${e.y1}|${e.x2}|${e.y2}`;
      }
      if (Number.isFinite(e.x) && Number.isFinite(e.y)) return `${e.x}|${e.y}|${e.width ?? ''}|${e.depth ?? ''}`;
      return null; // hosted openings & other shapes: exact-position check n/a
    };
    for (const e of entities) {
      const key = posKeyOf(e);
      if (!key) continue;
      const fullKey = `${e.kind}|${key}`;
      if (boxes.has(fullKey)) {
        issues.push(issue('medium', 'geo.duplicate', [boxes.get(fullKey), e.id], bboxOf(e),
          { position: key, kind: e.kind },
          `Two ${e.kind} entities occupy the exact same position ("${entities.find(x => x.id === boxes.get(fullKey))?.name || boxes.get(fullKey)}" and "${e.name || e.id}").`,
          'Delete one of the duplicates.'));
      } else {
        boxes.set(fullKey, e.id);
      }
    }
    return issues;
  }
);

rule(
  { id: 'geo.overlap', name: 'Overlapping rooms', severity: 'high', scope: 'document',
    description: 'Two room footprints overlap.',
    recommendedAction: 'Move or resize one of the rooms.' },
  (entities) => {
    const issues = [];
    const rooms = entities.filter(e => e.kind === 'room' && typeof e.width === 'number');
    for (let i = 0; i < rooms.length; i++) {
      for (let j = i + 1; j < rooms.length; j++) {
        const a = rooms[i], b = rooms[j];
        const ox = Math.min(a.x + a.width, b.x + b.width) - Math.max(a.x, b.x);
        const oy = Math.min(a.y + a.depth, b.y + b.depth) - Math.max(a.y, b.y);
        if (ox > 0.02 && oy > 0.02) {
          issues.push(issue('high', 'geo.overlap', [a.id, b.id],
            { x: Math.max(a.x, b.x), y: Math.max(a.y, b.y) },
            { overlapArea: +(ox * oy).toFixed(2), a: a.name, b: b.name },
            `Rooms "${a.name}" and "${b.name}" overlap by ${(ox * oy).toFixed(1)} m².`,
            'Move or resize one room so footprints do not overlap.'));
        }
      }
    }
    return issues;
  }
);

rule(
  { id: 'geo.disconnected', name: 'Disconnected wall', severity: 'low', scope: 'entity',
    description: 'A wall shares no endpoint with any other wall.',
    recommendedAction: 'Snap the wall endpoint to the wall network or delete the stray wall.' },
  (entities) => {
    const issues = [];
    const walls = entities.filter(e => e.kind === 'wall');
    const near = (p, q) => Math.hypot(p.x - q.x, p.y - q.y) < 0.05;
    for (const w of walls) {
      const pts = [{ x: w.x1, y: w.y1 }, { x: w.x2, y: w.y2 }];
      const connected = walls.some(o => o !== w &&
        [{ x: o.x1, y: o.y1 }, { x: o.x2, y: o.y2 }].some(p => pts.some(q => near(p, q))));
      if (walls.length > 1 && !connected) {
        issues.push(issue('low', 'geo.disconnected', [w.id], bboxOf(w),
          { length: +Math.hypot(w.x2 - w.x1, w.y2 - w.y1).toFixed(2) },
          `Wall "${w.name}" shares no endpoint with any other wall.`,
          'Snap its endpoints onto the wall network or delete it.'));
      }
    }
    return issues;
  }
);

// --- Room rules --------------------------------------------------------------

rule(
  { id: 'room.min_area', name: 'Room below minimum area', severity: 'medium', scope: 'entity',
    description: 'Named habitable room is below the configured minimum area.',
    recommendedAction: 'Enlarge the room or adjust the minimum.' },
  (entities, ctx) => {
    const issues = [];
    const minArea = ctx?.roomMinArea ?? 7.5;
    for (const e of entities) {
      if (e.kind !== 'room' || !/bed/i.test(String(e.name || ''))) continue;
      const area = (e.width || 0) * (e.depth || 0);
      if (area > 0 && area < minArea) {
        issues.push(issue('medium', 'room.min_area', [e.id], bboxOf(e),
          { area: +area.toFixed(2), minimum: minArea },
          `Bedroom "${e.name}" is ${area.toFixed(1)} m², below the ${minArea} m² habitable minimum.`,
          `Enlarge the room (constraint: room_min_area) or rename it to match its actual use.`));
      }
    }
    return issues;
  }
);

rule(
  { id: 'room.proportion', name: 'Extreme room proportion', severity: 'low', scope: 'entity',
    description: 'Room aspect ratio exceeds 2.5:1.',
    recommendedAction: 'Re-proportion the room or introduce a partition.' },
  (entities) => {
    const issues = [];
    for (const e of entities) {
      if (e.kind !== 'room' || !(e.width > 0) || !(e.depth > 0)) continue;
      const ratio = Math.max(e.width, e.depth) / Math.min(e.width, e.depth);
      if (ratio > 2.5) {
        issues.push(issue('low', 'room.proportion', [e.id], bboxOf(e),
          { ratio: +ratio.toFixed(2), width: e.width, depth: e.depth },
          `Room "${e.name}" has an aspect ratio of ${ratio.toFixed(2)}:1 (over 2.5:1).`,
          'Re-proportion, add a partition, or accept the corridor-like proportion.'));
      }
    }
    return issues;
  }
);

rule(
  { id: 'room.missing_door', name: 'Room without a door', severity: 'medium', scope: 'entity',
    description: 'A room has no door opening on its bounds.',
    recommendedAction: 'Place a door on one of the bounding walls.' },
  (entities) => {
    const issues = [];
    const rooms = entities.filter(e => e.kind === 'room' && typeof e.width === 'number');
    for (const r of rooms) {
      const hasDoor = entities.some(d => d.kind === 'door' && openingInRoom(d, r, entities));
      if (!hasDoor) {
        issues.push(issue('medium', 'room.missing_door', [r.id], bboxOf(r),
          { room: r.name },
          `Room "${r.name}" has no door within its bounds.`,
          'Place a door on one of the bounding walls.'));
      }
    }
    return issues;
  }
);

rule(
  { id: 'room.missing_window', name: 'Habitable room without a window', severity: 'low', scope: 'entity',
    description: 'A bedroom/living room has no window (daylighting).',
    recommendedAction: 'Place a window on an exterior wall.' },
  (entities) => {
    const issues = [];
    for (const r of entities.filter(e => e.kind === 'room')) {
      if (!/bed|liv|living/i.test(String(r.name || ''))) continue;
      const hasWin = entities.some(w => w.kind === 'window' && openingInRoom(w, r, entities));
      if (!hasWin) {
        issues.push(issue('low', 'room.missing_window', [r.id], bboxOf(r),
          { room: r.name },
          `Habitable room "${r.name}" has no window.`,
          'Place a window on an exterior wall for daylighting.'));
      }
    }
    return issues;
  }
);

rule(
  { id: 'room.furniture_fit', name: 'Furniture outside its room', severity: 'low', scope: 'entity',
    description: 'Furniture footprint is not fully inside any room.',
    recommendedAction: 'Move the furniture into a room.' },
  (entities) => {
    const issues = [];
    const rooms = entities.filter(e => e.kind === 'room');
    for (const f of entities.filter(e => e.kind === 'furniture')) {
      const host = rooms.find(r => f.x >= r.x - 0.01 && f.x + f.width <= r.x + r.width + 0.01 &&
        f.y >= r.y - 0.01 && f.y + f.depth <= r.y + r.depth + 0.01);
      if (!host) {
        issues.push(issue('low', 'room.furniture_fit', [f.id], bboxOf(f),
          { furniture: f.name },
          `Furniture "${f.name}" is not fully inside a room.`,
          'Move it into a room (or accept it as free-placed).'));
      }
    }
    return issues;
  }
);

// --- Door / window rules ------------------------------------------------------

rule(
  { id: 'door.host', name: 'Door without host wall', severity: 'medium', scope: 'entity',
    description: 'A door is not hosted by a wall in this document.',
    recommendedAction: 'Re-place the door on a wall.' },
  (entities) => {
    const issues = [];
    for (const d of entities.filter(e => e.kind === 'door')) {
      const dp = openingWorldPoint(d, entities);
      const host = entities.find(w => w.kind === 'wall' &&
        (w.id === d.wallId || (dp && pointNearSegment(dp, w, 0.3))));
      if (!host) {
        issues.push(issue('medium', 'door.host', [d.id], bboxOf(d),
          { door: d.name },
          `Door "${d.name}" has no host wall at its position.`,
          'Re-place the door on a wall (doors snap to walls).'));
      }
    }
    return issues;
  }
);

rule(
  { id: 'door.clearance', name: 'Door swing blocked', severity: 'medium', scope: 'entity',
    description: 'Another object sits inside the door swing area.',
    recommendedAction: 'Move the obstruction or flip the swing.' },
  (entities) => {
    const issues = [];
    for (const d of entities.filter(e => e.kind === 'door')) {
      const dp = openingWorldPoint(d, entities);
      if (!dp) continue; // unhosted doors are flagged by door.host instead
      const swingR = (d.width || 0.9);
      const cx = dp.x + (d.swing === 'right' ? swingR : 0);
      const cy = dp.y - swingR;
      const blocker = entities.find(o => o !== d && o.kind === 'furniture' &&
        typeof o.x === 'number' &&
        o.x + o.width > cx - swingR && o.x < cx + swingR &&
        o.y + o.depth > Math.min(dp.y, cy) && o.y < Math.max(dp.y, cy));
      if (blocker) {
        issues.push(issue('medium', 'door.clearance', [d.id, blocker.id], bboxOf(d),
          { door: d.name, blockedBy: blocker.name, swingRadius: +swingR.toFixed(2) },
          `Door "${d.name}" swing area is blocked by "${blocker.name}".`,
          'Move the furniture or flip the door swing.'));
      }
    }
    return issues;
  }
);

rule(
  { id: 'window.host', name: 'Window without host wall', severity: 'medium', scope: 'entity',
    description: 'A window is not hosted by a wall in this document.',
    recommendedAction: 'Re-place the window on a wall.' },
  (entities) => {
    const issues = [];
    for (const w of entities.filter(e => e.kind === 'window')) {
      const wp = openingWorldPoint(w, entities);
      const host = entities.find(wall => wall.kind === 'wall' &&
        (wall.id === w.wallId || (wp && pointNearSegment(wp, wall, 0.3))));
      if (!host) {
        issues.push(issue('medium', 'window.host', [w.id], bboxOf(w),
          { window: w.name },
          `Window "${w.name}" has no host wall at its position.`,
          'Re-place the window on a wall.'));
      }
    }
    return issues;
  }
);

// --- Dimension rules -----------------------------------------------------------

rule(
  { id: 'dim.mismatch', name: 'Dimension does not match geometry', severity: 'medium', scope: 'entity',
    description: 'A recorded dimension equals no wall/line/room edge in the document.',
    recommendedAction: 'Re-measure with DIST and re-place the dimension.' },
  (entities) => {
    const issues = [];
    const measure = (d) => {
      const p1 = d.p1 || { x: d.x1, y: d.y1 };
      const p2 = d.p2 || { x: d.x2, y: d.y2 };
      return (typeof p1?.x === 'number' && typeof p2?.x === 'number')
        ? Math.hypot(p2.x - p1.x, p2.y - p1.y) : NaN;
    };
    const edgeLen = (t) => {
      if (t.kind === 'wall' || t.kind === 'line') return Math.hypot(t.x2 - t.x1, t.y2 - t.y1);
      if (t.kind === 'room') return t.width;
      return NaN;
    };
    for (const d of entities.filter(e => e.kind === 'dimension')) {
      const val = measure(d);
      if (!Number.isFinite(val)) continue;
      const match = entities.some(t => (t.kind === 'wall' || t.kind === 'line' || t.kind === 'room') &&
        Math.abs(edgeLen(t) - val) < 0.02);
      if (!match) {
        issues.push(issue('medium', 'dim.mismatch', [d.id], bboxOf(d),
          { recorded: +val.toFixed(3) },
          `Dimension ${val.toFixed(2)} m matches no wall/line/room edge.`,
          'Re-measure with DIST and re-place the dimension, or update the geometry.'));
      }
    }
    return issues;
  }
);

rule(
  { id: 'dim.duplicate', name: 'Duplicate dimensions', severity: 'low', scope: 'document',
    description: 'Two dimensions measure the same span at the same place.',
    recommendedAction: 'Delete one of the duplicates.' },
  (entities) => {
    const issues = [];
    const dims = entities.filter(e => e.kind === 'dimension');
    const seen = new Map();
    const measure = (d) => {
      const p1 = d.p1 || { x: d.x1, y: d.y1 };
      const p2 = d.p2 || { x: d.x2, y: d.y2 };
      return (typeof p1?.x === 'number') ? Math.hypot(p2.x - p1.x, p2.y - p1.y) : null;
    };
    for (const d of dims) {
      const key = `${Math.round((d.x ?? 0) * 10)}|${Math.round((d.y ?? 0) * 10)}|${measure(d)?.toFixed(2)}`;
      if (seen.has(key)) {
        issues.push(issue('low', 'dim.duplicate', [seen.get(key), d.id], bboxOf(d),
          { measured: measure(d)?.toFixed(2) },
          'Two dimensions measure the same span at the same place.',
          'Delete one of the duplicates.'));
      } else {
        seen.set(key, d.id);
      }
    }
    return issues;
  }
);

// --- Stair / ramp rules ---------------------------------------------------------

rule(
  { id: 'stair.blondel', name: 'Stair outside Blondel band', severity: 'medium', scope: 'entity',
    description: 'Stair 2R+T is outside the 600–660 mm comfort band.',
    recommendedAction: 'Adjust riser/tread with the Stair Calculator.' },
  (entities) => {
    const issues = [];
    for (const s of entities.filter(e => e.kind === 'stair')) {
      const blondel = typeof s.blondel === 'number' ? s.blondel : 2 * (s.riserHeight || 0) + (s.tread || 0);
      if (blondel > 0 && (blondel < 0.6 || blondel > 0.66)) {
        issues.push(issue('medium', 'stair.blondel', [s.id], bboxOf(s),
          { blondelMm: Math.round(blondel * 1000) },
          `Stair "${s.name}" 2R+T = ${Math.round(blondel * 1000)} mm (band 600–660 mm).`,
          'Adjust riser height and tread.'));
      }
    }
    return issues;
  }
);

rule(
  { id: 'stair.riser_high', name: 'Riser above maximum', severity: 'high', scope: 'entity',
    description: 'Stair riser exceeds 190 mm.',
    recommendedAction: 'Add risers to reduce the riser height.' },
  (entities) => {
    const issues = [];
    for (const s of entities.filter(e => e.kind === 'stair')) {
      const rh = s.riserHeight ?? 0;
      if (rh > 0.19) {
        issues.push(issue('high', 'stair.riser_high', [s.id], bboxOf(s),
          { riserMm: Math.round(rh * 1000) },
          `Stair "${s.name}" riser is ${Math.round(rh * 1000)} mm (over 190 mm).`,
          'Add risers to bring the riser height down.'));
      }
    }
    return issues;
  }
);

rule(
  { id: 'ramp.slope', name: 'Ramp steeper than 1:12', severity: 'high', scope: 'entity',
    description: 'Ramp slope exceeds the 8.33% accessibility maximum.',
    recommendedAction: 'Lengthen the run or add switchbacks.' },
  (entities) => {
    const issues = [];
    for (const r of entities.filter(e => e.kind === 'ramp')) {
      if (typeof r.slopePercent === 'number' && r.slopePercent > 8.33 + 0.05) {
        issues.push(issue('high', 'ramp.slope', [r.id], bboxOf(r),
          { slopePercent: +r.slopePercent.toFixed(2), ratio: `1:${(r.slopeRatio || 100 / r.slopePercent).toFixed(1)}` },
          `Ramp "${r.name}" is ${r.slopePercent.toFixed(2)}% (steeper than 1:12).`,
          'Lengthen the run or add switchbacks.'));
      }
    }
    return issues;
  }
);

// --- Documentation rules ---------------------------------------------------------

rule(
  { id: 'doc.missing_dimension', name: 'Undimensioned walls', severity: 'medium', scope: 'document',
    description: 'Most walls carry no dimension on their endpoints.',
    recommendedAction: 'Run dimension chains or DIMLIN per wall.' },
  (entities) => {
    const issues = [];
    const walls = entities.filter(e => e.kind === 'wall');
    if (walls.length < 3) return issues;
    const undimensioned = walls.filter(w => !entities.some(d => d.kind === 'dimension' && dimensionOnWall(d, w)));
    if (undimensioned.length > walls.length / 2) {
      issues.push(issue('medium', 'doc.missing_dimension',
        undimensioned.slice(0, 8).map(w => w.id), bboxOf(walls[0]),
        { undimensioned: undimensioned.length, total: walls.length },
        `${undimensioned.length} of ${walls.length} walls carry no dimension.`,
        'Add dimension chains or per-wall DIMLIN for construction layout.'));
    }
    return issues;
  }
);

rule(
  { id: 'doc.missing_north', name: 'No north arrow', severity: 'low', scope: 'document',
    description: 'The plan has no north arrow.',
    recommendedAction: 'Place a north arrow (north tool) for orientation.' },
  (entities) => {
    const hasNorth = entities.some(e => e.kind === 'north_arrow');
    if (!hasNorth && entities.filter(e => e.kind === 'room').length > 0) {
      return [issue('low', 'doc.missing_north', [], null,
        {}, 'The plan has no north arrow for orientation.',
        'Place a north arrow (north tool).')];
    }
    return [];
  }
);

rule(
  { id: 'doc.missing_annotation', name: 'Rooms without labels', severity: 'low', scope: 'document',
    description: 'Rooms carry default auto-generated names.',
    recommendedAction: 'Rename rooms to their functional names.' },
  (entities) => {
    const issues = [];
    for (const r of entities.filter(e => e.kind === 'room')) {
      if (/^Room \d+/.test(String(r.name || ''))) {
        issues.push(issue('low', 'doc.missing_annotation', [r.id], bboxOf(r),
          { name: r.name },
          `Room "${r.name}" still has its default generated name.`,
          'Rename it to its functional name (e.g. Bedroom, Kitchen).'));
      }
    }
    return issues;
  }
);

// --- helpers ---------------------------------------------------------------------

function bboxOf(e) {
  if (!e) return null;
  if (e.kind === 'wall' || e.kind === 'line' || e.kind === 'dimension') {
    const p1 = { x: e.x1 ?? e.p1?.x ?? 0, y: e.y1 ?? e.p1?.y ?? 0 };
    const p2 = { x: e.x2 ?? e.p2?.x ?? 0, y: e.y2 ?? e.p2?.y ?? 0 };
    return { x: Math.min(p1.x, p2.x), y: Math.min(p1.y, p2.y), width: Math.abs(p2.x - p1.x), depth: Math.abs(p2.y - p1.y) };
  }
  return { x: e.x ?? 0, y: e.y ?? 0, width: e.width ?? 0, depth: e.depth ?? 0 };
}

function pointNearSegment(p, wall, tol) {
  const x1 = wall.x1 ?? wall.p1?.x, y1 = wall.y1 ?? wall.p1?.y;
  const x2 = wall.x2 ?? wall.p2?.x, y2 = wall.y2 ?? wall.p2?.y;
  if (!Number.isFinite(x1) || !Number.isFinite(y1) || !Number.isFinite(x2) || !Number.isFinite(y2)) return false;
  const dx = x2 - x1, dy = y2 - y1;
  const lenSq = dx * dx + dy * dy;
  if (lenSq < 1e-12) return Math.hypot(p.x - x1, p.y - y1) < tol;
  let t = ((p.x - x1) * dx + (p.y - y1) * dy) / lenSq;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(p.x - (x1 + t * dx), p.y - (y1 + t * dy)) < tol;
}

/** World position of a hosted opening (door/window). Factory openings carry
 *  wallId + position along the wall — no x/y. Returns null when unresolvable. */
function openingWorldPoint(opening, entities) {
  if (typeof opening.x === 'number' && typeof opening.y === 'number') {
    return { x: opening.x, y: opening.y };
  }
  const wall = entities.find(w => w.kind === 'wall' && w.id === (opening.wallId || opening.hostWallId));
  if (!wall || !Number.isFinite(wall.x1) || !Number.isFinite(wall.y1)) return null;
  const dx = wall.x2 - wall.x1;
  const dy = wall.y2 - wall.y1;
  const len = Math.hypot(dx, dy);
  if (len < 1e-9) return { x: wall.x1, y: wall.y1 };
  const t = Math.min(1, Math.max(0, ((opening.position ?? 0) + (opening.width ?? 0) / 2) / len));
  return { x: wall.x1 + t * dx, y: wall.y1 + t * dy };
}

/** Rect of a room honoring polygonal boundaries; fallback to width×depth. */
function roomRectOf(r) {
  if (Array.isArray(r.boundary) && r.boundary.length >= 3) {
    const xs = r.boundary.map(p => p.x), ys = r.boundary.map(p => p.y);
    const x = Math.min(...xs), y = Math.min(...ys);
    return { x, y, width: Math.max(...xs) - x, depth: Math.max(...ys) - y };
  }
  return { x: r.x ?? 0, y: r.y ?? 0, width: r.width ?? 0, depth: r.depth ?? 0 };
}

/** True when a hosted/positioned opening falls within a room's envelope. */
function openingInRoom(opening, room, entities, pad = 0.3) {
  const p = openingWorldPoint(opening, entities);
  if (!p) return false;
  const r = roomRectOf(room);
  return p.x >= r.x - pad && p.x <= r.x + r.width + pad &&
    p.y >= r.y - pad && p.y <= r.y + r.depth + pad;
}

function dimensionOnWall(d, wall) {
  const p1 = d.p1 || { x: d.x1, y: d.y1 };
  const p2 = d.p2 || { x: d.x2, y: d.y2 };
  const near = (p, q) => Math.hypot(p.x - q.x, p.y - q.y) < 0.05;
  return (near(p1, { x: wall.x1, y: wall.y1 }) && near(p2, { x: wall.x2, y: wall.y2 })) ||
         (near(p1, { x: wall.x2, y: wall.y2 }) && near(p2, { x: wall.x1, y: wall.y1 }));
}

// ---------------------------------------------------------------------------
// Engine entry point
// ---------------------------------------------------------------------------

/**
 * Runs all registered rules against an entity list.
 * @param {Array<Object>} entities - active document entities
 * @param {Object} [context] - rule parameters (roomMinArea, …)
 * @returns {{ issues: Array, passed: number, failed: number, warning: number,
 *            rulesRun: number, ranAt: string }}
 */
function runAllChecks(entities, context = {}) {
  const list = Array.isArray(entities) ? entities : [];
  const all = [];
  for (const r of RULES) {
    try {
      all.push(...r.run(list, context));
    } catch (e) {
      // a failing rule must not abort the audit — report as UNVERIFIED
      all.push(issue('low', r.id + '.unverified', [], null,
        { reason: e.message?.slice(0, 120) },
        `Rule "${r.id}" could not run: ${e.message?.slice(0, 80)}`,
        'Inspect the rule inputs.'));
    }
  }
  return {
    issues: all,
    failed: all.filter(i => i.status === 'FAIL').length,
    warning: all.filter(i => i.status === 'WARNING').length,
    passed: 0,
    rulesRun: RULES.length,
    ranAt: new Date().toISOString()
  };
}

/** Rule registry metadata for UI/debug display. */
function listRules() {
  return RULES.map(r => ({ id: r.id, name: r.name, severity: r.severity, scope: r.scope, description: r.description }));
}


  // =========================================================================
  // MODULE: Requirements
  // =========================================================================

/**
 * Architecture Helping Hand — Project Brief, Requirements & Design Intent
 *
 * The brief captures WHAT the building must do; the model captures what it
 * IS; the requirements engine compares the two deterministically.
 *
 *   - BRIEF: building type, site, area targets, room requirements, floors,
 *     circulation, accessibility, orientation, special constraints, user rules
 *   - REQUIREMENTS: typed records { id, name, type, target, unit, scope,
 *     status, evidence } evaluated against actual geometry — PASS / FAIL /
 *     NEEDS INPUT / NOT APPLICABLE, never invented
 *   - ADJACENCY: required / preferred / avoid relationships between spaces
 *   - DESIGN INTENT: decisions with rationale, alternatives considered and
 *     the rejected ones (feeds the existing project.decisions container)
 *
 * All pure and deterministic: evaluation reads entities, never mutates them.
 */



// ---------------------------------------------------------------------------
// Project brief
// ---------------------------------------------------------------------------

/** Creates an empty project brief with sensible defaults. */
function createProjectBrief(overrides = {}) {
  return {
    buildingType: '',
    site: { location: '', notes: '', areaM2: null, orientation: '' },
    floors: null,
    areaTargets: { grossM2: null, netM2: null },
    circulation: { strategy: '', targetPctOfNet: null },
    accessibility: { target: '', notes: '' },
    orientation: { primary: '', notes: '' },
    specialConstraints: [],
    userRules: [],
    ...structuredCloneCompat(overrides)
  };
}

// structuredClone is unavailable in some embedded runtimes; a local deep copy
// keeps this module dependency-free.
function structuredCloneCompat(value) {
  return JSON.parse(JSON.stringify(value ?? {}));
}

/** Validates a brief field set; returns {ok, errors[]} without throwing. */
function validateBrief(brief) {
  const errors = [];
  if (!brief || typeof brief !== 'object') {
    return { ok: false, errors: ['Brief must be an object'] };
  }
  if (brief.buildingType !== undefined && typeof brief.buildingType !== 'string') {
    errors.push('buildingType must be a string');
  }
  if (brief.floors !== undefined && brief.floors !== null &&
      (!Number.isInteger(brief.floors) || brief.floors < 1 || brief.floors > 200)) {
    errors.push('floors must be an integer between 1 and 200');
  }
  if (brief.areaTargets) {
    for (const key of ['grossM2', 'netM2']) {
      const v = brief.areaTargets[key];
      if (v !== undefined && v !== null && (typeof v !== 'number' || v <= 0)) {
        errors.push(`areaTargets.${key} must be a positive number`);
      }
    }
  }
  return { ok: errors.length === 0, errors };
}

// ---------------------------------------------------------------------------
// Room requirements
// ---------------------------------------------------------------------------

/**
 * Creates a room requirement: "N rooms of kind X, each ≥ target area".
 * Example: createRoomRequirement('Bedroom', { count: 3, minAreaM2: 14 })
 */
function createRoomRequirement(name, { count = 1, minAreaM2 = null, minDimensions = null, notes = '' } = {}) {
  if (typeof name !== 'string' || !name.trim()) {
    throw new Error('Room requirement needs a room name (e.g. "Bedroom")');
  }
  if (minAreaM2 !== null && !(minAreaM2 > 0)) {
    throw new Error('minAreaM2 must be a positive number when provided');
  }
  if (minDimensions !== null &&
      (typeof minDimensions !== 'object' || !(minDimensions.width > 0) || !(minDimensions.depth > 0))) {
    throw new Error('minDimensions must be { width > 0, depth > 0 } when provided');
  }
  return {
    id: `req-room-${String(name).toLowerCase().replace(/\s+/g, '-')}-${Date.now().toString(36)}`,
    kind: 'room',
    name: name.trim(),
    count,
    minAreaM2,
    minDimensions,
    notes
  };
}

// ---------------------------------------------------------------------------
// Generic requirements (target / min / max against a scope metric)
// ---------------------------------------------------------------------------

const REQUIREMENT_TYPES = Object.freeze({
  MIN: 'min',     // scope metric must be >= target
  MAX: 'max',     // scope metric must be <= target
  EQUAL: 'equal', // scope metric must == target (within tolerance)
  PRESENCE: 'presence' // scope must exist
});

const REQUIREMENT_SCOPES = Object.freeze([
  'gross_area', 'net_area', 'room_count', 'room_area', 'corridor_width',
  'floor_count', 'door_clearance', 'stair_rise', 'stair_tread', 'custom'
]);

function createRequirement({ name, type, scope, target, unit = '', tolerance = 1e-9 } = {}) {
  if (typeof name !== 'string' || !name.trim()) {
    throw new Error('Requirement needs a name');
  }
  if (!REQUIREMENT_TYPES[type]) {
    throw new Error(`Unknown requirement type "${type}" — allowed: ${Object.values(REQUIREMENT_TYPES).join(', ')}`);
  }
  if (!REQUIREMENT_SCOPES.includes(scope) && !scope.startsWith('custom.')) {
    throw new Error(`Unknown requirement scope "${scope}" — allowed: ${REQUIREMENT_SCOPES.join(', ')}, or "custom.*"`);
  }
  return {
    id: `req-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
    kind: 'metric',
    name: name.trim(),
    type,
    scope,
    target,
    unit,
    tolerance
  };
}

// ---------------------------------------------------------------------------
// Evaluation — deterministic comparison against the actual model
// ---------------------------------------------------------------------------

/** Area of a room entity (m²). Honors polygonal boundaries via the
 *  canonical factory (entities.roomArea); width×depth is the fallback. */
function roomAreaOf(room) {
  const a = roomArea(room);
  return Number.isFinite(a) && a > 0 ? a : (room.width || 0) * (room.depth || 0);
}

/** Sum of all room areas = net internal area. */
function netInternalArea(entities) {
  return entities.filter(e => e.kind === 'room')
    .reduce((sum, r) => sum + roomAreaOf(r), 0);
}

/** Extracts the metric for a requirement scope. Returns {value, detail} or null. */
function scopeMetric(scope, entities, brief) {
  const rooms = entities.filter(e => e.kind === 'room');
  switch (scope) {
    case 'gross_area': return { value: netInternalArea(entities), detail: `${rooms.length} rooms` };
    case 'net_area': return { value: netInternalArea(entities), detail: `${rooms.length} rooms` };
    case 'room_count': return { value: rooms.length, detail: rooms.map(r => r.name).join(', ') };
    case 'floor_count': return { value: brief?.floors ?? null, detail: 'from brief' };
    case 'room_area': {
      // Smallest room area: the binding constraint when requiring a minimum
      // usable area per room; largest when requiring no oversized rooms is a
      // MAX check the caller composes. Detail exposes per-room areas.
      const areas = rooms.map(r => roomAreaOf(r));
      if (areas.length === 0) return { value: null, detail: 'no rooms in model' };
      return {
        value: Math.min(...areas),
        detail: rooms.map(r => `${r.name}: ${roomAreaOf(r).toFixed(1)}m²`).join(', ')
      };
    }
    case 'corridor_width': {
      const corridors = rooms.filter(r => /corridor|hall/i.test(String(r.name || '')));
      if (corridors.length === 0) return { value: null, detail: 'no corridor rooms' };
      return {
        value: Math.min(...corridors.map(r => Math.min(r.width || 0, r.depth || 0))),
        detail: `${corridors.length} corridor room(s)`
      };
    }
    default:
      if (scope.startsWith('custom.')) return { value: null, detail: scope };
      return null;
  }
}

/**
 * Evaluates a room requirement against the model: matches rooms by name
 * (case-insensitive substring) and checks count / min area / min dimensions.
 */
function evaluateRoomRequirement(req, entities) {
  const matched = entities.filter(e => e.kind === 'room' &&
    String(e.name || '').toLowerCase().includes(req.name.toLowerCase()));
  const found = matched.length;
  const evidence = {
    required: { name: req.name, count: req.count, minAreaM2: req.minAreaM2, minDimensions: req.minDimensions },
    matched: matched.map(r => ({ id: r.id, name: r.name, areaM2: +roomAreaOf(r).toFixed(2), width: r.width, depth: r.depth }))
  };

  if (found === 0) {
    return { status: 'NEEDS_INPUT', message: `No room matching "${req.name}" exists yet.`, evidence };
  }

  const problems = [];
  if (found < req.count) {
    problems.push(`only ${found} of ${req.count} required "${req.name}" rooms present`);
  }
  for (const r of matched) {
    const area = roomAreaOf(r);
    if (req.minAreaM2 && area < req.minAreaM2 - 1e-9) {
      problems.push(`"${r.name}" is ${area.toFixed(1)} m², below the ${req.minAreaM2} m² minimum`);
    }
    if (req.minDimensions) {
      const wOk = r.width >= req.minDimensions.width - 1e-9;
      const dOk = r.depth >= req.minDimensions.depth - 1e-9;
      if (!wOk || !dOk) {
        problems.push(`"${r.name}" is ${r.width}×${r.depth} m, below the ${req.minDimensions.width}×${req.minDimensions.depth} m minimum`);
      }
    }
  }

  if (problems.length > 0) {
    return { status: 'FAIL', message: `Room requirement not met: ${problems.join('; ')}.`, evidence };
  }
  return { status: 'PASS', message: `Room requirement met: ${found} × "${req.name}" present and within limits.`, evidence };
}

/**
 * Evaluates a generic metric requirement. Returns
 *   { status: 'PASS'|'FAIL'|'NOT_APPLICABLE'|'NEEDS_INPUT', evidence }
 */
function evaluateRequirement(req, entities, brief) {
  const metric = scopeMetric(req.scope, entities, brief);
  if (metric === null || metric.value === null || metric.value === undefined) {
    return { status: 'NOT_APPLICABLE', evidence: { scope: req.scope, reason: 'metric unavailable for this model' } };
  }
  const evidence = { scope: req.scope, actual: +Number(metric.value).toFixed(3), target: req.target, unit: req.unit, detail: metric.detail };

  switch (req.type) {
    case 'MIN': {
      if (!Number.isFinite(req.target)) return { status: 'NEEDS_INPUT', evidence: { ...evidence, reason: 'target not set' } };
      return { status: metric.value >= req.target - (req.tolerance ?? 1e-9) ? 'PASS' : 'FAIL', evidence };
    }
    case 'MAX': {
      if (!Number.isFinite(req.target)) return { status: 'NEEDS_INPUT', evidence: { ...evidence, reason: 'target not set' } };
      return { status: metric.value <= req.target + (req.tolerance ?? 1e-9) ? 'PASS' : 'FAIL', evidence };
    }
    case 'EQUAL': {
      if (!Number.isFinite(req.target)) return { status: 'NEEDS_INPUT', evidence: { ...evidence, reason: 'target not set' } };
      return { status: Math.abs(metric.value - req.target) <= (req.tolerance ?? 1e-9) ? 'PASS' : 'FAIL', evidence };
    }
    case 'PRESENCE':
      return { status: metric.value > 0 ? 'PASS' : 'FAIL', evidence };
    default:
      return { status: 'UNVERIFIED', evidence: { ...evidence, reason: `unknown type ${req.type}` } };
  }
}

// ---------------------------------------------------------------------------
// Adjacency
// ---------------------------------------------------------------------------

const ADJACENCY_LEVELS = Object.freeze({ REQUIRED: 'required', PREFERRED: 'preferred', AVOID: 'avoid' });

/**
 * Creates an adjacency expectation between two room names.
 * Example: createAdjacency('Kitchen', 'Dining', ADJACENCY_LEVELS.PREFERRED, 'HIGH')
 */
function createAdjacency(roomA, roomB, level = ADJACENCY_LEVELS.PREFERRED, strength = 'MEDIUM', notes = '') {
  if (!roomA?.trim() || !roomB?.trim()) throw new Error('Adjacency needs two room names');
  const levelMatch = Object.values(ADJACENCY_LEVELS).find(l => l.toLowerCase() === String(level).toLowerCase());
  if (!levelMatch) {
    throw new Error(`Adjacency level must be one of: ${Object.values(ADJACENCY_LEVELS).join(', ')}`);
  }
  level = levelMatch;
  if (!['LOW', 'MEDIUM', 'HIGH'].includes(strength)) {
    throw new Error('Strength must be LOW, MEDIUM or HIGH');
  }
  return {
    id: `adj-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 5)}`,
    roomA: roomA.trim(), roomB: roomB.trim(), level, strength, notes
  };
}

/** Rooms whose names contain the given name (case-insensitive). */
function findRoomsByName(entities, name) {
  const n = name.toLowerCase();
  return entities.filter(e => e.kind === 'room' && String(e.name || '').toLowerCase().includes(n));
}

/** Rooms touch (share a boundary edge within tolerance) or come within `gap`. */
function roomsAdjacentOrNear(a, b, gap = 0.5) {
  const gapX = Math.max(a.x, b.x) - Math.min(a.x + a.width, b.x + b.width);
  const gapY = Math.max(a.y, b.y) - Math.min(a.y + a.depth, b.y + b.depth);
  return gapX <= gap && gapY <= gap;
}

/**
 * Evaluates one adjacency expectation. FAIL only for REQUIRED adjacency
 * that is missing; AVOID fails when the rooms DO touch; PREFERRED missing
 * is a WARNING-grade note (returned in status for the panel to style).
 */
function evaluateAdjacency(adj, entities) {
  const a = findRoomsByName(entities, adj.roomA);
  const b = findRoomsByName(entities, adj.roomB);
  const evidence = {
    roomA: adj.roomA, roomB: adj.roomB, level: adj.level, strength: adj.strength,
    matchedA: a.map(r => r.name), matchedB: b.map(r => r.name)
  };
  if (a.length === 0 || b.length === 0) {
    return { status: 'NEEDS_INPUT', message: `Room "${a.length === 0 ? adj.roomA : adj.roomB}" not present yet.`, evidence };
  }
  let touching = false;
  for (const ra of a) {
    for (const rb of b) {
      if (ra.id === rb.id) continue;
      if (roomsAdjacentOrNear(ra, rb, 0.1)) { touching = true; break; }
    }
    if (touching) break;
  }
  if (adj.level === ADJACENCY_LEVELS.AVOID) {
    return touching
      ? { status: 'FAIL', message: `"${adj.roomA}" and "${adj.roomB}" should NOT be adjacent but they touch.`, evidence: { ...evidence, touching } }
      : { status: 'PASS', message: `"${adj.roomA}" and "${adj.roomB}" are separated as required.`, evidence: { ...evidence, touching } };
  }
  return touching
    ? { status: 'PASS', message: `"${adj.roomA}" and "${adj.roomB}" are adjacent (${adj.level}).`, evidence: { ...evidence, touching } }
    : { status: adj.level === ADJACENCY_LEVELS.REQUIRED ? 'FAIL' : 'WARNING',
        message: `"${adj.roomA}" and "${adj.roomB}" are not adjacent (required).`, evidence: { ...evidence, touching } };
}

// ---------------------------------------------------------------------------
// Evaluation of a whole brief
// ---------------------------------------------------------------------------

/**
 * Evaluates brief + requirements + adjacency against the model.
 * @returns {{ results: Array, counts: {PASS,FAIL,WARNING,NEEDS_INPUT,NOT_APPLICABLE,UNVERIFIED}, ranAt }}
 */
function evaluateBriefCompliance(brief, entities) {
  const results = [];
  const reqs = Array.isArray(brief?.roomRequirements) ? brief.roomRequirements : [];
  for (const req of reqs) {
    const r = evaluateRoomRequirement(req, entities);
    results.push({ kind: 'room', name: req.name, ...r });
  }
  const metrics = Array.isArray(brief?.requirements) ? brief.requirements : [];
  for (const req of metrics) {
    const r = evaluateRequirement(req, entities, brief);
    results.push({ kind: 'metric', name: req.name, ...r });
  }
  const adjs = Array.isArray(brief?.adjacencies) ? brief.adjacencies : [];
  for (const adj of adjs) {
    const r = evaluateAdjacency(adj, entities);
    results.push({ kind: 'adjacency', name: `${adj.roomA} ↔ ${adj.roomB}`, ...r });
  }
  const counts = { PASS: 0, FAIL: 0, WARNING: 0, NEEDS_INPUT: 0, NOT_APPLICABLE: 0, UNVERIFIED: 0 };
  for (const r of results) counts[r.status] = (counts[r.status] || 0) + 1;
  return { results, counts, ranAt: new Date().toISOString() };
}

// ---------------------------------------------------------------------------
// Design intent
// ---------------------------------------------------------------------------

/**
 * Creates a design-intent record: a decision WITH its reasoning trail —
 * alternatives considered and the rejected ones. Feeds project.decisions.
 */
function createDesignIntent({ name, rationale, alternatives = [], rejected = [], createdBy = 'user' } = {}) {
  if (typeof name !== 'string' || !name.trim()) {
    throw new Error('Design intent needs a name');
  }
  if (typeof rationale !== 'string' || !rationale.trim()) {
    throw new Error('Design intent needs a rationale (the "why")');
  }
  return {
    id: `intent-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 5)}`,
    kind: 'intent',
    name: name.trim(),
    rationale: rationale.trim(),
    alternatives: alternatives.map(a => ({ option: a.option || String(a), whyNotChosen: a.whyNotChosen || '' })),
    rejected: rejected.map(r => ({ option: r.option || String(r), whyRejected: r.whyRejected || '' })),
    createdBy,
    createdAt: new Date().toISOString()
  };
}


  // =========================================================================
  // MODULE: AiBridge
  // =========================================================================

/**
 * Architecture Helping Hand - Omnipresent AI Context Bridge
 * Serializes live drawing canvas context, formats architectural prompt envelopes,
 * parses structured generative actions, and dispatches them into the active document.
 */




/**
 * Serializes the current active drawing viewport, persona, scale, and entities
 * into a structured context snapshot for AI queries.
 * @param {Object} state Studio global state
 * @returns {Object} Context snapshot
 */
function serializeDrawingContext(state = {}) {
  const plan = state.plan || {};
  const activeDocId = plan.activeDocId;
  const docs = Array.isArray(plan.documents) ? plan.documents : [];
  const activeDoc = docs.find(d => d.id === activeDocId) || docs[0] || {};
  const entities = Array.isArray(activeDoc.entities) ? activeDoc.entities : (Array.isArray(plan.entities) ? plan.entities : []);

  const rooms = entities.filter(e => e.kind === 'room');
  const walls = entities.filter(e => e.kind === 'wall');
  const furniture = entities.filter(e => e.kind === 'furniture');
  const stairs = entities.filter(e => e.kind === 'stair');
  const dims = entities.filter(e => e.kind === 'dimension');

  const grossArea = rooms.reduce((sum, r) => sum + (typeof r.width === 'number' && typeof r.depth === 'number' ? (r.width * r.depth) : 0), 0);
  const wallLength = walls.reduce((sum, w) => {
    if (typeof w.x1 === 'number' && typeof w.x2 === 'number') {
      const dx = w.x2 - w.x1;
      const dy = (w.y2 || 0) - (w.y1 || 0);
      return sum + Math.sqrt(dx * dx + dy * dy);
    }
    return sum;
  }, 0);

  return {
    persona: state.activePersona || 'studio',
    activeDocId: activeDoc.id || 'doc-1',
    activeDocName: activeDoc.name || 'Plan View',
    documentName: activeDoc.name || 'Ground Floor',
    activeDocType: activeDoc.type || '2d_plan',
    scale: plan.scale || '1:50',
    grid: plan.grid || 0.5,
    snap: plan.snap !== false,
    activeTool: plan.tool || 'select',
    entityCount: entities.length,
    roomsCount: rooms.length,
    grossArea: Math.round(grossArea * 100) / 100,
    wallCount: walls.length,
    totalWallLength: Math.round(wallLength * 100) / 100,
    furnitureCount: furniture.length,
    stairCount: stairs.length,
    dimensionCount: dims.length,
    rooms: rooms.map(r => ({ name: r.name, width: r.width, depth: r.depth, area: Math.round((r.width * r.depth) * 10) / 10 })),
    selectedCount: plan.selectedIds ? plan.selectedIds.size : 0,
    selection: serializeSelection(entities, plan.selectedIds),
    availableTools: serializeToolCapabilities()
  };
}

/**
 * Serializes the CURRENT SELECTION with full deterministic geometry,
 * relationships, and per-type measurements. This is what makes "AI answers
 * about the exact selected entity" possible: the model receives verified
 * numbers, not a request to guess.
 *
 * @param {Array<Object>} entities - active document entities
 * @param {Set<string>|Array<string>} selectedIds
 * @returns {Array<Object>} per-entity evidence packets (empty when nothing selected)
 */
function serializeSelection(entities = [], selectedIds = null) {
  const ids = selectedIds instanceof Set ? [...selectedIds] : (Array.isArray(selectedIds) ? selectedIds : []);
  if (ids.length === 0) return [];
  const byId = new Map(entities.map(e => [e.id, e]));
  const packets = [];
  for (const id of ids) {
    const e = byId.get(id);
    if (!e) continue;
    const packet = {
      id: e.id,
      kind: e.kind,
      name: e.name || e.id,
      layerId: e.layerId || null
    };
    switch (e.kind) {
      case 'wall': {
        const len = Math.hypot(e.x2 - e.x1, e.y2 - e.y1);
        packet.length = round(len);
        packet.thickness = e.thickness ?? null;
        packet.assemblyId = e.assemblyId || null;
        packet.angleDegrees = round((Math.atan2(e.y2 - e.y1, e.x2 - e.x1) * 180) / Math.PI);
        packet.p1 = { x: round(e.x1), y: round(e.y1) };
        packet.p2 = { x: round(e.x2), y: round(e.y2) };
        packet.openings = (typeof wallOpenings === 'function' ? wallOpenings(e, entities) : []).map(o => ({
          id: o.id, kind: o.kind, name: o.name, width: o.width
        }));
        packet.dimensions = entities
          .filter(d => d.kind === 'dimension' && dimensionTouchesSegment(d, e))
          .map(d => ({ id: d.id, value: round(dimensionValue(d)) }));
        break;
      }
      case 'line': {
        packet.length = round(typeof e.length === 'number' ? e.length : Math.hypot(e.x2 - e.x1, e.y2 - e.y1));
        packet.angleDegrees = round(e.angleDegrees ?? 0);
        packet.p1 = { x: round(e.x1), y: round(e.y1) };
        packet.p2 = { x: round(e.x2), y: round(e.y2) };
        break;
      }
      case 'room': {
        const area = typeof e.width === 'number' && typeof e.depth === 'number' ? e.width * e.depth : 0;
        packet.width = round(e.width ?? 0);
        packet.depth = round(e.depth ?? 0);
        packet.area = round(area);
        packet.perimeter = round(e.width && e.depth ? 2 * (e.width + e.depth) : 0);
        packet.aspectRatio = e.width && e.depth ? round(Math.max(e.width, e.depth) / Math.min(e.width, e.depth), 2) : null;
        packet.furniture = entities.filter(f => f.kind === 'furniture' &&
          typeof f.x === 'number' && f.x >= e.x - 0.01 && f.x <= e.x + e.width + 0.01 &&
          f.y >= e.y - 0.01 && f.y <= e.y + e.depth + 0.01
        ).map(f => ({ id: f.id, name: f.name, width: round(f.width), depth: round(f.depth) }));
        packet.doors = entities.filter(d => d.kind === 'door' &&
          typeof d.x === 'number' && d.x >= e.x - 0.3 && d.x <= e.x + e.width + 0.3 &&
          d.y >= e.y - 0.3 && d.y <= e.y + e.depth + 0.3
        ).map(d => ({ id: d.id, name: d.name, width: round(d.width) }));
        packet.dimensions = entities.filter(d => d.kind === 'dimension' &&
          (Math.abs(dimensionValue(d) - e.width) < 0.02 || Math.abs(dimensionValue(d) - e.depth) < 0.02)
        ).map(d => ({ id: d.id, value: round(dimensionValue(d)) }));
        break;
      }
      case 'dimension': {
        packet.measuredLength = round(dimensionValue(e));
        packet.p1 = e.p1 ? { x: round(e.p1.x), y: round(e.p1.y) } : null;
        packet.p2 = e.p2 ? { x: round(e.p2.x), y: round(e.p2.y) } : null;
        packet.unit = e.unit || 'm';
        packet.textOverride = e.textOverride || null;
        // Verification: is a wall/room edge actually this long?
        const matches = entities.filter(t => (t.kind === 'wall' || t.kind === 'line' || t.kind === 'room') &&
          Math.abs(entityPrimaryLength(t) - dimensionValue(e)) < 0.02
        ).map(t => ({ id: t.id, kind: t.kind, name: t.name, length: round(entityPrimaryLength(t)) }));
        packet.matchesGeometry = matches.length > 0;
        packet.matchingEntities = matches.slice(0, 5);
        break;
      }
      case 'stair': {
        packet.risers = e.risers ?? null;
        packet.width = round(e.width ?? 0);
        packet.riserHeight = e.riserHeight ?? null;
        packet.tread = e.tread ?? null;
        packet.blondel = e.blondel ?? null;
        packet.pitchAngle = e.pitchAngle ?? null;
        break;
      }
      case 'ramp': {
        packet.slopePercent = e.slopePercent ?? null;
        packet.slopeRatio = e.slopeRatio ?? null;
        packet.width = round(e.width ?? 0);
        packet.length = round(e.depth ?? 0);
        break;
      }
      case 'door':
      case 'window': {
        packet.width = round(e.width ?? 0);
        packet.hostWallId = e.wallId || e.hostWallId || null;
        packet.swing = e.swing || null;
        break;
      }
      case 'furniture': {
        packet.width = round(e.width ?? 0);
        packet.depth = round(e.depth ?? 0);
        packet.catalogId = e.catalogId || e.templateId || null;
        packet.hostRoom = entities.find(r => r.kind === 'room' &&
          typeof e.x === 'number' && e.x >= r.x && e.x <= r.x + r.width &&
          e.y >= r.y && e.y <= r.y + r.depth
        )?.name || null;
        break;
      }
      default: {
        packet.width = round(e.width ?? 0);
        packet.depth = round(e.depth ?? 0);
      }
    }
    packets.push(packet);
  }
  return packets;
}

/**
 * Tool-awareness capabilities for "what can I do with this?" answers:
 * the real registered catalog (single source of truth: personas.js).
 */
function serializeToolCapabilities(toolCatalog = STUDIO_TOOL_CATALOG) {
  const tools = (toolCatalog || []).map(t => ({
    id: t.id,
    name: t.name,
    description: t.description || '',
    command: t.commandAlias || null,
    shortcut: t.shortcut || null,
    category: t.category,
    personas: t.personas || []
  }));
  return { count: tools.length, tools };
}

function round(v, digits = 3) {
  if (typeof v !== 'number' || !Number.isFinite(v)) return null;
  const f = Math.pow(10, digits);
  return Math.round(v * f) / f;
}

function dimensionValue(d) {
  const p1 = d.p1 || { x: d.x1, y: d.y1 };
  const p2 = d.p2 || { x: d.x2, y: d.y2 };
  if (typeof p1?.x !== 'number' || typeof p2?.x !== 'number') return NaN;
  return Math.hypot(p2.x - p1.x, p2.y - p1.y);
}

function dimensionTouchesSegment(dim, wall) {
  const p1 = dim.p1 || { x: dim.x1, y: dim.y1 };
  const p2 = dim.p2 || { x: dim.x2, y: dim.y2 };
  const near = (p, q) => Math.hypot(p.x - q.x, p.y - q.y) < 0.05;
  return (near(p1, { x: wall.x1, y: wall.y1 }) && near(p2, { x: wall.x2, y: wall.y2 })) ||
         (near(p1, { x: wall.x2, y: wall.y2 }) && near(p2, { x: wall.x1, y: wall.y1 }));
}

function entityPrimaryLength(e) {
  if (e.kind === 'wall' || e.kind === 'line') return Math.hypot(e.x2 - e.x1, e.y2 - e.y1);
  if (e.kind === 'room') return typeof e.width === 'number' ? e.width : 0;
  return 0;
}

/**
 * Builds an architectural design prompt envelope injecting live drawing metrics.
 * @param {string} userQuery Natural language prompt from the user
 * @param {Object} context Serialized drawing context
 * @returns {string} Enriched prompt string
 */
function buildArchitecturalPrompt(userQuery, context = {}) {
  return `You are the Architecture Helping Hand AI Studio Assistant.
You have real-time visibility into the architect's active drawing workspace.

WORKSPACE CONTEXT:
- Active Persona: ${context.persona || 'studio'}
- Active Document: ${context.activeDocName || 'Level 1'} (${context.activeDocType || '2d_plan'})
- Total Entities: ${context.entityCount || 0}
- Rooms: ${context.roomsCount || 0} (Gross Floor Area: ${context.grossArea || 0} m²)
- Walls: ${context.wallCount || 0} (Total Run: ${context.totalWallLength || 0} m)
- Furniture Pieces: ${context.furnitureCount || 0}
- Active Tool: ${context.activeTool || 'select'}

ARCHITECT INSTRUCTION / QUESTION:
"${userQuery}"

Provide professional architectural guidance, IBC code compliance insight, Blondel stair calculation (2R+T=630mm), and spatial flow critique.
If your suggestion involves geometric additions or edits, append a JSON code block with executable actions:
\`\`\`json
[
  { "action": "CREATE_ROOM", "name": "Living Room", "width": 5.0, "depth": 4.0, "x": 0, "y": 0 },
  { "action": "CREATE_WALL", "x1": 0, "y1": 0, "x2": 5, "y2": 0, "thickness": 0.20 },
  { "action": "EXECUTE_TOOL", "toolId": "dimension" }
]
\`\`\``;
}

/**
 * Parses structured actionable geometric payloads from AI responses.
 * @param {string} aiResponseText
 * @returns {Array<Object>} Parsed action items
 */
function parseAiActions(aiResponseText) {
  if (!aiResponseText || typeof aiResponseText !== 'string') return [];
  const actions = [];

  const jsonBlocks = aiResponseText.match(/```(?:json)?\s*([\s\S]*?)```/gi);
  if (jsonBlocks) {
    for (const block of jsonBlocks) {
      const clean = block.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
      try {
        const parsed = JSON.parse(clean);
        if (Array.isArray(parsed)) {
          actions.push(...parsed);
        } else if (Array.isArray(parsed.actions)) {
          actions.push(...parsed.actions);
        } else if (parsed.type || parsed.action) {
          actions.push(parsed);
        }
      } catch (e) {
        // Continue searching
      }
    }
  }

  return actions;
}

/**
 * Executes a parsed AI action directly into the active drawing model.
 * @param {Object} action Parsed action item
 * @param {Object} planState state.plan or global state
 * @returns {Object} Result { success: boolean, entity?: Object, error?: string }
 */
function executeAiAction(action, planState) {
  if (!action) return { success: false, error: 'No action provided' };
  const targetPlan = planState?.plan ? planState.plan : (planState || {});
  const actionType = String(action.type || action.action || '').toLowerCase();

  // Determine entities container
  let targetEntities = null;
  if (Array.isArray(targetPlan.documents) && targetPlan.documents.length > 0) {
    const activeDoc = targetPlan.documents.find(d => d.id === targetPlan.activeDocId) || targetPlan.documents[0];
    if (!Array.isArray(activeDoc.entities)) activeDoc.entities = [];
    targetEntities = activeDoc.entities;
  } else {
    if (!Array.isArray(targetPlan.entities)) targetPlan.entities = [];
    targetEntities = targetPlan.entities;
  }

  let newEntity = null;

  switch (actionType) {
    case 'add_room':
    case 'create_room': {
      const rx = action.x !== undefined ? action.x : (action.x1 || 0);
      const ry = action.y !== undefined ? action.y : (action.y1 || 0);
      const rw = action.width !== undefined ? action.width : (action.x2 !== undefined ? Math.abs(action.x2 - rx) : 4.0);
      const rd = action.depth !== undefined ? action.depth : (action.y2 !== undefined ? Math.abs(action.y2 - ry) : 3.0);
      newEntity = createRoom({
        name: action.name || 'Room',
        x: rx,
        y: ry,
        width: rw,
        depth: rd
      });
      break;
    }
    case 'add_wall':
    case 'create_wall': {
      newEntity = createWall({
        name: action.name || 'Wall',
        x1: action.x1 !== undefined ? action.x1 : (action.x || 0),
        y1: action.y1 !== undefined ? action.y1 : (action.y || 0),
        x2: action.x2 !== undefined ? action.x2 : ((action.x || 0) + 5),
        y2: action.y2 !== undefined ? action.y2 : (action.y || 0),
        thickness: action.thickness || 0.20
      });
      break;
    }
    case 'add_stair':
    case 'create_stair':
    case 'calculate_stair': {
      newEntity = createStairEntity({
        name: action.name || 'Stair Flight',
        x: action.x || 0,
        y: action.y || 0,
        width: action.width || 1.10,
        run: action.run || 3.50,
        rise: action.rise || 2.80,
        risers: action.risers || 16,
        stairType: action.stairType || 'straight'
      });
      break;
    }
    case 'add_detail':
    case 'create_detail': {
      newEntity = createDetailCallout({
        name: action.name || 'Detail Callout',
        detailNum: action.detailNum || '1',
        sheetRef: action.sheetRef || 'A-501',
        detailKey: action.detailKey || 'footing',
        x: action.x || 0,
        y: action.y || 0,
        width: 1.4,
        depth: 1.4
      });
      break;
    }
    case 'add_section':
    case 'create_section': {
      newEntity = createSectionCut({
        name: action.name || 'Section Cut',
        label: action.label || 'A',
        sheetRef: action.sheetRef || 'A-201',
        p1: { x: action.x1 || 0, y: action.y1 || 3 },
        p2: { x: action.x2 || 10, y: action.y2 || 3 }
      });
      break;
    }
    case 'execute_tool':
    case 'set_tool': {
      if (action.toolId) {
        targetPlan.tool = action.toolId;
      }
      return { success: true, tool: targetPlan.tool };
    }
    case 'set_view':
    case 'switch_view': {
      if (action.viewType && Array.isArray(targetPlan.documents)) {
        const found = targetPlan.documents.find(d => d.type === action.viewType);
        if (found) targetPlan.activeDocId = found.id;
      }
      return { success: true, viewType: action.viewType };
    }
    default:
      break;
  }

  if (newEntity) {
    targetEntities.push(newEntity);
    if (!targetPlan.selectedIds) targetPlan.selectedIds = new Set();
    targetPlan.selectedIds = new Set([newEntity.id]);
    return { success: true, entity: newEntity };
  }

  return { success: false, error: `Unknown action: ${actionType}` };
}


  // =========================================================================
  // MODULE: PlanCanvas
  // =========================================================================

/**
 * Architecture Helping Hand - Plan Canvas Core
 * Phase 3: pure view/interaction math for the SVG plan editor.
 *
 * The Plan Canvas never mixes pixel and project coordinates:
 *   world coordinates (meters) → view transform → SVG coordinates
 * This module owns the transform, grid/snapping, selection geometry,
 * and a lightweight undo/redo command stack. Rendering lives in the UI
 * view; persistence in the project document via the store.
 */





/**
 * Creates a view transform for the plan canvas.
 * @param {Object} [init] - { offsetX, offsetY, zoom }
 *   SVG point = world point * zoom + offset  (screen y grows downward,
 *   so the view flips the world y axis: svgY = offsetY - worldY * zoom)
 */
function createViewTransform(init = {}) {
  return {
    offsetX: typeof init.offsetX === 'number' ? init.offsetX : 60,
    offsetY: typeof init.offsetY === 'number' ? init.offsetY : 420,
    zoom: typeof init.zoom === 'number' && init.zoom > 0 ? init.zoom : 40 // px per meter
  };
}

function worldToSvg(transform, wx, wy) {
  return { x: transform.offsetX + wx * transform.zoom, y: transform.offsetY - wy * transform.zoom };
}

function svgToWorld(transform, sx, sy) {
  return { x: (sx - transform.offsetX) / transform.zoom, y: (transform.offsetY - sy) / transform.zoom };
}

/** Clamped zoom change (weak laptop: keep between 4 and 400 px/m). */
function zoomAt(transform, factor, svgX, svgY, minZoom = 4, maxZoom = 400) {
  const before = svgToWorld(transform, svgX, svgY);
  const zoom = Math.max(minZoom, Math.min(maxZoom, transform.zoom * factor));
  const after = { zoom, offsetX: 0, offsetY: 0 };
  // keep the world point under the cursor fixed
  const next = createViewTransform({ ...transform, zoom });
  const world = svgToWorld(transform, svgX, svgY);
  next.offsetX = svgX - world.x * zoom;
  next.offsetY = svgY + world.y * zoom;
  void after; void before;
  return next;
}

/** Pan by SVG pixels. */
function panBy(transform, dx, dy) {
  return { ...transform, offsetX: transform.offsetX + dx, offsetY: transform.offsetY + dy };
}

// ---------------------------------------------------------------------------
// Grid & snapping
// ---------------------------------------------------------------------------

/**
 * Builds grid line coordinates (world meters) for the visible extent.
 * Minor lines at gridMeters spacing, major lines every majorEvery lines.
 * Kept cheap: count-bounded for weak laptops.
 */
function buildGrid(transform, svgWidth, svgHeight, gridMeters = 0.5, majorEvery = 4, maxLines = 200) {
  const tl = svgToWorld(transform, 0, 0);
  const br = svgToWorld(transform, svgWidth, svgHeight);
  const lines = [];
  const startX = Math.floor(tl.x / gridMeters) * gridMeters;
  const endX = Math.ceil(br.x / gridMeters) * gridMeters;
  const startY = Math.floor(br.y / gridMeters) * gridMeters;
  const endY = Math.ceil(tl.y / gridMeters) * gridMeters;

  let count = 0;
  for (let x = startX; x <= endX && count < maxLines; x += gridMeters) {
    const index = Math.round(x / gridMeters);
    lines.push({ axis: 'x', world: x, major: ((index % majorEvery) + majorEvery) % majorEvery === 0 });
    count++;
  }
  for (let y = startY; y <= endY && count < maxLines * 2; y += gridMeters) {
    const index = Math.round(y / gridMeters);
    lines.push({ axis: 'y', world: y, major: ((index % majorEvery) + majorEvery) % majorEvery === 0 });
    count++;
  }
  return lines;
}

/**
 * Snaps a world coordinate to the grid (or to a finer snap step).
 * Deterministic epsilon handling via round-to-step.
 */
function snapToGrid(value, gridMeters) {
  const snapped = Math.round(value / gridMeters) * gridMeters;
  return Math.abs(snapped) < 1e-9 ? 0 : snapped;
}

function snapRect(rect, gridMeters) {
  return {
    x: snapToGrid(rect.x, gridMeters),
    y: snapToGrid(rect.y, gridMeters),
    width: Math.max(gridMeters, snapToGrid(rect.width, gridMeters)),
    depth: Math.max(gridMeters, snapToGrid(rect.depth, gridMeters))
  };
}

/**
 * Detects nearby object snap targets (corners, midpoints, endpoints, intersections,
 * perpendiculars, centers, extensions) or falls back to grid.
 *
 * @param {{x: number, y: number}} point - Candidate world coordinate
 * @param {Array<Object>} entities - Project entities list
 * @param {Object} [options]
 * @param {number} [options.snapDistance=0.20] - Max distance in meters to latch onto an object target
 * @param {boolean} [options.snapGrid=true] - Whether to snap to grid when no object is nearby
 * @param {number} [options.gridMeters=0.5] - Grid increment in meters
 * @param {string} [options.excludeId] - Optional ID of entity being moved/modified
 * @param {{x: number, y: number}} [options.startPoint] - Start point when drafting a vector (enables perpendicular foot snap)
 * @param {Object} [options.osnaps] - Optional boolean toggle map for specific snap types
 * @returns {{ x: number, y: number, type: 'corner'|'midpoint'|'endpoint'|'intersection'|'perpendicular'|'center'|'extension'|'grid'|'none', snapped: boolean, targetId?: string, guideRay?: Array<{x: number, y: number}>|null }}
 */
function findSnapPoint(point, entities = [], options = {}) {
  const snapDist = typeof options.snapDistance === 'number' ? options.snapDistance : 0.20;
  const snapGrid = options.snapGrid !== false;
  const gridMeters = options.gridMeters || 0.5;
  const excludeId = options.excludeId || null;
  const startPoint = options.startPoint || options.draftStart || null;
  const osnaps = options.osnaps || {};

  const isEnabled = (type) => osnaps[type] !== false;

  let bestHit = null;
  let bestDist = snapDist;

  const PRIORITY = { endpoint: 5, corner: 5, intersection: 5, midpoint: 3, center: 2, perpendicular: 2, extension: 1 };

  const testCandidate = (cand) => {
    if (!isEnabled(cand.type)) return;
    const d = Math.hypot(cand.x - point.x, cand.y - point.y);
    const candPrio = PRIORITY[cand.type] || 0;
    const bestPrio = bestHit ? (PRIORITY[bestHit.type] || 0) : -1;

    if (d < bestDist - 1e-4) {
      bestDist = d;
      bestHit = cand;
    } else if (Math.abs(d - bestDist) <= 1e-4 && candPrio > bestPrio) {
      bestHit = cand;
    }
  };

  const walls = [];
  const otherEntities = [];
  const gridLines = [];
  const columns = [];

  for (const e of entities) {
    if (!e || e.id === excludeId) continue;
    if (e.kind === 'wall' && typeof e.x1 === 'number') {
      walls.push(e);
    } else if (e.kind === 'grid_line' && e.p1 && e.p2) {
      gridLines.push(e);
    } else if (e.kind === 'column') {
      columns.push(e);
    } else if (typeof e.x === 'number' && typeof e.width === 'number') {
      otherEntities.push(e);
    }
  }

  // 1. Wall endpoints & midpoints
  for (const w of walls) {
    if (isEnabled('endpoint')) {
      testCandidate({ x: w.x1, y: w.y1, type: 'endpoint', targetId: w.id });
      testCandidate({ x: w.x2, y: w.y2, type: 'endpoint', targetId: w.id });
    }
    if (isEnabled('midpoint')) {
      testCandidate({ x: (w.x1 + w.x2) / 2, y: (w.y1 + w.y2) / 2, type: 'midpoint', targetId: w.id });
    }
  }

  // Grid line endpoints & midpoints
  for (const gl of gridLines) {
    if (isEnabled('endpoint')) {
      testCandidate({ x: gl.p1.x, y: gl.p1.y, type: 'endpoint', targetId: gl.id });
      testCandidate({ x: gl.p2.x, y: gl.p2.y, type: 'endpoint', targetId: gl.id });
    }
    if (isEnabled('midpoint')) {
      testCandidate({ x: (gl.p1.x + gl.p2.x) / 2, y: (gl.p1.y + gl.p2.y) / 2, type: 'midpoint', targetId: gl.id });
    }
  }

  // 2. Wall-wall Intersections & Grid Line Intersections
  if (isEnabled('intersection')) {
    if (walls.length >= 2) {
      const segments = walls.map(w => ({
        p1: { x: w.x1, y: w.y1 },
        p2: { x: w.x2, y: w.y2 },
        id: w.id
      }));
      const intersections = findSegmentIntersections(segments);
      for (const hit of intersections) {
        testCandidate({
          x: hit.x,
          y: hit.y,
          type: 'intersection',
          targetId: hit.segId1
        });
      }
    }
    if (gridLines.length >= 2) {
      for (let i = 0; i < gridLines.length; i++) {
        for (let j = i + 1; j < gridLines.length; j++) {
          const hit = gridLineIntersection(gridLines[i], gridLines[j]);
          if (hit) {
            testCandidate({
              x: hit.x,
              y: hit.y,
              type: 'intersection',
              targetId: gridLines[i].id
            });
          }
        }
      }
    }
  }

  // Column snap points (center, corners, midpoints, quadrants)
  for (const col of columns) {
    const snaps = columnSnapPoints(col);
    for (const s of snaps) {
      if (isEnabled(s.type)) {
        testCandidate(s);
      }
    }
  }

  // 3. Rooms, Furniture, and other rectilinear entities (discrete corners, midpoints, center)
  for (const e of otherEntities) {
    const w = e.width;
    const d = e.depth || e.run || 0;

    if (isEnabled('corner')) {
      testCandidate({ x: e.x, y: e.y, type: 'corner', targetId: e.id });
      testCandidate({ x: e.x + w, y: e.y, type: 'corner', targetId: e.id });
      testCandidate({ x: e.x + w, y: e.y + d, type: 'corner', targetId: e.id });
      testCandidate({ x: e.x, y: e.y + d, type: 'corner', targetId: e.id });
    }

    if (isEnabled('midpoint')) {
      testCandidate({ x: e.x + w / 2, y: e.y, type: 'midpoint', targetId: e.id });
      testCandidate({ x: e.x + w, y: e.y + d / 2, type: 'midpoint', targetId: e.id });
      testCandidate({ x: e.x + w / 2, y: e.y + d, type: 'midpoint', targetId: e.id });
      testCandidate({ x: e.x, y: e.y + d / 2, type: 'midpoint', targetId: e.id });
    }

    if (isEnabled('center')) {
      testCandidate({ x: e.x + w / 2, y: e.y + d / 2, type: 'center', targetId: e.id });
    }
  }

  // 4. Perpendicular projection onto walls
  if (isEnabled('perpendicular')) {
    for (const w of walls) {
      const w1 = { x: w.x1, y: w.y1 };
      const w2 = { x: w.x2, y: w.y2 };

      if (startPoint && typeof startPoint.x === 'number') {
        // Orthogonal foot projection of the drafting start point onto target wall segment
        const proj = projectPointOnSegment(startPoint, w1, w2);
        if (proj.t >= 0.01 && proj.t <= 0.99) {
          testCandidate({
            x: proj.point.x,
            y: proj.point.y,
            type: 'perpendicular',
            targetId: w.id
          });
        }
      } else if (!bestHit) {
        // Cursor proximity perpendicular projection onto target wall segment (only when no discrete keypoint hit)
        const proj = findPerpendicularProjection(point, w1, w2, snapDist);
        if (proj) {
          testCandidate({
            x: proj.x,
            y: proj.y,
            type: 'perpendicular',
            targetId: w.id
          });
        }
      }
    }
  }

  // 5. Collinear Extension rays beyond wall endpoints
  if (isEnabled('extension')) {
    for (const w of walls) {
      const ext = findExtensionSnap(
        point,
        { x: w.x1, y: w.y1 },
        { x: w.x2, y: w.y2 },
        3.0,
        snapDist
      );
      if (ext) {
        testCandidate({
          x: ext.x,
          y: ext.y,
          type: 'extension',
          targetId: w.id,
          guideRay: ext.guideRay
        });
      }
    }
  }

  if (bestHit) {
    return {
      x: bestHit.x,
      y: bestHit.y,
      type: bestHit.type,
      snapped: true,
      targetId: bestHit.targetId,
      guideRay: bestHit.guideRay || null
    };
  }

  if (snapGrid && gridMeters > 0) {
    return {
      x: snapToGrid(point.x, gridMeters),
      y: snapToGrid(point.y, gridMeters),
      type: 'grid',
      snapped: true,
      guideRay: null
    };
  }

  return {
    x: point.x,
    y: point.y,
    type: 'none',
    snapped: false,
    guideRay: null
  };
}

/**
 * Computes dynamic dashed alignment guidelines between a dragged entity rect and all other entities.
 *
 * @param {{x: number, y: number, width: number, depth: number}} draggedRect
 * @param {Array<Object>} allEntities
 * @param {Object} [options] - { threshold = 0.08, excludeId }
 * @returns {{ guidesX: Array<{x: number, y1: number, y2: number}>, guidesY: Array<{y: number, x1: number, x2: number}> }}
 */
function computeAlignmentGuides(draggedRect, allEntities = [], options = {}) {
  const threshold = typeof options.threshold === 'number' ? options.threshold : 0.08;
  const excludeId = options.excludeId || null;
  const guidesX = [];
  const guidesY = [];

  if (!draggedRect || typeof draggedRect.x !== 'number') return { guidesX, guidesY };

  const left = draggedRect.x;
  const right = draggedRect.x + draggedRect.width;
  const centerX = draggedRect.x + draggedRect.width / 2;

  const bottom = draggedRect.y;
  const top = draggedRect.y + draggedRect.depth;
  const centerY = draggedRect.y + draggedRect.depth / 2;

  const xCands = [left, centerX, right];
  const yCands = [bottom, centerY, top];

  for (const e of allEntities) {
    if (!e || e.id === excludeId) continue;
    const r = e.kind === 'wall' ? wallRect(e) : (typeof e.x === 'number' ? { x: e.x, y: e.y, width: e.width || 0, depth: e.depth || 0 } : null);
    if (!r) continue;

    const eLeft = r.x;
    const eRight = r.x + r.width;
    const eCenterX = r.x + r.width / 2;
    const targetXs = [eLeft, eCenterX, eRight];

    for (const tx of targetXs) {
      for (const mx of xCands) {
        if (Math.abs(mx - tx) <= threshold) {
          const minY = Math.min(bottom, r.y);
          const maxY = Math.max(top, r.y + r.depth);
          guidesX.push({ x: tx, y1: minY - 0.2, y2: maxY + 0.2 });
        }
      }
    }

    const eBottom = r.y;
    const eTop = r.y + r.depth;
    const eCenterY = r.y + r.depth / 2;
    const targetYs = [eBottom, eCenterY, eTop];

    for (const ty of targetYs) {
      for (const my of yCands) {
        if (Math.abs(my - ty) <= threshold) {
          const minX = Math.min(left, r.x);
          const maxX = Math.max(right, r.x + r.width);
          guidesY.push({ y: ty, x1: minX - 0.2, x2: maxX + 0.2 });
        }
      }
    }
  }

  // Deduplicate and cap to at most 4 guides (weak laptop protection)
  const uniqueX = [];
  for (const g of guidesX) {
    if (!uniqueX.some(u => Math.abs(u.x - g.x) < 0.01)) uniqueX.push(g);
  }
  const uniqueY = [];
  for (const g of guidesY) {
    if (!uniqueY.some(u => Math.abs(u.y - g.y) < 0.01)) uniqueY.push(g);
  }

  return { guidesX: uniqueX.slice(0, 4), guidesY: uniqueY.slice(0, 4) };
}

/**
 * Computes live measurement metrics between two world points.
 *
 * @param {{x: number, y: number}} p1 - Start point
 * @param {{x: number, y: number}} p2 - End point
 * @returns {{ p1: Object, p2: Object, dx: number, dy: number, distanceMeters: number, distanceMm: number, angleDegrees: number, formattedM: string, formattedMm: string, formattedAngle: string }|null}
 */
function computeMeasurement(p1, p2) {
  if (!p1 || !p2) return null;
  const dx = p2.x - p1.x;
  const dy = p2.y - p1.y;
  const distanceMeters = Math.hypot(dx, dy);
  const distanceMm = distanceMeters * 1000;
  let angle = Math.atan2(dy, dx) * (180 / Math.PI);
  if (angle < 0) angle += 360;

  return {
    p1: { x: p1.x, y: p1.y },
    p2: { x: p2.x, y: p2.y },
    dx,
    dy,
    distanceMeters,
    distanceMm,
    angleDegrees: angle,
    formattedM: `${distanceMeters.toFixed(3)} m`,
    formattedMm: `${Math.round(distanceMm)} mm`,
    formattedAngle: `${angle.toFixed(1)}°`
  };
}

/**
 * Duplicates an entity with an offset and unique identity.
 *
 * @param {Object} entity
 * @param {number} [offset=0.5] - Meters offset along x and y
 * @returns {Object|null} Fresh duplicated entity
 */
function duplicateEntity(entity, offset = 0.5) {
  if (!entity || typeof entity !== 'object') return null;
  // Hostile offset contract: only finite numbers may shift geometry — a
  // non-numeric offset would stringify coords into NaN-corrupting data.
  const dx = Number.isFinite(offset) ? offset : (Number.isFinite(offset?.x) ? offset.x : 0);
  const dy = Number.isFinite(offset) ? offset : (Number.isFinite(offset?.y) ? offset.y : 0);
  const clone = JSON.parse(JSON.stringify(entity));
  clone.id = generateEntityId(clone.kind || 'item');
  clone.name = clone.name ? `${clone.name} (Copy)` : 'Copy';
  clone.locked = false;

  if (clone.kind === 'wall' && typeof clone.x1 === 'number') {
    clone.x1 += dx;
    clone.x2 += dx;
    clone.y1 += dy;
    clone.y2 += dy;
  } else if (typeof clone.x === 'number') {
    clone.x += dx;
    clone.y += dy;
  }
  return clone;
}

// ---------------------------------------------------------------------------
// Selection geometry
// ---------------------------------------------------------------------------

function distToSegment(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const l2 = dx * dx + dy * dy;
  if (l2 === 0) return Math.hypot(px - x1, py - y1);
  let t = ((px - x1) * dx + (py - y1) * dy) / l2;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(px - (x1 + t * dx), py - (y1 + t * dy));
}

/** Returns ids of entities whose rect intersects the selection point/rect. */
function pickEntities(entities, worldRect) {
  const hits = [];
  const list = Array.isArray(entities)
    ? entities
    : (entities && typeof entities === 'object' ? Object.values(entities).flat().filter(Boolean) : []);
  for (const e of list) {
    if (!e) continue;
    // Walls are point-pair entities without x/y — map to their bounding rect
    const r = e.kind === 'wall'
      ? wallRect(e)
      : (typeof e.x === 'number' ? { x: e.x, y: e.y, width: e.width ?? 0, depth: e.depth ?? 0 } : null);
    if (!r) continue;
    if (worldRect.width === 0 && worldRect.depth === 0) {
      // point pick
      if (e.kind === 'room' && Array.isArray(e.boundary) && e.boundary.length >= 3) {
        if (pointInPolygon({ x: worldRect.x, y: worldRect.y }, e.boundary)) {
          hits.push(e.id);
        }
      } else if (e.kind === 'wall' && typeof e.x1 === 'number' && typeof e.x2 === 'number') {
        const d = distToSegment(worldRect.x, worldRect.y, e.x1, e.y1, e.x2, e.y2);
        if (d <= (e.thickness || 0.2) / 2 + 0.15) {
          hits.push(e.id);
        }
      } else if (worldRect.x >= r.x && worldRect.x <= r.x + r.width && worldRect.y >= r.y && worldRect.y <= r.y + r.depth) {
        hits.push(e.id);
      }
    } else if (rectsIntersect(worldRect, r)) {
      hits.push(e.id);
    }

    if ((e.kind === 'door' || e.kind === 'window') && e.wallId) {
      const hostWall = list.find(w => w && w.id === e.wallId);
      if (hostWall && typeof hostWall.x1 === 'number') {
        const lenW = Math.hypot(hostWall.x2 - hostWall.x1, hostWall.y2 - hostWall.y1);
        if (lenW > 1e-4) {
          const uW = { x: (hostWall.x2 - hostWall.x1) / lenW, y: (hostWall.y2 - hostWall.y1) / lenW };
          const opMid = (e.position || 0) + (e.width || 0.9) / 2;
          const px = hostWall.x1 + opMid * uW.x;
          const py = hostWall.y1 + opMid * uW.y;
          const rad = (e.width || 0.9) / 2 + 0.25;
          if (worldRect.width === 0 && worldRect.depth === 0) {
            if (Math.hypot(worldRect.x - px, worldRect.y - py) <= rad) {
              hits.push(e.id);
            }
          }
        }
      }
    }
  }
  return hits;
}

/** Bounding rect of an axis-aligned wall (with thickness). */
function wallRect(wall) {
  const minX = Math.min(wall.x1, wall.x2) - wall.thickness / 2;
  const minY = Math.min(wall.y1, wall.y2) - wall.thickness / 2;
  const width = Math.abs(wall.x2 - wall.x1) + wall.thickness;
  const depth = Math.abs(wall.y2 - wall.y1) + wall.thickness;
  return { x: minX, y: minY, width, depth };
}

// ---------------------------------------------------------------------------
// Undo/Redo — lightweight command stack
// ---------------------------------------------------------------------------

/**
 * Command history: each command is { label, undo(state), redo(state) }
 * operating on an externally owned document object (applied mutatively to
 * a draft the caller controls). Bounded history keeps memory flat.
 */
function createHistory(limit = 100) {
  const undoStack = [];
  const redoStack = [];

  return {
    /** Record a command AFTER its redo() side effect has been applied. */
    push(command) {
      if (!command || typeof command.undo !== 'function' || typeof command.redo !== 'function') {
        throw new Error('History commands need undo() and redo()');
      }
      undoStack.push(command);
      if (undoStack.length > limit) undoStack.shift();
      redoStack.length = 0;
    },
    canUndo: () => undoStack.length > 0,
    canRedo: () => redoStack.length > 0,
    undo() {
      const cmd = undoStack.pop();
      if (!cmd) return null;
      cmd.undo();
      redoStack.push(cmd);
      return cmd.label;
    },
    redo() {
      const cmd = redoStack.pop();
      if (!cmd) return null;
      cmd.redo();
      undoStack.push(cmd);
      return cmd.label;
    },
    clear() {
      undoStack.length = 0;
      redoStack.length = 0;
    },
    depth: () => undoStack.length
  };
}

/** Builds an add/remove command pair for an entity in an array. */
function entityAddRemoveCommand(list, entity, label) {
  let removedIndex = -1;
  return {
    label,
    redo() {
      if (removedIndex === -1) list.push(entity);
      else list.splice(removedIndex, 0, entity);
      removedIndex = -1;
    },
    undo() {
      removedIndex = list.indexOf(entity);
      if (removedIndex !== -1) list.splice(removedIndex, 1);
    }
  };
}

/** Builds a move command (translates an entity by dx,dy; undo reverses). */
function entityMoveCommand(entity, dx, dy, label) {
  return {
    label,
    redo() {
      if (typeof entity.x === 'number') entity.x += dx;
      if (typeof entity.y === 'number') entity.y += dy;
      if (typeof entity.x1 === 'number') entity.x1 += dx;
      if (typeof entity.y1 === 'number') entity.y1 += dy;
      if (typeof entity.x2 === 'number') entity.x2 += dx;
      if (typeof entity.y2 === 'number') entity.y2 += dy;
      if (Array.isArray(entity.boundary)) {
        for (const pt of entity.boundary) {
          pt.x += dx;
          pt.y += dy;
        }
      }
    },
    undo() {
      if (typeof entity.x === 'number') entity.x -= dx;
      if (typeof entity.y === 'number') entity.y -= dy;
      if (typeof entity.x1 === 'number') entity.x1 -= dx;
      if (typeof entity.y1 === 'number') entity.y1 -= dy;
      if (typeof entity.x2 === 'number') entity.x2 -= dx;
      if (typeof entity.y2 === 'number') entity.y2 -= dy;
      if (Array.isArray(entity.boundary)) {
        for (const pt of entity.boundary) {
          pt.x -= dx;
          pt.y -= dy;
        }
      }
    }
  };
}

// ---------------------------------------------------------------------------
// Export geometry (P14): world-space outlines for SVG/DXF export
// ---------------------------------------------------------------------------

/**
 * Reduces plan entities to plain export geometry (world meters):
 *   { lines: [{x1,y1,x2,y2,label}], polygons: [{points:[[x,y]...], closed, label}], texts: [{x,y,text}] }
 * Pure: the exporter decides units/scale; this module only shapes geometry.
 * Rooms become closed polygons + a centered label; walls become thick-edge
 * outlines (their bounding rect) so DXF (no thickness concept here) still
 * shows the wall footprint; furniture becomes closed polygons + labels.
 *
 * @param {Array<Object>} entities - plan entities (rooms/walls/furniture)
 * @param {Object} [options] - { includeLabels (default true) }
 * @returns {{ lines: Array, polygons: Array, texts: Array }}
 */
function planToExportGeometry(entities, options = {}) {
  const includeLabels = options.includeLabels !== false;
  const out = { lines: [], polygons: [], texts: [], circles: [] };
  const list = Array.isArray(entities)
    ? entities
    : (entities && typeof entities === 'object' ? Object.values(entities).flat().filter(Boolean) : []);
  for (const e of list) {
    if (!e || typeof e !== 'object') continue;
    const lyr = e.layerId || (e.kind === 'wall' ? 'A-WALL'
      : e.kind === 'door' ? 'A-DOOR'
      : e.kind === 'window' ? 'A-GLAZ'
      : e.kind === 'room' ? 'A-AREA'
      : (e.kind === 'stair' || e.kind === 'ramp') ? 'A-FLOR-STRS'
      : e.kind === 'furniture' ? 'A-FURN'
      : e.kind === 'dimension' ? 'A-DIMS'
      : (e.kind === 'room_tag' || e.kind === 'door_tag' || e.kind === 'window_tag' || e.kind === 'north_arrow') ? 'A-ANNO-TAGS'
      : (e.kind === 'column' || e.kind === 'grid_line') ? 'A-GRID'
      : 'A-ANNO-TEXT');

    if (e.kind === 'room') {
      if (Array.isArray(e.boundary) && e.boundary.length >= 3) {
        out.polygons.push({
          closed: true,
          points: e.boundary.map(pt => [pt.x, pt.y]),
          label: e.name || 'Room',
          layer: lyr
        });
        if (includeLabels) {
          const cx = e.boundary.reduce((sum, p) => sum + p.x, 0) / e.boundary.length;
          const cy = e.boundary.reduce((sum, p) => sum + p.y, 0) / e.boundary.length;
          out.texts.push({ x: cx, y: cy, text: e.name || 'Room', layer: lyr });
        }
      } else if (typeof e.x === 'number' && typeof e.width === 'number' &&
                 typeof e.y === 'number' && typeof e.depth === 'number') {
        out.polygons.push({
          closed: true,
          points: [[e.x, e.y], [e.x + e.width, e.y], [e.x + e.width, e.y + e.depth], [e.x, e.y + e.depth]],
          label: e.name || 'Room',
          layer: lyr
        });
        if (includeLabels) {
          out.texts.push({ x: e.x + e.width / 2, y: e.y + e.depth / 2, text: e.name || 'Room', layer: lyr });
        }
      }
    } else if (e.kind === 'wall' && typeof e.x1 === 'number') {
      const dx = (e.x2 || 0) - e.x1;
      const dy = (e.y2 || 0) - e.y1;
      if (dx === 0 || dy === 0) {
        // Exact axis-aligned footprint preserves bounding box contract
        const minX = Math.min(e.x1, e.x2) - (e.thickness || 0) / 2;
        const minY = Math.min(e.y1, e.y2) - (e.thickness || 0) / 2;
        const w = Math.abs(e.x2 - e.x1) + (e.thickness || 0);
        const d = Math.abs(e.y2 - e.y1) + (e.thickness || 0);
        out.polygons.push({
          closed: true,
          points: [[minX, minY], [minX + w, minY], [minX + w, minY + d], [minX, minY + d]],
          label: e.name || 'Wall',
          layer: lyr
        });
      } else {
        const wallCorners = calcWallPolygon(e);
        out.polygons.push({
          closed: true,
          points: wallCorners.map(pt => [pt.x, pt.y]),
          label: e.name || 'Wall',
          layer: lyr
        });
      }
    } else if (e.kind === 'door') {
      const host = list.find(w => w.id === e.wallId);
      if (host && typeof host.x1 === 'number') {
        try {
          const doorCAD = calcDoorCADGeometry(host, e);
          if (doorCAD.jamb1Line) {
            out.lines.push({ x1: doorCAD.jamb1Line[0].x, y1: doorCAD.jamb1Line[0].y, x2: doorCAD.jamb1Line[1].x, y2: doorCAD.jamb1Line[1].y, layer: lyr });
          }
          if (doorCAD.jamb2Line) {
            out.lines.push({ x1: doorCAD.jamb2Line[0].x, y1: doorCAD.jamb2Line[0].y, x2: doorCAD.jamb2Line[1].x, y2: doorCAD.jamb2Line[1].y, layer: lyr });
          }
          if (doorCAD.type === 'double' && Array.isArray(doorCAD.leaves)) {
            for (const leaf of doorCAD.leaves) {
              out.lines.push({ x1: leaf.hinge.x, y1: leaf.hinge.y, x2: leaf.openEnd.x, y2: leaf.openEnd.y, layer: lyr });
            }
          } else if (doorCAD.hinge && doorCAD.openEnd) {
            out.lines.push({ x1: doorCAD.hinge.x, y1: doorCAD.hinge.y, x2: doorCAD.openEnd.x, y2: doorCAD.openEnd.y, layer: lyr });
          }
        } catch (_) {}
      }
    } else if (e.kind === 'window') {
      const host = list.find(w => w.id === e.wallId);
      if (host && typeof host.x1 === 'number') {
        try {
          const winCAD = calcWindowCADGeometry(host, e);
          if (winCAD.jamb1) out.lines.push({ x1: winCAD.jamb1[0].x, y1: winCAD.jamb1[0].y, x2: winCAD.jamb1[1].x, y2: winCAD.jamb1[1].y, layer: lyr });
          if (winCAD.jamb2) out.lines.push({ x1: winCAD.jamb2[0].x, y1: winCAD.jamb2[0].y, x2: winCAD.jamb2[1].x, y2: winCAD.jamb2[1].y, layer: lyr });
          if (winCAD.sillOuter) out.lines.push({ x1: winCAD.sillOuter[0].x, y1: winCAD.sillOuter[0].y, x2: winCAD.sillOuter[1].x, y2: winCAD.sillOuter[1].y, layer: lyr });
          if (winCAD.sillInner) out.lines.push({ x1: winCAD.sillInner[0].x, y1: winCAD.sillInner[0].y, x2: winCAD.sillInner[1].x, y2: winCAD.sillInner[1].y, layer: lyr });
          if (winCAD.glassPane1) out.lines.push({ x1: winCAD.glassPane1[0].x, y1: winCAD.glassPane1[0].y, x2: winCAD.glassPane1[1].x, y2: winCAD.glassPane1[1].y, layer: lyr });
          if (winCAD.glassPane2) out.lines.push({ x1: winCAD.glassPane2[0].x, y1: winCAD.glassPane2[0].y, x2: winCAD.glassPane2[1].x, y2: winCAD.glassPane2[1].y, layer: lyr });
        } catch (_) {}
      }
    } else if (e.kind === 'furniture' && typeof e.x === 'number' && typeof e.width === 'number') {
      out.polygons.push({
        closed: true,
        points: [[e.x, e.y], [e.x + e.width, e.y], [e.x + e.width, e.y + e.depth], [e.x, e.y + e.depth]],
        label: e.name || 'Furniture',
        layer: lyr
      });
      if (includeLabels) {
        out.texts.push({ x: e.x + e.width / 2, y: e.y + e.depth / 2, text: e.name || 'Furniture', layer: lyr });
      }
    } else if (e.kind === 'stair' && typeof e.x === 'number' && typeof e.width === 'number') {
      out.polygons.push({
        closed: true,
        points: [[e.x, e.y], [e.x + e.width, e.y], [e.x + e.width, e.y + e.depth], [e.x, e.y + e.depth]],
        label: e.name || 'Stair',
        layer: lyr
      });
      if (includeLabels) {
        out.texts.push({ x: e.x + e.width / 2, y: e.y + e.depth / 2, text: `${e.name || 'Stair'} (${e.risers || 0}R)`, layer: lyr });
      }
    } else if (e.kind === 'ramp' && typeof e.x === 'number' && typeof e.width === 'number') {
      out.polygons.push({
        closed: true,
        points: [[e.x, e.y], [e.x + e.width, e.y], [e.x + e.width, e.y + e.depth], [e.x, e.y + e.depth]],
        label: e.name || 'Ramp',
        layer: lyr
      });
      if (includeLabels) {
        out.texts.push({ x: e.x + e.width / 2, y: e.y + e.depth / 2, text: `${e.name || 'Ramp'} (1:${(e.slopeRatio || 12).toFixed(1)})`, layer: lyr });
      }
    } else if (e.kind === 'dimension') {
      const p1 = e.p1 || { x: e.x1 ?? 0, y: e.y1 ?? 0 };
      const p2 = e.p2 || { x: e.x2 ?? 0, y: e.y2 ?? 0 };
      const dimGeom = calcDimensionGeometry(p1, p2, e);
      if (dimGeom && dimGeom.dimLine && dimGeom.dimLine[0] && dimGeom.dimLine[1]) {
        out.lines.push({
          x1: dimGeom.dimLine[0].x, y1: dimGeom.dimLine[0].y,
          x2: dimGeom.dimLine[1].x, y2: dimGeom.dimLine[1].y,
          layer: lyr
        });
      }
      if (dimGeom && dimGeom.witness1 && dimGeom.witness1[0] && dimGeom.witness1[1]) {
        out.lines.push({
          x1: dimGeom.witness1[0].x, y1: dimGeom.witness1[0].y,
          x2: dimGeom.witness1[1].x, y2: dimGeom.witness1[1].y,
          layer: lyr
        });
      }
      if (dimGeom && dimGeom.witness2 && dimGeom.witness2[0] && dimGeom.witness2[1]) {
        out.lines.push({
          x1: dimGeom.witness2[0].x, y1: dimGeom.witness2[0].y,
          x2: dimGeom.witness2[1].x, y2: dimGeom.witness2[1].y,
          layer: lyr
        });
      }
      if (includeLabels && dimGeom && dimGeom.textMid) {
        out.texts.push({
          x: dimGeom.textMid.x,
          y: dimGeom.textMid.y,
          text: e.textOverride || `${(dimGeom.distance || 0).toFixed(2)}m`,
          height: 0.18,
          layer: lyr
        });
      }
    } else if (e.kind === 'leader') {
      const p1 = e.p1 || { x: e.x1 ?? 0, y: e.y1 ?? 0 };
      const knee = e.knee || { x: p1.x + 0.5, y: p1.y + 0.5 };
      const p2 = e.p2 || { x: knee.x + 1.0, y: knee.y };
      out.lines.push({ x1: p1.x, y1: p1.y, x2: knee.x, y2: knee.y, layer: lyr });
      out.lines.push({ x1: knee.x, y1: knee.y, x2: p2.x, y2: p2.y, layer: lyr });
      if (includeLabels && e.text) {
        out.texts.push({ x: (knee.x + p2.x) / 2, y: knee.y + 0.15, text: e.text, height: 0.18, layer: lyr });
      }
    } else if (e.kind === 'room_tag') {
      if (includeLabels) {
        const areaStr = typeof e.area === 'number' ? `${e.area.toFixed(1)}m²` : '';
        const tagLine = [e.roomNumber ? `#${e.roomNumber}` : '', areaStr].filter(Boolean).join(' · ');
        out.texts.push({ x: e.x, y: e.y + 0.12, text: e.name || 'Room', height: 0.22, layer: lyr });
        if (tagLine) {
          out.texts.push({ x: e.x, y: e.y - 0.12, text: tagLine, height: 0.16, layer: lyr });
        }
      }
    } else if (e.kind === 'door_tag' || e.kind === 'window_tag') {
      if (includeLabels) {
        out.texts.push({ x: e.x, y: e.y, text: e.tagText || (e.kind === 'door_tag' ? 'D01' : 'W01'), height: 0.18, layer: lyr });
      }
    } else if (e.kind === 'north_arrow') {
      const s = (e.size || 1.0) / 2;
      const rotRad = ((e.rotation || 0) * Math.PI) / 180;
      const cosR = Math.cos(rotRad);
      const sinR = Math.sin(rotRad);
      const rot = (px, py) => [e.x + px * cosR - py * sinR, e.y + px * sinR + py * cosR];
      const tip = rot(0, s);
      const bL = rot(-s * 0.35, -s * 0.7);
      const bR = rot(s * 0.35, -s * 0.7);
      const center = rot(0, -s * 0.3);
      out.polygons.push({ closed: true, points: [tip, bL, center], label: 'North Arrow', layer: lyr });
      out.polygons.push({ closed: true, points: [tip, center, bR], label: 'North Arrow', layer: lyr });
      if (includeLabels) {
        const labelPos = rot(0, s + 0.25);
        out.texts.push({ x: labelPos[0], y: labelPos[1], text: 'N', height: 0.25, layer: lyr });
      }
    } else if (e.kind === 'column') {
      const contour = columnContour(e);
      if (contour.length >= 3) {
        out.polygons.push({ closed: true, points: contour, label: e.name || 'Column', layer: lyr });
      }
      const hatches = columnHatchLines(e);
      for (const h of hatches) {
        out.lines.push({ x1: h.x1, y1: h.y1, x2: h.x2, y2: h.y2, layer: lyr });
      }
    } else if (e.kind === 'grid_line' && e.p1 && e.p2) {
      out.lines.push({ x1: e.p1.x, y1: e.p1.y, x2: e.p2.x, y2: e.p2.y, layer: lyr, linetype: 'CENTER' });
      const bRad = e.bubbleRadius || 0.35;
      if (e.bubblePosition === 'both' || e.bubblePosition === 'start') {
        out.circles.push({ cx: e.p1.x, cy: e.p1.y, r: bRad, layer: lyr });
        if (includeLabels && e.name) {
          out.texts.push({ x: e.p1.x, y: e.p1.y, text: e.name, height: 0.22, layer: lyr });
        }
      }
      if (e.bubblePosition === 'both' || e.bubblePosition === 'end') {
        out.circles.push({ cx: e.p2.x, cy: e.p2.y, r: bRad, layer: lyr });
        if (includeLabels && e.name) {
          out.texts.push({ x: e.p2.x, y: e.p2.y, text: e.name, height: 0.22, layer: lyr });
        }
      }
    } else if (e.kind === 'text' && typeof e.x === 'number' && typeof e.y === 'number') {
      if (includeLabels) {
        out.texts.push({ x: e.x, y: e.y, text: e.text || e.name || '', height: 0.2, layer: lyr });
      }
    }
  }
  return out;
}

/**
 * Renders plan export geometry as a standalone inline SVG markup string
 (world meters × pixelsPerMeter scale, y-axis flipped like the canvas view).
 * Pure string output — the Export Center wraps it with wrapSVGDocument().
 *
 * @param {Object} geometry - output of planToExportGeometry
 * @param {Object} [options] - { pixelsPerMeter (default 40), paddingMeters (default 1) }
 * @returns {string} `<svg ...>...</svg>` markup with xmlns
 */
function generatePlanSVG(geometry, options = {}) {
  const ppm = typeof options.pixelsPerMeter === 'number' && options.pixelsPerMeter > 0
    ? options.pixelsPerMeter : 40;
  const pad = typeof options.paddingMeters === 'number' && options.paddingMeters >= 0
    ? options.paddingMeters : 1;

  const polys = (geometry && Array.isArray(geometry.polygons)) ? geometry.polygons : [];
  const texts = (geometry && Array.isArray(geometry.texts)) ? geometry.texts : [];

  // Bounds over all points (fall back to a 1m empty frame)
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  for (const poly of polys) {
    for (const [x, y] of poly.points || []) {
      if (x < minX) minX = x; if (y < minY) minY = y;
      if (x > maxX) maxX = x; if (y > maxY) maxY = y;
    }
  }
  for (const t of texts) {
    if (t.x < minX) minX = t.x; if (t.y < minY) minY = t.y;
    if (t.x > maxX) maxX = t.x; if (t.y > maxY) maxY = t.y;
  }
  if (!isFinite(minX) || !isFinite(minY) || !isFinite(maxX) || !isFinite(maxY)) {
    minX = 0; minY = 0; maxX = 1; maxY = 1;
  }
  minX -= pad; minY -= pad; maxX += pad; maxY += pad;

  const widthM = Math.max(maxX - minX, 0.1);
  const heightM = Math.max(maxY - minY, 0.1);
  const widthPx = Math.min(widthM * ppm, 6000);
  const heightPx = Math.min(heightM * ppm, 6000);

  const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const X = x => ((x - minX) * ppm).toFixed(1);
  const Y = y => (heightPx - (y - minY) * ppm).toFixed(1); // flip y (screen down)

  const shapes = polys.map(poly => {
    const ptsAttr = (poly.points || []).map(([x, y]) => `${X(x)},${Y(y)}`).join(' ');
    return `<polygon points="${ptsAttr}" fill="none" stroke="#26418f" stroke-width="1.5"/>`;
  }).join('\n  ');

  const labels = texts.map(t =>
    `<text x="${X(t.x)}" y="${Y(t.y)}" text-anchor="middle" font-family="monospace" font-size="10" fill="#333">${esc(t.text)}</text>`
  ).join('\n  ');

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${widthPx.toFixed(0)}" height="${heightPx.toFixed(0)}" viewBox="0 0 ${widthPx.toFixed(0)} ${heightPx.toFixed(0)}">
  <rect x="0" y="0" width="${widthPx.toFixed(0)}" height="${heightPx.toFixed(0)}" fill="#ffffff"/>
  ${shapes}
  ${labels}
</svg>`;
}


  // =========================================================================
  // MODULE: Sheet
  // =========================================================================







const SHEET_SIZES = Object.freeze({
  A4: { widthMm: 297, heightMm: 210, name: 'ISO A4 (297 × 210 mm)' },
  A3: { widthMm: 420, heightMm: 297, name: 'ISO A3 (420 × 297 mm)' },
  A2: { widthMm: 594, heightMm: 420, name: 'ISO A2 (594 × 420 mm)' },
  A1: { widthMm: 841, heightMm: 594, name: 'ISO A1 (841 × 594 mm)' }
});

const ARCHITECTURAL_SCALES = Object.freeze([
  { ratio: 20, label: '1:20 (Detail)' },
  { ratio: 50, label: '1:50 (Detailed Plan)' },
  { ratio: 100, label: '1:100 (Standard Floor Plan)' },
  { ratio: 200, label: '1:200 (Site / Overall Plan)' },
  { ratio: 500, label: '1:500 (Master Plan)' }
]);

/**
 * Creates default presentation sheet document metadata.
 *
 * @param {Object} options
 * @returns {Object} Sheet configuration
 */
function createSheetConfig(options = {}) {
  const rawSize = options.size || options.sheetSize || 'A3';
  const sizeKey = SHEET_SIZES[rawSize] ? rawSize : 'A3';
  const sizeDef = SHEET_SIZES[sizeKey];
  const isPortrait = options.orientation === 'portrait';

  const widthMm = isPortrait ? sizeDef.heightMm : sizeDef.widthMm;
  const heightMm = isPortrait ? sizeDef.widthMm : sizeDef.heightMm;
  const pName = options.projectName || 'Studio Residence Project';
  const sTitle = options.sheetTitle || 'GROUND FLOOR PLAN & STRUCTURAL GRID';
  const sNumber = options.sheetNumber || 'A-101';
  const sRatio = options.scaleRatio || 100;
  const layoutMode = options.layoutMode || 'single';

  return {
    size: sizeKey,
    sheetSize: sizeKey,
    orientation: isPortrait ? 'portrait' : 'landscape',
    widthMm,
    heightMm,
    scaleRatio: sRatio,
    layoutMode,
    projectName: pName,
    sheetTitle: sTitle,
    sheetNumber: sNumber,
    marginMm: typeof options.marginMm === 'number' ? options.marginMm : 10,
    bindingMarginMm: typeof options.bindingMarginMm === 'number' ? options.bindingMarginMm : 20,
    titleBlock: {
      projectName: pName,
      sheetTitle: sTitle,
      sheetNumber: sNumber,
      scale: options.scale || `1:${sRatio}`,
      date: options.date || new Date().toISOString().slice(0, 10),
      revision: options.revision || 'REV 01',
      author: options.author || 'Architectural Studio',
      widthMm: 170,
      heightMm: 48
    },
    viewport: {
      scaleRatio: sRatio, // 1:100 scale default
      title: options.viewportTitle || `1  ${sTitle}`,
      showGrid: options.showGrid !== false
    }
  };
}

/**
 * Computes bounding box of real-world plan entities in meters.
 */
function computePlanBounds(entities = []) {
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

  for (const e of entities) {
    if (!e) continue;
    if (e.kind === 'wall' && typeof e.x1 === 'number') {
      minX = Math.min(minX, e.x1, e.x2);
      minY = Math.min(minY, e.y1, e.y2);
      maxX = Math.max(maxX, e.x1, e.x2);
      maxY = Math.max(maxY, e.y1, e.y2);
    } else if (e.kind === 'grid_line' && e.p1 && e.p2) {
      minX = Math.min(minX, e.p1.x, e.p2.x);
      minY = Math.min(minY, e.p1.y, e.p2.y);
      maxX = Math.max(maxX, e.p1.x, e.p2.x);
      maxY = Math.max(maxY, e.p1.y, e.p2.y);
    } else if (e.kind === 'column' && typeof e.x === 'number' && typeof e.y === 'number') {
      const hw = (e.width || (e.radius ? e.radius * 2 : 0.4)) / 2;
      const hd = (e.depth || (e.radius ? e.radius * 2 : 0.4)) / 2;
      minX = Math.min(minX, e.x - hw);
      minY = Math.min(minY, e.y - hd);
      maxX = Math.max(maxX, e.x + hw);
      maxY = Math.max(maxY, e.y + hd);
    } else if (typeof e.x === 'number' && typeof e.y === 'number') {
      const w = e.width || (e.radius ? e.radius * 2 : 1);
      const d = e.depth || (e.radius ? e.radius * 2 : 1);
      minX = Math.min(minX, e.x);
      minY = Math.min(minY, e.y);
      maxX = Math.max(maxX, e.x + w);
      maxY = Math.max(maxY, e.y + d);
    }
  }

  if (!isFinite(minX)) {
    return { minX: 0, minY: 0, maxX: 10, maxY: 10, widthM: 10, heightM: 10, centerX: 5, centerY: 5 };
  }

  const widthM = Math.max(1, maxX - minX);
  const heightM = Math.max(1, maxY - minY);
  return {
    minX, minY, maxX, maxY,
    widthM, heightM,
    centerX: minX + widthM / 2,
    centerY: minY + heightM / 2
  };
}

/**
 * Computes drawing viewport placement and transformation on the sheet.
 *
 * @param {Object} sheetConfig
 * @param {Array<Object>} entities
 * @returns {Object} Viewport layout parameters
 */
function computeViewportLayout(sheetConfig, entities = []) {
  const cfg = sheetConfig || createSheetConfig();
  const leftMargin = cfg.bindingMarginMm || 20;
  const rightMargin = cfg.marginMm || 10;
  const topMargin = cfg.marginMm || 10;
  const bottomMargin = cfg.marginMm || 10;

  // Usable area inside borders
  const drawAreaX = leftMargin;
  const drawAreaY = topMargin;
  const drawAreaW = cfg.widthMm - leftMargin - rightMargin;
  const drawAreaH = cfg.heightMm - topMargin - bottomMargin;

  const tb = cfg.titleBlock || {};
  const tbW = tb.widthMm || 170;
  const tbH = tb.heightMm || 48;
  const tbX = cfg.widthMm - rightMargin - tbW;
  const tbY = cfg.heightMm - bottomMargin - tbH;

  // Plan bounds in world meters (accepts entities array or precomputed bounds object)
  const bounds = (entities && typeof entities.minX === 'number')
    ? entities
    : computePlanBounds(entities);
  const scaleRatio = (cfg.viewport && cfg.viewport.scaleRatio) || cfg.scaleRatio || 100;
  // 1 meter in real world = (1000 / scaleRatio) millimeters on sheet paper
  const mmPerMeter = 1000 / scaleRatio;

  const planWidthMm = bounds.widthM * mmPerMeter;
  const planHeightMm = bounds.heightM * mmPerMeter;

  const layoutMode = cfg.layoutMode || 'single';
  let vpCenterX, vpCenterY;
  let vignette3D = null;
  let scheduleTable = null;
  let elevationViewport = null;
  let sectionViewport = null;
  let detailViewport = null;
  let detailsSheetMatrix = null;

  if (layoutMode === 'plan_3d') {
    // 3D Vignette box in upper right quadrant above title block
    const vigH = Math.max(60, tbY - topMargin - 10);
    vignette3D = {
      x: tbX,
      y: topMargin + 5,
      width: tbW,
      height: vigH,
      title: '3D AXONOMETRIC MASSING'
    };
    // Plan placed in left drawing region to leave right side clear
    const leftRegionW = Math.max(100, tbX - drawAreaX - 10);
    vpCenterX = drawAreaX + leftRegionW / 2;
    vpCenterY = drawAreaY + drawAreaH / 2;
  } else if (layoutMode === 'plan_schedule') {
    // CAD Schedule table in right region above title block
    const schedH = Math.max(60, tbY - topMargin - 10);
    scheduleTable = {
      x: tbX,
      y: topMargin + 5,
      width: tbW,
      height: schedH,
      title: 'ROOM AREA & OCCUPANCY SCHEDULE'
    };
    // Plan placed in left drawing region to leave right side clear
    const leftRegionW = Math.max(100, tbX - drawAreaX - 10);
    vpCenterX = drawAreaX + leftRegionW / 2;
    vpCenterY = drawAreaY + drawAreaH / 2;
  } else if (layoutMode === 'plan_elevation') {
    // Building Elevation viewport in right region above title block
    const elevH = Math.max(60, tbY - topMargin - 10);
    elevationViewport = {
      x: tbX,
      y: topMargin + 5,
      width: tbW,
      height: elevH,
      title: 'SOUTH ELEVATION'
    };
    const leftRegionW = Math.max(100, tbX - drawAreaX - 10);
    vpCenterX = drawAreaX + leftRegionW / 2;
    vpCenterY = drawAreaY + drawAreaH / 2;
  } else if (layoutMode === 'plan_section') {
    // Building Section viewport in right region above title block
    const sectH = Math.max(60, tbY - topMargin - 10);
    sectionViewport = {
      x: tbX,
      y: topMargin + 5,
      width: tbW,
      height: sectH,
      title: 'BUILDING SECTION A-A'
    };
    const leftRegionW = Math.max(100, tbX - drawAreaX - 10);
    vpCenterX = drawAreaX + leftRegionW / 2;
    vpCenterY = drawAreaY + drawAreaH / 2;
  } else if (layoutMode === 'plan_detail') {
    // Enlarged Construction Detail in right region above title block
    const detH = Math.max(60, tbY - topMargin - 10);
    detailViewport = {
      x: tbX,
      y: topMargin + 5,
      width: tbW,
      height: detH,
      title: 'ENLARGED CONSTRUCTION DETAIL (1:10)'
    };
    const leftRegionW = Math.max(100, tbX - drawAreaX - 10);
    vpCenterX = drawAreaX + leftRegionW / 2;
    vpCenterY = drawAreaY + drawAreaH / 2;
  } else if (layoutMode === 'details_sheet') {
    // Full presentation sheet of 4 standard construction details
    const totalAvailW = tbX - drawAreaX - 10;
    const qW = totalAvailW / 2;
    const qH = (drawAreaH - 10) / 2;
    detailsSheetMatrix = [
      { x: drawAreaX, y: topMargin, width: qW - 3, height: qH - 3, detailKey: 'footing', title: '1  STRIP FOOTING DETAIL' },
      { x: drawAreaX + qW + 3, y: topMargin, width: qW - 3, height: qH - 3, detailKey: 'parapet', title: '2  ROOF PARAPET DETAIL' },
      { x: drawAreaX, y: topMargin + qH + 5, width: qW - 3, height: qH - 5, detailKey: 'window_sill', title: '3  WINDOW SILL DETAIL' },
      { x: drawAreaX + qW + 3, y: topMargin + qH + 5, width: qW - 3, height: qH - 5, detailKey: 'stair_nosing', title: '4  STAIR NOSING DETAIL' }
    ];
    vpCenterX = drawAreaX + totalAvailW / 2;
    vpCenterY = drawAreaY + drawAreaH / 2;
  } else {
    // Single viewport centered
    vpCenterX = drawAreaX + drawAreaW / 2;
    vpCenterY = drawAreaY + (drawAreaH - tbH * 0.4) / 2;
  }

  return {
    drawArea: { x: drawAreaX, y: drawAreaY, width: drawAreaW, height: drawAreaH },
    titleBlock: { x: tbX, y: tbY, width: tbW, height: tbH },
    layoutMode,
    vignette3D,
    scheduleTable,
    elevationViewport,
    sectionViewport,
    detailViewport,
    detailsSheetMatrix,
    mmPerMeter,
    scaleRatio,
    planBounds: bounds,
    planSizeMm: { width: planWidthMm, height: planHeightMm },
    viewportWidth: planWidthMm,
    viewportHeight: planHeightMm,
    viewportCenterMm: { x: vpCenterX, y: vpCenterY }
  };
}

/**
 * Generates print-ready SVG presentation sheet with borders, title block,
 * and scaled drawing viewport.
 *
 * @param {Object|Array} arg1 - sheetConfig or entities
 * @param {Array|Object} [arg2] - entities or sheetConfig
 * @param {Object} [renderOptions]
 * @returns {string} Clean SVG markup string
 */
function generateSheetSVG(arg1, arg2 = [], renderOptions = {}) {
  let cfg, entities;
  if (Array.isArray(arg1)) {
    entities = arg1;
    cfg = (arg2 && typeof arg2 === 'object' && arg2.widthMm) ? arg2 : createSheetConfig(arg2);
  } else {
    cfg = (arg1 && typeof arg1 === 'object' && arg1.widthMm) ? arg1 : createSheetConfig(arg1);
    entities = Array.isArray(arg2) ? arg2 : [];
  }
  const layout = computeViewportLayout(cfg, entities);

  const wMm = cfg.widthMm;
  const hMm = cfg.heightMm;
  const pxPerMm = renderOptions.pxPerMm || 3.7795; // ~96 DPI screen preview or 300 DPI print
  const wPx = (wMm * pxPerMm).toFixed(1);
  const hPx = (hMm * pxPerMm).toFixed(1);

  const { drawArea, titleBlock, mmPerMeter, planBounds, viewportCenterMm } = layout;

  // Title block cell paths and labels
  const tb = cfg.titleBlock;
  const tbX = titleBlock.x;
  const tbY = titleBlock.y;
  const tbW = titleBlock.width;
  const tbH = titleBlock.height;

  // Vector linework of plan inside viewport
  // Transform world (meters) to sheet (mm):
  // sheetX = vpCenterX + (worldX - centerX) * mmPerMeter
  // sheetY = vpCenterY - (worldY - centerY) * mmPerMeter
  const worldToSheet = (wx, wy) => ({
    x: viewportCenterMm.x + (wx - planBounds.centerX) * mmPerMeter,
    y: viewportCenterMm.y - (wy - planBounds.centerY) * mmPerMeter
  });

  const planElements = [];

  for (const e of entities) {
    if (!e) continue;
    if (e.kind === 'wall' && typeof e.x1 === 'number') {
      const p1 = worldToSheet(e.x1, e.y1);
      const p2 = worldToSheet(e.x2, e.y2);
      const thMm = (e.thickness || 0.2) * mmPerMeter;
      planElements.push(
        `<line x1="${p1.x.toFixed(2)}" y1="${p1.y.toFixed(2)}" x2="${p2.x.toFixed(2)}" y2="${p2.y.toFixed(2)}" stroke="#1e293b" stroke-width="${Math.max(0.6, thMm).toFixed(2)}" stroke-linecap="round" />`
      );
    } else if (e.kind === 'room' && typeof e.x === 'number' && typeof e.width === 'number') {
      const tl = worldToSheet(e.x, e.y + (e.depth || 0));
      const br = worldToSheet(e.x + e.width, e.y);
      const rw = Math.abs(br.x - tl.x);
      const rh = Math.abs(br.y - tl.y);
      planElements.push(
        `<rect x="${tl.x.toFixed(2)}" y="${tl.y.toFixed(2)}" width="${rw.toFixed(2)}" height="${rh.toFixed(2)}" fill="#f1f5f9" stroke="#94a3b8" stroke-width="0.3" stroke-dasharray="2 1" />`
      );
      if (e.name) {
        const c = worldToSheet(e.x + e.width / 2, e.y + (e.depth || 0) / 2);
        planElements.push(
          `<text x="${c.x.toFixed(2)}" y="${c.y.toFixed(2)}" font-family="system-ui, sans-serif" font-size="2.5" font-weight="600" fill="#334155" text-anchor="middle">${e.name}</text>`
        );
      }
    } else if (e.kind === 'column' && typeof e.x === 'number') {
      const c = worldToSheet(e.x, e.y);
      const cw = (e.width || 0.4) * mmPerMeter;
      const cd = (e.depth || 0.4) * mmPerMeter;
      if (e.profile === 'circle') {
        const cr = (e.radius || 0.2) * mmPerMeter;
        planElements.push(
          `<circle cx="${c.x.toFixed(2)}" cy="${c.y.toFixed(2)}" r="${cr.toFixed(2)}" fill="#475569" stroke="#0f172a" stroke-width="0.4" />`
        );
      } else {
        planElements.push(
          `<rect x="${(c.x - cw / 2).toFixed(2)}" y="${(c.y - cd / 2).toFixed(2)}" width="${cw.toFixed(2)}" height="${cd.toFixed(2)}" fill="#475569" stroke="#0f172a" stroke-width="0.4" />`
        );
      }
    } else if (e.kind === 'grid_line' && e.p1 && e.p2) {
      const p1 = worldToSheet(e.p1.x, e.p1.y);
      const p2 = worldToSheet(e.p2.x, e.p2.y);
      const bRad = (e.bubbleRadius || 0.35) * mmPerMeter;
      planElements.push(
        `<line x1="${p1.x.toFixed(2)}" y1="${p1.y.toFixed(2)}" x2="${p2.x.toFixed(2)}" y2="${p2.y.toFixed(2)}" stroke="#64748b" stroke-width="0.25" stroke-dasharray="4 1.5 1 1.5" />`
      );
      if (e.bubblePosition === 'both' || e.bubblePosition === 'start') {
        planElements.push(
          `<circle cx="${p1.x.toFixed(2)}" cy="${p1.y.toFixed(2)}" r="${bRad.toFixed(2)}" fill="#ffffff" stroke="#475569" stroke-width="0.3" />`,
          `<text x="${p1.x.toFixed(2)}" y="${(p1.y + 0.8).toFixed(2)}" font-family="system-ui, sans-serif" font-size="2.2" font-weight="bold" fill="#0f172a" text-anchor="middle">${e.name}</text>`
        );
      }
      if (e.bubblePosition === 'both' || e.bubblePosition === 'end') {
        planElements.push(
          `<circle cx="${p2.x.toFixed(2)}" cy="${p2.y.toFixed(2)}" r="${bRad.toFixed(2)}" fill="#ffffff" stroke="#475569" stroke-width="0.3" />`,
          `<text x="${p2.x.toFixed(2)}" y="${(p2.y + 0.8).toFixed(2)}" font-family="system-ui, sans-serif" font-size="2.2" font-weight="bold" fill="#0f172a" text-anchor="middle">${e.name}</text>`
        );
      }
    }
  }

  // Viewport Title underline mark
  const vpTitleY = Math.min(viewportCenterMm.y + layout.planSizeMm.height / 2 + 12, drawArea.y + drawArea.height - 8);
  const vpTitleMarkup = `
    <!-- Drawing Viewport Title -->
    <g class="sheet-viewport-title">
      <circle cx="${drawArea.x + 10}" cy="${vpTitleY.toFixed(2)}" r="4.5" fill="none" stroke="#0f172a" stroke-width="0.5" />
      <text x="${drawArea.x + 10}" y="${(vpTitleY + 1.5).toFixed(2)}" font-family="system-ui, sans-serif" font-size="3.5" font-weight="bold" fill="#0f172a" text-anchor="middle">1</text>
      <text x="${drawArea.x + 18}" y="${vpTitleY.toFixed(2)}" font-family="system-ui, sans-serif" font-size="3.5" font-weight="bold" fill="#0f172a">${cfg.viewport.title || 'GROUND FLOOR PLAN'}</text>
      <text x="${drawArea.x + 18}" y="${(vpTitleY + 4.5).toFixed(2)}" font-family="system-ui, sans-serif" font-size="2.5" font-weight="normal" fill="#64748b">SCALE ${cfg.titleBlock.scale || '1:100'}</text>
      <line x1="${drawArea.x + 5}" y1="${(vpTitleY + 7).toFixed(2)}" x2="${drawArea.x + 120}" y2="${(vpTitleY + 7).toFixed(2)}" stroke="#0f172a" stroke-width="0.6" />
    </g>
  `;

  let vignetteMarkup = '';
  if (layout.layoutMode === 'plan_3d' && layout.vignette3D) {
    const vig = layout.vignette3D;
    let inner3DSVG = '';
    if (renderOptions.massingSVG) {
      inner3DSVG = renderOptions.massingSVG;
    } else {
      const docForMassing = renderOptions.document || { entities };
      const model = renderOptions.massingModel || buildMassing3DModel(docForMassing);
      inner3DSVG = generateMassingSVG(model, {
        viewAngle: renderOptions.viewAngle || 'axonometric',
        colorMode: renderOptions.colorMode || 'department'
      });
    }

    let vb = '0 0 800 600';
    const vbMatch = inner3DSVG.match(/viewBox="([^"]+)"/);
    if (vbMatch) vb = vbMatch[1];
    const innerContent = inner3DSVG
      .replace(/^<svg[^>]*>/i, '')
      .replace(/<\/svg>$/i, '');

    vignetteMarkup = `
    <!-- 3D Axonometric Vignette Viewport -->
    <g class="sheet-vignette-3d" id="sheet-vignette-3d">
      <rect x="${vig.x}" y="${vig.y}" width="${vig.width}" height="${vig.height}" fill="#f8fafc" stroke="#0f172a" stroke-width="0.7" />
      <rect x="${vig.x}" y="${vig.y}" width="${vig.width}" height="7" fill="#0f172a" />
      <text x="${vig.x + 4}" y="${vig.y + 4.8}" font-family="system-ui, sans-serif" font-size="2.6" font-weight="bold" fill="#ffffff">2  3D AXONOMETRIC MASSING</text>
      <text x="${vig.x + vig.width - 4}" y="${vig.y + 4.8}" font-family="system-ui, sans-serif" font-size="2" fill="#94a3b8" text-anchor="end">NTS</text>
      <svg x="${vig.x + 1}" y="${vig.y + 7.5}" width="${vig.width - 2}" height="${vig.height - 9}" viewBox="${vb}" preserveAspectRatio="xMidYMid meet">
        ${innerContent}
      </svg>
    </g>`;
  }

  let scheduleMarkup = '';
  if (layout.layoutMode === 'plan_schedule' && layout.scheduleTable) {
    const st = layout.scheduleTable;
    const schedule = renderOptions.schedule || calculateRoomSchedule(entities);
    const totals = renderOptions.floorTotals || calculateFloorTotals(schedule);

    const rowH = 5.2;
    const headerH = 7;
    const colHeaderH = 5.5;
    const footerH = 6;
    const maxDataRows = Math.floor((st.height - headerH - colHeaderH - footerH) / rowH);
    const visibleRooms = schedule.slice(0, Math.max(1, maxDataRows));

    const rowElements = [];
    visibleRooms.forEach((r, idx) => {
      const ry = st.y + headerH + colHeaderH + idx * rowH;
      const bg = idx % 2 === 1 ? '#f8fafc' : '#ffffff';
      rowElements.push(`
        <rect x="${st.x}" y="${ry}" width="${st.width}" height="${rowH}" fill="${bg}" stroke="#e2e8f0" stroke-width="0.25" />
        <text x="${st.x + 8}" y="${ry + 3.6}" font-family="system-ui, sans-serif" font-size="2.1" fill="#475569" text-anchor="middle">${r.roomNumber}</text>
        <text x="${st.x + 18}" y="${ry + 3.6}" font-family="system-ui, sans-serif" font-size="2.1" font-weight="600" fill="#0f172a">${r.name}</text>
        <text x="${st.x + 74}" y="${ry + 3.6}" font-family="system-ui, sans-serif" font-size="2" fill="${(r.zoningTag && r.zoningTag.color) || '#64748b'}">${(r.zoningTag && r.zoningTag.name) || 'General'}</text>
        <text x="${st.x + 136}" y="${ry + 3.6}" font-family="system-ui, sans-serif" font-size="2.1" fill="#0f172a" text-anchor="end">${r.areaM2.toFixed(1)} m²</text>
        <text x="${st.x + 155}" y="${ry + 3.6}" font-family="system-ui, sans-serif" font-size="2.1" font-weight="600" fill="#0f172a" text-anchor="middle">${r.occupantLoad}</text>
      `);
    });

    const footerY = st.y + st.height - footerH;

    scheduleMarkup = `
    <!-- CAD Room & Area Schedule Table -->
    <g class="sheet-schedule-table" id="sheet-schedule-table">
      <rect x="${st.x}" y="${st.y}" width="${st.width}" height="${st.height}" fill="#ffffff" stroke="#0f172a" stroke-width="0.7" />
      
      <!-- Table Header -->
      <rect x="${st.x}" y="${st.y}" width="${st.width}" height="${headerH}" fill="#0f172a" />
      <text x="${st.x + st.width / 2}" y="${st.y + 4.8}" font-family="system-ui, sans-serif" font-size="2.6" font-weight="bold" fill="#ffffff" text-anchor="middle">ROOM &amp; AREA SCHEDULE</text>

      <!-- Column Headers -->
      <rect x="${st.x}" y="${st.y + headerH}" width="${st.width}" height="${colHeaderH}" fill="#f1f5f9" stroke="#cbd5e1" stroke-width="0.3" />
      <text x="${st.x + 8}" y="${st.y + headerH + 3.8}" font-family="system-ui, sans-serif" font-size="1.9" font-weight="bold" fill="#475569" text-anchor="middle">NO.</text>
      <text x="${st.x + 18}" y="${st.y + headerH + 3.8}" font-family="system-ui, sans-serif" font-size="1.9" font-weight="bold" fill="#475569">ROOM NAME</text>
      <text x="${st.x + 74}" y="${st.y + headerH + 3.8}" font-family="system-ui, sans-serif" font-size="1.9" font-weight="bold" fill="#475569">ZONING</text>
      <text x="${st.x + 136}" y="${st.y + headerH + 3.8}" font-family="system-ui, sans-serif" font-size="1.9" font-weight="bold" fill="#475569" text-anchor="end">AREA</text>
      <text x="${st.x + 155}" y="${st.y + headerH + 3.8}" font-family="system-ui, sans-serif" font-size="1.9" font-weight="bold" fill="#475569" text-anchor="middle">OCC</text>
      
      <!-- Data Rows -->
      ${rowElements.join('\n')}

      <!-- Summary Footer -->
      <rect x="${st.x}" y="${footerY}" width="${st.width}" height="${footerH}" fill="#0f172a" />
      <text x="${st.x + 6}" y="${footerY + 4}" font-family="system-ui, sans-serif" font-size="2.2" font-weight="bold" fill="#ffffff">TOTAL NET AREA: ${totals.netInternalArea.toFixed(1)} m²</text>
      <text x="${st.x + st.width - 6}" y="${footerY + 4}" font-family="system-ui, sans-serif" font-size="2.2" font-weight="bold" fill="#38bdf8" text-anchor="end">TOTAL OCC: ${totals.totalOccupants} P</text>
    </g>`;
  }

  let elevationMarkup = '';
  if (layout.layoutMode === 'plan_elevation' && layout.elevationViewport) {
    const ev = layout.elevationViewport;
    const elevDir = renderOptions.elevationDirection || 'south';
    const elevSVG = generateElevationSVG(entities, elevDir, { scale: 30 });
    let vb = '0 0 800 600';
    const vbMatch = elevSVG.match(/viewBox="([^"]+)"/);
    if (vbMatch) vb = vbMatch[1];
    const innerContent = elevSVG
      .replace(/^<svg[^>]*>/i, '')
      .replace(/<\/svg>$/i, '');

    elevationMarkup = `
    <!-- Building Elevation Viewport -->
    <g class="sheet-elevation-viewport" id="sheet-elevation-viewport">
      <rect x="${ev.x}" y="${ev.y}" width="${ev.width}" height="${ev.height}" fill="#0f172a" stroke="#0f172a" stroke-width="0.7" />
      <rect x="${ev.x}" y="${ev.y}" width="${ev.width}" height="7" fill="#0f172a" />
      <text x="${ev.x + 4}" y="${ev.y + 4.8}" font-family="system-ui, sans-serif" font-size="2.6" font-weight="bold" fill="#ffffff">2  ${ev.title}</text>
      <text x="${ev.x + ev.width - 4}" y="${ev.y + 4.8}" font-family="system-ui, sans-serif" font-size="2" fill="#94a3b8" text-anchor="end">1:100</text>
      <svg x="${ev.x + 1}" y="${ev.y + 7.5}" width="${ev.width - 2}" height="${ev.height - 9}" viewBox="${vb}" preserveAspectRatio="xMidYMid meet">
        ${innerContent}
      </svg>
    </g>`;
  }

  let sectionMarkup = '';
  if (layout.layoutMode === 'plan_section' && layout.sectionViewport) {
    const sv = layout.sectionViewport;
    const sectSVG = generateSectionSVG(entities, renderOptions.sectionCut || {}, { scale: 30 });
    let vb = '0 0 800 600';
    const vbMatch = sectSVG.match(/viewBox="([^"]+)"/);
    if (vbMatch) vb = vbMatch[1];
    const innerContent = sectSVG
      .replace(/^<svg[^>]*>/i, '')
      .replace(/<\/svg>$/i, '');

    sectionMarkup = `
    <!-- Building Section Viewport -->
    <g class="sheet-section-viewport" id="sheet-section-viewport">
      <rect x="${sv.x}" y="${sv.y}" width="${sv.width}" height="${sv.height}" fill="#0f172a" stroke="#0f172a" stroke-width="0.7" />
      <rect x="${sv.x}" y="${sv.y}" width="${sv.width}" height="7" fill="#0f172a" />
      <text x="${sv.x + 4}" y="${sv.y + 4.8}" font-family="system-ui, sans-serif" font-size="2.6" font-weight="bold" fill="#ffffff">2  ${sv.title}</text>
      <text x="${sv.x + sv.width - 4}" y="${sv.y + 4.8}" font-family="system-ui, sans-serif" font-size="2" fill="#94a3b8" text-anchor="end">1:100</text>
      <svg x="${sv.x + 1}" y="${sv.y + 7.5}" width="${sv.width - 2}" height="${sv.height - 9}" viewBox="${vb}" preserveAspectRatio="xMidYMid meet">
        ${innerContent}
      </svg>
    </g>`;
  }

  let detailMarkup = '';
  if (layout.layoutMode === 'plan_detail' && layout.detailViewport) {
    const dv = layout.detailViewport;
    const detKey = renderOptions.detailKey || 'footing';
    const detSVG = generateDetailSVG(detKey, { width: 800, height: 600 });
    let vb = '0 0 800 600';
    const vbMatch = detSVG.match(/viewBox="([^"]+)"/);
    if (vbMatch) vb = vbMatch[1];
    const innerContent = detSVG
      .replace(/^<svg[^>]*>/i, '')
      .replace(/<\/svg>$/i, '');

    detailMarkup = `
    <!-- Construction Detail Viewport -->
    <g class="sheet-detail-viewport" id="sheet-detail-viewport">
      <rect x="${dv.x}" y="${dv.y}" width="${dv.width}" height="${dv.height}" fill="#ffffff" stroke="#0f172a" stroke-width="0.7" />
      <rect x="${dv.x}" y="${dv.y}" width="${dv.width}" height="7" fill="#0f172a" />
      <text x="${dv.x + 4}" y="${dv.y + 4.8}" font-family="system-ui, sans-serif" font-size="2.6" font-weight="bold" fill="#ffffff">2  ${dv.title}</text>
      <text x="${dv.x + dv.width - 4}" y="${dv.y + 4.8}" font-family="system-ui, sans-serif" font-size="2" fill="#94a3b8" text-anchor="end">1:10</text>
      <svg x="${dv.x + 1}" y="${dv.y + 7.5}" width="${dv.width - 2}" height="${dv.height - 9}" viewBox="${vb}" preserveAspectRatio="xMidYMid meet">
        ${innerContent}
      </svg>
    </g>`;
  }

  let detailsSheetMarkup = '';
  if (layout.layoutMode === 'details_sheet' && Array.isArray(layout.detailsSheetMatrix)) {
    const parts = [];
    layout.detailsSheetMatrix.forEach((cell, idx) => {
      const cellSVG = generateDetailSVG(cell.detailKey, { width: 800, height: 600 });
      let vb = '0 0 800 600';
      const vbMatch = cellSVG.match(/viewBox="([^"]+)"/);
      if (vbMatch) vb = vbMatch[1];
      const innerContent = cellSVG
        .replace(/^<svg[^>]*>/i, '')
        .replace(/<\/svg>$/i, '');

      parts.push(`
      <g class="sheet-matrix-detail" id="sheet-matrix-detail-${idx + 1}">
        <rect x="${cell.x}" y="${cell.y}" width="${cell.width}" height="${cell.height}" fill="#ffffff" stroke="#0f172a" stroke-width="0.6" />
        <rect x="${cell.x}" y="${cell.y}" width="${cell.width}" height="6.5" fill="#0f172a" />
        <text x="${cell.x + 4}" y="${cell.y + 4.5}" font-family="system-ui, sans-serif" font-size="2.4" font-weight="bold" fill="#ffffff">${cell.title}</text>
        <text x="${cell.x + cell.width - 4}" y="${cell.y + 4.5}" font-family="system-ui, sans-serif" font-size="2" fill="#94a3b8" text-anchor="end">1:10</text>
        <svg x="${cell.x + 1}" y="${cell.y + 7}" width="${cell.width - 2}" height="${cell.height - 8}" viewBox="${vb}" preserveAspectRatio="xMidYMid meet">
          ${innerContent}
        </svg>
      </g>`);
    });
    detailsSheetMarkup = `
    <!-- Construction Details Sheet Matrix -->
    <g class="sheet-details-matrix" id="sheet-details-matrix">
      ${parts.join('\n')}
    </g>`;
  }

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${wMm} ${hMm}" width="${wPx}px" height="${hPx}px">
  <!-- Sheet Background (Paper) -->
  <rect x="0" y="0" width="${wMm}" height="${hMm}" fill="#ffffff" />

  <!-- Outer Sheet Margin Guide -->
  <rect x="5" y="5" width="${wMm - 10}" height="${hMm - 10}" fill="none" stroke="#e2e8f0" stroke-width="0.25" />

  <!-- Inner CAD Drawing Border -->
  <rect x="${drawArea.x}" y="${drawArea.y}" width="${drawArea.width}" height="${drawArea.height}" fill="none" stroke="#0f172a" stroke-width="0.7" />

  <!-- Scaled Plan Viewport Geometry -->
  <g class="sheet-plan-graphics">
    ${planElements.join('\n    ')}
  </g>

  ${vpTitleMarkup}
  ${vignetteMarkup}
  ${scheduleMarkup}
  ${elevationMarkup}
  ${sectionMarkup}
  ${detailMarkup}
  ${detailsSheetMarkup}

  <!-- CAD Title Block -->
  <g class="sheet-title-block" id="title-block" transform="translate(${tbX}, ${tbY})">
    <!-- Title block border -->
    <rect x="0" y="0" width="${tbW}" height="${tbH}" fill="#ffffff" stroke="#0f172a" stroke-width="0.7" />

    <!-- Grid dividing lines -->
    <line x1="0" y1="16" x2="${tbW}" y2="16" stroke="#0f172a" stroke-width="0.4" />
    <line x1="0" y1="32" x2="${tbW}" y2="32" stroke="#0f172a" stroke-width="0.4" />
    <line x1="100" y1="16" x2="100" y2="${tbH}" stroke="#0f172a" stroke-width="0.4" />
    <line x1="135" y1="32" x2="135" y2="${tbH}" stroke="#0f172a" stroke-width="0.4" />

    <!-- Top cell: Practice & Project Name -->
    <text x="6" y="6.5" font-family="system-ui, sans-serif" font-size="2" fill="#64748b" font-weight="600">PROJECT</text>
    <text x="6" y="12" font-family="system-ui, sans-serif" font-size="4" fill="#0f172a" font-weight="bold">${tb.projectName}</text>

    <!-- Middle cell: Drawing Title -->
    <text x="6" y="21" font-family="system-ui, sans-serif" font-size="2" fill="#64748b" font-weight="600">DRAWING TITLE</text>
    <text x="6" y="27" font-family="system-ui, sans-serif" font-size="3.5" fill="#0f172a" font-weight="bold">${tb.sheetTitle}</text>

    <!-- Bottom Left: Author & Date -->
    <text x="6" y="37" font-family="system-ui, sans-serif" font-size="1.8" fill="#64748b">AUTHOR: <tspan fill="#0f172a" font-weight="bold">${tb.author}</tspan></text>
    <text x="6" y="43" font-family="system-ui, sans-serif" font-size="1.8" fill="#64748b">DATE: <tspan fill="#0f172a" font-weight="bold">${tb.date}</tspan></text>

    <!-- Middle Right: Scale & Rev -->
    <text x="104" y="21" font-family="system-ui, sans-serif" font-size="2" fill="#64748b" font-weight="600">SCALE</text>
    <text x="104" y="27" font-family="system-ui, sans-serif" font-size="3.5" fill="#0f172a" font-weight="bold">${tb.scale}</text>

    <text x="104" y="37" font-family="system-ui, sans-serif" font-size="2" fill="#64748b" font-weight="600">REV</text>
    <text x="104" y="44" font-family="system-ui, sans-serif" font-size="4" fill="#0f172a" font-weight="bold">${tb.revision}</text>

    <!-- Bottom Right: Sheet Number -->
    <text x="139" y="37" font-family="system-ui, sans-serif" font-size="2" fill="#64748b" font-weight="600">SHEET NO.</text>
    <text x="139" y="44" font-family="system-ui, sans-serif" font-size="5" fill="#0f172a" font-weight="bold">${tb.sheetNumber}</text>

    <!-- Mini North Arrow inside title block -->
    <g class="sheet-north-arrow" id="north-arrow" transform="translate(${tbW - 14}, 8) scale(0.6)">
      <polygon points="0,-7 -3.5,4 0,1.5" fill="#0f172a" />
      <polygon points="0,-7 0,1.5 3.5,4" fill="#94a3b8" />
      <text x="0" y="-8.5" font-family="system-ui, sans-serif" font-size="3" font-weight="bold" fill="#0f172a" text-anchor="middle">N</text>
    </g>
  </g>
</svg>`;
}


  // =========================================================================
  // MODULE: SpacePlanning
  // =========================================================================

/**
 * Architecture Helping Hand - Space Planning Core
 * Phase 5: deterministic spatial reasoning over plan entities.
 *
 * Evidence-first: every check returns numbers explaining the verdict —
 * never a bare boolean. Clearance values are USER-CONFIGURED study
 * envelopes, NOT universal legal requirements (labels: User Configured /
 * Educational Reference / Needs Verification).
 *
 * Scope: rectilinear rooms/furniture (axis-aligned rects), straight
 * corridors. No pathfinding, no terrain, no compliance claims.
 */




/** Default clearance envelopes (educational study values, user-configurable). */
const DEFAULT_CLEARANCES = Object.freeze({
  circulation: 0.9,      // m — common study value for a walkway
  wheelchairTurning: 1.5, // m — widely taught turning circle diameter (study value)
  doorApproach: 0.75,    // m — clear space in front of a door (study value)
  bedSide: 0.6,          // m — walking space beside a bed (study value)
  deskChair: 0.75,       // m — chair pull-back (study value)
  diningChair: 0.75      // m — chair pull-back (study value)
});

/**
 * Furniture-fit check for one piece inside one room.
 * @returns {{ verdict: 'fits'|'partial'|'no-fit', evidence: {...} }}
 */
function checkFurnitureFit(furniture, room) {
  if (!furniture || !room) {
    return { verdict: 'no-fit', evidence: { reason: 'missing furniture or room' } };
  }
  const fr = { x: furniture.x, y: furniture.y, width: furniture.width, depth: furniture.depth };
  const fitsEntirely = fr.x >= room.x - 1e-9 && fr.y >= room.y - 1e-9 &&
    fr.x + fr.width <= room.x + room.width + 1e-9 &&
    fr.y + fr.depth <= room.y + room.depth + 1e-9;

  if (fitsEntirely) {
    return {
      verdict: 'fits',
      evidence: {
        furnitureId: furniture.id, roomId: room.id,
        furnitureWidth: furniture.width, furnitureDepth: furniture.depth,
        roomWidth: room.width, roomDepth: room.depth,
        marginEast: room.x + room.width - (fr.x + fr.width),
        marginWest: fr.x - room.x,
        marginNorth: room.y + room.depth - (fr.y + fr.depth),
        marginSouth: fr.y - room.y
      }
    };
  }

  // Partial: does any part overlap the room?
  const intersects = rectsIntersect(fr, { x: room.x, y: room.y, width: room.width, depth: room.depth });
  if (intersects) {
    return {
      verdict: 'partial',
      evidence: {
        furnitureId: furniture.id, roomId: room.id,
        reason: 'Furniture partially inside the room — protrudes beyond a wall.',
        furnitureWidth: furniture.width, furnitureDepth: furniture.depth,
        roomWidth: room.width, roomDepth: room.depth
      }
    };
  }
  return {
    verdict: 'no-fit',
    evidence: { furnitureId: furniture.id, roomId: room.id, reason: 'Furniture entirely outside the room.' }
  };
}

/**
 * Clearance envelope check: does the furniture respect the requested
 * clearance on all sides within the room? (Envelope-based, not pathfinding.)
 */
function checkClearance(furniture, room, clearanceMeters, clearanceLabel = 'User Configured') {
  const fr = furniture;
  const innerRoom = {
    x: room.x + clearanceMeters,
    y: room.y + clearanceMeters,
    width: room.width - 2 * clearanceMeters,
    depth: room.depth - 2 * clearanceMeters
  };
  if (innerRoom.width <= 0 || innerRoom.depth <= 0) {
    return {
      satisfied: false, clearanceMeters, clearanceLabel,
      evidence: { reason: `Room smaller than 2 × clearance (${clearanceMeters} m on each side).` }
    };
  }
  const inside = fr.x >= innerRoom.x - 1e-9 && fr.y >= innerRoom.y - 1e-9 &&
    fr.x + fr.width <= innerRoom.x + innerRoom.width + 1e-9 &&
    fr.y + fr.depth <= innerRoom.y + innerRoom.depth + 1e-9;

  return {
    satisfied: inside,
    clearanceMeters,
    clearanceLabel,
    evidence: inside
      ? { reason: `Furniture stays within the ${clearanceMeters} m envelope on all sides.` }
      : {
          reason: `Furniture breaches the ${clearanceMeters} m envelope on at least one side.`,
          availableMarginEast: innerRoom.x + innerRoom.width - (fr.x + fr.width),
          availableMarginWest: fr.x - innerRoom.x,
          availableMarginNorth: innerRoom.y + innerRoom.depth - (fr.y + fr.depth),
          availableMarginSouth: fr.y - innerRoom.y
        }
  };
}

/**
 * Overlap detection between furniture pieces, furniture vs walls, and
 * furniture outside any room. Deterministic rect math with evidence.
 */
function checkOverlaps(furnitureList, rooms, walls) {
  const conflicts = [];
  const furn = furnitureList || [];
  const roomList = rooms || [];
  const wallList = walls || [];

  // furniture vs furniture
  for (let i = 0; i < furn.length; i++) {
    for (let j = i + 1; j < furn.length; j++) {
      if (rectsIntersect(furn[i], furn[j])) {
        conflicts.push({
          type: 'furniture-furniture',
          a: furn[i].id, b: furn[j].id,
          aName: furn[i].name, bName: furn[j].name,
          evidence: `Overlap area between "${furn[i].name}" and "${furn[j].name}".`
        });
      }
    }
    // furniture vs walls
    for (const w of wallList) {
      if (rectsIntersect(furn[i], wallRect(w))) {
        conflicts.push({
          type: 'furniture-wall',
          a: furn[i].id, b: w.id,
          aName: furn[i].name, bName: w.name,
          evidence: `"${furn[i].name}" intersects wall "${w.name}".`
        });
      }
    }
    // furniture outside every room
    const contained = roomList.some(r =>
      furn[i].x >= r.x - 1e-9 && furn[i].y >= r.y - 1e-9 &&
      furn[i].x + furn[i].width <= r.x + r.width + 1e-9 &&
      furn[i].y + furn[i].depth <= r.y + r.depth + 1e-9);
    if (roomList.length > 0 && !contained) {
      conflicts.push({
        type: 'furniture-outside-room',
        a: furn[i].id, b: null,
        aName: furn[i].name, bName: null,
        evidence: `"${furn[i].name}" is not fully inside any room.`
      });
    }
  }
  return { conflicts, count: conflicts.length };
}

/**
 * Adjacency: explicit relationships between rooms sharing a wall edge or
 * declared in the project. Returns satisfied/missing with evidence.
 * Touch test: rooms are adjacent if any edge of one coincides with an edge
 * of the other (within epsilon) — corner-only contact is NOT adjacency.
 */
function checkAdjacency(adjacencyRequirements, rooms) {
  const roomList = rooms || [];
  const eps = 1e-6;
  const results = (adjacencyRequirements || []).map(req => {
    const a = roomList.find(r => r.id === req.a || r.name === req.a);
    const b = roomList.find(r => r.id === req.b || r.name === req.b);
    if (!a || !b) {
      return { ...req, satisfied: false, evidence: 'One or both rooms do not exist in the plan.' };
    }
    // Vertical edge shared: a right edge == b left edge (or vice versa), with y-overlap
    const verticalTouch =
      (Math.abs((a.x + a.width) - b.x) < eps || Math.abs((b.x + b.width) - a.x) < eps) &&
      a.y < b.y + b.depth - eps && b.y < a.y + a.depth - eps;
    // Horizontal edge shared: a top edge == b bottom edge (or vice versa), with x-overlap
    const horizontalTouch =
      (Math.abs((a.y + a.depth) - b.y) < eps || Math.abs((b.y + b.depth) - a.y) < eps) &&
      a.x < b.x + b.width - eps && b.x < a.x + a.width - eps;
    const touching = verticalTouch || horizontalTouch;
    return {
      ...req,
      satisfied: touching,
      evidence: touching
        ? `"${a.name}" and "${b.name}" share an edge.`
        : `"${a.name}" and "${b.name}" do not share an edge in the current plan.`
    };
  });
  const satisfiedCount = results.filter(r => r.satisfied).length;
  return { results, satisfiedCount, total: results.length };
}

/**
 * Efficiency metrics for a plan. Formulas documented in evidence.
 */
function calculateEfficiency(rooms, furnitureList, circulationAreaM2 = 0) {
  const roomList = rooms || [];
  const furn = furnitureList || [];
  const totalRoomArea = roomList.reduce((acc, r) => acc + roomArea(r), 0);
  const occupiedArea = furn.reduce((acc, f) => acc + f.width * f.depth, 0);
  const circulation = Math.max(0, circulationAreaM2);
  const usableArea = Math.max(0, totalRoomArea - occupiedArea - circulation);
  return {
    totalRoomAreaM2: totalRoomArea,
    occupiedAreaM2: occupiedArea,
    circulationAreaM2: circulation,
    usableAreaM2: usableArea,
    occupancyPercent: totalRoomArea > 0 ? (occupiedArea / totalRoomArea) * 100 : 0,
    circulationPercent: totalRoomArea > 0 ? (circulation / totalRoomArea) * 100 : 0,
    furnitureCount: furn.length,
    roomCount: roomList.length,
    formulaNotes: {
      usableArea: 'totalRoomArea − occupiedArea − circulationArea',
      occupancyPercent: 'occupiedArea / totalRoomArea × 100',
      circulationPercent: 'circulationArea / totalRoomArea × 100',
      note: 'Circulation area is user-supplied (rectangle sum or estimate) — the analyzer does not pathfind.'
    }
  };
}

/**
 * Layout comparison across snapshots/options: shows differences rather than
 * declaring a winner.
 */
function compareLayouts(layouts) {
  const rows = (layouts || []).map((l, idx) => ({
    label: l.label || `Option ${String.fromCharCode(65 + idx)}`,
    roomCount: (l.rooms || []).length,
    totalAreaM2: (l.rooms || []).reduce((acc, r) => acc + roomArea(r), 0),
    furnitureCount: (l.furniture || []).length,
    conflicts: l.conflicts !== undefined ? l.conflicts : (l.furniture || []).length,
    efficiency: l.efficiency || null
  }));
  const best = rows.reduce((acc, r) => (r.conflicts < acc.conflicts ? r : acc), rows[0] || null);
  return {
    rows,
    fewestConflicts: best ? best.label : null,
    note: 'Differences are shown, not judged. Choose per brief: area, conflicts, adjacency, and efficiency trade off against each other.'
  };
}

/**
 * Simple corridor-width check: minimum unobstructed passage between two
 * parallel boundaries on a straight segment (no pathfinding).
 */
function checkCorridorWidth(corridorRect, obstacles, minwidthMeters = DEFAULT_CLEARANCES.circulation) {
  // Corridor modeled as a rect; obstacles intersecting it reduce usable width.
  // Simplified evidence: list obstructions and compare with the minimum width.
  const obstructions = (obstacles || []).filter(o => rectsIntersect(corridorRect, o));
  return {
    corridorWidthMeters: corridorRect.width,
    minimumRequiredMeters: minwidthMeters,
    obstructionCount: obstructions.length,
    obstructions: obstructions.map(o => o.name || o.id),
    clear: obstructions.length === 0 && corridorRect.width >= minwidthMeters - 1e-9,
    evidence: obstructions.length > 0
      ? `${obstructions.length} obstruction(s) inside the corridor envelope.`
      : `Corridor is ${corridorRect.width.toFixed(2)} m wide (minimum ${minwidthMeters} m).`
  };
}


  // =========================================================================
  // MODULE: Survey
  // =========================================================================

/**
 * Architecture Helping Hand - Survey & Calibration Core
 * Phases 6+7: measurement notebook with provenance + raster image
 * calibration math. Pure, deterministic, zero-DOM.
 *
 * Survey measurements keep provenance (source + verification status) and
 * may stay uncertain — recording does not force geometry.
 * Calibration maps image pixels ↔ world meters through a two-point known
 * distance; the math is exact and testable without a browser.
 */



// ---------------------------------------------------------------------------
// Phase 6: Survey / Measurement Notebook
// ---------------------------------------------------------------------------

const MEASUREMENT_SOURCES = Object.freeze([
  'Measured', 'Estimated', 'Imported', 'AI Interpreted', 'User Entered'
]);

const MEASUREMENT_STATUSES = Object.freeze([
  'Verified', 'Unverified', 'Needs Review'
]);

/**
 * Creates a survey measurement record. Values are stored as entered plus a
 * canonical meters field when parseable; uncertain records stay records.
 */
function createMeasurement({ id, label, value, unit = 'm', source = 'Measured', status = 'Unverified', location = '', note = '', timestamp = null, roomId = null }) {
  if (typeof label !== 'string' || !label.trim()) {
    throw new TypeError('Measurement requires a label');
  }
  requireFiniteNumber(value, 'measurement.value');
  if (value <= 0) throw new Error('Measurement value must be greater than zero');
  if (!MEASUREMENT_SOURCES.includes(source)) {
    throw new Error(`Invalid measurement source "${source}". Valid: ${MEASUREMENT_SOURCES.join(', ')}`);
  }
  if (!MEASUREMENT_STATUSES.includes(status)) {
    throw new Error(`Invalid measurement status "${status}". Valid: ${MEASUREMENT_STATUSES.join(', ')}`);
  }
  return {
    kind: 'measurement',
    id: id || `meas-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    label: label.trim(),
    value,
    unit,
    meters: null, // filled by the caller with the unit system (kept pure here)
    source,
    status,
    location: typeof location === 'string' ? location : '',
    note: typeof note === 'string' ? note : '',
    timestamp: timestamp || new Date().toISOString(),
    roomId
  };
}

/** Marks a measurement verified / needs-review (returns a new record). */
function setMeasurementStatus(measurement, status) {
  if (!MEASUREMENT_STATUSES.includes(status)) {
    throw new Error(`Invalid status "${status}"`);
  }
  return { ...measurement, status };
}

/** Survey summary: counts by status and source, flagged items. */
function summarizeSurvey(measurements) {
  const list = measurements || [];
  return {
    total: list.length,
    byStatus: MEASUREMENT_STATUSES.reduce((acc, s) => ({ ...acc, [s]: list.filter(m => m.status === s).length }), {}),
    bySource: MEASUREMENT_SOURCES.reduce((acc, s) => ({ ...acc, [s]: list.filter(m => m.source === s).length }), {}),
    needsAttention: list.filter(m => m.status !== 'Verified').map(m => ({ id: m.id, label: m.label, status: m.status }))
  };
}

/**
 * Converts recorded survey measurements into room-candidate dimensions when
 * the student explicitly chooses (label convention: "Room W" / "Room D").
 * Only VERIFIED records become proposal geometry — unverified measurements
 * stay records. Returns a proposal — never silently mutates the plan.
 */
function proposeRoomFromMeasurements(measurements, roomName) {
  const list = measurements || [];
  const verified = list.filter(m => m.status === 'Verified');
  const width = verified.find(m => /(^|\s)(W|width)$/i.test(m.label)) || verified[0] || null;
  const depth = verified.find(m => /(^|\s)(D|depth)$/i.test(m.label)) || verified[1] || null;
  return {
    proposal: width && depth ? {
      name: roomName || 'Surveyed Room',
      widthMeters: width.meters !== null ? width.meters : width.value,
      depthMeters: depth.meters !== null ? depth.meters : depth.value,
      basedOn: [width.id, depth.id],
      note: 'Proposal only — the student accepts/edits it before any plan change.'
    } : null,
    needsMore: !width || !depth,
    unverifiedCount: list.filter(m => m.status !== 'Verified').length
  };
}

// ---------------------------------------------------------------------------
// Phase 7: Drawing / Image Calibration
// ---------------------------------------------------------------------------

/**
 * Creates a calibration from two image points and a known real distance.
 * Pure math: scale = realMeters / pixelDistance (meters per pixel).
 */
function createCalibration({ pointA, pointB, realMeters, unitLabel = 'm' }) {
  if (!pointA || !pointB || typeof pointA.x !== 'number' || typeof pointA.y !== 'number' ||
      typeof pointB.x !== 'number' || typeof pointB.y !== 'number') {
    throw new TypeError('Calibration requires two image points with numeric x/y.');
  }
  requireFiniteNumber(realMeters, 'calibration.realMeters');
  if (realMeters <= 0) throw new Error('Known real distance must be greater than zero');
  const pixelDistance = Math.hypot(pointB.x - pointA.x, pointB.y - pointA.y);
  if (pixelDistance <= 0) throw new Error('The two calibration points must differ.');
  return {
    kind: 'calibration',
    pointA, pointB,
    pixelDistance,
    realMeters,
    unitLabel,
    metersPerPixel: realMeters / pixelDistance,
    pixelsPerMeter: pixelDistance / realMeters
  };
}

/** Converts an image pixel coordinate to calibrated world meters. */
function pixelToWorld(calibration, px, py) {
  return {
    x: px * calibration.metersPerPixel,
    y: py * calibration.metersPerPixel
  };
}

/** Converts world meters back to image pixels. */
function worldToPixel(calibration, wx, wy) {
  return {
    x: wx * calibration.pixelsPerMeter,
    y: wy * calibration.pixelsPerMeter
  };
}

/** Distance between two pixel points, expressed in calibrated meters. */
function calibratedDistance(calibration, a, b) {
  const pixelDist = Math.hypot(b.x - a.x, b.y - a.y);
  return pixelDist * calibration.metersPerPixel;
}

/**
 * Chained measurement: sums calibrated segments (point-to-point walk).
 */
function calibratedChainDistance(calibration, points) {
  if (!Array.isArray(points) || points.length < 2) {
    throw new TypeError('Chained measurement requires at least two points.');
  }
  let total = 0;
  for (let i = 1; i < points.length; i++) {
    total += calibratedDistance(calibration, points[i - 1], points[i]);
  }
  return total;
}

/** Shoelace area of a pixel polygon, in calibrated square meters. */
function calibratedPolygonArea(calibration, points) {
  if (!Array.isArray(points) || points.length < 3) {
    throw new TypeError('Polygon area requires at least three points.');
  }
  let sum = 0;
  for (let i = 0; i < points.length; i++) {
    const a = points[i];
    const b = points[(i + 1) % points.length];
    sum += a.x * b.y - b.x * a.y;
  }
  return Math.abs(sum / 2) * calibration.metersPerPixel ** 2;
}

// ---------------------------------------------------------------------------
// Image constraints (weak laptop: conservative limits, documented)
// ---------------------------------------------------------------------------

const IMAGE_LIMITS = Object.freeze({
  maxFileBytes: 10 * 1024 * 1024,      // 10 MB import cap
  maxPixelDimension: 2000,             // downscale longest side to 2000 px
  recommendedFormats: ['png', 'jpg', 'jpeg', 'webp'],
  storageNote: 'Image blobs belong in IndexedDB (future) — never base64 in localStorage.'
});

/** Validates an image descriptor against the documented limits. */
function validateImageMeta({ widthPx, heightPx, bytes }) {
  const problems = [];
  if (typeof bytes === 'number' && bytes > IMAGE_LIMITS.maxFileBytes) {
    problems.push(`File exceeds the ${IMAGE_LIMITS.maxFileBytes / 1024 / 1024} MB import cap.`);
  }
  if (typeof widthPx === 'number' && typeof heightPx === 'number') {
    const longest = Math.max(widthPx, heightPx);
    if (longest > IMAGE_LIMITS.maxPixelDimension) {
      problems.push(`Image will be downscaled: longest side ${longest} px > ${IMAGE_LIMITS.maxPixelDimension} px.`);
    }
  }
  return { ok: problems.length === 0, problems, limits: IMAGE_LIMITS };
}


  // =========================================================================
  // MODULE: Annotations
  // =========================================================================

/**
 * Architecture Helping Hand - Annotations Core
 * Phase 8: structured 2D annotation objects for the plan canvas and
 * calibrated images. Pure data + validation; rendering is the view's job.
 *
 * Supported kinds: text, dimension, arrow, line, rect, circle, note-marker.
 * Annotations live in the project document (id-referenced) and participate
 * in undo/redo through the plan history.
 */



const ANNOTATION_KINDS = Object.freeze([
  'text', 'dimension', 'arrow', 'line', 'rect', 'circle', 'note'
]);

/**
 * Creates a validated annotation. Geometry is in the coordinate space of
 * whatever layer it belongs to (plan world meters or image pixels) — the
 * layer field records which.
 */
function createAnnotation({ id, kind, layer = 'plan', x, y, x2, y2, text = '', color = 'accent', roomId = null, imageId = null, createdAt = null }) {
  if (!ANNOTATION_KINDS.includes(kind)) {
    throw new Error(`Invalid annotation kind "${kind}". Valid: ${ANNOTATION_KINDS.join(', ')}`);
  }
  requireFiniteNumber(x, 'annotation.x');
  requireFiniteNumber(y, 'annotation.y');
  if (['dimension', 'arrow', 'line', 'rect'].includes(kind)) {
    requireFiniteNumber(x2, 'annotation.x2');
    requireFiniteNumber(y2, 'annotation.y2');
  }
  if (kind === 'text' && (typeof text !== 'string' || !text.trim())) {
    throw new Error('Text annotations require non-empty text.');
  }
  if (kind === 'note' && (typeof text !== 'string' || !text.trim())) {
    throw new Error('Note markers require note text.');
  }
  if (kind === 'circle') {
    // circle stores radius in x2
    requireFiniteNumber(x2, 'annotation.radius');
    if (x2 <= 0) throw new Error('Circle radius must be greater than zero.');
  }
  return {
    kind: 'annotation',
    annotationKind: kind,
    id: id || `ann-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 7)}`,
    layer, // 'plan' | 'image'
    x, y,
    x2: x2 !== undefined ? x2 : null,
    y2: y2 !== undefined ? y2 : null,
    text,
    color,
    roomId,
    imageId,
    createdAt: createdAt || new Date().toISOString()
  };
}

/** Moves an annotation by dx/dy (both anchor and end). Returns a new object. */
function moveAnnotation(annotation, dx, dy) {
  return {
    ...annotation,
    x: annotation.x + dx,
    y: annotation.y + dy,
    x2: annotation.x2 !== null ? annotation.x2 + dx : null,
    y2: annotation.y2 !== null ? annotation.y2 + dy : null
  };
}

/** Dimension annotations expose their measured length (same-space units). */
function annotationLength(annotation) {
  if (annotation.annotationKind !== 'dimension' && annotation.annotationKind !== 'line' && annotation.annotationKind !== 'arrow') {
    return null;
  }
  return Math.hypot(annotation.x2 - annotation.x, annotation.y2 - annotation.y);
}

/** Validates a list of annotation payloads; returns { valid, errors } without throwing. */
function validateAnnotations(annotations) {
  const errors = [];
  for (const a of annotations || []) {
    try {
      // Strip wrapper fields so raw payloads validate cleanly
      const { kind: wrapperKind, id, createdAt, ...rest } = a || {};
      createAnnotation({ ...rest, kind: rest.annotationKind || a?.annotationKind || a?.kind });
    } catch (e) {
      errors.push({ id: a?.id || null, error: e.message });
    }
  }
  return { valid: errors.length === 0, errors };
}


