/**
 * Architecture Helping Hand - Customizable Keyboard Shortcuts Manager
 * Implements architectural CAD conventions (AutoCAD, Revit, Rhino, SketchUp)
 * with dynamic rebinding, conflict detection, and local storage persistence.
 */

const DEFAULT_SHORTCUTS = [
  // Plan Canvas & Drafting (Architectural CAD Standard)
  { id: 'tool_select', label: 'Select & Transform', category: 'canvas', defaultKey: 'v', key: 'v', description: 'Switch to selection and transform tool' },
  { id: 'tool_wall', label: 'Draw Wall Segment', category: 'canvas', defaultKey: 'w', key: 'w', description: 'Switch to continuous wall placement' },
  { id: 'tool_room', label: 'Draw Room Rectangle', category: 'canvas', defaultKey: 'r', key: 'r', description: 'Draw rectangular room footprint' },
  { id: 'tool_furniture', label: 'Place Furniture', category: 'canvas', defaultKey: 'f', key: 'f', description: 'Place selected furniture block' },
  { id: 'tool_measure', label: 'Tape Measure', category: 'canvas', defaultKey: 'm', key: 'm', description: 'Measure distance between points' },
  { id: 'tool_dimension', label: 'Dimension String', category: 'canvas', defaultKey: 'd', key: 'd', description: 'Place aligned architectural dimension string' },
  { id: 'tool_stair', label: 'Place Stair Flight', category: 'canvas', defaultKey: 't', key: 't', description: 'Place parametric stair flight' },
  { id: 'tool_ramp', label: 'Place Ramp Wedge', category: 'canvas', defaultKey: 'p', key: 'p', description: 'Place accessible ramp entity' },
  { id: 'plan_grid', label: 'Cycle Grid Snap', category: 'canvas', defaultKey: 'g', key: 'g', description: 'Cycle grid snap increment' },
  { id: 'plan_snap', label: 'Toggle Snapping', category: 'canvas', defaultKey: 's', key: 's', description: 'Toggle smart snapping on/off' },
  { id: 'plan_zoom_fit', label: 'Zoom to Extents', category: 'canvas', defaultKey: 'z', key: 'z', description: 'Frame entire plan on canvas' },
  { id: 'plan_duplicate', label: 'Duplicate Entity', category: 'canvas', defaultKey: 'ctrl+d', key: 'ctrl+d', description: 'Duplicate selected entity with offset' },
  { id: 'plan_delete', label: 'Delete Selected', category: 'canvas', defaultKey: 'delete', key: 'delete', description: 'Remove selected entity from plan' },
  { id: 'plan_cancel', label: 'Cancel / Deselect', category: 'canvas', defaultKey: 'escape', key: 'escape', description: 'Clear selection or cancel active tool' },
  { id: 'plan_undo', label: 'Undo Plan Action', category: 'canvas', defaultKey: 'ctrl+z', key: 'ctrl+z', description: 'Undo last drafting step' },
  { id: 'plan_redo', label: 'Redo Plan Action', category: 'canvas', defaultKey: 'ctrl+y', key: 'ctrl+y', description: 'Redo undone drafting step' },

  // Studio Navigation & Tools
  { id: 'cmd_palette', label: 'Studio Command Bar', category: 'studio', defaultKey: 'ctrl+k', key: 'ctrl+k', description: 'Open natural language command palette' },
  { id: 'quick_dim', label: 'Quick Dimension Strip', category: 'studio', defaultKey: 'q', key: 'q', description: 'Toggle quick dimension flyout' },
  { id: 'cad_clipboard', label: 'Open CAD Clipboard', category: 'studio', defaultKey: 'c', key: 'c', description: 'Direct CAD clipboard formatter' },
  { id: 'batch_cad', label: 'Batch CAD Converter', category: 'studio', defaultKey: 'b', key: 'b', description: 'Multi-line CAD batch converter' },
  { id: 'history_drawer', label: 'Calculation Journal', category: 'studio', defaultKey: 'h', key: 'h', description: 'Toggle history journal drawer' },
  { id: 'shortcuts_modal', label: 'Shortcuts Reference', category: 'studio', defaultKey: '?', key: '?', description: 'View and customize keybindings' }
];

const SHORTCUTS_STORAGE_KEY = 'archiscale_custom_shortcuts';

/**
 * Normalizes a keyboard event or string into a canonical lowercase combo string.
 * Examples: 'Ctrl + D' -> 'ctrl+d', KeyboardEvent(ctrlKey=true, key='D') -> 'ctrl+d'
 */
function normalizeKeyCombo(input) {
  if (!input) return '';
  if (typeof input === 'string') {
    return input
      .toLowerCase()
      .replace(/\s+/g, '')
      .replace(/[⌘]/g, 'ctrl+')
      .replace(/cmd|command|meta/g, 'ctrl')
      .replace(/del/g, 'delete')
      .replace(/esc/g, 'escape');
  }

  // Handle KeyboardEvent
  if (typeof input === 'object' && input.key) {
    const rawKey = input.key;
    if (['Control', 'Shift', 'Alt', 'Meta'].includes(rawKey)) {
      return ''; // Modifiers alone are not a full combo
    }

    const parts = [];
    if (input.ctrlKey || input.metaKey) parts.push('ctrl');
    if (input.altKey) parts.push('alt');
    // Shift+<letter> arrives as an uppercase key ('M'); without this guard the
    // Shift modifier is dropped and Shift+M collapses onto bare 'm'.
    if (input.shiftKey && (rawKey.length > 1 || /^[A-Z]$/.test(rawKey))) parts.push('shift');

    let keyName = rawKey.toLowerCase();
    if (keyName === 'escape' || keyName === 'esc') keyName = 'escape';
    else if (keyName === 'delete' || keyName === 'backspace') keyName = 'delete';

    parts.push(keyName);
    return parts.join('+');
  }

  return '';
}

/**
 * Formats a canonical combo string for elegant UI display.
 * Example: 'ctrl+d' -> 'Ctrl + D', 'escape' -> 'Esc'
 */
function formatDisplayKey(combo) {
  if (!combo) return '';
  const isMac = typeof navigator !== 'undefined' && /Mac|iPhone|iPad|iPod/.test(navigator.platform || '');
  return combo
    .split('+')
    .map(part => {
      const p = part.trim().toLowerCase();
      if (p === 'ctrl') return isMac ? '⌘' : 'Ctrl';
      if (p === 'alt') return isMac ? '⌥' : 'Alt';
      if (p === 'shift') return isMac ? '⇧' : 'Shift';
      if (p === 'escape') return 'Esc';
      if (p === 'delete') return 'Del';
      if (p === 'enter') return '↵ Enter';
      if (p === 'space') return 'Space';
      return p.toUpperCase();
    })
    .join(isMac ? '' : ' + ');
}

/**
 * ShortcutsManager Class: handles loading, saving, rebinding, conflict detection,
 * and keydown event matching.
 */
class ShortcutsManagerClass {
  constructor() {
    this.shortcuts = DEFAULT_SHORTCUTS.map(s => ({ ...s }));
    this.listeners = new Set();
    this.storage = null;
    this.initStorage();
    this.loadFromStorage();
  }

  initStorage() {
    try {
      if (typeof window !== 'undefined' && window.localStorage) {
        this.storage = window.localStorage;
      }
    } catch {
      this.storage = null;
    }
  }

  /**
   * Set custom storage adapter (e.g. for testing)
   */
  setStorage(storageAdapter) {
    this.storage = storageAdapter;
    this.loadFromStorage();
  }

  loadFromStorage() {
    if (!this.storage) return;
    try {
      const raw = this.storage.getItem(SHORTCUTS_STORAGE_KEY);
      if (!raw) return;
      const customBindings = JSON.parse(raw);
      if (customBindings && typeof customBindings === 'object') {
        for (const item of this.shortcuts) {
          if (typeof customBindings[item.id] === 'string' && customBindings[item.id].trim().length > 0) {
            item.key = normalizeKeyCombo(customBindings[item.id]);
          }
        }
        // Resolve collisions between stored bindings (possible from versions
        // that allowed cross-category duplicates or dropped Shift modifiers).
        // Policy: defaults always win. All default keys are reserved first,
        // then a stored custom binding is honored only if it does not collide;
        // colliding customs reset to their default. This guarantees the loaded
        // set has no duplicate keys (unlike first-in-order wins, which can
        // reset a duplicate onto the very key that spawned it).
        const taken = new Set(this.shortcuts.map(s => s.defaultKey));
        let mutated = false;
        for (const item of this.shortcuts) {
          const custom = customBindings[item.id];
          if (
            typeof custom === 'string' && custom.trim().length > 0 &&
            normalizeKeyCombo(custom) === item.key && item.key !== item.defaultKey &&
            !taken.has(item.key)
          ) {
            taken.add(item.key); // custom binding is collision-free — keep it
          } else if (item.key !== item.defaultKey) {
            item.key = item.defaultKey; // colliding/stale custom — discard
            mutated = true;
          }
        }
        if (mutated) this.saveToStorage();
      }
    } catch {
      // Corrupt storage handled safely
    }
  }

  saveToStorage() {
    if (!this.storage) return;
    try {
      const bindings = {};
      for (const item of this.shortcuts) {
        if (item.key !== item.defaultKey) {
          bindings[item.id] = item.key;
        }
      }
      if (Object.keys(bindings).length === 0) {
        this.storage.removeItem(SHORTCUTS_STORAGE_KEY);
      } else {
        this.storage.setItem(SHORTCUTS_STORAGE_KEY, JSON.stringify(bindings));
      }
    } catch {
      // Ignore storage quota errors
    }
  }

  /**
   * Returns all registered shortcuts with their current bindings.
   */
  getAllShortcuts() {
    return this.shortcuts.map(s => ({
      ...s,
      displayKey: formatDisplayKey(s.key),
      isCustom: s.key !== s.defaultKey
    }));
  }

  /**
   * Get a shortcut by its action ID.
   */
  getShortcut(id) {
    const s = this.shortcuts.find(x => x.id === id);
    if (!s) return null;
    return {
      ...s,
      displayKey: formatDisplayKey(s.key),
      isCustom: s.key !== s.defaultKey
    };
  }

  /**
   * Get the current key combo for an action ID.
   */
  getKeyForAction(id) {
    const s = this.shortcuts.find(x => x.id === id);
    return s ? s.key : '';
  }

  /**
   * Rebinds a shortcut to a new key combination with conflict detection.
   * @param {string} id - The action ID to rebind
   * @param {string|KeyboardEvent} newKeyCombo - The new shortcut
   * @returns {{ success: boolean, conflict?: Object, error?: string }}
   */
  bindShortcut(id, newKeyCombo) {
    const target = this.shortcuts.find(x => x.id === id);
    if (!target) {
      return { success: false, error: `Shortcut ID "${id}" not found.` };
    }

    const normalized = normalizeKeyCombo(newKeyCombo);
    if (!normalized) {
      return { success: false, error: 'Invalid key combination.' };
    }

    // Check for conflict against ANY existing binding. Cross-category
    // duplicates previously slipped through, and since no handler stops
    // propagation both actions would fire on a single keypress.
    const conflict = this.shortcuts.find(x => x.id !== id && x.key === normalized);
    if (conflict) {
      return {
        success: false,
        conflict: {
          id: conflict.id,
          label: conflict.label,
          category: conflict.category
        },
        error: `Key "${formatDisplayKey(normalized)}" is already assigned to "${conflict.label}".`
      };
    }

    target.key = normalized;
    this.saveToStorage();
    this.notifyListeners();
    return { success: true };
  }

  /**
   * Force rebinds a shortcut, taking over any conflicting shortcut by resetting the conflicting one.
   */
  forceBindShortcut(id, newKeyCombo) {
    const normalized = normalizeKeyCombo(newKeyCombo);
    if (!normalized) return { success: false, error: 'Invalid key combination.' };

    const target = this.shortcuts.find(x => x.id === id);
    if (!target) return { success: false, error: 'Shortcut not found.' };

    // Clear conflict
    const conflict = this.shortcuts.find(x => x.id !== id && x.key === normalized);
    if (conflict) {
      conflict.key = conflict.defaultKey === normalized ? '' : conflict.defaultKey;
    }

    target.key = normalized;
    this.saveToStorage();
    this.notifyListeners();
    return { success: true };
  }

  /**
   * Resets a single shortcut to its architectural default.
   */
  resetShortcut(id) {
    const target = this.shortcuts.find(x => x.id === id);
    if (!target) return false;
    target.key = target.defaultKey;
    this.saveToStorage();
    this.notifyListeners();
    return true;
  }

  /**
   * Resets all shortcuts to default architectural CAD keybindings.
   */
  resetAllShortcuts() {
    for (const item of this.shortcuts) {
      item.key = item.defaultKey;
    }
    if (this.storage) {
      try { this.storage.removeItem(SHORTCUTS_STORAGE_KEY); } catch {}
    }
    this.notifyListeners();
    return true;
  }

  /**
   * Tests if a native KeyboardEvent matches the bound shortcut for an action ID.
   * @param {string} id - Action ID
   * @param {KeyboardEvent} event - Native keyboard event
   * @returns {boolean}
   */
  matchesEvent(id, event) {
    if (!event || !id) return false;
    const target = this.shortcuts.find(x => x.id === id);
    if (!target || !target.key) return false;

    const eventCombo = normalizeKeyCombo(event);
    return eventCombo === target.key;
  }

  subscribe(fn) {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  notifyListeners() {
    for (const fn of this.listeners) {
      try { fn(this.getAllShortcuts()); } catch {}
    }
  }
}

const ShortcutsManager = new ShortcutsManagerClass();


  // =========================================================================
  // MODULE: ExportModel
  // =========================================================================

/**
 * Architecture Helping Hand - Universal Export Model
 * Phase: Universal Export Center.
 *
 * One normalized export architecture for the whole application. Tools
 * produce (or already hold) project data; this module shapes it into a
 * provenance-stamped export document and provides PURE serializers for
 * every supported format. Side effects (download/clipboard/print) live in
 * services/export.js — nothing here touches the DOM.
 *
 * Formats: JSON (round-trip), TXT (human-readable), CSV, TSV, SVG (vector),
 * DXF (conservative 2D subset). PDF is handled by the print stylesheet +
 * window.print() (services), not by a heavy library.
 *
 * Every export carries provenance: source, format, timestamp, projectId.
 */




/** Format identifiers. */
const EXPORT_FORMATS = Object.freeze({
  JSON: 'json',
  TXT: 'txt',
  CSV: 'csv',
  TSV: 'tsv',
  SVG: 'svg',
  DXF: 'dxf'
});

/** Content-type mapping for downloads. */
const EXPORT_CONTENT_TYPES = Object.freeze({
  json: 'application/json',
  txt: 'text/plain',
  csv: 'text/csv',
  tsv: 'text/tab-separated-values',
  svg: 'image/svg+xml',
  dxf: 'application/dxf'
});

/** Human-readable format descriptions for the export UI. */
const EXPORT_FORMAT_INFO = Object.freeze({
  json: 'Full structured export — round-trips back into the project system.',
  txt: 'Human-readable report of the exported data.',
  csv: 'Comma-separated schedule (RFC-4180 escaping).',
  tsv: 'Tab-separated schedule — CAD/spreadsheet friendly.',
  svg: 'Vector drawing of geometry (chains, plans, diagrams).',
  dxf: 'AutoCAD DXF (ASCII R12 subset: LINE, POLYLINE, TEXT). Conservative 2D only.'
});

/** Provenance stamp embedded in every export document. */
function createExportProvenance(source, format, projectId = null, extra = {}) {
  return {
    application: 'Architecture Helping Hand',
    source,
    format,
    projectId,
    exportedAt: new Date().toISOString(),
    ...extra
  };
}

// ---------------------------------------------------------------------------
// Data collection: normalized table shape used by tabular serializers
// ---------------------------------------------------------------------------

/**
 * Normalizes arbitrary exportable content into a table description:
 * { title, columns: [{key,label}], rows: [{...}] } — consumed by CSV/TSV/TXT.
 *
 * @param {string} title
 * @param {Array<{key:string,label:string}>} columns
 * @param {Array<Object>} rows
 */
function createExportTable(title, columns, rows) {
  return { title, columns, rows };
}

/** Collects the workspace (dimensions) as a normalized table. */
function workspaceToTable(workspace) {
  if (!workspace || !Array.isArray(workspace.entries)) return null;
  return createExportTable(
    'Dimension Schedule',
    [
      { key: 'name', label: 'Name' },
      { key: 'rawInput', label: 'Input' },
      { key: 'type', label: 'Type' },
      { key: 'realMeters', label: 'Real (m)' },
      { key: 'drawingMeters', label: 'Drawing (m)' },
      { key: 'notes', label: 'Notes' }
    ],
    workspace.entries.map(e => ({
      name: e.name || 'Dimension',
      rawInput: e.rawInput || '',
      type: (e.dimensionType || 'segment').toUpperCase(),
      realMeters: typeof e.realMeters === 'number' ? e.realMeters : '',
      drawingMeters: typeof e.realMeters === 'number' && workspace.scaleRatio ? e.realMeters / workspace.scaleRatio : '',
      notes: e.notes || ''
    }))
  );
}

/** Collects chain segments as a normalized table. */
function chainToTable(calculatedChain) {
  if (!calculatedChain || !Array.isArray(calculatedChain.segments)) return null;
  return createExportTable(
    `Dimension Chain — ${calculatedChain.name || 'Chain'}`,
    [
      { key: 'index', label: '#' },
      { key: 'name', label: 'Segment' },
      { key: 'startMeters', label: 'Start (m)' },
      { key: 'endMeters', label: 'End (m)' },
      { key: 'lengthMeters', label: 'Length (m)' },
      { key: 'type', label: 'Type' }
    ],
    calculatedChain.segments
      .filter(s => s.enabled !== false && s.isValid !== false)
      .map((s, idx) => ({
        index: idx + 1,
        name: s.name || `Segment ${idx + 1}`,
        startMeters: s.startMeters,
        endMeters: s.endMeters,
        lengthMeters: typeof s.lengthMeters === 'number' ? s.lengthMeters : (typeof s.realMeters === 'number' ? s.realMeters : 0),
        type: (s.dimensionType || 'segment').toUpperCase()
      }))
  );
}

/** Collects a stair result as a normalized single-row table. */
function stairToTable(stairResult) {
  if (!stairResult || !stairResult.valid) return null;
  const g = stairResult.geometry;
  return createExportTable(
    'Stair Calculation',
    [
      { key: 'risers', label: 'Risers' },
      { key: 'goings', label: 'Goings' },
      { key: 'riserHeight', label: 'Riser (m)' },
      { key: 'treadDepth', label: 'Going (m)' },
      { key: 'totalRise', label: 'Total Rise (m)' },
      { key: 'totalRun', label: 'Total Run (m)' },
      { key: 'angle', label: 'Angle (°)' },
      { key: 'twoRPlusT', label: '2R+T (m)' }
    ],
    [{
      risers: stairResult.risers.count,
      goings: stairResult.treads.count,
      riserHeight: stairResult.risers.heightMeters,
      treadDepth: stairResult.treads.depthMeters,
      totalRise: stairResult.input.totalRiseMeters,
      totalRun: g.totalRunMeters,
      angle: g.angleDegrees,
      twoRPlusT: stairResult.proportion.twoRPlusTMeters
    }]
  );
}

/** Collects a ramp/slope result (shared geometry shape) as a table. */
function slopeToTable(geometryResult, kindLabel) {
  if (!geometryResult || !geometryResult.valid || !geometryResult.geometry) return null;
  const g = geometryResult.geometry;
  return createExportTable(
    kindLabel || 'Slope Calculation',
    [
      { key: 'rise', label: 'Rise (m)' },
      { key: 'run', label: 'Run (m)' },
      { key: 'slopePercent', label: 'Slope (%)' },
      { key: 'ratio', label: 'Ratio (1:X)' },
      { key: 'angle', label: 'Angle (°)' },
      { key: 'flight', label: 'Flight Length (m)' }
    ],
    [{
      rise: g.riseMeters,
      run: g.runMeters,
      slopePercent: g.slopePercent,
      ratio: g.ratioValue,
      angle: g.angleDegrees,
      flight: g.flightLengthMeters !== undefined ? g.flightLengthMeters : (g.slopedLengthMeters !== undefined ? g.slopedLengthMeters : '')
    }]
  );
}

/** Collects project decisions as a normalized table. */
function decisionsToTable(project) {
  if (!project || !Array.isArray(project.decisions)) return null;
  return createExportTable(
    'Design Decisions',
    [
      { key: 'id', label: 'ID' },
      { key: 'kind', label: 'Kind' },
      { key: 'name', label: 'Name' },
      { key: 'createdAt', label: 'Created' },
      { key: 'data', label: 'Result Data (JSON)' }
    ],
    project.decisions.map(d => ({
      id: d.id || '',
      kind: d.kind || '',
      name: d.name || '',
      createdAt: d.createdAt || '',
      data: d.result ? JSON.stringify(d.result) : ''
    }))
  );
}

/** Collects project notes as a normalized table. */
function notesToTable(project) {
  if (!project || !Array.isArray(project.notes)) return null;
  return createExportTable(
    'Project Notes',
    [
      { key: 'id', label: 'ID' },
      { key: 'title', label: 'Title' },
      { key: 'body', label: 'Note' },
      { key: 'createdAt', label: 'Created' }
    ],
    project.notes.map(n => ({
      id: n.id || '',
      title: n.title || 'Note',
      body: n.body || n.text || '',
      createdAt: n.createdAt || ''
    }))
  );
}

// ---------------------------------------------------------------------------
// Pure serializers
// ---------------------------------------------------------------------------

/** Serializes a table to TSV (with header). Reuses CAD-safe escaping. */
function tableToTSV(table) {
  if (!table) return '';
  const header = table.columns.map(c => escapeTSV(c.label)).join('\t');
  const rows = table.rows.map(row => table.columns.map(c => escapeTSV(row[c.key])).join('\t'));
  return [table.title, header, ...rows].join('\n');
}

/** Serializes a table to CSV (with header). Reuses RFC-4180 escaping. */
function tableToCSV(table) {
  if (!table) return '';
  const header = table.columns.map(c => escapeCSV(c.label)).join(',');
  const rows = table.rows.map(row => table.columns.map(c => escapeCSV(row[c.key])).join(','));
  return [escapeCSV(table.title), header, ...rows].join('\n');
}

/** Serializes a table to human-readable TXT. */
function tableToTXT(table) {
  if (!table) return '';
  const lines = [table.title.toUpperCase(), '='.repeat(Math.max(table.title.length, 8)), ''];
  for (const row of table.rows) {
    for (const col of table.columns) {
      const val = row[col.key];
      lines.push(`${col.label}: ${val === '' ? '—' : val}`);
    }
    lines.push('');
  }
  return lines.join('\n').trimEnd() + '\n';
}

/**
 * Full JSON export of a project document (round-trip capable).
 * Provenance lives in a sibling envelope, never inside the project itself,
 * so the project part re-imports cleanly.
 */
function serializeProjectJSON(project, provenance) {
  const check = validateProject(project);
  if (!check.ok) {
    throw new Error(`Cannot export invalid project: ${check.errors[0]}`);
  }
  return JSON.stringify({
    _provenance: provenance || createExportProvenance('project', EXPORT_FORMATS.JSON, project.id),
    project
  }, null, 2);
}

/**
 * Parses a JSON export back into a validated project document.
 * Throws on malformed input; callers decide recovery policy.
 */
function deserializeProjectJSON(json) {
  const parsed = JSON.parse(json);
  const project = parsed && typeof parsed === 'object' && parsed.project ? parsed.project : parsed;
  const check = validateProject(project);
  if (!check.ok) {
    throw new Error(`Imported document is not a valid project: ${check.errors[0]}`);
  }
  return project;
}

// ---------------------------------------------------------------------------
// DXF writer — conservative ASCII R12 subset
// ---------------------------------------------------------------------------

/**
 * DXF scope (documented limitation): ASCII R12, ENTITIES section only with
 * LINE, POLYLINE (as LWPOLLINE-free classic VERTEX chain), TEXT, and CIRCLE.
 * Coordinates are plain 2D (X, Y); no layers beyond '0', no blocks, no dims,
 * no 3D. Units are interpreted by the recipient — exported values are the
 * canonical meters multiplied by the caller's scale (mm by default).
 */

function dxfPair(code, value) {
  return `${code}\n${value}`;
}

function dxfLine(x1, y1, x2, y2, layer = '0') {
  return [
    dxfPair(0, 'LINE'),
    dxfPair(8, layer),
    dxfPair(10, x1), dxfPair(20, y1),
    dxfPair(11, x2), dxfPair(21, y2)
  ].join('\n');
}

function dxfPolyline(points, layer = '0', closed = false) {
  const parts = [
    dxfPair(0, 'POLYLINE'),
    dxfPair(8, layer),
    dxfPair(66, 1),
    dxfPair(70, closed ? 1 : 0)
  ];
  for (const [x, y] of points) {
    parts.push(dxfPair(0, 'VERTEX'));
    parts.push(dxfPair(8, layer));
    parts.push(dxfPair(10, x));
    parts.push(dxfPair(20, y));
  }
  parts.push(dxfPair(0, 'SEQEND'));
  return parts.join('\n');
}

function dxfText(x, y, text, height = 0.2, layer = '0') {
  const safe = String(text).replace(/[\r\n]+/g, ' ');
  return [
    dxfPair(0, 'TEXT'),
    dxfPair(8, layer),
    dxfPair(10, x), dxfPair(20, y),
    dxfPair(40, height),
    dxfPair(1, safe)
  ].join('\n');
}

/**
 * Builds a DXF document from a normalized entity list.
 *
 * @param {Array<Object>} entities - { type: 'line'|'polyline'|'text'|'circle', ... }
 *   line: { x1, y1, x2, y2 }
 *   polyline: { points: [[x,y]...], closed }
 *   text: { x, y, text, height }
 *   circle: { x, y, r }
 * @param {Object} [options] - { scale (default 1000 → m to mm), header }
 * @returns {string} DXF text
 */
function buildDXF(entities, options = {}) {
  const scale = typeof options.scale === 'number' && options.scale > 0 ? options.scale : 1000;
  const list = Array.isArray(entities) ? entities : [];
  const S = v => (v * scale).toFixed(4);

  const body = [];
  for (const e of list) {
    if (!e || typeof e !== 'object') continue;
    if (e.type === 'line') {
      body.push(dxfLine(S(e.x1), S(e.y1), S(e.x2), S(e.y2), e.layer || '0'));
    } else if (e.type === 'polyline' && Array.isArray(e.points) && e.points.length >= 2) {
      body.push(dxfPolyline(e.points.map(p => [S(p[0]), S(p[1])]), e.layer || '0', !!e.closed));
    } else if (e.type === 'text') {
      body.push(dxfText(S(e.x), S(e.y), e.text || '', (e.height || 0.2) * scale, e.layer || '0'));
    } else if (e.type === 'circle') {
      body.push([
        dxfPair(0, 'CIRCLE'),
        dxfPair(8, e.layer || '0'),
        dxfPair(10, S(e.x)), dxfPair(20, S(e.y)),
        dxfPair(40, S(e.r || 0))
      ].join('\n'));
    }
  }

  const usedLayers = new Set(['0']);
  for (const e of list) {
    if (e && e.layer) usedLayers.add(String(e.layer));
  }
  const sortedLayers = Array.from(usedLayers).sort();

  const LAYER_COLOR_MAP = {
    '0': 7,
    'A-WALL': 4,
    'A-DOOR': 2,
    'A-GLAZ': 4,
    'A-AREA': 3,
    'A-FLOR-STRS': 6,
    'A-FURN': 5,
    'A-DIMS': 1,
    'A-ANNO-TEXT': 7,
    'A-ANNO-TAGS': 2,
    'A-GRID': 8,
    'REF': 1,
    'CHAIN': 4,
    'ROOM': 3,
    'PLAN': 7
  };

  const tableParts = [
    dxfPair(0, 'SECTION'),
    dxfPair(2, 'TABLES'),
    dxfPair(0, 'TABLE'),
    dxfPair(2, 'LAYER'),
    dxfPair(70, sortedLayers.length)
  ];

  for (const lyr of sortedLayers) {
    const col = LAYER_COLOR_MAP[lyr] || 7;
    tableParts.push(
      dxfPair(0, 'LAYER'),
      dxfPair(2, lyr),
      dxfPair(70, 0),
      dxfPair(62, col),
      dxfPair(6, 'CONTINUOUS')
    );
  }
  tableParts.push(dxfPair(0, 'ENDTAB'), dxfPair(0, 'ENDSEC'));

  return [
    dxfPair(0, 'SECTION'),
    dxfPair(2, 'HEADER'),
    dxfPair(9, '$ACADVER'), dxfPair(1, 'AC1009'),
    dxfPair(9, '$INSUNITS'), dxfPair(70, 4), // 4 = millimeters
    dxfPair(0, 'ENDSEC'),
    tableParts.join('\n'),
    dxfPair(0, 'SECTION'),
    dxfPair(2, 'ENTITIES'),
    body.join('\n'),
    dxfPair(0, 'ENDSEC'),
    dxfPair(0, 'EOF')
  ].join('\n');
}

/** Chain geometry → DXF entities (closed room-style outline of cumulative points). */
function chainToDXFEntities(calculatedChain) {
  if (!calculatedChain || !Array.isArray(calculatedChain.segments)) return [];
  const entities = [];
  for (const s of calculatedChain.segments) {
    if (s.enabled === false || s.isValid === false) continue;
    entities.push({
      type: 'line',
      x1: s.startMeters, y1: 0,
      x2: s.endMeters, y2: 0,
      layer: (s.dimensionType || 'segment') === 'reference' ? 'REF' : 'CHAIN'
    });
  }
  return entities;
}

/** Room rectangles → DXF entities (initial rectilinear scope). */
function roomsToDXFEntities(rooms) {
  if (!Array.isArray(rooms)) return [];
  const entities = [];
  for (const room of rooms) {
    if (!room || typeof room.x !== 'number' || typeof room.y !== 'number') continue;
    const w = room.widthMeters ?? room.width ?? 0;
    const h = room.depthMeters ?? room.depth ?? 0;
    if (w <= 0 || h <= 0) continue;
    entities.push({
      type: 'polyline',
      closed: true,
      layer: 'ROOM',
      points: [
        [room.x, room.y],
        [room.x + w, room.y],
        [room.x + w, room.y + h],
        [room.x, room.y + h]
      ]
    });
    if (room.name) {
      entities.push({ type: 'text', x: room.x + w / 2 - 0.4, y: room.y + h / 2, text: room.name, height: 0.2 });
    }
  }
  return entities;
}

// ---------------------------------------------------------------------------
// SVG export (wraps existing diagram generators' output into a standalone file)
// ---------------------------------------------------------------------------

/**
 * Wraps SVG markup (from generateChainSVG / generateStairSVG / generateRampSVG
 * / generateSlopeSVG / the plan canvas) into a standalone, namespaced SVG
 * document with provenance metadata.
 */
function wrapSVGDocument(svgMarkup, provenance) {
  if (typeof svgMarkup !== 'string' || !svgMarkup.includes('<svg')) {
    throw new Error('wrapSVGDocument requires valid SVG markup containing an <svg> element.');
  }
  const meta = provenance || createExportProvenance('diagram', EXPORT_FORMATS.SVG);
  const comment = `<!-- ${meta.application} | source: ${meta.source} | exported: ${meta.exportedAt} -->`;
  // Ensure xmlns exists on the root element
  const withNs = svgMarkup.includes('xmlns=')
    ? svgMarkup
    : svgMarkup.replace('<svg', '<svg xmlns="http://www.w3.org/2000/svg"');
  return `<?xml version="1.0" encoding="UTF-8"?>\n${comment}\n${withNs}\n`;
}

/**
 * Master entry: serializes any supported export request.
 *
 * @param {Object} request
 * @param {string} request.format - one of EXPORT_FORMATS
 * @param {string} request.source - provenance label (e.g. 'dimension-workspace')
 * @param {Object} [request.project] - project document (JSON format / provenance)
 * @param {Array<Object>} [request.tables] - normalized tables (CSV/TSV/TXT)
 * @param {string} [request.svgMarkup] - SVG markup (SVG format)
 * @param {Array<Object>} [request.dxfEntities] - DXF entities (DXF format)
 * @param {string} [request.projectId]
 * @returns {{ content: string, contentType: string, fileName: string, provenance: Object }}
 */
function buildExport(request) {
  const format = request && request.format;
  if (!Object.values(EXPORT_FORMATS).includes(format)) {
    throw new Error(`Unknown export format: "${format}". Supported: ${Object.values(EXPORT_FORMATS).join(', ')}`);
  }
  const provenance = createExportProvenance(request.source || 'unknown', format, request.projectId || null);
  const stamp = provenance.exportedAt.replace(/[:.]/g, '-').slice(0, 19);
  const baseName = (request.source || 'export').replace(/[^a-z0-9_-]+/gi, '-').toLowerCase();

  switch (format) {
    case EXPORT_FORMATS.JSON: {
      if (!request.project) throw new Error('JSON export requires a project document.');
      const content = serializeProjectJSON(request.project, provenance);
      return { content, contentType: EXPORT_CONTENT_TYPES.json, fileName: `${baseName}-${stamp}.json`, provenance };
    }
    case EXPORT_FORMATS.TXT: {
      const tables = (request.tables || []).filter(Boolean);
      if (tables.length === 0) throw new Error('TXT export requires at least one table.');
      return { content: tables.map(tableToTXT).join('\n'), contentType: EXPORT_CONTENT_TYPES.txt, fileName: `${baseName}-${stamp}.txt`, provenance };
    }
    case EXPORT_FORMATS.CSV: {
      const tables = (request.tables || []).filter(Boolean);
      if (tables.length === 0) throw new Error('CSV export requires at least one table.');
      return { content: tables.map(tableToCSV).join('\n'), contentType: EXPORT_CONTENT_TYPES.csv, fileName: `${baseName}-${stamp}.csv`, provenance };
    }
    case EXPORT_FORMATS.TSV: {
      const tables = (request.tables || []).filter(Boolean);
      if (tables.length === 0) throw new Error('TSV export requires at least one table.');
      return { content: tables.map(tableToTSV).join('\n'), contentType: EXPORT_CONTENT_TYPES.tsv, fileName: `${baseName}-${stamp}.tsv`, provenance };
    }
    case EXPORT_FORMATS.SVG: {
      if (!request.svgMarkup) throw new Error('SVG export requires svgMarkup.');
      return { content: wrapSVGDocument(request.svgMarkup, provenance), contentType: EXPORT_CONTENT_TYPES.svg, fileName: `${baseName}-${stamp}.svg`, provenance };
    }
    case EXPORT_FORMATS.DXF: {
      const entities = request.dxfEntities || [];
      const content = buildDXF(entities, { scale: request.dxfScale || 1000 });
      return { content, contentType: EXPORT_CONTENT_TYPES.dxf, fileName: `${baseName}-${stamp}.dxf`, provenance };
    }
    default:
      throw new Error('Unhandled export format.');
  }
}


  // =========================================================================
  // MODULE: AIProvider
  // =========================================================================

/**
 * Architecture Helping Hand - AI Provider Abstraction
 * Phase 9.1-9.5: capability-declared cloud providers. NO local AI, no GPU
 * inference, no Ollama — the target laptop runs CAD beside the browser.
 *
 * Providers are declared, never hard-coded with permanent model ids: the
 * runtime configuration supplies model names; this module only defines the
 * provider shape, capability manifest, and error taxonomy. Network calls
 * happen in services (fetch wrappers) — this module stays importable
 * headless and defines the CONTRACT.
 *
 * Free-cost policy: no paid fallback. When quota is exhausted the
 * orchestrator reports AI_UNAVAILABLE and the app keeps working.
 */

/** Error codes shared by all providers (stable contract for the UI). */
const AI_ERROR_CODES = Object.freeze({
  PROVIDER_UNCONFIGURED: 'PROVIDER_UNCONFIGURED',   // no API key set
  NETWORK_ERROR: 'NETWORK_ERROR',                    // fetch failed / offline
  AUTH_FAILED: 'AUTH_FAILED',                        // 401/403
  QUOTA_EXHAUSTED: 'QUOTA_EXHAUSTED',                // 429 / free limit
  TIMEOUT: 'TIMEOUT',
  INVALID_MODEL: 'INVALID_MODEL',                    // 404 model
  MALFORMED_RESPONSE: 'MALFORMED_RESPONSE',
  UNSAFE_CONTENT: 'UNSAFE_CONTENT',                  // provider blocked
  UNKNOWN: 'UNKNOWN'
});

/** Capability keys every provider manifest must declare. */
const AI_CAPABILITIES = Object.freeze([
  'text', 'reasoning', 'toolCalling', 'structuredOutput', 'vision', 'imageGen', 'contextLimit'
]);

/**
 * Creates a provider instance from a declaration.
 *
 * @param {Object} declaration
 * @param {string} declaration.id - 'gemini' | 'glm' | ...
 * @param {string} declaration.label - human name
 * @param {Object} declaration.capabilities - booleans + contextLimit
 * @param {Function} declaration.sendPrompt - async ({ systemPrompt, userPrompt, options }) =>
 *   { ok: true, text } | { ok: false, errorCode, message }  (implemented in services)
 * @returns {Object} frozen provider handle
 */
function createProvider(declaration) {
  if (!declaration || typeof declaration !== 'object') {
    throw new TypeError('Provider declaration required');
  }
  if (typeof declaration.id !== 'string' || !declaration.id) {
    throw new TypeError('Provider id required');
  }
  if (typeof declaration.sendPrompt !== 'function') {
    throw new TypeError(`Provider "${declaration.id}" must implement sendPrompt()`);
  }
  const capabilities = {};
  for (const key of AI_CAPABILITIES) {
    capabilities[key] = declaration.capabilities?.[key] ?? false;
  }
  return Object.freeze({
    id: declaration.id,
    label: declaration.label || declaration.id,
    capabilities: Object.freeze(capabilities),
    sendPrompt: declaration.sendPrompt
  });
}

/** True when a provider can serve a request needing the given capabilities. */
function providerSupports(provider, needed) {
  if (!provider) return false;
  for (const key of Object.keys(needed || {})) {
    if (needed[key] && !provider.capabilities[key]) return false;
  }
  return true;
}

/** Normalizes a provider/network failure into the stable error taxonomy. */
function normalizeProviderError(err) {
  if (err && err.errorCode && typeof err.errorCode === 'string' && Object.values(AI_ERROR_CODES).includes(err.errorCode)) {
    return { errorCode: err.errorCode, message: err.message || 'Provider error' };
  }
  if (err && err.aiErrorCode) {
    return { errorCode: err.aiErrorCode, message: err.message || 'Provider error' };
  }
  const message = err?.message || String(err || 'Unknown error');
  if (/failed to fetch|network|offline/i.test(message)) {
    return { errorCode: AI_ERROR_CODES.NETWORK_ERROR, message: 'Network unavailable — the app works fully without AI.' };
  }
  if (/aborted|timeout/i.test(message)) {
    return { errorCode: AI_ERROR_CODES.TIMEOUT, message: 'AI request timed out.' };
  }
  return { errorCode: AI_ERROR_CODES.UNKNOWN, message };
}

/** Maps an HTTP status to the taxonomy. */
function statusCodeToError(status) {
  if (status === 401 || status === 403) return { errorCode: AI_ERROR_CODES.AUTH_FAILED, message: 'Authentication failed — check the API key.' };
  if (status === 429) return { errorCode: AI_ERROR_CODES.QUOTA_EXHAUSTED, message: 'AI temporarily unavailable — free provider limit reached.' };
  if (status === 404) return { errorCode: AI_ERROR_CODES.INVALID_MODEL, message: 'Model not found — check the configured model name.' };
  if (status >= 500) return { errorCode: AI_ERROR_CODES.NETWORK_ERROR, message: 'Provider server error — try again later.' };
  return { errorCode: AI_ERROR_CODES.UNKNOWN, message: `Provider returned HTTP ${status}.` };
}

/**
 * Runtime key storage (session-only or persisted via StorageService by the
 * caller). Keys NEVER live in this module's code and are never logged.
 */
function createKeyStore(storageAdapter, { sessionOnly = false } = {}) {
  const key = sessionOnly ? 'archiscale_ai_key_session' : 'archiscale_ai_keys';
  let memoryKeys = new Map(); // session-only keys live only here (per provider)
  return {
    setKey(providerId, apiKey) {
      if (sessionOnly) {
        memoryKeys.set(providerId, apiKey);
        return true;
      }
      try {
        const all = JSON.parse(storageAdapter.getItem(key) || '{}');
        all[providerId] = apiKey;
        storageAdapter.setItem(key, JSON.stringify(all));
        return true;
      } catch (e) {
        return false;
      }
    },
    getKey(providerId) {
      if (sessionOnly) return memoryKeys.has(providerId) ? memoryKeys.get(providerId) : null;
      try {
        const all = JSON.parse(storageAdapter.getItem(key) || '{}');
        return all[providerId] || null;
      } catch (e) {
        return null;
      }
    },
    clearKey(providerId) {
      if (sessionOnly) {
        memoryKeys.delete(providerId);
        return true;
      }
      try {
        const all = JSON.parse(storageAdapter.getItem(key) || '{}');
        delete all[providerId];
        storageAdapter.setItem(key, JSON.stringify(all));
        return true;
      } catch (e) {
        return false;
      }
    },
    /** True when a key exists for at least one provider. */
    hasAnyKey(providerId) {
      return this.getKey(providerId) !== null;
    }
  };
}


  // =========================================================================
  // MODULE: AIToolRegistry
  // =========================================================================

/**
 * Architecture Helping Hand - AI Tool Registry
 * Phase 9.7-9.9: declared tools with schemas and permissions. The model
 * can only call registered tools; tool calls never evaluate model-generated
 * code. Every tool executes DETERMINISTIC core functions.
 *
 * Permission tiers:
 *   READ_*  — safe, automatic
 *   PROPOSE_* — returns a proposal object; UI shows Preview/Accept/Reject
 *   APPLY_* — requires explicit user approval (handled by the orchestrator)
 */

/**
 * @param {Object} tools - map of tool implementations keyed by name
 */
function createToolRegistry(tools = {}) {
  const registry = new Map();
  for (const [name, tool] of Object.entries(tools)) {
    registerTool(registry, name, tool);
  }
  return {
    register(name, tool) { registerTool(registry, name, tool); },
    get: name => registry.get(name) || null,
    list() {
      return Array.from(registry.values()).map(t => ({
        name: t.name, description: t.description, permission: t.permission,
        inputSchema: t.inputSchema
      }));
    },
    /** Executes a tool call with basic argument validation against the schema. */
    async execute(name, args) {
      const tool = registry.get(name);
      if (!tool) {
        return { ok: false, error: `Unknown tool "${name}"` };
      }
      const validation = validateAgainstSchema(args || {}, tool.inputSchema || {});
      if (!validation.ok) {
        return { ok: false, error: `Invalid arguments for ${name}: ${validation.error}` };
      }
      try {
        const result = await tool.handler(args || {});
        return { ok: true, tool: name, permission: tool.permission, result };
      } catch (e) {
        return { ok: false, tool: name, error: e.message };
      }
    }
  };
}

function registerTool(registry, name, tool) {
  if (typeof tool.handler !== 'function') {
    throw new TypeError(`Tool "${name}" needs a handler function`);
  }
  if (!tool.permission) {
    throw new TypeError(`Tool "${name}" needs a permission tier`);
  }
  registry.set(name, Object.freeze({
    name,
    description: tool.description || '',
    permission: tool.permission,
    inputSchema: tool.inputSchema || {},
    handler: tool.handler
  }));
}

/** Minimal schema validation: type + required. (No JSON-schema dep.) */
function validateAgainstSchema(args, schema) {
  for (const key of Object.keys(schema)) {
    const expected = schema[key];
    const value = args[key];
    if (value === undefined) {
      if (expected.required) return { ok: false, error: `missing "${key}"` };
      continue;
    }
    const actual = Array.isArray(value) ? 'array' : typeof value;
    if (expected.type && actual !== expected.type) {
      return { ok: false, error: `"${key}" must be ${expected.type}, got ${actual}` };
    }
  }
  return { ok: true };
}

/** Permission tier constants. */
const AI_PERMISSIONS = Object.freeze({
  READ_PROJECT: 'READ_PROJECT',
  READ_GEOMETRY: 'READ_GEOMETRY',
  READ_MEASUREMENTS: 'READ_MEASUREMENTS',
  READ_CALCULATIONS: 'READ_CALCULATIONS',
  PROPOSE_CHANGE: 'PROPOSE_CHANGE',
  PROPOSE_NOTE: 'PROPOSE_NOTE',
  PROPOSE_LAYOUT: 'PROPOSE_LAYOUT',
  APPLY_CHANGE: 'APPLY_CHANGE'
});


  // =========================================================================
  // MODULE: AIArchitectureTools
  // =========================================================================

/**
 * Architecture Helping Hand - AI Tools
 * Phase 9.7: the tool set exposed to the model. Every handler calls
 * DETERMINISTIC core functions with REAL project data — the model never
 * calculates facts the core already knows, and never mutates the project
 * directly (PROPOSE_* tools return proposal objects for the user).
 */









/**
 * Builds the standard read/calculate tool set bound to live project state.
 *
 * @param {Function} getProject - () => project document (real store)
 * @param {Function} getPlanEntities - () => plan entity array (real canvas state)
 */
function createArchitectureTools(getProject, getPlanEntities) {
  const findRoom = (roomRef) => {
    const p = getProject();
    const entities = getPlanEntities();
    return entities.find(e => e.kind === 'room' && (e.id === roomRef || e.name === roomRef)) ||
      (p?.rooms || []).find(r => r.id === roomRef || r.name === roomRef) || null;
  };

  return {
    // ---- READ tools ----
    getProject: {
      description: 'Full project document: metadata, site, containers, decisions, snapshots.',
      permission: AI_PERMISSIONS.READ_PROJECT,
      inputSchema: {},
      handler: async () => getProject()
    },
    getRooms: {
      description: 'All rooms with calculated area and perimeter.',
      permission: AI_PERMISSIONS.READ_GEOMETRY,
      inputSchema: {},
      handler: async () => {
        const p = getProject();
        const entities = getPlanEntities();
        const rooms = entities.filter(e => e.kind === 'room');
        return rooms.map(r => ({
          id: r.id, name: r.name, widthMeters: r.width, depthMeters: r.depth,
          areaM2: roomArea(r), perimeterM2: roomPerimeter(r),
          furnitureIds: (p?.plan?.entities || []).filter(e => e.kind === 'furniture' && e.roomId === r.id).map(f => f.id)
        }));
      }
    },
    getRoom: {
      description: 'One room by id or name, with furniture inside it.',
      permission: AI_PERMISSIONS.READ_GEOMETRY,
      inputSchema: { roomRef: { type: 'string', required: true } },
      handler: async ({ roomRef }) => {
        const room = findRoom(roomRef);
        if (!room) return { error: `Room "${roomRef}" not found` };
        const furniture = getPlanEntities().filter(e => e.kind === 'furniture' && e.roomId === room.id);
        return {
          id: room.id, name: room.name, widthMeters: room.width, depthMeters: room.depth,
          areaM2: roomArea(room), perimeterM2: roomPerimeter(room),
          furniture: furniture.map(f => ({ id: f.id, name: f.name, x: f.x, y: f.y, widthMeters: f.width, depthMeters: f.depth }))
        };
      }
    },
    getWalls: {
      description: 'All walls with lengths.',
      permission: AI_PERMISSIONS.READ_GEOMETRY,
      inputSchema: {},
      handler: async () => getPlanEntities().filter(e => e.kind === 'wall')
    },
    getOpenings: {
      description: 'All doors and windows.',
      permission: AI_PERMISSIONS.READ_GEOMETRY,
      inputSchema: {},
      handler: async () => getPlanEntities().filter(e => e.kind === 'door' || e.kind === 'window')
    },
    getFurniture: {
      description: 'All placed furniture with positions and footprints.',
      permission: AI_PERMISSIONS.READ_GEOMETRY,
      inputSchema: {},
      handler: async () => getPlanEntities().filter(e => e.kind === 'furniture')
    },
    getDimensions: {
      description: 'All recorded dimensions (the dimension schedule).',
      permission: AI_PERMISSIONS.READ_MEASUREMENTS,
      inputSchema: {},
      handler: async () => getProject()?.dimensions || []
    },
    getMeasurements: {
      description: 'Survey measurements with provenance and verification status.',
      permission: AI_PERMISSIONS.READ_MEASUREMENTS,
      inputSchema: {},
      handler: async () => getProject()?.measurements || []
    },
    getDecisions: {
      description: 'Design decision journal (kind, name, result data).',
      permission: AI_PERMISSIONS.READ_PROJECT,
      inputSchema: {},
      handler: async () => getProject()?.decisions || []
    },

    // ---- CALCULATION tools (deterministic core) ----
    evaluateExpression: {
      description: 'Evaluate an architectural dimension expression, e.g. "2400+900" or "2.8m/2".',
      permission: AI_PERMISSIONS.READ_CALCULATIONS,
      inputSchema: { expression: { type: 'string', required: true } },
      handler: async ({ expression }) => evaluateExpressionSafe(expression)
    },
    calculateStair: {
      description: 'Stair calculation: rise + riser count → riser/tread/run/angle/Blondel.',
      permission: AI_PERMISSIONS.READ_CALCULATIONS,
      inputSchema: { totalRiseMeters: { type: 'number', required: true }, riserCount: { type: 'number', required: true } },
      handler: async ({ totalRiseMeters, riserCount }) => calculateStair({ mode: 'rise_riser_count', totalRise: totalRiseMeters, riserCount })
    },
    calculateRamp: {
      description: 'Ramp geometry: rise + run → slope %, ratio, angle.',
      permission: AI_PERMISSIONS.READ_CALCULATIONS,
      inputSchema: { riseMeters: { type: 'number', required: true }, runMeters: { type: 'number', required: true } },
      handler: async ({ riseMeters, runMeters }) => calculateRamp({ mode: 'rise_run_direct', rise: riseMeters, run: runMeters })
    },
    calculateSlope: {
      description: 'General slope analysis: rise + run → percent/ratio/angle (signed).',
      permission: AI_PERMISSIONS.READ_CALCULATIONS,
      inputSchema: { riseMeters: { type: 'number', required: true }, runMeters: { type: 'number', required: true } },
      handler: async ({ riseMeters, runMeters }) => analyzeSlope({ mode: 'rise_run', rise: riseMeters, run: runMeters })
    },
    checkFurnitureFit: {
      description: 'Does a furniture piece fit in a room? Returns fits/partial/no-fit with margins.',
      permission: AI_PERMISSIONS.READ_GEOMETRY,
      inputSchema: { furnitureId: { type: 'string', required: true }, roomId: { type: 'string', required: true } },
      handler: async ({ furnitureId, roomId }) => {
        const f = getPlanEntities().find(e => e.id === furnitureId && e.kind === 'furniture');
        const room = findRoom(roomId);
        if (!f || !room) return { error: 'Furniture or room not found' };
        return checkFurnitureFit(f, room);
      }
    },
    checkClearance: {
      description: 'Clearance-envelope check for furniture in a room (user-configured meters).',
      permission: AI_PERMISSIONS.READ_GEOMETRY,
      inputSchema: { furnitureId: { type: 'string', required: true }, roomId: { type: 'string', required: true }, clearanceMeters: { type: 'number', required: true } },
      handler: async ({ furnitureId, roomId, clearanceMeters }) => {
        const f = getPlanEntities().find(e => e.id === furnitureId && e.kind === 'furniture');
        const room = findRoom(roomId);
        if (!f || !room) return { error: 'Furniture or room not found' };
        return checkClearance(f, room, clearanceMeters, 'User Configured');
      }
    },
    checkOverlaps: {
      description: 'All overlap conflicts in the current plan (furniture/furniture, furniture/wall, outside-room).',
      permission: AI_PERMISSIONS.READ_GEOMETRY,
      inputSchema: {},
      handler: async () => checkOverlaps(
        getPlanEntities().filter(e => e.kind === 'furniture'),
        getPlanEntities().filter(e => e.kind === 'room'),
        getPlanEntities().filter(e => e.kind === 'wall')
      )
    },

    // ---- PROPOSE tools (return proposals; the user applies them) ----
    proposeNote: {
      description: 'Propose a project note. Returns a proposal — the user must accept it.',
      permission: AI_PERMISSIONS.PROPOSE_NOTE,
      inputSchema: { title: { type: 'string', required: true }, body: { type: 'string', required: true } },
      handler: async ({ title, body }) => ({
        proposalType: 'add-note',
        proposal: { id: null, title, body, createdAt: null, createdBy: 'ai' },
        requiresApproval: true,
        note: 'Preview and accept in the UI — the AI never writes directly.'
      })
    },
    proposeFurnitureMove: {
      description: 'Propose moving a furniture piece by (dx, dy) meters. Returns a previewable proposal.',
      permission: AI_PERMISSIONS.PROPOSE_CHANGE,
      inputSchema: { furnitureId: { type: 'string', required: true }, dx: { type: 'number', required: true }, dy: { type: 'number', required: true }, reason: { type: 'string' } },
      handler: async ({ furnitureId, dx, dy, reason }) => {
        const f = getPlanEntities().find(e => e.id === furnitureId && e.kind === 'furniture');
        if (!f) return { error: `Furniture "${furnitureId}" not found` };
        return {
          proposalType: 'move-furniture',
          proposal: {
            furnitureId, entityName: f.name,
            from: { x: f.x, y: f.y },
            to: { x: f.x + dx, y: f.y + dy },
            reason: reason || 'No reason given'
          },
          requiresApproval: true,
          note: 'Preview shows from/to; applying recalculates checks and keeps undo.'
        };
      }
    }
  };
}


  // =========================================================================
  // MODULE: AISchemas
  // =========================================================================

/**
 * Architecture Helping Hand - AI Schemas & Validators
 * Phase 9.10-9.13: structured response validation, trust classification,
 * numeric fact-checking. The model's output is UNTRUSTED — everything is
 * validated before rendering and numeric claims are compared with core.
 */

/** Trust classification labels (stable contract). */
const TRUST_LEVELS = Object.freeze([
  'CALCULATED', 'FACT', 'REFERENCE', 'INFERENCE',
  'DESIGN JUDGMENT', 'SPECULATION', 'UNKNOWN', 'NEEDS VERIFICATION'
]);

/**
 * Structured critic schema: every finding carries evidence, severity,
 * recommendation, alternative, trade-off, and a next test.
 */
const CRITIC_RESPONSE_SCHEMA = Object.freeze({
  summary: { type: 'string' },
  verdict: { type: 'string' },
  findings: {
    type: 'array',
    item: {
      title: { type: 'string', required: true },
      severity: { type: 'string', enum: ['high', 'medium', 'low'] },
      observation: { type: 'string', required: true },
      evidence: { type: 'array', required: true },
      whyItMatters: { type: 'string', required: true },
      recommendation: { type: 'string', required: true },
      alternative: { type: 'string' },
      tradeOff: { type: 'string' },
      testNext: { type: 'string', required: true },
      trust: { type: 'string' }
    }
  }
});

/** Minimal structural validator (no dependencies). */
function validateStructuredResponse(response, schema) {
  if (!response || typeof response !== 'object') {
    return { ok: false, errors: ['Response must be an object'] };
  }
  const errors = [];
  for (const [key, spec] of Object.entries(schema)) {
    const value = response[key];
    if (spec.type === 'array') {
      if (!Array.isArray(value)) {
        errors.push(`"${key}" must be an array`);
        continue;
      }
      if (spec.item) {
        value.forEach((item, idx) => {
          // P14 hardening: model output is untrusted — a findings array can
          // contain null/primitives. Flag them instead of crashing.
          if (!item || typeof item !== 'object' || Array.isArray(item)) {
            errors.push(`"${key}[${idx}]" must be an object`);
            return;
          }
          for (const [ik, ispec] of Object.entries(spec.item)) {
            if (ispec.required && item[ik] === undefined) {
              errors.push(`"${key}[${idx}].${ik}" missing`);
            } else if (item[ik] !== undefined && ispec.type === 'string' && typeof item[ik] !== 'string') {
              errors.push(`"${key}[${idx}].${ik}" must be a string`);
            } else if (item[ik] !== undefined && ispec.type === 'array' && !Array.isArray(item[ik])) {
              errors.push(`"${key}[${idx}].${ik}" must be an array`);
            } else if (item[ik] !== undefined && ispec.enum && !ispec.enum.includes(item[ik])) {
              errors.push(`"${key}[${idx}].${ik}" must be one of: ${ispec.enum.join(', ')}`);
            }
          }
        });
      }
    } else if (spec.type === 'string') {
      if (typeof value !== 'string') errors.push(`"${key}" must be a string`);
    } else if (spec.type === 'number') {
      if (typeof value !== 'number' || !isFinite(value)) errors.push(`"${key}" must be a finite number`);
    }
  }
  return { ok: errors.length === 0, errors };
}

/**
 * Numeric claim validation: extracts "number + unit" claims from AI text and
 * compares them against the deterministic facts pack. Claim-centric: a claim
 * passes if it matches ANY known fact (within tolerance); otherwise, if there
 * are facts of the same unit family, it is flagged NEEDS VERIFICATION.
 * This implements "AI SUGGESTS. CORE VERIFIES." mechanically.
 *
 * @param {string} aiText - the model's prose
 * @param {Array<{label: string, value: number, unit?: string, tolerancePercent?: number}>} facts
 * @returns {{ claims: Array, mismatches: Array }}
 */
function validateNumericClaims(aiText, facts) {
  const claims = [];
  const mismatches = [];
  const text = String(aiText || '');
  const factList = (facts || []).filter(f => typeof f.value === 'number' && isFinite(f.value));

  // Matches: 14.2 m² | 14.2m² | 14.2 m2 | 3.2 m | 2800 mm | 12.5 %
  const re = /(-?\d+(?:[.,]\d+)?)\s*(m2|m²|m3|m³|mm|cm|m|km|ft|in|%)/gi;
  let match;
  while ((match = re.exec(text)) !== null) {
    const rawValue = parseFloat(match[1].replace(',', '.'));
    const claim = { text: match[0], value: rawValue, unit: match[2].toLowerCase() };
    claims.push(claim);

    // Normalize the claim's unit token so 'm²' and 'm2' both match an 'm2' fact
    const normalizedUnit = claim.unit === 'm²' ? 'm2' : claim.unit;
    const matchingFacts = factList.filter(f => factClaimUnits(f).includes(normalizedUnit));
    if (matchingFacts.length === 0) continue; // nothing to check against
    const matched = matchingFacts.some(fact => {
      const normalized = normalizeClaimToFact(claim, fact);
      if (normalized === null) return false;
      const tolerance = fact.tolerancePercent !== undefined ? fact.tolerancePercent : 2;
      const diff = Math.abs(normalized - fact.value);
      return diff <= fact.value * (tolerance / 100) + 1e-9;
    });
    if (!matched) {
      mismatches.push({
        factLabel: matchingFacts.map(f => f.label).join(' | '),
        factValue: matchingFacts[0].value,
        claimText: claim.text,
        claimValue: claim.value,
        classification: 'NEEDS VERIFICATION',
        note: `AI claimed ${claim.text} but no deterministic fact matches it (known: ${matchingFacts.map(f => `${f.label}=${f.value}`).join(', ')}).`
      });
    }
  }
  return { claims, mismatches };
}

function factClaimUnits(fact) {
  const unit = (fact.unit || '').toLowerCase();
  if (/m2|sq/.test(unit)) return ['m2', 'm²'];
  if (unit === 'mm') return ['mm', 'm'];
  if (unit === 'cm') return ['cm', 'm'];
  if (unit === '%') return ['%'];
  return ['m', 'mm', 'cm'];
}

/** Normalizes a claim's value into the fact's unit; null when incompatible. */
function normalizeClaimToFact(claim, fact) {
  const fuRaw = (fact.unit || '').toLowerCase();
  const fu = fuRaw === 'm²' ? 'm2' : fuRaw;
  const cuRaw = claim.unit;
  const cu = cuRaw === 'm²' ? 'm2' : cuRaw;
  if (fu === cu) return claim.value;
  if (fu === 'mm') return cu === 'm' ? claim.value * 1000 : (cu === 'cm' ? claim.value * 10 : null);
  if (fu === 'cm') return cu === 'm' ? claim.value * 100 : (cu === 'mm' ? claim.value / 10 : null);
  if (fu === 'm') return cu === 'mm' ? claim.value / 1000 : (cu === 'cm' ? claim.value / 100 : null);
  return null;
}

/**
 * Trust classifier: given an AI statement's provenance metadata, produce the
 * label. Modes tag their output; unknown provenance = UNKNOWN.
 */
function classifyTrust(provenance) {
  if (!provenance) return 'UNKNOWN';
  if (provenance.calculatedByCore) return 'CALCULATED';
  if (provenance.fromProjectData) return 'FACT';
  if (provenance.fromReference) return 'REFERENCE';
  if (provenance.fromReasoning) return 'INFERENCE';
  if (provenance.fromJudgment) return 'DESIGN JUDGMENT';
  if (provenance.speculative) return 'SPECULATION';
  return 'UNKNOWN';
}


  // =========================================================================
  // MODULE: AIContext
  // =========================================================================

/**
 * Architecture Helping Hand - AI Context Builder (Facts Pack)
 * Phase 9.12: a compact DETERMINISTIC summary of project state for the AI.
 * The AI reasons over these facts; it must not recalculate what the core
 * already knows. Pure: reads project + plan entities, emits text + data.
 */




/**
 * Builds the facts pack.
 *
 * @param {Object} project - real project document (from the store)
 * @param {Array} planEntities - real plan entities (rooms/walls/furniture)
 * @param {Object} [options] - { includeMeasurements, includeDecisions, maxFacts }
 * @returns {{ text: string, data: Object, factChecks: Array }}
 */
function buildFactsPack(project, planEntities, options = {}) {
  const p = project || {};
  // Defensive normalization (P14): plan entities come from live canvas state
  // or from imported project documents. Imported data is validated only at the
  // envelope level, so individual entries may be null/garbage — skip them
  // instead of crashing the AI context build.
  const entities = (Array.isArray(planEntities) ? planEntities : [])
    .filter(e => e && typeof e === 'object' && typeof e.kind === 'string');
  const rooms = entities.filter(e => e.kind === 'room');
  const walls = entities.filter(e => e.kind === 'wall');
  const furniture = entities.filter(e => e.kind === 'furniture');
  const openings = entities.filter(e => e.kind === 'door' || e.kind === 'window');

  const isFiniteNumber = v => typeof v === 'number' && isFinite(v);
  const roomHasGeometry = r => isFiniteNumber(r.width) && isFiniteNumber(r.depth);
  const round2 = v => (isFiniteNumber(v) ? Number(v.toFixed(2)) : null);

  // Only rooms with calculable geometry feed numeric claim validation —
  // a null-valued fact would be uncheckable noise.
  const roomFacts = rooms
    .filter(roomHasGeometry)
    .map(r => ({
      label: `Room "${r.name}" area`,
      value: Number(roomArea(r).toFixed(2)),
      unit: 'm2',
      id: r.id
    }));

  const overlaps = checkOverlaps(furniture, rooms, walls);

  const data = {
    project: {
      id: p.id || null,
      name: (p.metadata && typeof p.metadata === 'object' ? p.metadata.name : null) || 'Untitled Project',
      description: (p.metadata && p.metadata.description) || (p.site && p.site.description) || ''
    },
    site: p.site ? { location: p.site.location || '', areaM2: p.site.areaM2 || null } : null,
    rooms: rooms.map(r => ({
      id: r.id, name: r.name,
      widthMeters: round2(r.width), depthMeters: round2(r.depth),
      areaM2: round2(roomArea(r)),
      perimeterM2: round2(roomPerimeter(r))
    })),
    walls: walls.map(w => ({ id: w.id, name: w.name })),
    openings: openings.map(o => ({ kind: o.kind, id: o.id, name: o.name, widthMeters: round2(o.width) })),
    furniture: furniture.map(f => ({ id: f.id, name: f.name, x: round2(f.x), y: round2(f.y), widthMeters: round2(f.width), depthMeters: round2(f.depth) })),
    dimensions: Array.isArray(p.dimensions) ? p.dimensions.length : 0,
    measurements: (Array.isArray(p.measurements) ? p.measurements : []).map(m => ({ label: m?.label, value: m?.value, unit: m?.unit, status: m?.status })),
    decisions: (Array.isArray(p.decisions) ? p.decisions : []).map(d => ({ kind: d?.kind, name: d?.name, createdAt: d?.createdAt })),
    conflicts: overlaps.conflicts,
    currentOption: (Array.isArray(p.snapshots) && p.snapshots.length) ? `${p.snapshots.length} snapshots recorded` : 'no snapshots'
  };

  const lines = [];
  lines.push(`PROJECT: ${data.project.name}`);
  if (data.project.description) lines.push(`INTENT: ${data.project.description}`);
  if (data.site && (data.site.location || data.site.areaM2)) {
    lines.push(`SITE: ${data.site.location || '—'}${data.site.areaM2 ? ` (${data.site.areaM2} m²)` : ''}`);
  }
  lines.push(`ROOMS (${data.rooms.length}):`);
  for (const r of data.rooms) {
    lines.push(`  ${r.name}: ${r.widthMeters ?? '?'} × ${r.depthMeters ?? '?'} m = ${r.areaM2 ?? '?'} m²`);
  }
  lines.push(`WALLS: ${data.walls.length} · OPENINGS: ${data.openings.length} · FURNITURE: ${data.furniture.length}`);
  if (data.conflicts.length > 0) {
    lines.push(`CONFLICTS (${data.conflicts.length}):`);
    for (const c of data.conflicts.slice(0, 5)) lines.push(`  ${c.evidence}`);
  }
  if (options.includeDecisions !== false && data.decisions.length > 0) {
    lines.push(`DECISIONS: ${data.decisions.slice(-3).map(d => d.name).join(', ')}`);
  }
  if (options.includeMeasurements !== false && data.measurements.length > 0) {
    lines.push(`MEASUREMENTS: ${data.measurements.map(m => `${m.label}=${m.value}${m.unit}(${m.status})`).join('; ')}`);
  }

  return {
    text: lines.join('\n'),
    data,
    factChecks: roomFacts // deterministic values for numeric claim validation
  };
}


  // =========================================================================
  // MODULE: AIProjectContext
  // =========================================================================

/**
 * Architecture Helping Hand - Project-Aware AI Context (Phase 15, M9)
 * Bridges the live application state (project store + plan entities) into
 * the job router's facts-pack callback, with SCOPING so a bedroom critique
 * does not ship the kitchen's furniture.
 *
 * Budgeting contract:
 *  - estimateTokens lives in job-router; here we trim entity lists by
 *    relevance (named scope match first, then proximity, then cap counts)
 *  - trimming is DISCLOSED: the returned summary records what was dropped
 *    so the UI can show "Context reduced to fit selected model."
 *  - pure: reads data, emits text — no DOM, no storage
 */




/** Caps for large projects — tuned to keep prompts modest by default. */
const SCOPE_LIMITS = Object.freeze({
  rooms: 24,
  furniturePerRoom: 12,
  furnitureGlobal: 40,
  measurements: 20,
  decisions: 6,
  notes: 4
});

/**
 * Extracts the relevant scope for a job.
 *
 * @param {Object} args
 * @param {Object} args.project - project document (store)
 * @param {Array} args.planEntities - live plan entities
 * @param {Object} [args.request] - { scopeHint: string (room/keyword name), jobId }
 * @returns {Object} scoped view { project, rooms, walls, openings, furniture, measurements, decisions, notes, site, conflicts, dropped: [] }
 */
function selectProjectScope({ project, planEntities, request = {} }) {
  const p = project && typeof project === 'object' ? project : {};
  const dropped = [];
  const entities = (Array.isArray(planEntities) ? planEntities : [])
    .filter(e => e && typeof e === 'object' && typeof e.kind === 'string');

  const allRooms = entities.filter(e => e.kind === 'room');
  const walls = entities.filter(e => e.kind === 'wall').slice(0, SCOPE_LIMITS.rooms * 2);
  const openings = entities.filter(e => e.kind === 'door' || e.kind === 'window').slice(0, 30);
  const allFurniture = entities.filter(e => e.kind === 'furniture');

  // Scope hint: keep rooms whose name matches any word of the hint; a
  // non-matching hint keeps everything (never narrow to nothing).
  let rooms = allRooms;
  const hint = typeof request.scopeHint === 'string' ? request.scopeHint.trim().toLowerCase() : '';
  if (hint) {
    const words = hint.split(/[^a-z0-9äöüß]+/i).filter(w => w.length >= 4);
    const matches = allRooms.filter(r => {
      const roomName = String(r.name || '').toLowerCase();
      return words.some(w => roomName.includes(w)) || roomName.includes(hint);
    });
    if (matches.length > 0 && matches.length < allRooms.length) {
      rooms = matches;
      // Furniture within or adjacent to the matched rooms only.
      const roomRects = matches.map(r => ({ x: r.x, y: r.y, width: r.width, depth: r.depth, name: r.name }));
      const inScope = [];
      for (const f of allFurniture) {
        const cx = (typeof f.x === 'number' ? f.x : 0) + (typeof f.width === 'number' ? f.width : 0) / 2;
        const cy = (typeof f.y === 'number' ? f.y : 0) + (typeof f.depth === 'number' ? f.depth : 0) / 2;
        const hit = roomRects.some(r =>
          cx >= r.x && cx <= r.x + r.width && cy >= r.y && cy <= r.y + r.depth);
        if (hit) inScope.push(f);
      }
      if (allFurniture.length > inScope.length) {
        dropped.push(`${allFurniture.length - inScope.length} furniture items outside ${matches.map(r => r.name).join('/')}`);
      }
      allFurniture.length = 0;
      allFurniture.push(...inScope);
    }
  }

  if (rooms.length > SCOPE_LIMITS.rooms) {
    dropped.push(`${rooms.length - SCOPE_LIMITS.rooms} rooms over the ${SCOPE_LIMITS.rooms}-room cap`);
    rooms = rooms.slice(0, SCOPE_LIMITS.rooms);
  }

  // Furniture cap per room (keep the first N by area, larger first — usually
  // the load-bearing pieces).
  const cappedFurniture = allFurniture
    .slice()
    .sort((a, b) => ((b.width || 0) * (b.depth || 0)) - ((a.width || 0) * (a.depth || 0)));
  if (cappedFurniture.length > SCOPE_LIMITS.furnitureGlobal) {
    dropped.push(`${cappedFurniture.length - SCOPE_LIMITS.furnitureGlobal} furniture items over the global cap`);
    cappedFurniture.length = SCOPE_LIMITS.furnitureGlobal;
  }

  const conflicts = checkOverlaps(cappedFurniture, rooms, walls);

  const measurements = ((Array.isArray(p.measurements) ? p.measurements : []) || [])
    .filter(m => m && typeof m === 'object')
    .slice(0, SCOPE_LIMITS.measurements);
  const decisions = ((Array.isArray(p.decisions) ? p.decisions : []) || [])
    .filter(d => d && typeof d === 'object')
    .slice(-SCOPE_LIMITS.decisions);
  const notes = ((Array.isArray(p.notes) ? p.notes : []) || [])
    .filter(n => n && typeof n === 'object')
    .slice(-SCOPE_LIMITS.notes);

  return {
    project: p,
    site: p.site || null,
    rooms,
    walls,
    openings,
    furniture: cappedFurniture,
    measurements,
    decisions,
    notes,
    conflicts,
    dropped
  };
}

/**
 * Builds the facts-pack shape the job router expects from a scoped view.
 * Deterministic text + data + numeric fact checks (room areas).
 */
function buildScopedFactsPack({ project, planEntities, request = {}, selectionPackets = null }) {
  const scope = selectProjectScope({ project, planEntities, request });
  const isNum = v => typeof v === 'number' && isFinite(v);
  const round2 = v => (isNum(v) ? Number(v.toFixed(2)) : null);
  const meta = scope.project.metadata && typeof scope.project.metadata === 'object' ? scope.project.metadata : {};

  const roomFacts = scope.rooms
    .filter(r => isNum(r.width) && isNum(r.depth) && r.width > 0 && r.depth > 0)
    .map(r => ({
      label: `Room "${r.name}" area`,
      value: Number(roomArea(r).toFixed(2)),
      unit: 'm2',
      id: r.id
    }));

  const data = {
    project: {
      id: scope.project.id || null,
      name: meta.name || 'Untitled Project',
      description: meta.description || ''
    },
    site: scope.site ? { location: scope.site.location || '', areaM2: scope.site.areaM2 || null } : null,
    rooms: scope.rooms.map(r => ({
      id: r.id, name: r.name,
      widthMeters: round2(r.width), depthMeters: round2(r.depth),
      areaM2: round2(roomArea(r)), perimeterM2: round2(roomPerimeter(r))
    })),
    openings: scope.openings.map(o => ({ kind: o.kind, name: o.name, widthMeters: round2(o.width) })),
    furniture: scope.furniture.map(f => ({
      id: f.id, name: f.name, roomId: f.roomId || null,
      x: round2(f.x), y: round2(f.y),
      widthMeters: round2(f.width), depthMeters: round2(f.depth)
    })),
    measurements: scope.measurements.map(m => ({ label: m.label, value: m.value, unit: m.unit, status: m.status })),
    decisions: scope.decisions.map(d => ({ kind: d.kind, name: d.name })),
    conflicts: scope.conflicts,
    dropped: scope.dropped
  };

  // Selection evidence: exact deterministic geometry of the user's current
  // selection, when the caller provided packets (AI Query / Ask-AI paths).
  // Never send unrelated context when only one entity is selected.
  const selectionPacketsResolved = Array.isArray(selectionPackets) ? selectionPackets.filter(Boolean) : [];
  data.selection = selectionPacketsResolved;

  const lines = [];
  lines.push(`PROJECT: ${data.project.name}`);
  if (data.project.description) lines.push(`INTENT: ${data.project.description}`);
  if (data.site && (data.site.location || data.site.areaM2)) {
    lines.push(`SITE: ${data.site.location || '—'}${data.site.areaM2 ? ` (${data.site.areaM2} m²)` : ''}`);
  }
  lines.push(`ROOMS (${data.rooms.length}):`);
  for (const r of data.rooms) {
    lines.push(`  ${r.name}: ${r.widthMeters ?? '?'} × ${r.depthMeters ?? '?'} m = ${r.areaM2 ?? '?'} m² (perimeter ${r.perimeterM2 ?? '?'} m)`);
  }
  lines.push(`WALLS: ${scope.walls.length} · OPENINGS: ${data.openings.length} · FURNITURE: ${data.furniture.length}`);
  if (data.conflicts.length > 0) {
    lines.push(`CONFLICTS (${data.conflicts.length}):`);
    for (const c of data.conflicts.slice(0, 6)) lines.push(`  ${c.evidence}`);
  }
  if (data.decisions.length > 0) {
    lines.push(`DECISIONS: ${data.decisions.map(d => d.name).join(', ')}`);
  }
  if (data.measurements.length > 0) {
    lines.push(`MEASUREMENTS: ${data.measurements.map(m => `${m.label}=${m.value}${m.unit}(${m.status})`).join('; ')}`);
  }
  if (selectionPacketsResolved.length > 0) {
    lines.push(`SELECTED ENTITIES (${selectionPacketsResolved.length}) — verified deterministic facts; quote these numbers exactly:`);
    for (const p of selectionPacketsResolved.slice(0, 8)) {
      const facts = Object.entries(p)
        .filter(([k, v]) => !['id', 'kind', 'name'].includes(k) && v !== null && v !== undefined && !(Array.isArray(v) && v.length === 0))
        .map(([k, v]) => `${k}=${typeof v === 'object' ? JSON.stringify(v) : v}`)
        .slice(0, 10)
        .join(' · ');
      lines.push(`  [${p.kind}] "${p.name}" (${p.id}): ${facts}`);
    }
    lines.push(`Answer specifically about the selected entity/entities. Distinguish fact (from this pack) from inference. Do not invent dimensions.`);
  }
  for (const n of scope.notes.slice(0, SCOPE_LIMITS.notes)) {
    const title = typeof n?.title === 'string' ? n.title : 'note';
    const body = typeof n?.body === 'string' ? n.body.slice(0, 160) : '';
    lines.push(`NOTE: ${title}${body ? ` — ${body}` : ''}`);
  }
  if (scope.dropped.length > 0) {
    lines.push(`CONTEXT REDUCED: ${scope.dropped.join('; ')}`);
  }

  return {
    text: lines.join('\n'),
    data,
    factChecks: roomFacts,
    dropped: scope.dropped
  };
}


  // =========================================================================
  // MODULE: ImportModel
  // =========================================================================

/**
 * Architecture Helping Hand - Import Model (Phase 15, M10)
 * Normalized ingestion foundation: source text → classified entities →
 * import report. Pure core: no DOM, no fetch, no storage.
 *
 * Supported initial formats (documented scope — see IMPORTS.md):
 *   CSV/TSV  — dimension schedules: "label,value,unit" rows
 *   DXF      — ASCII R12+ LINE / LWPOLYLINE / POLYLINE / TEXT entities (2D)
 *   SVG      — line / rect / polyline / polygon / circle / text elements
 *
 * Every importer returns the SAME report shape:
 *   { ok, sourceType, entities, warnings, stats: { found, imported, units, scale, confidence } }
 *
 * Imported geometry is CANDIDATE data: coordinates are meters, flagged
 * NEEDS VERIFICATION until the user confirms scale. Nothing here mutates a
 * project — the imports view applies accepted entities to the plan state.
 */

// ---------------------------------------------------------------------------
// Shared helpers
// ---------------------------------------------------------------------------

/** Parses a numeric string (dot or comma decimal), null when not numeric. */
function parseNumeric(token) {
  if (typeof token !== 'string' || !token.trim()) return null;
  const cleaned = token.trim().replace(',', '.');
  if (!/^-?\d+(\.\d+)?$/.test(cleaned)) return null;
  const v = parseFloat(cleaned);
  return isFinite(v) ? v : null;
}

/** Infers the length unit from a header row or tokens; defaults to meters. */
function inferUnit(tokens) {
  const joined = tokens.join(' ').toLowerCase();
  if (/\bmm\b/.test(joined)) return 'mm';
  if (/\bcm\b/.test(joined)) return 'cm';
  if (/\b(in|inch|inches)\b/.test(joined)) return 'in';
  if (/\b(ft|foot|feet)\b/.test(joined)) return 'ft';
  return 'm';
}

const UNIT_TO_METERS = Object.freeze({
  mm: 0.001, cm: 0.01, m: 1, in: 0.0254, ft: 0.3048
});

/** Converts a value in the given unit to canonical meters. */
function toMeters(value, unit) {
  const factor = UNIT_TO_METERS[unit];
  if (factor === undefined || typeof value !== 'number' || !isFinite(value)) return null;
  return value * factor;
}

/** Detects the delimiter used in tabular text. */
function detectImportDelimiter(text) {
  if (!text) return ',';
  const firstLine = text.split(/\r?\n/).find(l => l.trim()) || '';
  const counts = {
    '\t': (firstLine.match(/\t/g) || []).length,
    ';': (firstLine.match(/;/g) || []).length,
    ',': (firstLine.match(/,/g) || []).length
  };
  let best = ',';
  let bestCount = -1;
  for (const [delim, count] of Object.entries(counts)) {
    if (count > bestCount) {
      best = delim;
      bestCount = count;
    }
  }
  return bestCount > 0 ? best : ',';
}

// ---------------------------------------------------------------------------
// CSV / TSV importer — dimension schedules
// ---------------------------------------------------------------------------

/**
 * Imports a CSV/TSV dimension schedule. Expected shapes (header optional):
 *   label, width, depth [, unit]     → furniture/room footprint candidates
 *   label, length [, unit]           → linear measurement candidates
 * Accepts extra columns; ignores empty rows. Numbers may carry a unit suffix
 * in the value cell ("2400mm"); an explicit unit column wins.
 */
function importCsvTable(text, { delimiter } = {}) {
  const report = {
    ok: false,
    sourceType: 'csv',
    entities: [],
    warnings: [],
    stats: { found: 0, imported: 0, units: 'm', scale: null, confidence: 'medium' }
  };
  if (typeof text !== 'string' || !text.trim()) {
    report.warnings.push('File is empty.');
    return report;
  }
  const delim = delimiter || detectImportDelimiter(text);
  const rows = text.split(/\r?\n/).map(r => r.split(delim).map(c => c.trim())).filter(r => r.some(c => c));
  if (rows.length === 0) {
    report.warnings.push('No rows found.');
    return report;
  }
  report.stats.found = rows.length;

  // Header detection: first row contains no numeric cell.
  const firstIsHeader = rows[0].every(c => parseNumeric(c.replace(/[a-z%]+/gi, '')) === null);
  const header = firstIsHeader ? rows[0].map(c => c.toLowerCase()) : null;
  const dataRows = firstIsHeader ? rows.slice(1) : rows;
  let unit = header ? inferUnit(header) : 'm';

  // An explicit "Unit" header column is authoritative for the whole file —
  // per-row unit cells below override it where present.
  let unitColumnIndex = -1;
  if (header) {
    const idx = header.findIndex(h => /^(unit|units|uom)$/.test(h.trim()));
    if (idx >= 0) unitColumnIndex = idx;
  }

  for (let i = 0; i < dataRows.length; i++) {
    const row = dataRows[i];
    if (row.every(c => !c)) continue;
    let rowUnit = null;
    if (unitColumnIndex >= 0) {
      const cellUnit = (row[unitColumnIndex] || '').toLowerCase().match(/(mm|cm|in|ft|m)\b/);
      if (cellUnit) rowUnit = cellUnit[1];
    }
    const label = row[0] || `Row ${i + 1}`;
    const numericCells = [];
    const maxCol = unitColumnIndex >= 0 ? Math.min(row.length, unitColumnIndex) : row.length;
    for (let c = 1; c < maxCol; c++) {
      const cell = row[c];
      if (!cell) continue;
      const suffix = cell.toLowerCase().match(/(mm|cm|in|ft|m)\b/);
      const value = parseNumeric(cell.replace(/(mm|cm|in|ft|m)\b/gi, ''));
      if (value !== null) {
        numericCells.push({ value, unit: suffix ? suffix[1] : null });
      }
    }
    if (rowUnit) unit = rowUnit;
    if (numericCells.length === 0) {
      report.warnings.push(`Row ${i + 1} ("${label}"): no numeric value found — skipped.`);
      continue;
    }

    const meters = numericCells.map(nc => toMeters(nc.value, nc.unit || unit));
    if (meters.some(m => m === null)) {
      report.warnings.push(`Row ${i + 1} ("${label}"): unknown unit — skipped.`);
      continue;
    }
    if (meters.length >= 2) {
      report.entities.push({
        kind: 'furniture',
        name: label,
        width: meters[0],
        depth: meters[1],
        provenance: 'imported'
      });
    } else {
      report.entities.push({
        kind: 'measurement',
        name: label,
        value: meters[0],
        unit: 'm',
        provenance: 'imported'
      });
    }
    report.stats.imported++;
  }

  report.stats.units = unit;
  report.stats.confidence = report.warnings.length === 0 ? 'high' : (report.stats.imported > 0 ? 'medium' : 'low');
  report.ok = report.stats.imported > 0;
  if (!report.ok && report.warnings.length === 0) {
    report.warnings.push('No importable rows found.');
  }
  return report;
}

// ---------------------------------------------------------------------------
// DXF importer — ASCII 2D subset
// ---------------------------------------------------------------------------

/**
 * Imports LINE, LWPOLYLINE, POLYLINE (VERTEX chain), TEXT and CIRCLE
 * entities from an ASCII DXF. Coordinates are imported as-is into meters
 * (canonical app unit) with the declared $INSUNITS recorded when present.
 * Confidence is 'medium': DXF units are receiver-interpreted by convention.
 */
function importDxf(text) {
  const report = {
    ok: false,
    sourceType: 'dxf',
    entities: [],
    warnings: [],
    stats: { found: 0, imported: 0, units: 'm', scale: null, confidence: 'medium' }
  };
  if (typeof text !== 'string' || !text.trim()) {
    report.warnings.push('File is empty.');
    return report;
  }
  const lines = text.split(/\r?\n/).map(l => l.trim());
  // Pair up (code, value) records
  const records = [];
  for (let i = 0; i + 1 < lines.length; i += 2) {
    const code = parseInt(lines[i], 10);
    if (isNaN(code)) {
      // Resync on malformed pair (some DXFs carry extra whitespace)
      i -= 1;
      continue;
    }
    records.push({ code, value: lines[i + 1] });
  }

  // $INSUNITS header (code 70 inside $INSUNITS variable): 1=in, 2=ft, 4=mm, 5=cm, 6=m
  let unit = 'm';
  for (let i = 0; i < records.length; i++) {
    if (records[i].code === 9 && records[i].value === '$INSUNITS') {
      const next = records[i + 1];
      if (next && next.code === 70) {
        unit = { 1: 'in', 2: 'ft', 4: 'mm', 5: 'cm', 6: 'm' }[next.value] || 'm';
      }
      break;
    }
  }
  report.stats.units = unit;
  const scale = UNIT_TO_METERS[unit];

  // Group entity records between 0-markers
  let current = null;
  const groups = [];
  for (const rec of records) {
    if (rec.code === 0) {
      if (current) groups.push(current);
      current = { type: rec.value, props: [] };
    } else if (current) {
      current.props.push(rec);
    }
  }
  if (current) groups.push(current);

  const prop = (group, code) => {
    const found = group.props.filter(p => p.code === code).map(p => parseNumeric(p.value));
    return found.length === 1 ? found[0] : found;
  };
  const text10 = group => {
    const t = group.props.find(p => p.code === 1);
    return t ? String(t.value) : '';
  };

  for (const g of groups) {
    report.stats.found++;
    if (g.type === 'LINE') {
      const x1 = prop(g, 10), y1 = prop(g, 20), x2 = prop(g, 11), y2 = prop(g, 20 + 1);
      const X1 = Array.isArray(x1) ? x1[0] : x1;
      const Y1 = Array.isArray(y1) ? y1[0] : y1;
      const X2 = Array.isArray(x2) ? x2[0] : x2;
      const Y2v = Array.isArray(prop(g, 21)) ? prop(g, 21)[0] : prop(g, 21);
      const Y2 = Array.isArray(Y2v) ? Y2v[0] : Y2v;
      if ([X1, Y1, X2, Y2].every(v => typeof v === 'number')) {
        report.entities.push({
          kind: 'line',
          name: text10(g) || 'Line',
          x1: X1 * scale, y1: Y1 * scale, x2: X2 * scale, y2: Y2 * scale,
          provenance: 'imported'
        });
        report.stats.imported++;
      }
    } else if (g.type === 'LWPOLYLINE' || g.type === 'POLYLINE') {
      const xs = g.props.filter(p => p.code === 10).map(p => parseNumeric(p.value));
      const ys = g.props.filter(p => p.code === (g.type === 'LWPOLYLINE' ? 20 : 10 + 10)).map(p => parseNumeric(p.value));
      const ysAlt = g.props.filter(p => p.code === 20).map(p => parseNumeric(p.value));
      const useYs = ys.length >= xs.length ? ys : ysAlt;
      if (xs.length >= 2 && useYs.length >= 2) {
        report.entities.push({
          kind: 'polyline',
          name: 'Polyline',
          points: xs.map((x, i) => [x * scale, (useYs[i] ?? useYs[useYs.length - 1]) * scale]),
          closed: g.type === 'POLYLINE',
          provenance: 'imported'
        });
        report.stats.imported++;
      }
    } else if (g.type === 'TEXT' || g.type === 'MTEXT') {
      const label = text10(g);
      if (label) {
        const x = prop(g, 10), y = prop(g, 20);
        const X = Array.isArray(x) ? x[0] : x;
        const Y = Array.isArray(y) ? y[0] : y;
        report.entities.push({
          kind: 'label',
          name: label.replace(/\\[A-Za-z0-9]+;/g, '').replace(/[{}]/g, ''),
          x: (typeof X === 'number' ? X : 0) * scale,
          y: (typeof Y === 'number' ? Y : 0) * scale,
          provenance: 'imported'
        });
        report.stats.imported++;
      }
    } else if (g.type === 'CIRCLE') {
      const cx = prop(g, 10), cy = prop(g, 20), r = prop(g, 40);
      const CX = Array.isArray(cx) ? cx[0] : cx;
      const CY = Array.isArray(cy) ? cy[0] : cy;
      const R = Array.isArray(r) ? r[0] : r;
      if (typeof R === 'number' && R > 0) {
        report.entities.push({
          kind: 'circle',
          name: 'Circle',
          cx: (typeof CX === 'number' ? CX : 0) * scale,
          cy: (typeof CY === 'number' ? CY : 0) * scale,
          radius: R * scale,
          provenance: 'imported'
        });
        report.stats.imported++;
      }
    }
  }

  if (report.stats.found > 0 && report.stats.imported === 0) {
    report.warnings.push('No supported 2D entities (LINE/LWPOLYLINE/TEXT/CIRCLE) found — the file may use unsupported entity types or binary DXF.');
  }
  if (unit === 'm') {
    report.warnings.push('No $INSUNITS header found — coordinates imported as meters. Verify the scale.');
  }
  report.stats.confidence = report.stats.imported > 0 ? 'medium' : 'low';
  report.ok = report.stats.imported > 0;
  return report;
}

// ---------------------------------------------------------------------------
// SVG importer — safe 2D geometry subset
// ---------------------------------------------------------------------------

/**
 * Imports geometry from SVG source using the browser DOMParser when
 * available (headless tests inject a tiny parser mock via options.parser).
 * Supports line, rect, polyline, polygon, circle, text. Transform attributes
 * are NOT applied (documented limitation) — flat-coordinate SVGs only.
 */
function importSvg(text, { parser } = {}) {
  const report = {
    ok: false,
    sourceType: 'svg',
    entities: [],
    warnings: [],
    stats: { found: 0, imported: 0, units: 'm', scale: null, confidence: 'low' }
  };
  if (typeof text !== 'string' || !text.trim()) {
    report.warnings.push('File is empty.');
    return report;
  }

  let doc;
  try {
    const domParser = parser || (typeof DOMParser === 'function' ? new DOMParser() : null);
    if (!domParser) throw new Error('no parser');
    doc = domParser.parseFromString(text, 'image/svg+xml');
  } catch (e) {
    report.warnings.push('SVG could not be parsed.');
    return report;
  }
  const svgRoot = doc.querySelector ? doc.querySelector('svg') : null;
  if (!svgRoot) {
    report.warnings.push('No <svg> root element found.');
    return report;
  }

  // Optional scale: pxPerMeter user-declared; otherwise px→m at 100 px/m.
  const num = el => {
    const v = parseFloat(el);
    return isFinite(v) ? v : null;
  };

  const elements = svgRoot.querySelectorAll
    ? Array.from(svgRoot.querySelectorAll('line, rect, polyline, polygon, circle, text'))
    : [];
  report.stats.found = elements.length;

  for (const el of elements) {
    const tag = el.tagName ? el.tagName.toLowerCase() : '';
    if (tag === 'line') {
      const x1 = num(el.getAttribute('x1')), y1 = num(el.getAttribute('y1'));
      const x2 = num(el.getAttribute('x2')), y2 = num(el.getAttribute('y2'));
      if ([x1, y1, x2, y2].every(v => v !== null)) {
        report.entities.push({ kind: 'line', name: 'Line', x1, y1, x2, y2, provenance: 'imported' });
        report.stats.imported++;
      }
    } else if (tag === 'rect') {
      const x = num(el.getAttribute('x')) || 0, y = num(el.getAttribute('y')) || 0;
      const w = num(el.getAttribute('width')), h = num(el.getAttribute('height'));
      if (w !== null && h !== null && w > 0 && h > 0) {
        report.entities.push({ kind: 'room', name: (el.getAttribute('data-name') || 'Rect').slice(0, 40), x, y, width: w, depth: h, provenance: 'imported' });
        report.stats.imported++;
      }
    } else if (tag === 'polyline' || tag === 'polygon') {
      const pointsAttr = el.getAttribute('points') || '';
      const nums = pointsAttr.trim().split(/[\s,]+/).map(num).filter(v => v !== null);
      if (nums.length >= 4) {
        const points = [];
        for (let i = 0; i + 1 < nums.length; i += 2) points.push([nums[i], nums[i + 1]]);
        report.entities.push({ kind: 'polyline', name: tag === 'polygon' ? 'Polygon' : 'Polyline', points, closed: tag === 'polygon', provenance: 'imported' });
        report.stats.imported++;
      }
    } else if (tag === 'circle') {
      const cx = num(el.getAttribute('cx')), cy = num(el.getAttribute('cy')), r = num(el.getAttribute('r'));
      if (r !== null && r > 0) {
        report.entities.push({ kind: 'circle', name: 'Circle', cx: cx || 0, cy: cy || 0, radius: r, provenance: 'imported' });
        report.stats.imported++;
      }
    } else if (tag === 'text') {
      const label = (el.textContent || '').trim();
      if (label) {
        const x = num(el.getAttribute('x')) || 0, y = num(el.getAttribute('y')) || 0;
        report.entities.push({ kind: 'label', name: label.slice(0, 80), x, y, provenance: 'imported' });
        report.stats.imported++;
      }
    }
  }

  if (report.stats.found > 0 && report.stats.imported === 0) {
    report.warnings.push('No supported geometry found (transform matrices are not applied).');
  }
  report.warnings.push('SVG pixel coordinates were imported 1:1 into meters — set the true scale before trusting dimensions.');
  report.stats.confidence = report.stats.imported > 0 ? 'low' : 'low';
  report.ok = report.stats.imported > 0;
  return report;
}

// ---------------------------------------------------------------------------
// Dispatch
// ---------------------------------------------------------------------------

/** Imports by explicit format id: 'csv' | 'dxf' | 'svg'. */
function importSource(text, format, options = {}) {
  switch (format) {
    case 'csv':
    case 'tsv':
      return importCsvTable(text, options);
    case 'dxf':
      return importDxf(text);
    case 'svg':
      return importSvg(text, options);
    default:
      return {
        ok: false,
        sourceType: format || 'unknown',
        entities: [],
        warnings: [`Unsupported import format "${format}". Supported: CSV/TSV, DXF, SVG.`],
        stats: { found: 0, imported: 0, units: 'm', scale: null, confidence: 'low' }
      };
  }
}

/** Detects the likely format from content sniffing (best effort). */
function detectImportFormat(text) {
  if (typeof text !== 'string' || !text.trim()) return null;
  const head = text.slice(0, 2048);
  if (/^\s*<\?xml|<svg[\s>]/i.test(head)) return 'svg';
  if (/\bSECTION\b/.test(head) && /\bENTITIES\b/.test(text) && /\bAcDb/i.test(text)) return 'dxf';
  if (/\bLINE\b/.test(head) && /\s\d+\r?\n/.test(head)) return 'dxf';
  return 'csv';
}

/** Builds the user-facing summary lines from a report (rule 37). */
function formatImportReport(report) {
  const s = report.stats || {};
  const lines = [];
  lines.push(`Imported: ${s.imported ?? 0} of ${s.found ?? 0} elements (${report.sourceType?.toUpperCase() || '?'})`);
  lines.push(`Units: ${s.units || 'm'} · Confidence: ${s.confidence || 'low'}`);
  if (report.warnings?.length) {
    lines.push(`Warnings (${report.warnings.length}):`);
    for (const w of report.warnings.slice(0, 5)) lines.push(`  ⚠ ${w}`);
    if (report.warnings.length > 5) lines.push(`  … and ${report.warnings.length - 5} more`);
  }
  return lines.join('\n');
}


  // =========================================================================
  // MODULE: AIModes
  // =========================================================================

/**
 * Architecture Helping Hand - AI Specialist Modes
 * Phase 10: Tutor / Mentor / Critic / Brutal Critic / Jury / Ideation /
 * Best Practice. Modes are system-prompt + schema + severity profiles —
 * NOT autonomous agents. One orchestrator drives them all.
 *
 * Tone contract: brutally honest ≠ insulting. Direct, specific, evidence-
 * based, willing to disagree, professionally respectful. No empty praise.
 */

const AI_MODES = Object.freeze({
  TUTOR: 'tutor',
  MENTOR: 'mentor',
  CRITIC: 'critic',
  BRUTAL: 'brutal',
  JURY: 'jury',
  IDEATION: 'ideation',
  BEST_PRACTICE: 'best-practice'
});

const CRITIC_SCHEMA_HINT = `Return STRICT JSON matching:
{ "summary": string, "verdict": string,
  "findings": [ { "title": string, "severity": "high"|"medium"|"low",
    "observation": string, "evidence": string[], "whyItMatters": string,
    "recommendation": string, "alternative": string, "tradeOff": string,
    "testNext": string, "trust": string } ] }`;

const MODE_PROFILES = Object.freeze({
  [AI_MODES.TUTOR]: {
    label: 'Tutor',
    severity: 'low',
    requiresStudentQuestion: true,
    systemPrompt: `You are an architecture TUTOR for a second-year student. Socratic first:
ask one focused question that helps the student reason before explaining.
Use the FACTS PACK for all numbers — never invent dimensions or areas.
After the student has had a chance to think (or explicitly asks), explain
clearly with reference to their actual geometry. Trust labels: mark
calculations as CALCULATED, teaching conventions as REFERENCE.`,
    expectsStructured: false
  },
  [AI_MODES.MENTOR]: {
    label: 'Design Mentor',
    severity: 'low',
    systemPrompt: `You are a DESIGN MENTOR. Using the project FACTS PACK:
offer observations, questions, possibilities, and trade-offs. Help the
student develop their own concept — do NOT impose a single correct answer.
Always note what to test next in the plan. Mark speculation explicitly.`,
    expectsStructured: false
  },
  [AI_MODES.CRITIC]: {
    label: 'Studio Critic',
    severity: 'medium',
    systemPrompt: `You are a STUDIO CRITIC. Analyze the FACTS PACK rigorously.
Cover concept, spatial hierarchy, circulation, proportion, light, thresholds,
efficiency, furniture, openings — whichever the data supports. NO empty praise.
Every finding must cite actual evidence from the facts pack (dimensions,
areas, conflicts). Use the numeric values verbatim from the facts pack.
${CRITIC_SCHEMA_HINT}
Mark uncertain claims "NEEDS VERIFICATION".`,
    expectsStructured: true
  },
  [AI_MODES.BRUTAL]: {
    label: 'Brutal Critic',
    severity: 'high',
    systemPrompt: `You are a BRUTAL STUDIO CRITIC: direct, unsentimental, highly
specific, willing to disagree with the student's stated concept. Attack the
WEAKEST parts of the scheme with evidence from the facts pack — quote real
numbers and name real conflicts. Say "I disagree" when warranted.
NEVER insult, demean, or attack the person — only the design decisions.
No praise unless it is load-bearing. ${CRITIC_SCHEMA_HINT}`,
    expectsStructured: true
  },
  [AI_MODES.JURY]: {
    label: 'Jury',
    severity: 'high',
    systemPrompt: `You are a JURY PANEL preparing the student for studio review.
Challenge: What is your architectural argument? Why this organization,
proportion, circulation, material? What makes this project yours? What is
unresolved? What assumption are you relying on? Use the DECISIONS history
and FACTS PACK as evidence. Ask, then evaluate the answers against the data.
${CRITIC_SCHEMA_HINT}`,
    expectsStructured: true
  },
  [AI_MODES.IDEATION]: {
    label: 'Ideation',
    severity: 'low',
    systemPrompt: `You are an IDEATION partner generating genuinely DIFFERENT
design strategies (e.g. linear spine, courtyard, split mass, vertical,
compressed/expanded sequence). Each strategy needs: concept, spatial effect,
circulation effect, advantages, disadvantages, trade-offs, what to test next
in the plan. Ground every strategy in the FACTS PACK dimensions. Mark
speculative parts SPECULATION.`,
    expectsStructured: false
  },
  [AI_MODES.BEST_PRACTICE]: {
    label: 'Best Practice',
    severity: 'medium',
    systemPrompt: `You are a BEST-PRACTICE advisor combining deterministic
calculations with stored references. Reference values are educational
heuristics — NEVER claim code compliance. For anything regulatory say
"NEEDS VERIFICATION — verify applicable local requirements". Show the
relevant calculation from the FACTS PACK, then the practice guidance.`,
    expectsStructured: false
  }
});

/** Returns the frozen profile for a mode id. */
function getModeProfile(modeId) {
  return MODE_PROFILES[modeId] || null;
}

/** All mode descriptors for the UI. */
function listModes() {
  return Object.values(MODE_PROFILES).map(p => ({
    id: p.label ? Object.keys(MODE_PROFILES).find(k => MODE_PROFILES[k] === p) : p.label,
    label: p.label,
    severity: p.severity,
    expectsStructured: p.expectsStructured
  }));
}


  // =========================================================================
  // MODULE: AIOrchestrator
  // =========================================================================

/**
 * Architecture Helping Hand - AI Orchestrator
 * Phase 9.6 + Phase 12: the single entry point for all AI requests.
 *
 *   AI Orchestrator → specialist mode → context builder (facts pack) →
 *   provider → structured response → validator → numeric fact-check → UI
 *
 * AI SUGGESTS. CORE VERIFIES. — the orchestrator never trusts model output:
 * responses are validated against the mode's schema and numeric claims are
 * compared against deterministic facts. No autonomous loops, one request =
 * one response. Network transport is injected (sendPrompt from services).
 *
 * The application is FULLY functional without AI: every failure returns a
 * controlled { ok: false, errorCode } and the UI stays usable.
 */





/** Local error code for unknown mode (kept in the same namespace shape). */
const ERROR_MISSING_MODE = 'MISSING_MODE';

/**
 * Creates the orchestrator.
 *
 * @param {Object} options
 * @param {Object} options.provider - provider handle from createProvider
 * @param {Function} options.getKey - () => apiKey | null (from the key store)
 * @param {Function} options.buildFactsPack - (modeId) => { text, data, factChecks }
 * @param {Object} [options.toolRegistry] - optional registered tools
 * @param {Function} [options.now] - clock override (tests)
 */
function createOrchestrator(options = {}) {
  const { provider, getKey, buildFactsPack } = options;
  if (!provider) throw new TypeError('Orchestrator requires a provider');
  if (typeof getKey !== 'function') throw new TypeError('Orchestrator requires a key getter');

  function requireReady(needed = {}) {
    if (!providerSupports(provider, needed)) {
      return { ok: false, errorCode: AI_ERROR_CODES.PROVIDER_UNCONFIGURED, message: `Provider "${provider.label}" lacks required capabilities.` };
    }
    const apiKey = getKey();
    if (!apiKey) {
      return { ok: false, errorCode: AI_ERROR_CODES.PROVIDER_UNCONFIGURED, message: 'AI is not configured — add an API key in settings. The app works fully without AI.' };
    }
    return { ok: true };
  }

  /**
   * Runs a mode request end-to-end.
   *
   * @param {Object} request
   * @param {string} request.mode - one of AI_MODES
   * @param {string} request.userMessage - the student's question/answer
   * @param {Object} [request.requiredCapabilities] - e.g. { vision: true }
   * @param {Object} [request.factsOptions] - passed to the facts pack builder
   * @returns {Promise<Object>} { ok, mode, text?, structured?, consistency?, errorCode?, message? }
   */
  async function run(request = {}) {
    const modeId = request.mode || AI_MODES.CRITIC;
    const profile = getModeProfile(modeId);
    if (!profile) {
      return { ok: false, errorCode: ERROR_MISSING_MODE, message: `Unknown AI mode "${modeId}"` };
    }

    const ready = requireReady(request.requiredCapabilities);
    if (!ready.ok) return { ok: false, mode: modeId, ...ready };

    const facts = buildFactsPack ? buildFactsPack(modeId, request.factsOptions) : { text: '', data: {}, factChecks: [] };

    const userPrompt = [
      'FACTS PACK (deterministic, from the application — trust these numbers):',
      facts.text || '(no project data available)',
      '',
      `STUDENT (${profile.label} mode):`,
      request.userMessage || '(no message)'
    ].join('\n');

    let providerResult;
    try {
      providerResult = await provider.sendPrompt({
        systemPrompt: profile.systemPrompt,
        userPrompt,
        options: { expectsStructured: profile.expectsStructured, apiKey: getKey() }
      });
    } catch (err) {
      const normalized = normalizeProviderError(err);
      return { ok: false, mode: modeId, ...normalized };
    }

    if (!providerResult.ok) {
      const normalized = normalizeProviderError(providerResult);
      return { ok: false, mode: modeId, ...normalized };
    }

    const text = providerResult.text;

    // Structured modes: parse + validate JSON from the response
    if (profile.expectsStructured) {
      const structured = extractJson(text);
      if (!structured) {
        return { ok: false, mode: modeId, errorCode: AI_ERROR_CODES.MALFORMED_RESPONSE, message: 'AI response was not valid structured JSON.', rawText: text };
      }
      const validation = validateStructuredResponse(structured, CRITIC_RESPONSE_SCHEMA);
      if (!validation.ok) {
        return { ok: false, mode: modeId, errorCode: AI_ERROR_CODES.MALFORMED_RESPONSE, message: `AI response failed validation: ${validation.errors[0]}`, rawText: text, validationErrors: validation.errors };
      }
      // Enforce trust labels on findings that lack one
      for (const finding of structured.findings || []) {
        if (!finding.trust) finding.trust = 'INFERENCE';
      }
      // Numeric fact-check against deterministic values
      const numeric = validateNumericClaims(text, facts.factChecks || []);
      return {
        ok: true, mode: modeId,
        structured,
        text,
        consistency: {
          numericClaimsChecked: numeric.claims.length,
          mismatches: numeric.mismatches,
          status: numeric.mismatches.length === 0 ? 'CONSISTENT' : 'NEEDS VERIFICATION'
        }
      };
    }

    // Unstructured modes: still run numeric fact-checking over the prose
    const numeric = validateNumericClaims(text, facts.factChecks || []);
    return {
      ok: true, mode: modeId, text,
      consistency: {
        numericClaimsChecked: numeric.claims.length,
        mismatches: numeric.mismatches,
        status: numeric.mismatches.length === 0 ? 'CONSISTENT' : 'NEEDS VERIFICATION'
      }
    };
  }

  return { run, provider, getModeProfile };
}

/** Extracts the first JSON object from a model response (tolerates prose fences). */
function extractJson(text) {
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenced ? fenced[1] : text;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  try {
    return JSON.parse(candidate.slice(start, end + 1));
  } catch (e) {
    return null;
  }
}


  // =========================================================================
  // MODULE: AIVisual
  // =========================================================================

/**
 * Architecture Helping Hand - Visual AI Capability Layer (Phase 13)
 * Optional image analysis and concept-image generation behind capability
 * detection. The non-visual application NEVER depends on this.
 *
 * Contract:
 *  - capability detection first; if the provider lacks vision/imageGen,
 *    requests return { available: false, reason } — never a fake result
 *  - image interpretation returns structured observations with confidence
 *    labels; never pretends pixel guesses are exact geometry
 *  - concept images are labelled CONCEPTUAL EXPLORATION / NOT A TECHNICAL
 *    DRAWING in both the data and the UI contract
 */



const VISUAL_CAPABILITIES = Object.freeze(['vision', 'imageGen']);

/** What the visual layer can do with a given provider. */
function visualCapabilities(provider) {
  return {
    sketchInterpretation: !!provider?.capabilities?.vision,
    planImageInterpretation: !!provider?.capabilities?.vision,
    sitePhotoAnalysis: !!provider?.capabilities?.vision,
    conceptImageGeneration: !!provider?.capabilities?.imageGen
  };
}

/**
 * Image interpretation request. Confidence/trust are ALWAYS attached:
 * image analysis is inherently uncertain — it is never treated as geometry.
 */
async function interpretImage(provider, { imageBase64, mimeType, question }) {
  const caps = visualCapabilities(provider);
  if (!caps.planImageInterpretation) {
    return {
      available: false,
      reason: `Provider "${provider?.label || 'unknown'}" does not declare vision capability. Image interpretation is unavailable — the rest of the application is unaffected.`
    };
  }
  if (!imageBase64) {
    return { available: true, ok: false, errorCode: AI_ERROR_CODES.MISSING_INPUT, message: 'No image provided.' };
  }
  let result;
  try {
    result = await provider.sendPrompt({
      systemPrompt: `You analyze architectural images (sketches, plans, site photos).
Return STRICT JSON: { "observations": [ { "topic": string, "description": string,
"confidence": "high"|"medium"|"low" } ], "summary": string }.
NEVER present pixel-derived measurements as exact geometry — describe
relationships and likely dimensions with confidence levels only.`,
      userPrompt: `IMAGE (base64 ${mimeType || 'image/png'}) attached. QUESTION: ${question || 'Describe this architectural image.'}`,
      options: { imageBase64, mimeType }
    });
  } catch (err) {
    // A throwing transport surfaces as a controlled error, never an exception
    const normalized = normalizeProviderError(err);
    return { available: true, ok: false, ...normalized };
  }
  if (!result.ok) return { available: true, ok: false, ...result };
  return {
    available: true,
    ok: true,
    interpretation: result.text,
    disclaimer: 'AI image interpretation is approximate. Never treat it as measured geometry. Needs Verification.'
  };
}

/**
 * Concept image generation (only when the provider declares imageGen AND
 * the user's free access supports it). Output is labelled conceptual.
 */
async function generateConceptImage(provider, { prompt }) {
  const caps = visualCapabilities(provider);
  if (!caps.conceptImageGeneration) {
    return {
      available: false,
      reason: `Provider "${provider?.label || 'unknown'}" does not declare image-generation capability. Concept generation is unavailable — the rest of the application is unaffected.`
    };
  }
  let result;
  try {
    result = await provider.sendPrompt({
      systemPrompt: 'Generate a CONCEPTUAL architectural image. Output is for inspiration only.',
      userPrompt: prompt || 'Conceptual massing study',
      options: { generateImage: true }
    });
  } catch (err) {
    // A throwing transport surfaces as a controlled error, never an exception
    const normalized = normalizeProviderError(err);
    return { available: true, ok: false, ...normalized };
  }
  if (!result.ok) return { available: true, ok: false, ...result };
  return {
    available: true,
    ok: true,
    imageBase64: result.imageBase64 || null,
    labels: ['CONCEPTUAL EXPLORATION', 'NOT A TECHNICAL DRAWING', 'NOT CONSTRUCTION DOCUMENTATION']
  };
}


  // =========================================================================
  // MODULE: Storage
  // =========================================================================

/**
 * Architecture Helping Hand - Safe Storage Service
 * Resilient localStorage wrapper with in-memory fallback for sandboxed environments.
 */

const memoryStore = new Map();

const StorageService = {
  getItem(key) {
    try {
      if (typeof window !== 'undefined' && window.localStorage) {
        return window.localStorage.getItem(key);
      }
    } catch (e) {
      // Fallback to memory store
    }
    return memoryStore.has(key) ? memoryStore.get(key) : null;
  },

  setItem(key, value) {
    let persisted = true;
    try {
      if (typeof window !== 'undefined' && window.localStorage) {
        window.localStorage.setItem(key, value);
        persisted = true;
      }
      // No localStorage at all (Node/sandboxed): the memory fallback is the
      // designed behavior, not a persistence failure — report success so
      // durability-aware callers don't false-alarm.
    } catch (e) {
      // Quota exceeded / private mode: fall back to memory and report failure
      persisted = false;
    }
    memoryStore.set(key, String(value));
    // Callers that need durability guarantees (e.g. the project store) use
    // this return value; fire-and-forget callers may ignore it.
    return persisted;
  },

  removeItem(key) {
    try {
      if (typeof window !== 'undefined' && window.localStorage) {
        window.localStorage.removeItem(key);
      }
    } catch (e) {}
    memoryStore.delete(key);
  },

  clear() {
    try {
      if (typeof window !== 'undefined' && window.localStorage) {
        window.localStorage.clear();
      }
    } catch (e) {}
    memoryStore.clear();
  }
};


  // =========================================================================
  // MODULE: ExportServices
  // =========================================================================

/**
 * Architecture Helping Hand - Export Services
 * Phase: Universal Export Center — side-effect layer.
 *
 * Download, clipboard, and print behavior. All pure serialization lives in
 * core/export/export-model.js; nothing here computes content.
 */



/**
 * Triggers a browser download of text content. Returns a promise-like
 * result the caller can toast about. Safe for file:// (uses Blob + anchor).
 */
function downloadExport(content, fileName, format) {
  const contentType = EXPORT_CONTENT_TYPES[format] || 'text/plain';
  try {
    const blob = new Blob([content], { type: `${contentType};charset=utf-8` });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    return true;
  } catch (e) {
    return false;
  }
}

/** Copies export content through the app's existing clipboard helper. */
function copyExport(text, copyFn, label) {
  if (typeof copyFn !== 'function') return false;
  copyFn(text, label || 'Export copied');
  return true;
}

/**
 * Opens a print-focused window with the export content and calls print().
 * PDF export strategy: browser print-to-PDF via a print stylesheet — no
 * heavy PDF runtime dependency.
 */
function printExport(title, content) {
  const win = window.open('', '_blank', 'width=900,height=700');
  if (!win) return false;
  const safeTitle = String(title || 'Export').replace(/</g, '&lt;');
  const safeBody = String(content)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
  win.document.write(`<!DOCTYPE html>
<html>
<head>
  <title>${safeTitle}</title>
  <style>
    body { font-family: 'JetBrains Mono', Consolas, monospace; font-size: 11pt; padding: 1.5rem; white-space: pre-wrap; color: #111; background: #fff; }
    h1 { font-size: 13pt; border-bottom: 1px solid #333; padding-bottom: 0.4rem; }
    @media print { body { padding: 0; } }
  </style>
</head>
<body><h1>${safeTitle}</h1>${safeBody}</body>
</html>`);
  win.document.close();
  win.focus();
  setTimeout(() => { try { win.print(); } catch (e) {} }, 250);
  return true;
}


  // =========================================================================
  // MODULE: ProjectStore
  // =========================================================================

/**
 * Architecture Helping Hand - Versioned Project Store
 * Stabilization 3+4: project persistence with schema versioning, a
 * non-destructive migration chain, malformed-data recovery, and a tiny
 * pub/sub notification surface for the UI.
 *
 * Design:
 *  - PROJECT DATA lives under one envelope key (archiscale_project_store):
 *      { version, project }
 *  - USER PREFERENCES stay in their existing per-feature keys — the store
 *    never touches them.
 *  - Migrations are pure functions v(N) -> v(N+1) registered in MIGRATIONS.
 *    A stored version newer than the app understands fails LOUDLY (no
 *    silent downgrade that could lose data written by a newer app).
 *  - Legacy per-feature keys are read-only here: importLegacy* helpers
 *    COPY data into the project document without deleting the originals.
 *  - All storage access goes through an injected storage adapter (defaults
 *    to the existing StorageService), keeping the module testable headless.
 */



/**
 * Migration chain: each entry upgrades a document from its index+1 to the
 * next version. Register future migrations here, e.g. MIGRATIONS[1] = v2->v3.
 * An empty chain means version 1 is current.
 */
const MIGRATIONS = Object.freeze([
  /**
   * v1 → v2 (project model foundation):
   *  - stable ids on every entity
   *  - identity contract (_meta: createdAt/updatedAt/revision/provenance)
   *  - stored derived shadows (length/angleDegrees/area/perimeter) stripped —
   *    measurements are derived on demand via core/project-schema.deriveFacts
   *  - empty relationship index created (rebuilt on demand)
   */
  (project) => migrateProjectV1toV2(project)
]);

/** Highest version this build understands. */
const CURRENT_STORE_VERSION = PROJECT_SCHEMA_VERSION;
// Invariant: MIGRATIONS.length === PROJECT_SCHEMA_VERSION - 1 (one migration
// per version step below the target), enforced by tests/store.test.js.

/**
 * Runs the migration chain on a raw store envelope.
 * @param {{ version: number, project: Object }} envelope
 * @returns {{ version: number, project: Object }}
 */
function migrateEnvelope(envelope) {
  if (!envelope || typeof envelope !== 'object') {
    throw new Error('Cannot migrate: store envelope must be an object');
  }
  if (!Number.isInteger(envelope.version) || envelope.version < 1) {
    throw new Error('Cannot migrate: envelope.version must be a positive integer');
  }
  if (envelope.version > CURRENT_STORE_VERSION) {
    throw new Error(
      `Stored project version ${envelope.version} is newer than this app understands (${CURRENT_STORE_VERSION}). ` +
      'Refusing to open it to avoid data loss. Please update the application.'
    );
  }

  let version = envelope.version;
  let project = envelope.project;

  while (version < CURRENT_STORE_VERSION) {
    const migrate = MIGRATIONS[version - 1];
    if (typeof migrate !== 'function') {
      throw new Error(`Missing migration from version ${version} to ${version + 1}`);
    }
    project = migrate(project);
    version += 1;
  }

  return { version, project };
}

/**
 * Creates a project store bound to a storage adapter.
 *
 * @param {Object} [options]
 * @param {Object} [options.storage] - { getItem(key), setItem(key, value) }
 *   adapter; defaults to the app StorageService-like surface via injection.
 * @param {Function} [options.generateId] - id generator override (tests)
 * @param {Function} [options.now] - clock override (tests)
 */
function createProjectStore(options = {}) {
  const storage = options.storage;
  if (!storage || typeof storage.getItem !== 'function' || typeof storage.setItem !== 'function') {
    throw new Error('createProjectStore requires a storage adapter with getItem/setItem');
  }

  let currentProject = null;
  const subscribers = new Set();
  const genId = options.generateId;
  const nowFn = options.now || (() => new Date());

  function makeProject(opts = {}) {
    if (typeof genId === 'function') {
      const p = createProject(opts);
      p.id = genId();
      return p;
    }
    return createProject(opts);
  }

  // ------------------------------------------------------------------
  // Pub/Sub (tiny, synchronous)
  // ------------------------------------------------------------------
  function subscribe(fn) {
    if (typeof fn !== 'function') {
      throw new Error('subscribe requires a callback function');
    }
    subscribers.add(fn);
    return () => subscribers.delete(fn);
  }

  function notify(reason, project) {
    for (const fn of subscribers) {
      try {
        fn(reason, project);
      } catch (e) {
        // A faulty subscriber must never break the store
      }
    }
  }

  // ------------------------------------------------------------------
  // Raw envelope I/O
  // ------------------------------------------------------------------
  function readEnvelope() {
    let raw;
    try {
      raw = storage.getItem(PROJECT_STORE_KEY);
    } catch (e) {
      return { ok: false, errors: ['storage unavailable'] };
    }
    if (!raw) return { ok: true, envelope: null };

    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      return { ok: false, errors: [`store envelope is not valid JSON: ${e.message}`] };
    }

    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
      return { ok: false, errors: ['store envelope must be an object'] };
    }
    if (!Number.isInteger(parsed.version) || parsed.version < 1) {
      return { ok: false, errors: ['store envelope.version must be a positive integer'] };
    }
    return { ok: true, envelope: parsed };
  }

  function writeEnvelope(envelope) {
    try {
      // StorageService signals a localStorage failure (quota/private mode) via
      // its return value rather than throwing — a false return must surface
      // to the caller just like a thrown error, otherwise saves are reported
      // as successful while data only lives in the in-memory fallback.
      if (storage.setItem(PROJECT_STORE_KEY, JSON.stringify(envelope)) === false) {
        return false;
      }
      return true;
    } catch (e) {
      // Quota failures and private-mode write errors surface to the caller
      return false;
    }
  }

  // ------------------------------------------------------------------
  // Public API
  // ------------------------------------------------------------------

  /**
   * Loads the persisted project (with migration). Returns a status object;
   * never throws for malformed persisted data — the caller decides whether
   * to start fresh or surface an error.
   */
  function loadProject() {
    const res = readEnvelope();
    if (!res.ok) {
      return { ok: false, errors: res.errors, project: null };
    }
    if (!res.envelope) {
      return { ok: true, project: null, fresh: true };
    }

    try {
      const migrated = migrateEnvelope(res.envelope);
      const check = validateProject(migrated.project);
      if (!check.ok) {
        return { ok: false, errors: check.errors, project: null };
      }
      currentProject = normalizeProject(migrated.project);
      notify('load', currentProject);
      return { ok: true, project: currentProject, migratedFrom: res.envelope.version };
    } catch (e) {
      return { ok: false, errors: [e.message], project: null };
    }
  }

  /**
   * Returns the in-memory current project (creating one if none exists).
   */
  function getProject(opts = {}) {
    if (!currentProject) {
      const created = makeProject(opts);
      currentProject = created;
      notify('create', currentProject);
    }
    return currentProject;
  }

  /**
   * Replaces the current project and persists it.
   */
  function setProject(doc) {
    const check = validateProject(doc);
    if (!check.ok) {
      return { ok: false, errors: check.errors };
    }
    currentProject = normalizeProject(doc);
    const saved = saveProject();
    if (!saved.ok) return saved;
    notify('set', currentProject);
    return { ok: true, project: currentProject };
  }

  /**
   * Applies a mutation to the current project (immutable style: the mutation
   * receives a clone and returns the next state), then persists.
   */
  function updateProject(mutator) {
    if (typeof mutator !== 'function') {
      return { ok: false, errors: ['updateProject requires a mutator function'] };
    }
    const base = getProject();
    const draft = cloneProject(base);
    let next;
    try {
      next = mutator(draft);
    } catch (e) {
      return { ok: false, errors: [`mutator failed: ${e.message}`] };
    }
    if (!next || typeof next !== 'object') {
      return { ok: false, errors: ['mutator must return the next project document'] };
    }
    const stamped = touchProject(next, nowFn());
    const check = validateProject(stamped);
    if (!check.ok) {
      return { ok: false, errors: check.errors };
    }
    currentProject = normalizeProject(stamped);
    const saved = saveProject();
    if (!saved.ok) return saved;
    notify('update', currentProject);
    return { ok: true, project: currentProject };
  }

  /**
   * Persists the current project under the versioned envelope.
   */
  function saveProject() {
    if (!currentProject) {
      return { ok: false, errors: ['no project to save'] };
    }
    const check = validateProject(currentProject);
    if (!check.ok) {
      return { ok: false, errors: check.errors };
    }
    const envelope = {
      version: CURRENT_STORE_VERSION,
      project: currentProject
    };
    if (!writeEnvelope(envelope)) {
      return { ok: false, errors: ['storage write failed (quota or unavailable)'] };
    }
    return { ok: true };
  }

  /**
   * Starts a brand-new project (replaces in-memory current; does NOT save
   * until the caller calls saveProject/updateProject explicitly).
   */
  function createNewProject(opts = {}) {
    currentProject = makeProject(opts);
    notify('create', currentProject);
    return currentProject;
  }

  // ------------------------------------------------------------------
  // Multi-project library (Phase 2: Project Workspace)
  // Stored under a separate key: { version, projects: { id: projectDoc } }
  // The active project stays in the single-project envelope for backward
  // compatibility with existing persistence.
  // ------------------------------------------------------------------

  function readLibrary() {
    let raw;
    try {
      raw = storage.getItem(PROJECT_LIBRARY_KEY);
    } catch (e) {
      return { ok: false, errors: ['storage unavailable'], library: null };
    }
    if (!raw) return { ok: true, library: { version: CURRENT_STORE_VERSION, projects: {} } };
    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (e) {
      return { ok: false, errors: ['project library is not valid JSON'], library: null };
    }
    if (!parsed || typeof parsed !== 'object' || typeof parsed.projects !== 'object' || parsed.projects === null) {
      return { ok: false, errors: ['project library envelope malformed'], library: null };
    }
    // Same future-version contract as the active envelope: a library written
    // by a newer app must be refused loudly, never silently downgraded
    // (individual project documents carry their own schemaVersion; the
    // envelope version tracks the library container format).
    if (parsed.version !== undefined && (!Number.isInteger(parsed.version) || parsed.version > CURRENT_STORE_VERSION)) {
      return {
        ok: false,
        errors: [
          `Project library version ${parsed.version} is newer than this app understands (${CURRENT_STORE_VERSION}). ` +
          'Refusing to open it to avoid data loss. Please update the application.'
        ],
        library: null
      };
    }
    return { ok: true, library: parsed };
  }

  function writeLibrary(library) {
    try {
      storage.setItem(PROJECT_LIBRARY_KEY, JSON.stringify({ ...library, version: CURRENT_STORE_VERSION }));
      return true;
    } catch (e) {
      return false;
    }
  }

  /**
   * Lists saved project summaries (id, name, updatedAt) — newest first.
   * Corrupted entries are skipped and reported, never thrown.
   */
  function listProjects() {
    const res = readLibrary();
    if (!res.ok) return { ok: false, errors: res.errors, projects: [] };
    const summaries = [];
    for (const [id, doc] of Object.entries(res.library.projects)) {
      try {
        const check = validateProject(doc);
        if (!check.ok) continue;
        summaries.push({
          id,
          name: doc.metadata?.name || 'Untitled Project',
          updatedAt: doc.metadata?.updatedAt || doc.metadata?.createdAt || '',
          createdAt: doc.metadata?.createdAt || ''
        });
      } catch (e) { /* skip corrupted */ }
    }
    summaries.sort((a, b) => String(b.updatedAt).localeCompare(String(a.updatedAt)));
    return { ok: true, projects: summaries };
  }

  /**
   * Saves (upserts) the current project into the library under its id.
   */
  function saveProjectToLibrary() {
    if (!currentProject) return { ok: false, errors: ['no project to save'] };
    const check = validateProject(currentProject);
    if (!check.ok) return { ok: false, errors: check.errors };
    const res = readLibrary();
    if (!res.ok) return { ok: false, errors: res.errors };
    res.library.projects[currentProject.id] = currentProject;
    if (!writeLibrary(res.library)) {
      return { ok: false, errors: ['storage write failed (quota or unavailable)'] };
    }
    notify('library-save', currentProject);
    return { ok: true, id: currentProject.id };
  }

  /**
   * Loads a project from the library by id (replaces in-memory current).
   */
  function loadProjectFromLibrary(id) {
    if (typeof id !== 'string' || !id) {
      return { ok: false, errors: ['loadProjectFromLibrary requires a project id'] };
    }
    const res = readLibrary();
    if (!res.ok) return { ok: false, errors: res.errors };
    let doc = res.library.projects[id];
    if (!doc) return { ok: false, errors: [`project "${id}" not found in library`] };
    // Older library documents are migrated through the same chain as the
    // active envelope; future documents are refused loudly (never silently
    // normalized down to the current schema).
    if (Number.isInteger(doc.schemaVersion) && doc.schemaVersion < CURRENT_STORE_VERSION) {
      const migrated = migrateEnvelope({ version: doc.schemaVersion, project: doc });
      doc = migrated.project;
    } else if (Number.isInteger(doc.schemaVersion) && doc.schemaVersion > CURRENT_STORE_VERSION) {
      return {
        ok: false,
        errors: [
          `Library project "${id}" has schema version ${doc.schemaVersion}, newer than this app understands (${CURRENT_STORE_VERSION}). ` +
          'Refusing to open it to avoid data loss. Please update the application.'
        ]
      };
    }
    const check = validateProject(doc);
    if (!check.ok) return { ok: false, errors: check.errors };
    currentProject = normalizeProject(doc);
    notify('open', currentProject);
    return { ok: true, project: currentProject };
  }

  /**
   * Deletes a project from the library. The ACTIVE project envelope is
   * untouched — deleting a library copy never destroys the open document.
   */
  function deleteProject(id) {
    const res = readLibrary();
    if (!res.ok) return { ok: false, errors: res.errors };
    if (!res.library.projects[id]) {
      return { ok: false, errors: [`project "${id}" not found in library`] };
    }
    delete res.library.projects[id];
    if (!writeLibrary(res.library)) {
      return { ok: false, errors: ['storage write failed (quota or unavailable)'] };
    }
    notify('delete', { id });
    return { ok: true };
  }

  /**
   * Creates a structured snapshot of the current project inside its own
   * snapshots container (structured copy — no branching/merge machinery).
   *
   * Semantics: the snapshot's embedded copy is taken AFTER the snapshot is
   * registered in the container, so restoring any snapshot always yields a
   * project that still contains that snapshot (restores never delete the
   * snapshot being restored, nor any earlier ones).
   */
  /**
   * Strips the embedded payloads of PRIOR snapshots from a project copy.
   * Snapshot N embeds the whole document as it was at time N — if that
   * document still contains snapshots 1..N-1 WITH their payloads, storage
   * grows O(n²) and blows the localStorage quota around snapshot 9-10 on
   * a real project. Payload-stripping prior snapshots inside the embedded
   * copy keeps every snapshot O(document size): restore re-attaches the
   * payloads from the LIVE snapshot container (ids are stable, the live
   * container always outlives any restore — see restoreSnapshot).
   */
  function stripEmbeddedSnapshotPayloads(projectCopy) {
    if (projectCopy && Array.isArray(projectCopy.snapshots)) {
      projectCopy.snapshots = projectCopy.snapshots.map(s =>
        s && typeof s === 'object' ? { ...s, project: null } : s
      );
    }
    return projectCopy;
  }

  /**
   * Oldest snapshots beyond this count are dropped when a new one is created.
   * Uncapped growth eventually exhausted localStorage quota (failing saves)
   * on long-running projects.
   */
  const MAX_SNAPSHOTS = 25;

  function createSnapshot(label) {
    if (!currentProject) return { ok: false, errors: ['no project to snapshot'] };
    // Enforce the cap BEFORE building anything: drop oldest snapshots first.
    if (currentProject.snapshots.length >= MAX_SNAPSHOTS) {
      const excess = currentProject.snapshots.length - (MAX_SNAPSHOTS - 1);
      currentProject.snapshots = currentProject.snapshots.slice(excess);
    }
    const snapshot = {
      id: `snap-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
      label: typeof label === 'string' && label ? label : `Snapshot ${currentProject.snapshots.length + 1}`,
      createdAt: nowFn().toISOString(),
      project: null
    };
    // Build the full payload copy BEFORE registering so persistence is a
    // single atomic write — the previous two-phase version durably stored a
    // payload-less snapshot between the first save and the payload re-attach,
    // leaving a snapshot that could never be restored if the session died
    // in between.
    const docWithSnapshot = cloneProject(currentProject);
    docWithSnapshot.snapshots.push(snapshot);
    const embedded = stripEmbeddedSnapshotPayloads(docWithSnapshot);
    const fullSnapshot = { ...snapshot, project: embedded };
    const registered = updateProject(draft => {
      draft.snapshots.push(fullSnapshot);
      return draft;
    });
    if (!registered.ok) return registered;
    notify('snapshot', currentProject);
    return { ok: true, snapshotId: snapshot.id, snapshot: cloneProject(currentProject.snapshots.find(s => s.id === snapshot.id)) };
  }

  /**
   * Restores a snapshot: replaces the current project with the snapshot's
   * stored copy (a structured copy — the snapshot itself is preserved).
   *
   * The embedded copy carries prior snapshots with STRIPPED payloads
   * (storage-size contract). The live container still holds every payload
   * for snapshots that existed when the snapshot was taken; re-attach
   * those payloads by id so a restore never loses a snapshot's payload.
   * Payloads for snapshots created AFTER the embedded point are, and must
   * be, absent from the restored state — they did not exist then.
   */
  function restoreSnapshot(snapshotId) {
    if (!currentProject) return { ok: false, errors: ['no project open'] };
    const snap = currentProject.snapshots.find(s => s.id === snapshotId);
    if (!snap || !snap.project) return { ok: false, errors: [`snapshot "${snapshotId}" not found`] };
    const check = validateProject(snap.project);
    if (!check.ok) return { ok: false, errors: check.errors };
    const restored = normalizeProject(cloneProject(snap.project));
    if (Array.isArray(restored.snapshots)) {
      const payloadById = new Map(
        currentProject.snapshots
          .filter(s => s && s.project)
          .map(s => [s.id, s.project])
      );
      restored.snapshots = restored.snapshots.map(s =>
        s && typeof s === 'object' && !s.project && payloadById.has(s.id)
          ? { ...s, project: cloneProject(payloadById.get(s.id)) }
          : s
      );
    }
    currentProject = restored;
    const saved = saveProject();
    if (!saved.ok) return saved;
    notify('restore', currentProject);
    return { ok: true, project: currentProject };
  }

  /**
   * Non-destructive legacy import: copies supported legacy payloads into the
   * current project document without deleting the original keys.
   * @param {Object} legacy - { workspace?, chains? } raw parsed payloads
   * @returns {{ ok: boolean, imported: string[], errors: string[] }}
   */
  function importLegacy(legacy) {
    const imported = [];
    const errors = [];
    const src = legacy && typeof legacy === 'object' ? legacy : {};

    if (Array.isArray(src.workspace?.entries)) {
      updateProject(draft => {
        draft.dimensions = src.workspace.entries.map(e => ({
          legacyId: e.id || null,
          name: e.name || 'Dimension',
          rawInput: e.rawInput || '',
          dimensionType: e.dimensionType || 'segment',
          notes: e.notes || ''
        }));
        return draft;
      });
      imported.push('workspace');
    } else if (src.workspace !== undefined) {
      errors.push('workspace payload does not contain an entries array');
    }

    if (src.chains && Array.isArray(src.chains.segments)) {
      updateProject(draft => {
        draft.chains = [{
          name: src.chains.name || 'Imported Chain',
          defaultUnit: src.chains.defaultUnit || 'mm',
          scaleRatio: src.chains.scaleRatio || 50,
          segments: src.chains.segments
        }];
        return draft;
      });
      imported.push('chains');
    } else if (src.chains !== undefined) {
      errors.push('chains payload does not contain a segments array');
    }

    return { ok: errors.length === 0, imported, errors };
  }

  /**
   * Clears the in-memory project (does not delete persisted data).
   */
  function reset() {
    currentProject = null;
  }

  return {
    subscribe,
    loadProject,
    getProject,
    setProject,
    updateProject,
    saveProject,
    createNewProject,
    importLegacy,
    reset,
    listProjects,
    saveProjectToLibrary,
    loadProjectFromLibrary,
    deleteProject,
    createSnapshot,
    restoreSnapshot,
    get CURRENT_VERSION() { return CURRENT_STORE_VERSION; }
  };
}


