  // MODULE: Audio
  // =========================================================================

/**
 * Architecture Helping Hand - Tactile Audio Feedback Synthesizer
 * Zero-asset synthesized acoustic feedback using the HTML5 Web Audio API.
 */



let audioCtx = null;
let isSoundEnabled = true;

const SOUND_STORAGE_KEY = 'archiscale_sound_enabled';

try {
  const saved = StorageService.getItem(SOUND_STORAGE_KEY);
  if (saved !== null) {
    isSoundEnabled = saved === 'true';
  }
} catch (e) {}

function getAudioContext() {
  if (typeof window === 'undefined') return null;
  if (!audioCtx) {
    const AudioContextClass = window.AudioContext || window.webkitAudioContext;
    if (AudioContextClass) {
      audioCtx = new AudioContextClass();
    }
  }
  if (audioCtx && audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {});
  }
  return audioCtx;
}

const AudioService = {
  isEnabled() {
    return isSoundEnabled;
  },

  setEnabled(enabled) {
    isSoundEnabled = !!enabled;
    StorageService.setItem(SOUND_STORAGE_KEY, String(isSoundEnabled));
  },

  toggleSound() {
    this.setEnabled(!isSoundEnabled);
    if (isSoundEnabled) {
      this.playTick();
    }
    return isSoundEnabled;
  },

  playTick() {
    if (!isSoundEnabled) return;
    try {
      const ctx = getAudioContext();
      if (!ctx) return;

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const now = ctx.currentTime;

      osc.type = 'sine';
      osc.frequency.setValueAtTime(800, now);
      osc.frequency.exponentialRampToValueAtTime(300, now + 0.025);

      gain.gain.setValueAtTime(0.04, now);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.025);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(now);
      osc.stop(now + 0.03);
    } catch (e) {}
  },

  playKeyClick() {
    if (!isSoundEnabled) return;
    try {
      const ctx = getAudioContext();
      if (!ctx) return;

      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const now = ctx.currentTime;

      osc.type = 'triangle';
      osc.frequency.setValueAtTime(450, now);
      osc.frequency.exponentialRampToValueAtTime(180, now + 0.015);

      gain.gain.setValueAtTime(0.025, now);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.015);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(now);
      osc.stop(now + 0.02);
    } catch (e) {}
  },

  playSwapSound() {
    if (!isSoundEnabled) return;
    try {
      const ctx = getAudioContext();
      if (!ctx) return;

      const now = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      osc.type = 'sine';
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 0.06);

      gain.gain.setValueAtTime(0.05, now);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.07);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(now);
      osc.stop(now + 0.08);
    } catch (e) {}
  },

  playCopySuccess() {
    if (!isSoundEnabled) return;
    try {
      const ctx = getAudioContext();
      if (!ctx) return;

      const now = ctx.currentTime;
      [523.25, 659.25, 783.99].forEach((freq, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const noteTime = now + (i * 0.05);

        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, noteTime);
        gain.gain.setValueAtTime(0.04, noteTime);
        gain.gain.exponentialRampToValueAtTime(0.0001, noteTime + 0.12);

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.start(noteTime);
        osc.stop(noteTime + 0.13);
      });
    } catch (e) {}
  },

  /**
   * Success arpeggio for completed multi-step actions (AI jobs, imports,
   * exports, saves). A brighter variant of the copy chime.
   */
  playSuccess() {
    if (!isSoundEnabled) return;
    try {
      const ctx = getAudioContext();
      if (!ctx) return;

      const now = ctx.currentTime;
      [587.33, 739.99, 880.00].forEach((freq, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        const noteTime = now + (i * 0.06);

        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, noteTime);
        gain.gain.setValueAtTime(0.05, noteTime);
        gain.gain.exponentialRampToValueAtTime(0.0001, noteTime + 0.18);

        osc.connect(gain);
        gain.connect(ctx.destination);

        osc.start(noteTime);
        osc.stop(noteTime + 0.2);
      });
    } catch (e) {}
  }
};


  // =========================================================================
  // MODULE: History
  // =========================================================================

/**
 * Architecture Helping Hand - History & Logging Service
 */



const HISTORY_STORAGE_KEY = 'archiscale_calculation_history';
let historyList = [];

function loadHistoryFromStorage() {
  try {
    const saved = StorageService.getItem(HISTORY_STORAGE_KEY);
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed)) {
        // Validate items: require a well-formed service-generated id (defense
        // against poisoned/persisted payloads — ids flow into DOM attributes
        // and querySelector lookups in the journal view).
        const idOk = id => typeof id === 'string' && /^hist_\d+_[a-z0-9]+$/.test(id);
        return parsed.filter(item => item && typeof item === 'object' && idOk(item.id))
          // Also strip any spread-in fields the service computes itself, so a
          // persisted entry cannot override id/timestamp through addEntry.
          .map(item => ({
            ...item,
            id: item.id,
            timestamp: typeof item.timestamp === 'string' ? item.timestamp.slice(0, 40) : '',
            date: typeof item.date === 'string' ? item.date.slice(0, 40) : ''
          }));
      }
    }
  } catch (e) {
    // Corrupted data handling
  }
  return [];
}

historyList = loadHistoryFromStorage();

const HistoryService = {
  getHistory() {
    return [...historyList];
  },

  reload() {
    historyList = loadHistoryFromStorage();
    return [...historyList];
  },

  addEntry(entry) {
    if (!entry || typeof entry !== 'object') {
      throw new Error('History entry must be a valid object');
    }

    // Service-owned identity fields are computed here and MUST NOT be
    // overridable through the spread — the caller's entry comes last in
    // the object literal below only for optional free-form fields, so the
    // protected fields are re-asserted after the spread.
    const item = {
      stateSnapshot: null,
      ...entry,
      id: 'hist_' + Date.now() + '_' + Math.random().toString(36).substring(2, 6),
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
      date: new Date().toLocaleDateString(),
      operation: entry.operation || entry.mode || 'Scale Converter',
      mode: entry.mode || entry.operation || 'Scale Converter',
      scaleStr: entry.scaleStr || (entry.scaleRatio ? `1:${entry.scaleRatio}` : '-'),
      inputStr: entry.inputStr || '',
      outputStr: entry.outputStr || ''
    };

    historyList.unshift(item);
    if (historyList.length > 100) {
      historyList.pop();
    }
    this.save();
    return item;
  },

  removeEntry(id) {
    historyList = historyList.filter(item => item.id !== id);
    this.save();
  },

  clear() {
    historyList = [];
    this.save();
  },

  save() {
    try {
      StorageService.setItem(HISTORY_STORAGE_KEY, JSON.stringify(historyList));
    } catch (e) {}
  },

  exportCSV() {
    if (historyList.length === 0) return null;
    const headers = ['Timestamp', 'Date', 'Operation', 'Scale', 'Input', 'Result', 'Notes'];
    const rows = historyList.map(h => [
      `"${h.timestamp || ''}"`,
      `"${h.date || ''}"`,
      `"${h.operation || h.mode || 'Scale'}"`,
      `"${h.scaleStr || ''}"`,
      `"${h.inputStr || ''}"`,
      `"${h.outputStr || ''}"`,
      `"${h.notes || ''}"`
    ]);
    return [headers.join(','), ...rows.map(r => r.join(','))].join('\n');
  },

  exportMarkdown() {
    if (historyList.length === 0) return null;
    let md = '# Architecture Helping Hand - Architectural Calculation Journal\n\n';
    md += `*Generated on ${new Date().toLocaleString()}*\n\n`;
    md += '| Time | Operation | Scale | Input | Result |\n';
    md += '| :--- | :--- | :--- | :--- | :--- |\n';
    historyList.forEach(h => {
      md += `| ${h.timestamp || ''} | ${h.operation || h.mode || 'Scale'} | ${h.scaleStr || '-'} | ${h.inputStr || '-'} | **${h.outputStr || '-'}** |\n`;
    });
    return md;
  }
};


